import React, { type ComponentType } from "react"
import type { ReactNode } from "react"
import { Card, CardContent, cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { SeeMoreLink } from "@/components/blocks/navigation/SeeMoreLink"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"
import { resolveIdentity, type CallerIdentity } from "@/components/frames/_identity"

/** Props for the {@link LabeledCard} block. */
export interface LabeledCardProps extends WithClassNames<undefined> {
    /** Section title rendered OUTSIDE (above) the card. */
    label: string
    /**
     * Optional secondary label pinned to the RIGHT of the label row (muted) — a
     * passive tag, NOT an action (e.g. a currency "VND", a count, a unit). Rendered
     * only when neither `action` nor `onSeeMore` claim the right slot.
     */
    labelEnd?: string
    /**
     * When provided, renders a shared {@link SeeMoreLink} on the right of the
     * label (semibold accent text + a caret that slides right on hover).
     */
    onSeeMore?: () => void
    /** Text for the see-more link. Defaults to "See more" — pass `t(...)` to localise. */
    seeMoreLabel?: string
    /**
     * Arbitrary right-aligned slot in the label row (e.g. an owner "Add / manage"
     * button) — a buildable slot. Takes precedence over `onSeeMore` when both are passed.
     */
    action?: ComponentType
    /** Card body content. */
    children: ReactNode
    /**
     * Optional secondary slot rendered OUTSIDE (below) the card, `gap-2` from
     * it — a caption/prompt/status that belongs to the section but not inside the
     * surface (e.g. a "complete all 3 to claim" prompt, a claim button) — a
     * buildable slot. Kept below the card so it never becomes surface-in-surface.
     * Caller owns its alignment.
     */
    description?: ComponentType
    /** Extra classes merged onto the card content wrapper. */
    contentClassName?: string
    /**
     * When true, drop the inner `<Card>` frame and render children directly under
     * the label — for sections whose content is ITSELF card(s) (e.g. a grid of
     * resume / course cards), so they never nest card-in-card.
     */
    frameless?: boolean
    /**
     * When true, the framed card drops padding on BOTH the root `.card` (HeroUI
     * bakes `p-4` there) and `CardContent`, so an EDGE-OWNING child (Accordion /
     * Table / full-bleed divider list) sits flush to the card edges — avoids the
     * inset-divider look. Ignored when `frameless`.
     */
    flushContent?: boolean
    /**
     * When true, the section + framed card stretch to fill their container's height
     * (`h-full` + the card grows via `flex-1`). Use for side-by-side cards in a grid
     * row so uneven content (e.g. a 1-line vs 2-line empty state) still renders at
     * equal height. Ignored when `frameless`.
     */
    fillHeight?: boolean
    /**
     * Renders the label as a SUBTLE eyebrow (`text-xs text-muted`) with a tighter
     * `gap-2` to the content, instead of the default section `Label` + `gap-3`. For
     * a minor/secondary header over a block — e.g. a time-bucket "Today" over a run
     * list — where a full section label reads too heavy (teacher 2026-07-13: "if a card
     * needs a secondary label, use label-gap-2"). `labelEnd` shrinks to `text-xs` to match.
     */
    subtleLabel?: boolean
    /**
     * When true, adds `border border-default` on top of the default
     * `shadow-surface` — for shells that need to stand out as a distinct
     * bounded surface even against a `bg-surface` sibling (e.g. FlipCard's
     * question/answer pair). Default false preserves the elevation-only
     * convention for every other LabeledCard consumer.
     */
    bordered?: boolean
    /**
     * Caller identity to wear on this block's root `<section>` instead of its own — pass this
     * when a `block`/`layout`/`overlay`/`page` component (BLOCK-2: never draws a shape of its
     * own) is using this card AS its root element, instead of wrapping it in a raw `<div
     * data-tier=… data-component=…>`. See `_identity.ts`. Omitted → this section keeps emitting
     * no `data-tier`/`data-component` at all, unchanged (this block has no identity of its own).
     */
    identity?: CallerIdentity
}

/**
 * The StarCi section card (UI 2.0): the title is a `Label` that sits OUTSIDE,
 * above the card, while the `Card` holds only content — `<Label/>` then
 * `<Card>…</Card>`. Optionally shows a right-aligned "see more →" link (the caret
 * slides right on hover). Replaces the legacy in-card header (SectionCard); owns
 * the whole look so features just pass label / see-more / children.
 *
 * @param props - {@link LabeledCardProps}
 * @see Story: .storybook/stories/blocks/cards/LabeledCard/LabeledCard.stories
 */
export const LabeledCard = ({
    label,
    labelEnd,
    onSeeMore,
    seeMoreLabel = "See more",
    action: Action,
    children,
    description: Description,
    className,
    contentClassName,
    frameless = false,
    flushContent = false,
    fillHeight = false,
    subtleLabel = false,
    bordered = false,
    identity,
}: LabeledCardProps) => {
    // Right slot of the label row — action wins over onSeeMore, which wins over labelEnd.
    const endSlot = Action ? <Action /> : (onSeeMore ? (
        <SeeMoreLink onPress={onSeeMore} size={subtleLabel ? "xs" : "sm"}>
            {seeMoreLabel}
        </SeeMoreLink>
    ) : labelEnd != null ? (
        <Typography size={subtleLabel ? "xs" : "sm"} color="muted" classNames={["shrink-0"]} text={labelEnd} />
    ) : null)
    // Non-subtle label goes through the atom instead of HeroUI `Label`: `Label` renders
    // exactly 14px/500/lh-20 = `size="sm" weight="medium"` (documented equivalence, see
    // `composites/cards/SurfaceCard/surface-card-header.tsx`), so the shape is unchanged.
    const labelSlot = subtleLabel ? (
        <Typography size="xs" color="muted" truncate classNames={["min-w-0"]} text={label} />
    ) : (
        <Typography size="sm" weight="medium" classNames={["min-w-0"]} text={label} />
    )
    // card body: frameless = content is itself card(s) → no inner Card (avoid nesting)
    const body = frameless ? (
        <Box className={contentClassName}>{children}</Box>
    ) : (
        <Card
            className={cn(
                bordered && "border border-default",
                fillHeight && "flex-1",
                // root `.card` bakes p-4 — zero it here or flush children stay inset
                flushContent && "gap-0 overflow-hidden p-0",
            )}
        >
            <CardContent className={cn(flushContent && "p-0", fillHeight && "h-full", contentClassName)}>
                {children}
            </CardContent>
        </Card>
    )
    return (
        <section
            {...resolveIdentity(identity)}
            data-principle={subtleLabel ? "sublabel-field" : "label-field"}
            className={cn("flex flex-col", subtleLabel ? "gap-2" : "gap-3", fillHeight && "h-full", className)}
        >
            <StackH gap={4} principle="content-row" justify="between" items={[() => labelSlot, () => endSlot]}
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            />
            {/* description sits OUTSIDE (below) the card, gap-2 — never surface-in-surface */}
            {Description ? (
                <StackV gap={3} items={[() => body, () => <Description />]} />
            ) : body}
        </section>
    )
}

"use client"

import React, { type ComponentType } from "react"
import {
    cn,
} from "@heroui/react"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"
import { StackH } from "@/components/frames/Stack"

/**
 * Props for the {@link PressableCard} block.
 *
 * TIER NOTE: this folder sits under `blocks/cards`, but the component itself
 * owns no domain entity — every prop here is a shape (`children`, `onPress`,
 * `href`, `actions`) never a field of something fetched. That is BLOCK-7's
 * detection signal: it is really a **composite** mis-filed in a block folder.
 * Left in place (moving the folder breaks every importer below), but treated
 * as a composite for this pass — one file, `cn()` allowed (COMPOSITE-5), and
 * `className` kept as a raw string rather than `classNames: Array<AllowedClassName>`
 * because three real callers outside this folder (`GroupPressableCard`,
 * `SummaryCard`, `ConsultantCard`) already forward arbitrary skin classes
 * (radius/border/hover overrides) through it — narrowing the type here would
 * break them without touching a single one of their files.
 *
 * `composites/cards/SurfaceCard` (`SurfaceCard`, exported off `Base`) is the
 * emerging canonical member for this exact job — same whole-card press target,
 * same stretched-link `actions` pattern, plus ripple/selection/verdict-band —
 * and its own header explicitly notes it folds in "was `PressableCard`". It is
 * NOT swapped in here: its hover/ripple treatment differs from this file's
 * (tint-on-hover, no ripple), so delegating to it would change the rendered
 * look for the three live callers above, not just the code shape. Consolidating
 * onto `SurfaceCard` is a separate migration (each caller needs the `children`
 * → `body` slot conversion too), left as debt rather than folded in silently.
 */
export interface PressableCardProps extends WithClassNames<undefined> {
    /** Card body — composed freely by the caller (icon tiles, text, chips…). */
    children: React.ReactNode
    /**
     * Press handler for an action card (select / toggle). Ignored when
     * {@link PressableCardProps.href} is set. One of `onPress` / `href` should
     * be provided for the card to be interactive.
     */
    onPress?: () => void
    /** Navigation target — renders the card as an anchor when provided. */
    href?: string
    /** Disables interaction and dims the card (action cards only). */
    isDisabled?: boolean
    /**
     * Secondary interactive controls (buttons / menus) that live INSIDE the card
     * but act INDEPENDENTLY of the whole-card press — e.g. a "Continue" button +
     * an overflow menu on a course-progress card.
     *
     * Providing this switches the card to the accessible **stretched-link**
     * pattern (Inclusive Components / Adrian Roselli): the whole-card target
     * becomes a TRANSPARENT overlay that covers the card, and these actions sit
     * ABOVE it (later in source order + `z-10`) so each stays separately
     * clickable. This is the correct alternative to illegally nesting a
     * `<button>` inside the card's own `<button>`/`<a>` — which is invalid HTML,
     * breaks the keyboard/AT focus order, AND is what made the card grow tall
     * (a block button laying its interactive children out on their own lines).
     *
     * REQUIRES {@link PressableCardProps.label} — the overlay target no longer
     * wraps the children text, so it needs its own accessible name.
     */
    actions?: ComponentType
    /**
     * Accessible name for the whole-card press target. REQUIRED when
     * {@link PressableCardProps.actions} is set (the stretched overlay covers the
     * card but has no visible text of its own, so it must carry an `aria-label`).
     * Optional otherwise — without `actions` the children ARE the card's
     * accessible name, so pass this only when they carry no readable text (an
     * icon-only tile). Keep it descriptive of the destination/action ("Open the
     * Fullstack Mastery track"), never generic ("click here").
     */
    label?: string
}

/**
 * A whole-card press target with the default surface card look (surface fill,
 * concentric `rounded-3xl`, fixed `px-4 py-3` padding, `shadow-surface`
 * elevation AT REST — per `card.md` §0, a top-level bounded card, so it must
 * read as a card even before hover) plus a hover affordance and keyboard
 * focus ring. Exists because HeroUI v3 `Card` is a
 * non-interactive `<div>` — this component owns the card styling on a real
 * `<button>` / `<a>` so features can compose a clickable card without
 * hand-rolling styles (per the no-style-in-features rule). Use for navigation
 * tiles, selectable option cards, and bookmark rows.
 *
 * When the card also needs its OWN buttons (a "Continue" CTA, an overflow menu),
 * pass them via {@link PressableCardProps.actions} + {@link PressableCardProps.label}:
 * the card renders as the accessible stretched-link pattern (a transparent
 * whole-card overlay UNDER the actions) instead of nesting interactive elements
 * — see the `actions` prop docs.
 *
 * @param props - {@link PressableCardProps}
 * @see Story: .storybook/stories/blocks/cards/PressableCard/PressableCard.stories
 */
export const PressableCard = ({
    children,
    onPress,
    href,
    isDisabled = false,
    actions: Actions,
    label,
    className,
}: PressableCardProps) => {
    // Shared card surface + disabled dim, identical across both render paths so
    // a card reads the same with or without actions. `shadow-surface` is a
    // top-level bounded card (card.md §0 elevation convention) — it must read as
    // one at rest, not only once the pointer arrives (teacher: "render it as a card").
    // One hover treatment only (tint) — no lift variant, no press-scale.
    const surface = cn(
        "rounded-3xl bg-surface px-4 py-3 text-left shadow-surface transition-colors hover:bg-surface-secondary",
        isDisabled && "cursor-not-allowed opacity-60",
        className,
    )

    // ── Simple whole-card target (no secondary actions) — the common case;
    // the whole card is ONE <button>/<a> and its children are its label. ──────
    if (!Actions) {
        const base = cn(
            "block w-full outline-none focus-visible:ring-2 focus-visible:ring-accent",
            surface,
        )
        if (href && !isDisabled) {
            return (
                <a href={href} aria-label={label} className={base} data-tier="composite" data-component="PressableCard">
                    {children}
                </a>
            )
        }
        return (
            <button
                type="button"
                onClick={onPress}
                disabled={isDisabled}
                aria-label={label}
                className={cn(base, !isDisabled && "cursor-pointer")}
                data-tier="composite"
                data-component="PressableCard"
            >
                {children}
            </button>
        )
    }

    // ── Card WITH its own buttons — stretched-link pattern. The card is a plain
    // relative <div>; a transparent overlay <a>/<button> covers it (whole-card
    // press), and the actions sit ABOVE the overlay so they stay clickable. No
    // interactive element is ever nested inside another. Row built with `StackH`
    // (frame tier) instead of a hand-rolled `flex items-center gap-3` wrapper —
    // same shape as `composites/cards/SurfaceCard`'s own actions branch. ───────
    const overlay = cn(
        // covers the whole card; the focus ring reads as a card-level ring since
        // the overlay's border-box IS the card's bounds
        "absolute inset-0 rounded-3xl outline-none focus-visible:ring-2 focus-visible:ring-accent",
        isDisabled ? "cursor-not-allowed" : "cursor-pointer",
    )
    return (
        <div className={cn("relative w-full", surface)} data-tier="composite" data-component="PressableCard">
            <StackH
                gap={4}
                items={[
                    () => <div className="min-w-0 flex-1">{children}</div>,
                    () => (
                        <div className="relative z-10">
                            <StackH gap={3} principle="flex-action" explain="Groups action controls on one horizontal peer row so they share a single hit baseline." classNames={["shrink-0"]} items={[() => <Actions />]} />
                        </div>
                    ),
                ]}
            />
            {href && !isDisabled ? (
                <a href={href} aria-label={label} className={overlay} />
            ) : (
                <button
                    type="button"
                    onClick={onPress}
                    disabled={isDisabled}
                    aria-label={label}
                    className={overlay}
                />
            )}
        </div>
    )
}

import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { Popover } from "@heroui/react"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { Chip } from "@/components/atoms/chips/Chip"
import { Cluster } from "@/components/frames/Cluster"
import { StackV } from "@/components/frames/Stack"
import { KeyValueList } from "@/components/composites/data/KeyValue"
import { Typography } from "@/components/atoms/text/Typography"

/**
 * DESIGN — a single course/product price: the amount to pay (bold), the struck
 * list price, a `−X%` success chip, and a breakdown popover.
 *
 * ANATOMY IS PER-LEAF: each story below is its OWN leaf and wraps its render in
 * its OWN BlockAnatomy (Diagram + Tree) reflecting the parts THAT leaf composes —
 * there is no separate consolidated "Anatomy" story. The composition shifts with
 * the shape: no-discount shows only the amount; on-sale adds the struck price,
 * chip, popover, and saving line; `showSavingLine={false}` drops that last line.
 */

/** Currency a price is shown in. */
export type PriceCurrency = "VND" | "USD"

/**
 * How loud the price is on its surface — decides the amount's font size. INTERNAL,
 * and deliberately NOT named `role`: that word is a DOM/ARIA attribute, so a prop by
 * that name reads as an accessibility role to both a reader and to eslint-jsx-a11y
 * (which flagged `role="prominent"` as an invalid ARIA role three times).
 * not exposed as a prop (§14d.1): the caller picks a MEMBER (`PriceTagInline` /
 * `PriceTagProminent`), not a size.
 */
export type PriceEmphasis = "inline" | "prominent"

/** Breakdown rows for the breakdown popover (amounts in the SAME currency as the price). */
export interface PriceBreakdown {
    /** Active-phase price BEFORE loyalty (the middle step list → phase → charge). */
    phase: number
    /** Localised phase name (e.g. "Early-bird") shown on the phase row. */
    phaseLabel?: string
    /** Loyalty discount percent (0 = no loyalty row). */
    loyaltyPercent: number
    /** Localised loyalty note (e.g. "already owns 2 courses") appended to the loyalty row. */
    loyaltyNote?: string
}

/** Every word the breakdown popover says — resolved by the connected {@link PriceTag}. */
export interface PriceTagLabels {
    /** Popover heading, and its accessible name. */
    breakdownTitle: string
    /** Row label for the pre-discount price. */
    listPrice: string
    /** Row label for the phase discount (already folded with the phase name when there is one). */
    phaseRow: string
    /** Row label for the loyalty discount (already folded with the loyalty note when there is one). */
    loyaltyRow: string
    /** Row label for the total the buyer actually pays. */
    youPay: string
}

/** Props for the {@link PriceTag} block. */
export interface PriceTagProps {
    /** Breakdown-popover copy, already localized. A story passes i18n keys. */
    labels: PriceTagLabels
    /** The price the user actually pays. */
    discounted: number
    /** The pre-discount (list/MSRP) price; struck through when greater than discounted. */
    original?: number | null
    /** Currency to format in. Defaults to "VND". */
    currency?: PriceCurrency
    /**
     * `true` → the price is in its RESTING state: the amount, the struck-through
     * original price, the `−X%` chip, and the saving line all turn to shimmer,
     * KEEPING the same line boxes so nothing jumps in layout (§8).
     *
     * The flag FLOWS DOWN into the atoms that render each part (`Typography`,
     * `Chip`), instead of building a second shimmer tree (§12c). The popover
     * is TURNED OFF while resting — there is no data to open yet, and a pressable
     * control while loading is a false promise.
     */
    isSkeleton?: boolean
    /**
     * Optional phase-tier + loyalty rows for the breakdown {@link Popover}. Whenever
     * there IS a saving the `−X%` chip is ALWAYS a button that opens the popover (at
     * minimum list price → "you pay"); `breakdown` just adds the middle steps that
     * explain WHERE the drop came from. Click/tap (not hover) so it works on touch too.
     */
    breakdown?: PriceBreakdown
    /**
     * Show the concrete "save N₫" line under the price (the real VND saved, not just
     * the percent). Defaults to `true`; set `false` where space is tight (dense cards).
     */
    showSavingLine?: boolean
    /** Where the root sits inside its parent. */
    classNames?: Array<AllowedClassName>
}

/**
 * Role → amount font size.
 */
const AMOUNT_TYPE: Record<PriceEmphasis, "base" | "h4"> = {
    inline: "base",
    prominent: "h4",
}

/** Role → struck-through original-price line size, placed next to {@link AMOUNT_TYPE} so the two scales don't drift apart. */
const ORIGINAL_TYPE: Record<PriceEmphasis, "xs" | "sm"> = {
    inline: "xs",
    prominent: "sm",
}

/** Format an amount in the given currency. */
export const formatPrice = (amount: number, currency: PriceCurrency): string =>
    currency === "USD"
        ? amount.toLocaleString("en-US", { style: "currency", currency: "USD" })
        : `${amount.toLocaleString("vi-VN")}₫`

/** Whole-percent saving between a "before" and an "after" amount (0 when none). */
const savingPercent = (before: number, after: number): number =>
    before > after ? Math.round((1 - after / before) * 100) : 0

/**
 * The single source of truth for rendering a course/product price: the discounted
 * amount (bold), the list price struck through (only when there IS a saving), and a
 * `−X%` success chip whose percent is the REAL list → charge gap (phase tier +
 * loyalty). Whenever there is a saving the chip is a clickable button opening a
 * {@link Popover} (at minimum list price → you pay; `breakdown` adds the phase +
 * loyalty steps). Works in VND or USD.
 *
 * @param props - {@link PriceTagProps}
 */
export const PriceTagBase = ({
    discounted,
    original,
    currency = "VND",
    emphasis,
    isSkeleton = false,
    breakdown,
    showSavingLine = true,
    classNames,
    labels,
}: PriceTagProps & { emphasis: PriceEmphasis }) => {
    const hasSaving = original != null && original > discounted
    const savePercent = hasSaving ? savingPercent(original, discounted) : 0

    // the −X% saving chip — composed from the `Chip` atom (tone success →
    // soft-success chip, matching src's raw `<Chip variant="soft" color="success">`).
    // The pressable/focusable button role lives on the canonical `Popover.Trigger`
    // wrapper (react-aria: role=button, aria-expanded/controls, tabindex), so there is
    // exactly ONE interactive element. No caret; the whole chip is the affordance.
    const chip =
        savePercent > 0 ? (
            <Chip
                tone="success"
                text={`−${savePercent}%`}
            />
        ) : null

    // phase saving = list → phase ; loyalty saving = phase → charge
    const phaseSave = original != null ? savingPercent(original, breakdown?.phase ?? discounted) : 0
    // Popover content — shown for EVERY saving (so the chip is always clickable), at
    // minimum list price → you pay. The phase-tier & loyalty rows only appear when a
    // full `breakdown` is supplied.
    const breakdownContent = hasSaving ? (
        // Those four rows are all ONE shape: label left ↔ value right, repeated ⇒
        // exactly `KeyValueList` (a repeated list ⇒ `items` is DATA). The "you
        // pay" row is the TOTAL row ⇒ `emphasis`, not a hand-drawn rule: the frame
        // already knows how to emphasise a total row, and that emphasis looks the same
        // across every price table in the system.
        //
        // ⚠️ The frame does NOT format for you: every money string coming in here
        // has already gone through `formatPrice`.
        // ⚠️ This column is NOT badged: the panel groups nodes BY NAME (`firstEl` keeps
        // only the first element of each name), so two `StackV`s with the same name
        // would MERGE into one node and the tree would read wrong. The node that
        // matters inside the popover is `KeyValueList` — that one is badged; the
        // wrapping column is just `p-3` padding.
        // Two vertical rows inside a design (the eyebrow and the breakdown list) =
        // `grouped`, not `tight`. `tight` (1) is reserved for what sits INSIDE a
        // composite, e.g. the icon+label pair of `InlineIconLabel`.
        <StackV gap={4} principle="cell-pad"
            explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body."
            padding={4} isSkeleton={isSkeleton} body={() => (
                <StackV gap={4} principle="label-field"
                    explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                    isSkeleton={isSkeleton} items={[
                        ({ isSkeleton }: SkeletonProps) => <Typography size="xs" color="muted" text={labels.breakdownTitle} isSkeleton={isSkeleton} />,
                        // No `gap` passed: `KeyValueList` already owns its row rhythm (its own default
                        // is the §10b `grouped` step). Passing one from here overrides the composite's
                        // spacing from OUTSIDE, which §10 forbids — a composite owns its internal
                        // spacing and must not receive it.
                        ({ isSkeleton }: SkeletonProps) => (
                            <KeyValueList
                                isSkeleton={isSkeleton}
                                items={[
                                    {
                                        key: "list",
                                        label: labels.listPrice,
                                        value: formatPrice(original ?? discounted, currency),
                                    },
                                    ...(breakdown && original != null && original > breakdown.phase
                                        ? [{
                                            key: "phase",
                                            label: labels.phaseRow,
                                            // NOTE: `KeyValueListItem.value` is now a plain `string` — this row
                                            // loses the `color="success-soft"` (green) tint it used to carry via
                                            // its own `Typography`. `KeyValueRow` only renders `value` through the
                                            // emphasis/plain split, no per-row tone prop. Preserving the green
                                            // accent needs either accepting the loss (done here) or a future
                                            // `tone`/`accent` field on `KeyValueListItem` — left for whoever owns
                                            // PriceTag/KeyValue next, not decided in this pass.
                                            value: `−${formatPrice(original - breakdown.phase, currency)} (−${phaseSave}%)`,
                                        }]
                                        : []),
                                    ...(breakdown && breakdown.loyaltyPercent > 0 && breakdown.phase > discounted
                                        ? [{
                                            key: "loyalty",
                                            label: labels.loyaltyRow,
                                            // See the "phase" row's note above — same loss of the green tint,
                                            // same reason.
                                            value: `−${formatPrice(breakdown.phase - discounted, currency)} (−${breakdown.loyaltyPercent}%)`,
                                        }]
                                        : []),
                                    {
                                        key: "total",
                                        label: labels.youPay,
                                        value: formatPrice(discounted, currency),
                                        // the TOTAL row: the frame handles the emphasis, replacing a hand-typed `border-t … pt-1`
                                        emphasis: true,
                                    },
                                ]}
                            />
                        ),
                    ]} />
            )} />
    ) : null

    // The price row aligns on BASELINE (big number, struck number, chip share the
    // same text baseline) and wraps on its own when tight ⇒ exactly `Cluster`.
    // The three elements are THREE separate items, not merged into one
    // fragment — merging them leaves the frame's `gap` with nowhere to apply.
    const priceRow = (
        <Cluster
            gap={3}
            principle="value-row"
            explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
            align="baseline"

            items={[
                // The amount goes through the ATOM `Typography` (§9c), NOT raw
                // HeroUI — thanks to that, `isSkeleton` flows straight into it instead
                // of branching off to build a separate shimmer bar.
                () => (
                    <Typography
                        size={AMOUNT_TYPE[emphasis]}
                        weight="bold"
                        isSkeleton={isSkeleton}
                        classNames={isSkeleton ? ["w-2/3"] : undefined}

                        text={formatPrice(discounted, currency)}
                    />
                ),
                ...(hasSaving
                    ? [() => (
                        <Typography
                            size={ORIGINAL_TYPE[emphasis]}
                            color="muted"
                            isSkeleton={isSkeleton}
                            isStruck
                            classNames={isSkeleton ? ["w-1/3"] : undefined}

                            text={formatPrice(original, currency)}
                        />
                    )]
                    : []),
                // While resting: the chip still holds its place but is NOT wrapped in a
                // Popover — there's no data yet to open, and a pressable control while
                // loading is a false promise.
                ...(isSkeleton
                    ? [() => <Chip isSkeleton />]
                    : savePercent > 0
                        ? [() => (
                            <Popover>
                                <Popover.Trigger
                                    aria-label={labels.breakdownTitle}
                                    className="cursor-pointer focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"

                                >
                                    {chip}
                                </Popover.Trigger>
                                <Popover.Content
                                    className="max-w-xs"

                                >
                                    {breakdownContent}
                                </Popover.Content>
                            </Popover>
                        )]
                        : []),
            ]}
        />
    )

    const savingLine = showSavingLine && (isSkeleton || hasSaving) ? (
        <Typography
            size="xs"
            color="muted"
            isSkeleton={isSkeleton}
            classNames={isSkeleton ? ["w-1/2"] : undefined}

            text={hasSaving ? `Save ${formatPrice(original - discounted, currency)}` : undefined}
        />
    ) : null

    return (
        // The outer column = two DIFFERENT lines (the price row · the "saving" line) ⇒
        // `StackV`, NOT `Cluster`: a cluster is ONE track of N PEER elements (§13b).
        <StackV
            // `grouped` (§10b): the price row and the saving line are two DIFFERENT vertical
            // rows of one design. It was `tight` (1), which §10b reserves for pairs sitting
            // inside a lower-tier component — the saving line read as if it were glued under the number.
            gap={4}
            classNames={classNames}
            isSkeleton={isSkeleton}
            items={[
                () => priceRow,
                () => savingLine,
            ]}
        />
    )
}

import { InputText } from "@/components/atoms/forms"
import React from "react"
import { GearSixIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"

import { Typography } from "@/components/atoms/text/Typography"
import { EnumChip, type EnumChipEntry } from "@/components/composites/chips/EnumChip"
import { SurfaceCardAccordion, markIcon, type ListMark, type MarkTone, type SurfaceCardAccordionItem } from "@/components/composites/cards/SurfaceCard"
import { Callout, type CalloutStatus } from "@/components/composites/feedback/Callout"
import { Disclosure } from "@/components/composites/layout/Disclosure"
import { MarkdownContent } from "@/components/composites/viewers/MarkdownContent"
import { ScoreValue } from "@/components/composites/text/ScoreValue"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `ChallengeDeliverableList` — the "Submit assignment" card: one
 * `SurfaceCard.Accordion` row per challenge requirement, its trigger a live
 * status, its panel the submission form plus, once graded, the verdict and its
 * reasons. `graded` toggles a state inside the same leaf. How many requirements,
 * which are graded, and whether a submission is mid-flight are all data.
 */

/** Where one requirement stands. */
export type ChallengeDeliverableStatus = "todo" | "done" | "failed"

/** How the last graded attempt on a requirement came out. */
export type ChallengeDeliverableVerdict = "pass" | "fail"

/**
 * The last graded attempt's result for one requirement.
 *
 * NO ITEMIZED FINDINGS HERE — only `shortFeedback`. An attempt can carry up to
 * EIGHT findings × 3 text fields, so rendering them here would bury the
 * submission form under two dozen lines. The itemized list belongs to the
 * dedicated result surface (`src`'s `SubmissionResult`, reachable from the
 * "View History" action right above); this panel keeps only the one-line
 * summary.
 */
export interface ChallengeDeliverableGrade {
    /** Pass/fail for this requirement's last attempt. */
    verdict: ChallengeDeliverableVerdict
    /** Score actually earned. */
    earnedScore: number
    /** Score needed to pass. */
    requiredScore: number
    /**
     * Which numbered attempt this grade came from (1-based) — the learner may
     * have submitted more than once. GROUND TRUTH: backend
     * `UserChallengeSubmissionAttemptEntity.attemptNumber`.
     */
    attemptNumber?: number
    /**
     * When this attempt was graded, PRE-FORMATTED for display — this block
     * does not own date/locale formatting, the caller does (§14d.1, same
     * boundary as every other display string in this file). GROUND TRUTH:
     * `UserChallengeSubmissionAttemptEntity.processedAt`.
     */
    processedAt?: string
    /**
     * One-line take on the WHOLE attempt — the ONLY feedback this panel shows
     * (see the type doc above on why the itemized findings live elsewhere).
     * GROUND TRUTH: backend `UserChallengeSubmissionAttemptEntity.shortFeedback`.
     * In practice this column is filled on every attempt, but it stays optional
     * in the type: a grading run that failed mid-way could leave it empty, and
     * the panel must not break.
     */
    shortFeedback?: string
}

/**
 * Where this row's GRADING JOB stands. Grading runs in the BACKGROUND (the submit
 * mutation returns a `jobId`, the screen subscribes to a socket), so a row must be
 * able to say "queued / grading / done / failed" while nothing else about it
 * changed yet.
 *
 * GROUND TRUTH: backend `JobStatus` (`src/modules/types/enums/job-status.ts`) —
 * all four members, spelled the same. Omit the prop when no job is in flight.
 */
export type ChallengeDeliverableJobStatus = "queued" | "processing" | "completed" | "failed"

/** One challenge requirement and its submission form. */
export interface ChallengeDeliverableItem {
    /** Stable id — also the accordion's expand key. */
    id: string
    /** Requirement title. */
    title: string
    /** Max score this requirement is worth. */
    points: number
    /** Where this requirement stands right now. */
    status: ChallengeDeliverableStatus
    /** What the requirement is asking for, as markdown. */
    description?: string
    /** The submission URL as typed so far. */
    url: string
    /** Validation message for the URL field. Set → the field shows invalid. */
    urlError?: string
    /** Fired as the learner types the submission URL. */
    onUrlChange: (value: string) => void
    /** Fired to submit this requirement's URL for grading. */
    onSubmit: () => void
    /** `true` → this requirement's grading job is in flight. */
    isPending?: boolean
    /**
     * Where this row's background grading job stands — drives the status callout
     * between the URL field and the action row. Omit when no job is running.
     */
    jobStatus?: ChallengeDeliverableJobStatus
    /**
     * Raw server error for a `failed` job, shown as a third line under the
     * callout's description. GROUND TRUTH: `activeJobError` in `src`'s
     * `ChallengeSubmissionPanel` is a plain UNTRANSLATED string straight off
     * `jobStatusByJobId[id].data.error` — so the block prints it as-is and never
     * pretends to localise it. Ignored unless `jobStatus` is `"failed"`.
     */
    jobError?: string
    /** Fired to open this requirement's attempt history. */
    onViewHistory: () => void
    /** The last graded attempt. Present → the panel shows the verdict + feedback. */
    graded?: ChallengeDeliverableGrade
}

/**
 * Where the URL autosave stands — a PANEL-WIDE fact, not a per-row one.
 *
 * GROUND TRUTH: `src`'s `ChallengeSubmissionPanel` (`AutosaveStatus` in
 * `hooks/rhf/useEditSubmissionForm.ts`) debounces every row's URL into ONE batch
 * sync, so one status covers the whole panel and the line renders ABOVE the
 * accordion, not inside a row. `"idle"` is deliberately NOT a member here: the
 * real panel renders nothing at all in that case, so "no line" is expressed by
 * omitting the prop rather than by a member that means "draw nothing".
 */
export type ChallengeDeliverableAutosaveStatus = "saving" | "saved" | "failed"

/** Props for {@link ChallengeDeliverableList}. */
export interface ChallengeDeliverableListProps {
    /** The challenge's requirements, in display order. */
    items: Array<ChallengeDeliverableItem>
    /**
     * Autosave state of the URL fields, shown as one quiet line above the list.
     * Omit while idle — see {@link ChallengeDeliverableAutosaveStatus}.
     */
    autosaveStatus?: ChallengeDeliverableAutosaveStatus
    /**
     * Fired when the learner opens the grading-lane settings from the card
     * header. Chrome trigger only this pass — see the file header's scope cut.
     */
    onOpenGradingSettings: () => void
    /** `true` → the card draws its own mirror while the requirements load. */
    isSkeleton?: boolean
}

/**
 * Status → the SAME icon-per-status mapping `SurfaceCard.CrossList` already owns:
 * a "not decided yet / passed / failed" row is the same shape as that composite's
 * check/cross mark, missing only the neutral pending case — extended there
 * (`ListMark`/`MarkTone` gained `"pending"`/`"neutral"`) rather than hand-rolled a
 * second time here. `failed` passes `tone="danger"` explicitly because `markIcon`'s
 * own default for `cross` is `"muted"` (an EXCLUDED row, not a FAILED one) — this
 * block's `cross` always means failed.
 */
const STATUS_MARK: Record<ChallengeDeliverableStatus, ListMark> = {
    todo: "pending",
    done: "check",
    failed: "cross",
}
const STATUS_TONE: Record<ChallengeDeliverableStatus, MarkTone | undefined> = {
    todo: undefined,
    done: undefined,
    failed: "danger",
}

/**
 * Verdict wording — the block's own (a caller passes `"pass" | "fail"`, never a string).
 *
 * `fail` gets a leading icon (`EnumChipIcon`'s closed "check"/"cross" set, not a raw
 * component — same as `ChallengeHeader.STATUS_MAP.failed`). `pass` stays text-only.
 */
const VERDICT_MAP: Partial<Record<ChallengeDeliverableVerdict, EnumChipEntry>> = {
    pass: { color: "success", label: "Passed" },
    fail: { color: "danger", label: "Not yet passed", icon: "cross" },
}

/**
 * Job status → content of the grading-status strip (`Callout`).
 *
 * Wording matches the `aiProcessing.submitChallenge.*` set in
 * `src/messages/vi.json` EXACTLY — never recomposed, since this is the exact
 * copy the learner already reads in the real app.
 *
 * `status` follows the same tone `AIProcessingText` uses: both in-flight
 * branches are WARNING (nothing wrong yet, just not done), `completed` is
 * SUCCESS, `failed` is DANGER. `accent` is not used for any branch — accent is
 * the brand's active-state pink, not a status tone (`matrix.md` §11).
 *
 * ⭐ DELIBERATELY DOES NOT port `AIProcessingText`'s rotating conic-gradient
 * border. That is `src`'s own IMPLEMENTATION detail (a `motion.div` gradient
 * spinning over 2.8s), not a shape this system has a slot for — porting it
 * would be exactly Trap 3 of `.claude/fe/boundary.md` (copying behaviour/
 * structure is fine, copying raw values/effects is not). This system's own
 * face for "a note with a tone living inside a face" is `Callout`, and that is
 * what is used here.
 */
const JOB_STATUS_CALLOUT: Record<
    ChallengeDeliverableJobStatus,
    { status: CalloutStatus, title: string, description: string }
> = {
    queued: {
        status: "warning",
        title: "Queued for processing",
        description: "Your submission is in the queue and will be processed shortly.",
    },
    processing: {
        status: "warning",
        title: "StarCI AI is grading your submission",
        description: "StarCI AI is analyzing your submission. Please wait a moment.",
    },
    completed: {
        status: "success",
        title: "Grading complete",
        description: "Your submission has been graded. You can view the result now.",
    },
    failed: {
        status: "danger",
        title: "Grading failed",
        description: "An error occurred while grading. Please try again.",
    },
}

/**
 * Autosave status → one quiet line above the list.
 *
 * Wording matches `autosave.*` in `src/messages/vi.json` exactly. Colour:
 * `failed` is DANGER, the other two are MUTED — `src` uses `text-default-500`
 * for the ordinary branch, i.e. a raw Tailwind class; here it goes through the
 * `Typography` atom's `color` (`muted`) instead of porting the raw class,
 * per Trap 3 of `boundary.md`.
 */
const AUTOSAVE_LABEL: Record<ChallengeDeliverableAutosaveStatus, string> = {
    saving: "Saving…",
    saved: "Saved",
    failed: "Save failed",
}

/**
 * Trailing trigger slot: points before an attempt, earned/required once
 * graded — never both.
 *
 * The graded branch is `default`, not `muted`: a number sitting right on an active
 * `Accordion.Trigger` and carrying real information reads as `default` (same
 * reasoning as `ScoreValue.tsx`).
 *
 * `weight="medium"` is explicit — without it this branch falls back to the atom's
 * default `font-normal`, while `ScoreValue` (the branch below it, AND the same
 * info-type "score" in `ChallengeBrief`'s Requirements) is always `weight="medium"`.
 * Same `size="xs"` but a different weight reads as a different font size — kept in
 * sync so the same info-type shares one typeface treatment.
 */
const scoreEnd = (item: ChallengeDeliverableItem) =>
    item.graded != null ? (
        <Typography
            size="xs"
            weight="medium"
            tabularNums
            text={`${item.graded.earnedScore}/${item.graded.requiredScore}`}

        />
    ) : (
        <ScoreValue points={item.points} />
    )

/**
 * Leading trigger icon: status icon, its OWN colour, independent of the title
 * text — rides `titleStart`, not composed into `title` itself (see file header).
 * Delegates the actual icon+tone to `SurfaceCard`'s `markIcon` (see `STATUS_MARK`).
 */
const triggerIcon = (item: ChallengeDeliverableItem) =>
    markIcon(STATUS_MARK[item.status], STATUS_TONE[item.status])

/** One requirement's panel: description → URL field → actions → the graded result once it exists. */
const deliverableBody = (item: ChallengeDeliverableItem) => {
    // No `justify="end"` — everything else in the panel (description, URL field, verdict
    // chip, "Latest feedback" trigger) hugs the left edge, so this button row hugs it too
    // rather than drifting right and reading like a different block. NOT using `flex-1`:
    // the `src` anchor (`SubmissionRow`: primary `shrink-0` + secondary `min-w-0 flex-1`)
    // makes the SECONDARY button wider than the PRIMARY one — inverted visual weight. Both
    // buttons hug their own text, neither stretches.
    const actions = (
        <>
            <Button
                label="Submit"
                variant="primary"
                onPress={item.onSubmit}
                isDisabled={item.url.trim().length === 0}
                isPending={item.isPending}

            />
            <Button
                label="View History"
                variant="secondary"
                onPress={item.onViewHistory}

            />
        </>
    )

    // Graded is a STATE of this same leaf (mirrors QuizQuestion's `verdict` toggle),
    // never a second component — see file header.
    //
    // Two lines only:
    // · ONE meta row always shows — verdict Chip + "attempt #N · HH:mm dd/MM"
    //   (`attemptNumber`/`processedAt`, real fields).
    // · ONE `Disclosure` "Latest feedback" → opens onto `shortFeedback`, one sentence.
    //
    // Not shown here: the full "scored N/M, minimum required R" sentence (N/M already
    //   sits in the accordion row's own `titleEnd` right above — see `scoreEnd` — and the
    //   chip already answers "passed or not"), and the per-line finding list (one attempt
    //   can carry up to EIGHT findings × 3 fields, which would bury the submission form;
    //   that detail belongs to the dedicated result page, `src`'s `SubmissionResult`,
    //   reached from the "View History" button right above).
    //
    // `Disclosure` here is a PRESENTATION decision, not an invented field: the content
    // inside is still exactly one real field, just placed behind a click because it's
    // secondary detail.
    const graded = item.graded
    const gradedSection = graded != null ? (
        <StackV
            gap={4}
            principle="card-caption"
            explain="Holds caption text under card media so the caption stays attached to the image above it."
            items={[
                /* ONE single meta row — verdict chip + "attempt #N · HH:mm dd/MM" — rather than
                    three stacked layers. No "Your latest attempt scored N/M. Minimum required: R."
                    sentence: the N/M figure already sits in the accordion row's own `titleEnd`
                    right above (see `scoreEnd`), and the chip already answers "passed or not" —
                    that sentence would restate the same fact a second time across both lines.
                    `earnedScore`/`requiredScore` are real fields and render, just in exactly ONE
                    place. */
                () => (
                    <StackH
                        gap={3}
                        principle="identity"
                        explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                        align="center"
                        at="sm"

                        items={[
                            () => <EnumChip value={graded.verdict} map={VERDICT_MAP} />,
                            ...(graded.attemptNumber != null ? [() => (
                                <Typography
                                    size="xs"
                                    color="muted"
                                    text={graded.processedAt != null
                                        ? `attempt #${graded.attemptNumber} · ${graded.processedAt}`
                                        : `attempt #${graded.attemptNumber}`}

                                />
                            )] : []),
                        ]}
                    />
                ),
                ...(graded.shortFeedback != null ? [() => (
                    <Disclosure
                        title="Latest feedback"

                        body={() => (
                            <Typography size="sm" text={graded.shortFeedback} />
                        )}
                    />
                )] : []),
            ]}
        />
    ) : null

    const panel = (
        <>
            {item.description != null ? (
                <MarkdownContent source={item.description} measure="compact" />
            ) : null}

            <InputText
                variant="secondary"
                value={item.url}
                onValueChange={item.onUrlChange}
                errorMessage={item.urlError}
                placeholder="https://github.com/…"
                ariaLabel={`Submission URL — ${item.title}`}
                isDisabled={item.isPending}

            />

            {/* Grading-status strip — BETWEEN the URL field and the button row, the exact spot
                `src`'s `SubmissionRow` places `AIProcessingText` (lines 173-195: after
                `TextField`, before `GradeModelDropdown`). This surfaces the "grading in
                progress" / "grading failed" states; `isPending` alone only locks the input
                and can't say which branch it's in. `jobError` prints RAW (untranslated)
                because `src` also prints it raw: it's a server error string, not a sentence
                meant for a reader. */}
            {item.jobStatus != null ? (
                <Callout
                    status={JOB_STATUS_CALLOUT[item.jobStatus].status}
                    title={JOB_STATUS_CALLOUT[item.jobStatus].title}
                    description={JOB_STATUS_CALLOUT[item.jobStatus].description}
                    body={item.jobStatus === "failed" && item.jobError != null
                        ? () => <Typography size="xs" color="danger" text={item.jobError} />
                        : undefined}


                />
            ) : null}

            <StackH gap={3} items={[() => actions]} />

            {gradedSection}
        </>
    )

    return <StackV gap={4} items={[() => panel]} />
}

/**
 * The "Submit" card. See the file header for the full contract.
 *
 * @param props - {@link ChallengeDeliverableListProps}
 */
const ChallengeDeliverableList = ({
    items,
    autosaveStatus,
    onOpenGradingSettings,
    isSkeleton = false,
}: ChallengeDeliverableListProps) => {
    // The first requirement that has not PASSED opens by default, so a returning
    // learner lands on what they still owe instead of requirement #1 every time.
    const firstOpenId = items.find((item) => item.status !== "done")?.id

    const accordionItems: Array<SurfaceCardAccordionItem> = items.map((item, index) => ({
        id: item.id,
        titleStart: () => triggerIcon(item),
        title: `${index + 1}. ${item.title}`,
        titleEnd: () => scoreEnd(item),
        body: () => deliverableBody(item),
    }))

    // ONE surface, not two: the accordion IS the card's entire content — nothing else
    // sits inside "Submit" beside it — so it draws its own top-level frame directly
    // (`label`/`action` are its own header slots) instead of a `SurfaceCard` wrapping a
    // `variant="nested"` child. Surface-in-surface is only for a part that stays SMALL
    // relative to a parent holding other things too; nesting a border around content
    // that already equals the whole parent just draws the same outline twice.
    // The autosave line sits ABOVE the accordion, the exact spot `src`'s
    // `ChallengeSubmissionPanel` places it (lines 388-398: the panel wrapper's first
    // child, right before `<Accordion>`) — it's a fact of the WHOLE PANEL (one sync pass
    // batching every URL field), so it can't be part of a single row.
    // Does not go through the header's `labelEnd` even though that slot looks like it
    // might fit: `action` (the gear button) WINS over `labelEnd` in
    // `surface-card-header.tsx:90-104`, so the label would never render.
    const listBody = (
        <>
            {autosaveStatus != null ? (
                <Typography
                    size="xs"
                    color={autosaveStatus === "failed" ? "danger" : "muted"}
                    text={AUTOSAVE_LABEL[autosaveStatus]}

                />
            ) : null}
            <SurfaceCardAccordion
                label="Submit"
                action={() => (
                    <Button
                        isIconOnly
                        prefixIcon={GearSixIcon}
                        ariaLabel="Grading settings"
                        variant="tertiary"
                        size="sm"
                        onPress={onOpenGradingSettings}
                        isSkeleton={isSkeleton}

                    />
                )}
                items={accordionItems}
                defaultExpandedKeys={firstOpenId != null ? new Set([firstOpenId]) : undefined}
                isSkeleton={isSkeleton}


            />
        </>
    )

    return (
        <StackV gap={3} isSkeleton={isSkeleton} items={[() => listBody]} />
    )
}

export { ChallengeDeliverableList }

import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { CaretLeftIcon, CaretRightIcon } from "@phosphor-icons/react"
import { Typography } from "@/components/atoms/text/Typography"
import { SurfaceCardPressableGroup, type SurfaceCardPressableGroupItem } from "@/components/composites/cards/SurfaceCard"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `ContentPager` — step to the neighbouring lesson at the foot of the reading
 * screen. It owns the "previous lesson" / "next lesson" labels and the lesson
 * title + link on each card. The right card mirrors the left so the pair reads
 * as a direction, pinning to a second column only where the grid has two (a
 * container query). Losing either card, and `isSkeleton`, are each their own
 * leaf; having no neighbour renders nothing.
 */

/** One neighbouring lesson — plain data, the block builds the card from it. */
export interface ContentPagerNeighbour {
    /** Lesson title, shown under the direction label and clamped to two lines. */
    title: string
    /** Where the card navigates. */
    href: string
}

/** Props for {@link ContentPager}. */
export interface ContentPagerProps {
    /** The lesson before this one. Omitted → the left card is not drawn. */
    previous?: ContentPagerNeighbour
    /** The lesson after this one. Omitted → the right card is not drawn. */
    next?: ContentPagerNeighbour
    /**
     * Accessible name for the pair, localized by the caller (blocks carry no
     * i18n). Without it a screen reader hears two loose links with nothing tying
     * them together.
     */
    ariaLabel: string
    /**
     * `true` → the group draws its own mirror. The flag FLOWS DOWN into
     * `SurfaceCardPressableGroup`, which owns the card box and the grid, so the
     * shimmer keeps the exact shape the real cards will take (§12c).
     */
    isSkeleton?: boolean
}

/**
 * Previous/next lesson pager. See the file header for the full contract.
 *
 * @param props - {@link ContentPagerProps}
 */
const ContentPager = ({
    previous,
    next,
    ariaLabel,
    isSkeleton = false,
}: ContentPagerProps) => {
    // Nothing to step to in either direction ⇒ draw nothing at all. Reached on the
    // first and last lesson of a course, which are ordinary, not exceptional.
    if (!isSkeleton && !previous && !next) {
        return null
    }

    const items: Array<SurfaceCardPressableGroupItem> = []
    if (previous) {
        const previousLabel = (
            <>
                <Typography size="xs" color="muted" text="Previous content" />
                <Typography size="sm" weight="medium" lineClamp={2} underlineOnGroupHover text={previous.title} />
            </>
        )
        const previousCard = (
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="center"
                isSkeleton={isSkeleton}
                items={[
                    // DIV position: this card is a control with its own FIXED padding
                    // (`SurfaceCardPressableGroup` tile, `cozy` inset) — not hug-content —
                    // so size tracks line-height, not font-size. Title is `text-sm` ⇒ `size-5`,
                    // matching the sibling `ITEM_ICON_CLS` convention this same file's parent
                    // (`SurfaceCard.tsx`) already forces for icons in this exact tile shape.
                    // Weight omitted → Phosphor default `regular`, correct at `size-5`.
                    () => <CaretLeftIcon aria-hidden focusable="false" className="size-5 shrink-0 text-muted" />,
                    ({ isSkeleton }: SkeletonProps) => <StackV gap={1} isSkeleton={isSkeleton} items={[() => previousLabel]} />,
                ]}
            />
        )
        items.push({
            key: "previous",
            href: previous.href,
            content: () => previousCard,
        })
    }
    if (next) {
        const nextLabel = (
            <>
                <Typography size="xs" color="muted" align="end" text="Next content" />
                <Typography size="sm" weight="medium" align="end" lineClamp={2} underlineOnGroupHover text={next.title} />
            </>
        )
        const nextCard = (
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="center"
                justify="end"
                isSkeleton={isSkeleton}
                items={[
                    ({ isSkeleton }: SkeletonProps) => <StackV gap={1} principle="name-handle"
                        explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
                        align="end" isSkeleton={isSkeleton} items={[() => nextLabel]} />,
                    // Same DIV position/size reasoning as the mirrored left caret above.
                    () => <CaretRightIcon aria-hidden focusable="false" className="size-5 shrink-0 text-muted" />,
                ]}
            />
        )
        items.push({
            key: "next",
            href: next.href,
            // `SurfaceCardPressableGroupItem.className` was removed entirely
            // (COMPOSITE-4) and the closed `AllowedClassName` union has no
            // container-conditional column-start member to reproduce "pin the lone
            // pager card to the right column" with. Until that union grows one (or
            // `Grid` grows a start-position prop), `col-span-2` (full-width lone
            // card) is the nearest supported fallback — same as the `PagerFullWidth`
            // leaf in `SurfaceCardPressableGroup.stories.tsx`.
            classNames: ["col-span-2"],
            content: () => nextCard,
        })
    }

    return (
        <div>
            <div>
                <SurfaceCardPressableGroup ariaLabel={ariaLabel} columns={{ base: 1, sm: 2 }} items={items} isSkeleton={isSkeleton} principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title." />
            </div>
        </div>
    )
}

