                            size="base"
                            weight="medium"
                            isSkeleton={isSkeleton}
                            text={title}

                        />
                    ),
                    () => (
                        <Typography
                            size="sm"
                            color="muted"
                            isSkeleton={isSkeleton}
                            text={description}

                        />
                    ),
                    () => (
                        <Button
                            isSkeleton={isSkeleton}
                            variant="primary"
                            size="sm"
                            label={ctaLabel}
                            suffixIcon={ArrowRightIcon}
                            iconSlide
                            onPress={onPress}
                            classNames={["w-fit", "shrink-0"]}

                        />
                    ),
                ]}
            />
        )}
    />
)

