 * a `Container` or wraps it in a `SectionCard` when a framed surface
 * is required.
 *
 * @param props - See {@link PageHeaderProps}.
 */
const Header = ({
    title,
    description,
    breadcrumb: Breadcrumb,
    actions: Actions,
    meta: Meta,
    size = "page",
    isSkeleton = false,
    classNames}: PageHeaderProps) => {
    // ONE render path (§12c) — every part this frame would render anyway stays,
    // each handed `isSkeleton`; the atoms draw their own shimmer. While loading, the
    // real shape (breadcrumb/description/meta presence) isn't known yet, so the
    // composite makes the same shape call the old hand-split branch made: assume a
    // description line and a 2-chip meta row, skip breadcrumb/actions (a route
    // rarely needs those before data lands).
    const showDescription = isSkeleton || description != null
    const showMeta = isSkeleton || Meta != null

    // Left column: stacked title and optional description
    const titleBlock = (
        <>
            {size === "compact" ? (
                <Typography weight="bold" isSkeleton={isSkeleton} text={title} />
            ) : (
                <Typography size="h3" weight="bold" isSkeleton={isSkeleton} text={title} />
            )}
            {showDescription ? (
                // clamp to 2 lines on mobile (keep the header short on a phone); full on sm+
                // — a viewport-width decision, so the wrapper owns it, not the atom.
                <div className={isSkeleton ? undefined : "line-clamp-2 @app-sm:line-clamp-none"}>
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={description}
                    />
                </div>
            ) : null}
        </>
    )
    // Main row: title+description stack on the left, actions pinned to the right
    const titleRow = (
        <StackH
            align="start"
            justify="between"
            gap={4}
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            items={[
                () => <StackV gap={3} classNames={["min-w-0"]} items={[() => titleBlock]} />,
                // Right slot: shrink-0 prevents action buttons from being squeezed.
                // Omitted while loading — the shape of the action row isn't known yet.
                ...(!isSkeleton && Actions ? [() => (
                    <div className="shrink-0"><Actions isSkeleton={isSkeleton} /></div>
                )] : []),
            ]}
        />
    )
    const headerBody = (
        <>
            {/* Breadcrumb row — rendered only when provided and loaded, sits above the main title row */}
            {!isSkeleton && Breadcrumb ? (
                <div><Breadcrumb isSkeleton={isSkeleton} /></div>
            ) : null}
            {titleRow}
            {/* Meta row: stat/meta chips below the title block (gap={4} from outer). While
                loading, 2 `Chip` placeholders stand in — the composite decides the count,
                the atom draws its own pill shimmer (no hand-rolled bar). */}
            {showMeta ? (
                isSkeleton ? (
                    <StackH
                        gap={3}
                        align="stretch"
                        principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        items={[
                            () => <Chip isSkeleton />,
                            () => <Chip isSkeleton />,
                        ]}
                    />
                ) : (
                    <div>{Meta ? <Meta isSkeleton={isSkeleton} /> : null}</div>
                )
            ) : null}
        </>
    )
    return (
        // outer gap={4}: breadcrumb ↔ title-block ↔ meta (different header tiers);
        // title ↔ description stay a related gap={3} pair inside the title block.
        <StackV gap={4} classNames={classNames} items={[() => headerBody]} />
    )
}

// ─────────────────────────────────────────────────────────────────────────────
// .BottomBar — the viewport-pinned action bar (was `StickyBottomBar`)
// ─────────────────────────────────────────────────────────────────────────────

/** Props for {@link PageBottomBar}. */
export interface PageBottomBarProps {
    /**
     * Leading content of the bar — typically a price — as a COMPONENT
     * reference (COMPOSITE-8): the frame calls it itself so it can forward
     * `isSkeleton`.
     */
    body?: ComponentTypeWithSkeleton
    /**
     * Trailing control(s) — the primary CTA — as a COMPONENT reference. When
     * BOTH `body` and `actions` are given the frame lays out the row itself
     * (`justify-between`, `shrink-0` on the actions) so callers stop
     * hand-rolling that flex row.
     */
    actions?: ComponentTypeWithSkeleton
    /** Shorthand for {@link PageBottomBarProps.body} — same component-reference contract. */
    /**
     * `true` → forwarded into whichever of `body`/`actions` renders, so a bar
     * whose price/CTA is not known yet (e.g. still loading enrollment status)
     * can shimmer instead of showing stale content.
     */
    isSkeleton?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * A fixed bottom action bar pinned to the viewport edge — owns the chrome
 * (fixed position, top divider, surface background, safe padding) so features
 * just drop a price + CTA inside. Typically `@app-md:hidden` for a mobile sticky
 * enroll/checkout bar.
 *
 * A bar is a horizontal row, so its named slots are `body` (leading) +
 * `actions` (trailing) rather than the vertical `header`/`body`/`footer` trio.
 * With only one of them the content renders RAW, so a full-width button or a
 * two-button decision row keeps its own sizing (`flex-1`, `w-full`).
 *
 * @param props - {@link PageBottomBarProps}
 */
const BottomBar = ({
    body,
    actions,
    isSkeleton = false,
    classNames}: PageBottomBarProps) => {
    const Main = body
    const Actions = actions
    const chrome = "fixed bottom-0 left-0 right-[var(--app-rail-w,0px)] z-40 border-t border-separator bg-background px-6 py-3"

    // Only ONE side supplied → render it raw: the caller's own width strategy
    // (`w-full` CTA, two `flex-1` buttons) must not be boxed by a shrink-0 wrapper.
    if (Main == null || Actions == null) {
        const Only = Main ?? Actions
        return (
            <div className={cn(chrome, classNames)} data-tier="composite" data-component="PageBottomBar">
                <div>{Only ? <Only isSkeleton={isSkeleton} /> : null}</div>
            </div>
        )
    }

    return (
        <div className={cn(chrome, classNames)} data-tier="composite" data-component="PageBottomBar">
            <StackH
                align="center"
                justify="between"
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => <div className="min-w-0"><Main isSkeleton={isSkeleton} /></div>,
                    () => <div className="shrink-0"><Actions isSkeleton={isSkeleton} /></div>,
                ]}
            />
        </div>
    )
}

/**
 * The page-chrome frame namespace — the frames a ROUTE is built out of, one
 * import, two members:
 *
 * | Member | Content channel |
 * |---|---|
 * | `.Header` | `breadcrumb`/`title`/`description`/`actions`/`meta` (no children) |
 * | `.BottomBar` | `body`/`actions` slots |
 *
 * `.Container` moved to `Container` (`@/components/frames/Container/Container`)
 * on 2026-07-26 — see the history note at the top of this file.
 */
export { Header as PageHeader, BottomBar as PageBottomBar }

/** Folder-matching compound namespace (export-matches-folder). Existing named exports stay public. */
export const Page = {
    Header: Header,
    BottomBar: BottomBar,
} as const

import type { ReactNode } from "react"
import { cn } from "@heroui/react"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { Typography, type TypographySize } from "@/components/atoms/text/Typography"
import { GAP_CLASS, type AllowedGap } from "@/components/frames/_spacing"
import { StackH, StackV } from "@/components/frames/Stack"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"

/**
 * ─────────────────────────────────────────────────────────────────────────────
 * COMPOSITE TIER (§13) — `Section.*`, the frame of a REGION inside a page.
 *
 * A section is the region between a page and a card: a titled band of a route
 * ("My courses", "Recent activity") that owns NO chrome of its own — no
 * surface fill, no border, no radius, no padding. It only stacks a header, a
 * body and an optional footer at ONE rhythm (§10).
 *
 * ⚠️ NOT `SectionCard` (design tier, `blocks/cards/SectionCard`): that one IS a
 * card — HeroUI `Card` chrome (border + radius + padding), an `accent` skin, a
 * `withVerdict` DATA band and its own `isSkeleton` mirror. `SectionCard` is the
 * SURFACE a section's body may sit ON; `Section` is the bare frame AROUND it.
 * Rule of thumb: needs a bounded surface ⇒ `SectionCard`/`SurfaceCard.*`; only
 * needs "title + content in one vertical rhythm" ⇒ `Section.*`.
 *
 * ⚠️ NOT `PageHeader` either: that is the chrome of a whole ROUTE (breadcrumb +
 * H3 title + meta strip), ONE per page. `SectionHeader` is the header of a
 * region INSIDE that page, many per page, and scales down via `level`.
 *
 * KHUNG API LAW (§13b):
 * - `.Base` is a WRAPPER frame → named slots `header`/`body`/`footer` are the
 *   main road, each a COMPONENT reference (COMPOSITE-8) this frame calls
 *   itself so `isSkeleton` can reach inside it.
 * - `.Header` is NOT a generic wrapper → it owns semantic slots
 *   (`eyebrow`/`title`/`description`/`action`) and takes no `children`.
 * - No repeating list here, so no `items` member (§13b list clause N/A).
 * - Namespace only — no bare component export.
 *
 * §10: the vertical rhythm is a TYPED token ({@link AllowedGap}), not a free number —
 * the frame cannot be asked for an off-scale step.
 * §13c: `title`/`description`/`eyebrow` are plain text — the frame wraps them in the
 * `Typography.*` ATOM itself, never a hand-rolled `<p>` (COMPOSITE-8); `action` takes
 * a COMPONENT reference composing a `Button.*` atom from the caller (the frame stays
 * feature-less — it never decides WHAT the action is).
 * ─────────────────────────────────────────────────────────────────────────────
 */

/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "Section" } as const

// ─────────────────────────────────────────────────────────────────────────────
// Shared scale
// ─────────────────────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────────────────────
// .Header — eyebrow · title · description · action
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Heading rank of a section header — picks the `Typography.*` member for every
 * line at once (title + description + eyebrow move together, so a header never
 * mixes scales by hand).
 *
 * `1` = the biggest band of a page · `2` (default) = a normal section ·
 * `3` = a sub-section nested under another header.
 */
export type SectionLevel = 1 | 2 | 3

/** level → the text size each line uses. A DATA table — the call-site never chooses it by hand. */
const TITLE_SIZE: Record<SectionLevel, TypographySize> = { 1: "lg", 2: "base", 3: "sm" }
const DESCRIPTION_SIZE: Record<SectionLevel, TypographySize> = { 1: "sm", 2: "sm", 3: "xs" }
const EYEBROW_SIZE: Record<SectionLevel, TypographySize> = { 1: "sm", 2: "xs", 3: "xs" }
/** §9b: the two top ranks read as headings (bold); the sub-section rank is only emphasized (medium). */
const TITLE_WEIGHT: Record<SectionLevel, "bold" | "medium"> = {
    1: "bold",
    2: "bold",
    3: "medium"}

/** Props for {@link SectionHeader}. */
export interface SectionHeaderProps {
    /** The region's title. The frame wraps it in `Typography` itself (COMPOSITE-8). */
    title: string
    /** Supporting line under the title, muted. Omit when the title says it all. The frame wraps it in `Typography` itself (COMPOSITE-8). */
    description?: string
    /** Muted kicker ABOVE the title — context, not a second title (e.g. a course name). The frame wraps it in `Typography` itself (COMPOSITE-8). */
    eyebrow?: string
    /**
     * Right-aligned control slot — a COMPONENT reference (COMPOSITE-8) the frame
     * calls itself, usually rendering a `Button.*` atom node ("View all",
     * "Manage"). Rendered `shrink-0` so it never squeezes the title column. The
     * frame never decides WHAT the action does (that would be a feature, §13).
     */
    action?: ComponentTypeWithSkeleton
    /** Heading rank → the text scale of every line. Default `2`. */
    level?: SectionLevel
    /**
     * `true` → `title`/`description`/`eyebrow` switch to shimmer, and `action`
     * (if any) is CALLED with `isSkeleton` too (COMPOSITE-8 — `action` is a
     * component reference this frame calls itself, so the flag reaches inside
     * it the same way it reaches the text lines).
     */
    isSkeleton?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * The header of a section: an optional eyebrow + a title + an optional
 * description stacked on the left, an optional action pinned right.
 *
 * Carries no surface of its own — it sits directly on the page background (or
 * inside whatever surface the caller already opened).
 *
 * @param props - {@link SectionHeaderProps}
 */
const Header = ({
    title,
    description,
    eyebrow,
    action: Action,
    level = 2,
    isSkeleton = false,
    classNames}: SectionHeaderProps) => {
    const titleSize = TITLE_SIZE[level]
    const descriptionSize = DESCRIPTION_SIZE[level]
    const eyebrowSize = EYEBROW_SIZE[level]
    // eyebrow ↔ title ↔ description are ONE text unit → tight gap={2} (§10b
    // "inside a lower-tier component"), not the grouped gap={4} used BETWEEN regions.
    const titleBlock = (
        <>
            {eyebrow != null ? (
                <span className="min-w-0">
                    <Typography size={eyebrowSize} text={eyebrow} color="muted" truncate isSkeleton={isSkeleton} />
                </span>
            ) : null}
            <span className="min-w-0">
                <Typography size={titleSize} text={title} weight={TITLE_WEIGHT[level]} isSkeleton={isSkeleton} />
            </span>
            {description != null ? (
                <span className="min-w-0">
                    <Typography size={descriptionSize} text={description} color="muted" isSkeleton={isSkeleton} />
                </span>
            ) : null}
        </>
    )
    return (
        // align="start": a 2-line title block keeps the action anchored at the top.
        <StackH
            align="start"
            justify="between"
            gap={4}
            classNames={classNames}
            isSkeleton={isSkeleton}
            items={[
                () => <StackV gap={2} principle="title-subtitle" classNames={["min-w-0"]} isSkeleton={isSkeleton} items={[() => titleBlock]} />,
                explain="Title over supporting line — not label-field, because neither line is a form control label."
                ...(Action != null ? [() => (
                    <div className="shrink-0"><Action isSkeleton={isSkeleton} /></div>
                )] : []),
            ]}
        />
    )
}

// ─────────────────────────────────────────────────────────────────────────────
// .Base — the region frame itself
// ─────────────────────────────────────────────────────────────────────────────

/**
 * The `header` channel of {@link Section}: either the PROPS of
 * {@link SectionHeader} (the frame builds it — the main road) or a COMPONENT
 * reference (COMPOSITE-8, an escape hatch for a header the section did not
 * author, e.g. a toolbar row) — the frame calls it itself so `isSkeleton` can
 * reach inside it.
 */
export type SectionHeaderSlot = SectionHeaderProps | ComponentTypeWithSkeleton

/** Props for {@link Section}. */
export interface SectionBaseProps {
    /**
     * Top region. Pass {@link SectionHeaderProps} (`{ title, description… }`) and
     * the frame renders a {@link SectionHeader} itself; pass a COMPONENT
     * reference and the frame calls it itself, forwarding `isSkeleton`.
     */
    header?: SectionHeaderSlot
    /** Main region, as a COMPONENT reference (COMPOSITE-8) — the frame calls it itself so `isSkeleton` can reach inside it. */
    body?: ComponentTypeWithSkeleton
    /** Bottom region (a closing CTA row, a caption, a "see more" link), as a COMPONENT reference (COMPOSITE-8) — same contract as `body`. */
    footer?: ComponentTypeWithSkeleton
    /**
     * Vertical rhythm between header ↔ body ↔ footer, on the §10c scale ONLY.
     * Default `{6}` (`gap-6`) — the rhythm between regions of a page. Drop to
     * `{4}` (`gap-3`) when the header is just a label over a tight list.
     */
    gap?: AllowedGap
    /**
     * `true` → forwarded into whichever of `header`/`body`/`footer` renders
     * (COMPOSITE-8 — each is a component reference this frame calls itself, so
     * the flag reaches inside every one of them).
     */
    isSkeleton?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/** A header slot is PROPS only when it is a plain object (not a component reference). */
const isHeaderProps = (header: SectionHeaderSlot): header is SectionHeaderProps =>
    typeof header === "object" && header !== null

/**
 * The region frame — a semantic `<section>` that stacks header / body / footer at
 * ONE typed rhythm and nothing else. No fill, no border, no radius, no padding:
 * a section is a BAND of a page, so the surfaces live INSIDE it (its body is
 * usually a `SurfaceCard.*` / `SectionCard` / a grid of them).
 *
 * @param props - {@link SectionBaseProps}
 */
const Base = ({
    header,
    body: Body,
    footer: Footer,
    gap = 6,
    isSkeleton = false,
    classNames}: SectionBaseProps) => {
    let headerNode: ReactNode = null
    if (header != null) {
        if (isHeaderProps(header)) {
            // props form → the frame builds ITS OWN SectionHeader (a fixed internal
            // choice, not arbitrary caller content) — badge that real component
            // directly rather than the generic wrapping div below.
            headerNode = <Header {...header} isSkeleton={isSkeleton} />
        } else {
            const HeaderSlot = header
            headerNode = <HeaderSlot isSkeleton={isSkeleton} />
        }
    }
    return (
        <section
            className={cn("flex flex-col", GAP_CLASS[gap], classNames)}
            data-tier="composite"
            data-component="Section"
            data-principle={gap === 6 ? "block-boundary" : undefined}
        >
            {headerNode != null ? (
                <div>{headerNode}</div>
            ) : null}
            {Body != null ? (
                <div><Body isSkeleton={isSkeleton} /></div>
            ) : null}
            {Footer != null ? (
                <div><Footer isSkeleton={isSkeleton} /></div>
            ) : null}
        </section>
    )
}

/**
 * The section frame namespace — the frame of a region inside a page, two members:
 *
 * | Member | Content channel |
 * |---|---|
 * | `.Base` | `header`/`body`/`footer` slots, `gap` on the §10 scale |
 * | `.Header` | `eyebrow`/`title`/`description`/`action` + `level` (no children) |
 */
export { Base as Section, Header as SectionHeader }

import React, { useEffect, useMemo, useState } from "react"
import { SparkleIcon } from "@phosphor-icons/react"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { EnumChip, type EnumChipEntry } from "@/components/composites/chips/EnumChip"
import { DrawerShell } from "@/components/composites/layout/DrawerShell"
import { InlineIconLabel } from "@/components/composites/text/InlineIconLabel"
import { Pagination } from "@/components/atoms/navigation/Pagination"
import { StackH, StackV } from "@/components/frames/Stack"
import { useSmViewpoint } from "@/hooks/reuseables/useSmViewpoint"
import type { AiModelCategory } from "@/modules/api/graphql/queries/query-ai-models"

/** Attempts per page inside the history drawer. */
const HISTORY_PAGE_SIZE = 6

/** Accessible name for the pager `<nav>` — `Pagination` already owns its own internal `aria-label`. */
const PAGER_ARIA_LABEL = "Task attempt history pagination"

/** One history row, already resolved by the connected `PersonalProjectTaskResultHistoryDrawer` — no raw entity. */
export interface PersonalProjectTaskResultHistoryRow {
    id: string
    /** Drives the verdict chip tone (comes straight off `attempt.passed`, no threshold math). */
    passed: boolean
    score: number | null
    servedModel: string | null
    category?: AiModelCategory
    /** `t("submissionAttempts.attemptLine", { number })`, already interpolated. */
    attemptLineLabel: string
    /** Relative time (`getTimeAgoLabel`), already localized — `null` when the attempt has no `processedAt`. */
    timeLabel: string | null
}

/** All display text, already localized by the connected `PersonalProjectTaskResultHistoryDrawer`; a story passes i18n keys. */
export interface PersonalProjectTaskResultHistoryDrawerLabels {
    /** Bare drawer title (`t("personalProjectResult.history")`) — the row count is appended alongside it. */
    historyLabel: string
    passed: string
    failed: string
    /** Empty-state title (no attempts yet). */
    emptyTitle: string
    /** Empty-state secondary line. Optional. */
    emptyDescription?: string
}

/** Props for {@link _PersonalProjectTaskResultHistoryDrawer} — presentational; all data resolved, no fetch/store/i18n. */
export type PersonalProjectTaskResultHistoryDrawerProps = {
    /** Whether the drawer is open. */
    isOpen: boolean
    /** Open/close callback (also closes when a row is selected). */
    onOpenChange: (open: boolean) => void
    /** Full attempt list (newest first), already resolved to display rows. */
    rows: Array<PersonalProjectTaskResultHistoryRow>
    /** Currently selected attempt (highlighted row). */
    selectedAttemptId?: string
    /** Task max score (for the `x/max` label); 0 → show bare score. */
    maxScore: number
    /** Select an attempt (the page navigates `?attempt=`). */
    onSelect: (attemptId: string) => void
    labels: PersonalProjectTaskResultHistoryDrawerLabels
    /** AI-model tier → chip presentation, already localized — the model-byline recipe (`EnumChip`). */
    categoryMap: Partial<Record<AiModelCategory, EnumChipEntry>>
}

/** `x/max` when `maxScore` is set, otherwise the bare score. `null` reads as `0`. */
const scoreLabel = (score: number | null, maxScore: number) => (maxScore > 0 ? `${score ?? 0}/${maxScore}` : `${score ?? 0}`)

/**
 * One row's free-form content: attempt line + verdict chip + score on the first line
 * (score pushed to the far edge), an optional model byline (sparkle + model name +
 * tier chip) + time-ago on the second. Mirrors the sibling `SubmissionAttemptsDrawer`
 * row recipe — the model byline is composed here from `InlineIconLabel` + `EnumChip`
 * instead of the `ModelByline` block, since this tier may only import composites/frames.
 */
const attemptRowContent = (
    row: PersonalProjectTaskResultHistoryRow,
    isSelected: boolean,
    maxScore: number,
    labels: PersonalProjectTaskResultHistoryDrawerLabels,
    categoryMap: Partial<Record<AiModelCategory, EnumChipEntry>>,
) => {
    const servedModel = row.servedModel
    const category = row.category
    const timeLabel = row.timeLabel

    const attemptLabelAndChip = [
        () => <Typography size="sm" weight="medium" text={row.attemptLineLabel} />,
        () => <Chip tone={row.passed ? "success" : "danger"} text={row.passed ? labels.passed : labels.failed} />,
    ]

    const attemptLine = [
        () => <StackH gap={2} principle="chip-row" align="center" items={attemptLabelAndChip} />,
        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
        () => (
            <Typography
                size="sm"
                color={row.passed ? "success-soft" : "muted"}
                text={scoreLabel(row.score, maxScore)}
            />
        ),
    ]

    const bylineParts = [
        ...(servedModel != null ? [() => (
            <InlineIconLabel icon={SparkleIcon} tone="default" size="xs" label={servedModel} />
        )] : []),
        ...(servedModel != null && category != null ? [() => (
            <EnumChip value={category} map={categoryMap} />
        )] : []),
    ]

    const rowContent = [
        () => <StackH gap={3} principle="sibling-stack" align="center" justify="between" items={attemptLine} />,
        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
        ...(bylineParts.length > 0 || timeLabel != null ? [() => (
            <StackH
                gap={3}
                principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                align="center"
                justify="between"
                items={[
                    ...(bylineParts.length > 0 ? [() => <StackH gap={3} principle="sibling-stack" align="center" items={bylineParts} />] : []),
                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                    ...(timeLabel != null ? [() => <Typography size="xs" color="muted" text={timeLabel} />] : []),
                ]}
            />
        )] : []),
    ]

    // highlight-exception (mirrors `SubmissionAttemptsDrawer`): the selected row's tint is
    // baked into the row's own content wrapper — a plain, un-tightened `<div>` — since
    // `SurfaceCardListItem` no longer takes a raw `className` of its own.
    return (
        <div className={isSelected ? "bg-accent-soft" : undefined}>
            <StackV gap={2} items={rowContent} />
        </div>
    )
}

/**
 * Personal-project task submission-history drawer — the presentational half of
 * {@link PersonalProjectTaskResultHistoryDrawer}: each attempt as a free-form
 * `SurfaceCardList` row (verdict, score, the AI model that graded it + tier, time),
 * paginated client-side. Right on desktop, bottom sheet on mobile. Sibling of
 * `SubmissionResultHistoryDrawer` (challenge) — here the verdict comes straight from
 * `row.passed` (no pass-threshold computation). See `tiers/split.md` — the connected
 * `index.tsx` owns i18n.
 *
 * @param props - {@link PersonalProjectTaskResultHistoryDrawerProps}
 */
export const _PersonalProjectTaskResultHistoryDrawer = ({
    isOpen,
    onOpenChange,
    rows,
    selectedAttemptId,
    maxScore,
    onSelect,
    labels,
    categoryMap,
}: PersonalProjectTaskResultHistoryDrawerProps) => {
    const { isMobile } = useSmViewpoint()
    const [page, setPage] = useState(1)

    // reset to the first page whenever the drawer opens
    useEffect(() => {
        if (isOpen) {
            setPage(1)
        }
    }, [isOpen])

    const totalPages = Math.max(1, Math.ceil(rows.length / HISTORY_PAGE_SIZE))
    const pagedRows = useMemo(
        () => rows.slice((page - 1) * HISTORY_PAGE_SIZE, page * HISTORY_PAGE_SIZE),
        [rows, page],
    )

    const items: Array<SurfaceCardListItem> = pagedRows.map((row) => ({
        key: row.id,
        content: () => attemptRowContent(row, row.id === selectedAttemptId, maxScore, labels, categoryMap),
        onPress: () => {
            onSelect(row.id)
            onOpenChange(false)
        },
    }))

    const listAndPager = [
        () => (
            <SurfaceCardList
                items={items}
                emptyState={() => <AsyncContentEmpty title={labels.emptyTitle} description={labels.emptyDescription} />}
            />
        ),
        ...(totalPages > 1 ? [() => (
            // `Pagination` hard-codes its own internal `aria-label` — the wrapping `<nav>`
            // is how this drawer's own accessible name still gets attached, same
            // convention `SubmissionAttemptsDrawer` uses.
            <nav aria-label={PAGER_ARIA_LABEL}>
                <Pagination currentPage={page} totalPages={totalPages} onPageChange={setPage} />
            </nav>
        )] : []),
    ]

    return (
        <DrawerShell
            identity={{ tier: "overlay", component: "PersonalProjectTaskResultHistoryDrawer" }}
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            placement={isMobile ? "bottom" : "right"}
            title={`${labels.historyLabel} · ${rows.length}`}
            body={() => <StackV gap={4} items={listAndPager} />}
        />
    )
}

import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { CheckCircleIcon } from "@phosphor-icons/react"
import { ModalShell } from "@/components/composites/layout/ModalShell"
import { PricingPhase } from "@/modules/types/enums/pricing-phase"
import { PhaseScarcityNote } from "@/components/blocks/commerce/PhaseScarcityNote"
import { PriceTagProminent, type PriceBreakdown } from "@/components/blocks/commerce/PriceTag"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV } from "@/components/frames/Stack"
import { Cluster } from "@/components/frames/Cluster"

/**
 * `PremiumGateModal` — the dismissable, value-first buy/register prompt shown when a
 * viewer taps a locked premium tab or the "Practice" button on a trial-read lesson.
 * Shows what unlocks, the loyalty-aware price, and one CTA. Composes `ModalShell` +
 * `PriceTagProminent` + `PhaseScarcityNote` + `Button`; owns its header and "what
 * unlocks" wording (`courseTitle` is interpolated into a fixed template).
 *
 * Presentational: `isOpen`/`onOpenChange` + `price`/`courseTitle`; `onUpgrade` only
 * fires the callback. Only the price region skeletons; the rest paints immediately.
 */

/** Minimal price-preview shape this modal needs (mirrors `TrialConversionStripPrice`). */
export interface PremiumGateModalPrice {
    /** The price the user actually pays. */
    discountedPriceVnd: number
    /** Pre-discount (list/MSRP) price; struck through when greater than {@link discountedPriceVnd}. */
    originalPriceVnd?: number | null
    /** Active-phase price BEFORE loyalty — feeds the breakdown popover's middle step. */
    phasePriceVnd: number
    /** Loyalty discount percent (0 = no loyalty row in the breakdown). */
    discountPercent: number
    /** The course's current pricing phase — shown by {@link PhaseScarcityNote}. */
    currentPhase: PricingPhase
    /** Seats left at this phase's price; `null` = unlimited → {@link PhaseScarcityNote} renders nothing. */
    seatsRemaining: number | null
    /** VND price after this phase sells out; `null` = no rise to mention. */
    nextPhasePriceVnd: number | null
}

/** Props for {@link _PremiumGateModal}. */
export interface PremiumGateModalProps {
    /** Whether the modal is currently open. Forwarded to {@link ModalShell}. */
    isOpen: boolean
    /** Open-state change handler — backdrop click, Escape, close button. Forwarded to {@link ModalShell}. */
    onOpenChange: (open: boolean) => void
    /**
     * The specific course being gated, when known. Drives which row of
     * {@link GATE_HEADER} renders — `null`/omitted falls back to the generic
     * copy (e.g. opened from a rail button with no course in scope yet).
     */
    courseTitle?: string | null
    /**
     * Price preview for the course; `undefined`/`null` while not yet resolved
     * and {@link isSkeleton} is off renders neither the real price nor a
     * shimmer (nothing to show yet is the caller's state to reach, same as
     * `TrialConversionStrip`).
     */
    price?: PremiumGateModalPrice | null
    /**
     * `true` → ONLY the price region rests: the header, the unlocks list, and
     * the CTA button do not depend on the price, so they render immediately
     * and the shimmer stands exactly where `PriceTagProminent` +
     * `PhaseScarcityNote` will land — the exact `TrialConversionStrip`
     * `isSkeleton` contract, carried over unchanged.
     */
    isSkeleton?: boolean
    /**
     * Fired when the upgrade CTA is pressed. The CALLER decides what pressing
     * it means (close this modal, open the payment flow) — Rule 13, same
     * handoff shape as `TrialConversionStrip`'s `onEnroll`.
     */
    onUpgrade: () => void
}

/** Whether the caller named a specific course, or this is a generic gate. */
type GateHeaderVariant = "named" | "generic"

/** One row of the {@link GATE_HEADER} table — a title template plus its description. */
interface GateHeaderCopy {
    /** Builds the header title; `courseTitle` is DATA plugged into the template, not caller wording. */
    title: (courseTitle?: string | null) => string
    /** Header description, shown under the title. */
    description: string
}

/**
 * variant → header copy. Fixed Vietnamese vocabulary this block owns
 * (§14d.1), same table shape as `ContentModeNav`'s `MODE_LABEL`.
 * `courseTitle` is DATA plugged into the `named` row's template — the
 * sentence itself never comes from the caller, mirroring
 * `PhaseScarcityNote`'s `${seatsRemaining} seats left…` pattern.
 */
const GATE_HEADER: Record<GateHeaderVariant, GateHeaderCopy> = {
    named: {
        title: (courseTitle) => `Unlock "${courseTitle}"`,
        description: "Watch every lecture, take unlimited challenges, and earn a certificate when you complete the course.",
    },
    generic: {
        title: () => "Unlock the full course",
        description: "Watch every lecture, take unlimited challenges, and earn a certificate when you complete the course.",
    },
}

/** One line of the "what unlocks" checklist. */
interface GateUnlockItem {
    /** Stable row key. */
    key: string
    /** The benefit line itself. */
    label: string
}

/**
 * What unlocking premium gives the viewer — fixed local vocabulary (§14d.1),
 * not caller data: a caller states IT WANTS a gate, never which benefits to
 * list, the same way `ContentModeNav`'s modes come from its own table.
 */
const GATE_UNLOCKS: ReadonlyArray<GateUnlockItem> = [
    { key: "content", label: "All of the course's lectures and resources" },
    { key: "practice", label: "Unlimited challenges, quizzes, and mock interviews" },
    { key: "certificate", label: "A certificate of completion when you finish the course" },
]

/**
 * Renders the value-first upgrade prompt inside the shared modal scaffold.
 * See the file header for the full contract.
 *
 * @param props - {@link PremiumGateModalProps}
 */
export const _PremiumGateModal = ({
    isOpen,
    onOpenChange,
    courseTitle,
    price,
    isSkeleton = false,
    onUpgrade,
}: PremiumGateModalProps) => {
    const headerVariant: GateHeaderVariant = courseTitle ? "named" : "generic"
    const header = GATE_HEADER[headerVariant]

    const breakdown: PriceBreakdown | undefined = price
        ? {
            phase: price.phasePriceVnd,
            loyaltyPercent: price.discountPercent,
        }
        : undefined

    const unlockItems = GATE_UNLOCKS.map((item) => () => (
        <Cluster
            gap={3}
            principle="icon-text"
            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
            align="center"

            items={[
                () => (
                    <CheckCircleIcon
                        aria-hidden
                        focusable="false"
                        weight="bold"
                        // No `data-anat-part`: a bare Phosphor glyph has no
                        // story to jump to (`PhaseScarcityNote`'s own
                        // convention) — badging it would dead-end the tree.
                        className="size-3.5 shrink-0 text-success-soft-foreground"
                    />
                ),
                () => (
                    <Typography
                        size="sm"
                        text={item.label}

                    />
                ),
            ]}
        />
    ))

    const skeletonPrice = [
        () => <Typography size="h4" isSkeleton classNames={["w-1/3"]} />,
        () => <Typography size="xs" isSkeleton classNames={["w-1/2"]} />,
    ]

    const gateBody = [
        // "What unlocks" — static chrome, never skeletonised: known before
        // any price data lands, exactly like `ContentModeNav`'s own row.
        ({ isSkeleton }: SkeletonProps) => <StackV gap={3} isSkeleton={isSkeleton} items={unlockItems} />,

        // Price + scarcity — the ONLY region `isSkeleton` reaches, same
        // `isSkeleton && !price` / `price?.discountedPriceVnd != null` split
        // `TrialConversionStrip` uses for its own price region.
        ...(isSkeleton && !price
            ? [({ isSkeleton }: SkeletonProps) => <StackV gap={4} isSkeleton={isSkeleton} items={skeletonPrice} />]
            : price?.discountedPriceVnd != null
                ? [({ isSkeleton }: SkeletonProps) => (
                    <StackV
                        gap={4}
                        isSkeleton={isSkeleton}
                        items={[
                            ({ isSkeleton }: SkeletonProps) => (
                                <PriceTagProminent
                                    discounted={price.discountedPriceVnd}
                                    original={price.originalPriceVnd}
                                    breakdown={breakdown}
                                    isSkeleton={isSkeleton}

                                />
                            ),
                            () => (
                                <PhaseScarcityNote

                                    currentPhase={price.currentPhase}
                                    seatsRemaining={price.seatsRemaining}
                                    nextPhasePriceVnd={price.nextPhasePriceVnd}
                                />
                            ),
                        ]}
                    />
                )]
                : []),
    ]

    return (
        <ModalShell
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            title={header.title(courseTitle)}
            description={header.description}
            size="md"
            identity={{ tier: "overlay", component: "PremiumGateModal" }}

            footer={() => (
                <Button
                    variant="primary"
                    size="lg"
                    classNames={["w-full"]}
                    label="Unlock now"
                    onPress={onUpgrade}

                />
            )}
            body={() => <StackV gap={6} isSkeleton={isSkeleton} items={gateBody} />}
        />
    )
}

