"use client"

import React, {
    useCallback,
    useEffect,
    useRef,
    useState,
} from "react"
import {
    Button,
    ColorArea,
    ColorPicker,
    ColorSlider,
    ColorSwatch,
    ColorSwatchPicker,
    Label,
    cn,
    parseColor,
} from "@heroui/react"
import type {
    Color,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    PageHeader,
} from "@/components/blocks/layout/PageHeader"
import {
    LabeledCard,
} from "@/components/blocks/cards/LabeledCard"
import {
    SettingsBreadcrumb,
} from "@/components/blocks/settings/SettingsBreadcrumb"
import {
    useAppDispatch,
    useAppSelector,
} from "@/redux/hooks"
import {
    setUser,
} from "@/redux/slices/user"
import {
    useMutateUpdateProfileSwr,
} from "@/hooks/swr/api/graphql/mutations/useMutateUpdateProfileSwr"
import {
    BackgroundEffect,
} from "@/modules/types/enums/background-effect"
import {
    AmbientBackground,
} from "@/components/blocks/layout/AmbientBackground"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/** Fallback accent (matches the default brand `--accent` token) when the user has never set one. */
const DEFAULT_ACCENT_HEX = "#e84393"

/** 10 named preset accents (hex, curated to stay legible with the default white `--accent-foreground`). */
const ACCENT_PRESETS: ReadonlyArray<{ hex: string, labelKey: string }> = [
    { hex: "#e84393", labelKey: "pink" },
    { hex: "#7c5cfc", labelKey: "purple" },
    { hex: "#2f86eb", labelKey: "blue" },
    { hex: "#16b5c4", labelKey: "teal" },
    { hex: "#25b56a", labelKey: "emerald" },
    { hex: "#84cc16", labelKey: "lime" },
    { hex: "#f39c12", labelKey: "amber" },
    { hex: "#e74c3c", labelKey: "red" },
    { hex: "#d946ef", labelKey: "fuchsia" },
    { hex: "#64748b", labelKey: "slate" },
]

/** The 10 selectable ambient background effects (including "off"). */
const EFFECT_OPTIONS: ReadonlyArray<BackgroundEffect> = [
    BackgroundEffect.None,
    BackgroundEffect.Ember,
    BackgroundEffect.Wave,
    BackgroundEffect.Snow,
    BackgroundEffect.Rain,
    BackgroundEffect.Bubbles,
    BackgroundEffect.Fireflies,
    BackgroundEffect.Stars,
    BackgroundEffect.Aurora,
    BackgroundEffect.Circuit,
]

/** How long to wait after the last color change before persisting (avoids spamming the mutation while dragging). */
const ACCENT_PERSIST_DEBOUNCE_MS = 500

/**
 * Settings → "AppearancePage": pick an accent color (10 presets or a free-form
 * `ColorPicker`) and an ambient background effect (10 options, tinted by the
 * chosen accent) — independent of light/dark mode, which stays on the navbar
 * toggle. Both persist to `UserEntity` via `updateProfile` (server is the
 * source of truth; `useAccentOverride` / `useBackgroundEffect` mirror them
 * app-wide + into localStorage for the no-flash fast path).
 */
export const AppearancePage = () => {
    const t = useTranslations()
    const dispatch = useAppDispatch()
    const user = useAppSelector((state) => state.user.user)
    const updateProfileSwr = useMutateUpdateProfileSwr()

    const [color, setColor] = useState<Color>(
        () => parseColor(user?.accentColor ?? DEFAULT_ACCENT_HEX),
    )
    const persistTimeoutRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)

    // instant preview while dragging — independent of the debounced persistence below
    useEffect(() => {
        document.documentElement.style.setProperty("--accent", color.toString("hex"))
    }, [
        color,
    ])

    const persistAccent = useCallback((hex: string | null) => {
        if (persistTimeoutRef.current) {
            clearTimeout(persistTimeoutRef.current)
        }
        persistTimeoutRef.current = setTimeout(() => {
            void updateProfileSwr.trigger({ accentColor: hex }).then((result) => {
                const updated = result?.data?.updateProfile?.data
                if (updated) {
                    dispatch(setUser(updated))
                }
            })
        }, ACCENT_PERSIST_DEBOUNCE_MS)
    }, [
        updateProfileSwr,
        dispatch,
    ])

    const onColorChange = useCallback((next: Color) => {
        setColor(next)
        persistAccent(next.toString("hex"))
    }, [
        persistAccent,
    ])

    const onResetAccent = useCallback(() => {
        setColor(parseColor(DEFAULT_ACCENT_HEX))
        document.documentElement.style.removeProperty("--accent")
        document.documentElement.style.removeProperty("--accent-foreground")
        persistAccent(null)
    }, [
        persistAccent,
    ])

    const effect = user?.backgroundEffect ?? BackgroundEffect.None

    const onSelectEffect = useCallback((next: BackgroundEffect) => {
        if (!user || next === effect) {
            return
        }
        // optimistic — the real confirmation comes back from the mutation below
        dispatch(setUser({ ...user, backgroundEffect: next }))
        void updateProfileSwr.trigger({ backgroundEffect: next }).then((result) => {
            const updated = result?.data?.updateProfile?.data
            if (updated) {
                dispatch(setUser(updated))
            }
        })
    }, [
        user,
        effect,
        dispatch,
        updateProfileSwr,
    ])

    return (
        <StackV gap={7} principle="layout-split"
            explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
            items={[
                () => (
                    <PageHeader
                        breadcrumb={<SettingsBreadcrumb current={t("appearance.title")} />}
                        title={t("appearance.title")}
                        description={t("appearance.description")}
                    />
                ),
                () => (
                    <StackV gap={6} principle="block-boundary"
                        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                        items={[
                            () => (
                                <LabeledCard label={t("appearance.accentLabel")}>
                                    <StackV gap={4} principle="content-row"
                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                        items={[
                                            () => (
                                                <ColorSwatchPicker value={color} onChange={onColorChange} size="lg">
                                                    {ACCENT_PRESETS.map((preset) => (
                                                        <ColorSwatchPicker.Item key={preset.hex} color={preset.hex}>
                                                            <ColorSwatchPicker.Swatch />
                                                            <ColorSwatchPicker.Indicator />
                                                        </ColorSwatchPicker.Item>
                                                    ))}
                                                </ColorSwatchPicker>
                                            ),
                                            () => (
                                                <StackH gap={4} principle="content-row" at="sm" align="center"
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    items={[
                                                        () => (
                                                            <ColorPicker value={color} onChange={onColorChange}>
                                                                <ColorPicker.Trigger>
                                                                    <ColorSwatch size="lg" />
                                                                    <Label>{t("appearance.customColor")}</Label>
                                                                </ColorPicker.Trigger>
                                                                <ColorPicker.Popover>
                                                                    <ColorArea
                                                                        aria-label={t("appearance.customColor")}
                                                                        className="max-w-full"
                                                                        colorSpace="hsb"
                                                                        xChannel="saturation"
                                                                        yChannel="brightness"
                                                                    >
                                                                        <ColorArea.Thumb />
                                                                    </ColorArea>
                                                                    <ColorSlider channel="hue" colorSpace="hsb">
                                                                        <ColorSlider.Track>
                                                                            <ColorSlider.Thumb />
                                                                        </ColorSlider.Track>
                                                                    </ColorSlider>
                                                                </ColorPicker.Popover>
                                                            </ColorPicker>
                                                        ),
                                                        () => (
                                                            <Button variant="tertiary" size="sm" onPress={onResetAccent}>
                                                                {t("appearance.resetAccent")}
                                                            </Button>
                                                        ),
                                                    ]} />
                                            ),
                                        ]} />
                                </LabeledCard>
                            ),

                            () => (
                                <LabeledCard label={t("appearance.effectLabel")}>
                                    <Box principle="content-row" className="grid grid-cols-2 gap-3 @app-sm:grid-cols-3 @app-md:grid-cols-5"
                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title.">
                                        {EFFECT_OPTIONS.map((option) => (
                                            <button
                                                key={option}
                                                type="button"
                                                onClick={() => onSelectEffect(option)}
                                                className={cn(
                                                    "relative flex h-24 flex-col justify-end overflow-hidden rounded-2xl border p-2 text-left transition-colors",
                                                    effect === option
                                                        ? "border-accent ring-2 ring-accent"
                                                        : "border-default hover:bg-default",
                                                )}
                                            >
                                                <AmbientBackground effect={option} className="absolute inset-0 -z-0" />
                                                <span className="relative z-10 text-xs font-medium text-foreground">
                                                    {t(`appearance.effects.${option}`)}
                                                </span>
                                            </button>
                                        ))}
                                    </Box>
                                </LabeledCard>
                            ),
                        ]} />
                ),
            ]} />
    )
}

"use client"

import React, { useMemo } from "react"
import { Card, Link, Typography, cn } from "@heroui/react"
import { useLocale, useTranslations } from "next-intl"
import { ArrowUpRightIcon, BookOpenTextIcon } from "@phosphor-icons/react"
import { Callout } from "@/components/composites/feedback/Callout"
import { SimpleEmptyState } from "@/components/blocks/feedback/SimpleEmptyState"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"
import { pathConfig } from "@/resources/path"
import { getTimeAgoLabel, getTimeAgoMessage } from "@/modules/dayjs"
import { ARCHITECTURE_COMPONENT_MAP } from "../constants"
import { ARCHITECTURE_MODULE_MAP } from "../modules"
import type { HealthByName } from "../hooks/useSystemHealthPoll"
import { MetricsInline } from "../MetricsInline"
import { getArchitectureStatusVisual, resolveArchitectureStatus } from "../statusVisual"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link NodeDissectionPanel}. */
export interface NodeDissectionPanelProps extends WithClassNames<undefined> {
    /** Selected component name (must exist in the catalog). */
    nodeId: string
    /** Live health keyed by component name, or `null` before the first probe resolves. */
    healthByName: HealthByName | null
}

/**
 * The "dissection" panel for the currently selected node: identity (icon +
 * name + role), live status (dot + text + latency + relative freshness), a
 * short "why this matters" note, and — when the component has one — a link to
 * its StarCi engineering-blog deep-dive. Public-safe only: no secrets, no
 * connection strings, just role + live traffic-light + a public failure
 * message when down.
 *
 * @param props - {@link NodeDissectionPanelProps}
 */
export const NodeDissectionPanel = ({ nodeId, healthByName, className }: NodeDissectionPanelProps) => {
    const t = useTranslations("architecture")
    const tRoot = useTranslations()
    const locale = useLocale()
    const component = ARCHITECTURE_COMPONENT_MAP[nodeId]

    const state = resolveArchitectureStatus(nodeId, healthByName)
    const visual = getArchitectureStatusVisual(state)
    const health = healthByName?.[nodeId] ?? null

    const checkedAgo = useMemo(
        () => (health ? getTimeAgoLabel(getTimeAgoMessage(health.checkedAt), tRoot) : null),
        [health, tRoot],
    )

    // feature module (Core API split) — no health probe exists, so no status /
    // metrics / blog: identity + role + the real infra it runs on (grounded in
    // `usesInfra`), which is exactly what makes the "Core → modules" reading legible.
    const module = ARCHITECTURE_MODULE_MAP[nodeId]
    if (module) {
        const ModuleIcon = module.icon
        const infraNames = module.usesInfra.map((id) => ARCHITECTURE_COMPONENT_MAP[id]?.name ?? id)
        return (
            <Card className={cn(className)}>
                <Box principle="page-pad" className="p-6"
                    explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                    <StackV gap={5} principle="group-boundary"
                        explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                        items={[
                            () => (
                                <div data-principle="content-row" className="flex min-w-0 items-center gap-3">
                                    <IconTile icon={<ModuleIcon aria-hidden />} tone="neutral" size="sm" />
                                    <div className="flex min-w-0 flex-col">
                                        <Typography type="h4" weight="semibold" className="min-w-0 truncate">
                                            {t(`module.${module.id}.name`)}
                                        </Typography>
                                        <Typography type="body-sm" color="muted">
                                            {t(`module.${module.id}.sub`)}
                                        </Typography>
                                    </div>
                                </div>
                            ),
                            () => (
                                <div data-principle="sibling-stack" className="flex flex-col gap-2 border-t border-default pt-3">
                                    <Typography type="body-sm" weight="medium">{t("panel.whyHeading")}</Typography>
                                    <Typography type="body-sm" color="muted">{t(`module.${module.id}.role`)}</Typography>
                                </div>
                            ),
                            () => (
                                <div data-principle="sibling-stack" className="flex flex-col gap-2 border-t border-default pt-3">
                                    <Typography type="body-sm" weight="medium">{t("panel.runsOn")}</Typography>
                                    <div data-principle="chip-row" className="flex flex-wrap gap-2">
                                        {infraNames.map((name) => (
                                            <span key={name} data-principle="control-pad" className="rounded-full bg-default px-2 py-1 font-mono text-xs text-muted">
                                                {name}
                                            </span>
                                        ))}
                                    </div>
                                </div>
                            ),
                        ]} />
                </Box>
            </Card>
        )
    }

    if (!component) {
        return (
            <Card className={cn(className)}>
                <Box principle="page-pad" className="p-6"
                    explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                    <SimpleEmptyState>{t("panel.notFound")}</SimpleEmptyState>
                </Box>
            </Card>
        )
    }

    const Icon = component.icon
    const blogHref = component.blogSlug
        ? `${pathConfig().locale(locale).blog().build()}/${component.blogSlug}`
        : null

    return (
        <Card className={cn(className)}>
            <Box principle="page-pad" className="p-6"
                explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                <StackV gap={5} principle="group-boundary"
                    explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                    items={[
                        () => (
                            <div data-principle="content-row" className="flex items-start justify-between gap-3">
                                <div data-principle="content-row" className="flex min-w-0 items-center gap-3">
                                    <IconTile icon={<Icon aria-hidden />} tone="neutral" size="sm" />
                                    <div className="flex min-w-0 flex-col">
                                        <Typography type="h4" weight="semibold" className="min-w-0 truncate font-mono">
                                            {component.name}
                                        </Typography>
                                        <Typography type="body-sm" color="muted">
                                            {t(`role.${component.name}`)}
                                        </Typography>
                                    </div>
                                </div>
                                <span className={cn("flex shrink-0 items-center gap-2 rounded-full px-2 py-1", visual.chipClassName)}>
                                    <span className={cn("size-2 shrink-0 rounded-full", visual.dotClassName, visual.pulse && "animate-pulse")} aria-hidden />
                                    <Typography type="body-xs" weight="medium" className="whitespace-nowrap">
                                        {t(`status.${state}`)}
                                    </Typography>
                                </span>
                            </div>
                        ),
                        () => (
                            <div className="flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-muted">
                                <span className="tabular-nums">
                                    {health?.latencyMs == null ? "—" : t("panel.latency", { ms: health.latencyMs })}
                                </span>
                                {checkedAgo ? <span>{t("panel.checked", { ago: checkedAgo })}</span> : null}
                                <MetricsInline metrics={health?.metrics} />
                            </div>
                        ),
                        ...(health?.message ? [
                            () => {
                                const message = health.message!
                                return <Callout status="danger" title={message} />
                            },
                        ] : []),
                        () => (
                            <div data-principle="sibling-stack" className="flex flex-col gap-2 border-t border-default pt-3">
                                <Typography type="body-sm" weight="medium">{t("panel.whyHeading")}</Typography>
                                <Typography type="body-sm" color="muted">{t(`why.${component.name}`)}</Typography>
                            </div>
                        ),
                        ...(blogHref ? [
                            () => (
                                <Link href={blogHref} data-principle="flex-action" className="group inline-flex items-center gap-2 text-accent-soft-foreground">
                                    <BookOpenTextIcon aria-hidden focusable="false" className="size-4" />
                                    {t("panel.deepDive")}
                                    <ArrowUpRightIcon
                                        aria-hidden
                                        focusable="false"
                                        className="size-4 transition-transform group-hover:translate-x-0.5 group-hover:-translate-y-0.5"
                                    />
                                </Link>
                            ),
                        ] : []),
                    ]} />
            </Box>
        </Card>
    )
}

"use client"

import React from "react"
import { Chip } from "@heroui/react"
import { useTranslations } from "next-intl"
import { Link } from "@/i18n/navigation"
import { CATEGORY_COLOR } from "@/modules/utils/blog-category"
import { type QueryBlogPostListItem } from "@/modules/api/graphql/queries/types/blog"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"

/** Props for {@link FeaturedPost}. */
export interface FeaturedPostProps {
    /** The newest post, given the editorial-lead treatment. */
    post: QueryBlogPostListItem
    /** Localized, preformatted publish date (the caller owns locale formatting). */
    formattedDate: string
}

/**
 * The editorial lead — the newest post rendered flat (no card) with a serif
 * display title so it anchors the page even when only a few posts exist. The
 * cover is shown only when present (most posts have none → typography leads).
 */
export const FeaturedPost = ({ post, formattedDate }: FeaturedPostProps) => {
    const t = useTranslations("blog")
    const readingMinutes = post.readingMinutes
    return (
        <Link
            href={`/blog/${post.slug}`}
            className="group cursor-pointer border-b border-default pb-6"
        >
            <StackV gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                // eyebrow: pillar chip · "latest" · optional premium
                    () => (
                        <Cluster gap={3} principle="chip-row"
                            explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                            items={[
                                () => (
                                    <Chip size="sm" variant="soft" color={CATEGORY_COLOR[post.category]}>
                                        {t(`categories.${post.category}`)}
                                    </Chip>
                                ),
                                () => (
                                    <span className="text-xs font-medium text-accent-soft-foreground">
                                        {t("latest")}
                                    </span>
                                ),
                                ...(post.isPremium ? [() => (
                                    <Chip size="sm" variant="soft" color="warning">
                                        {t("premium")}
                                    </Chip>
                                )] : []),
                            ]} />
                    ),

                    // optional cover — only when the post actually has one
                    () => (post.coverImageUrl ? (
                        <img
                            src={post.coverImageUrl}
                            alt=""
                            className="aspect-[16/9] w-full rounded-large object-cover"
                        />
                    ) : null),

                    // serif display title — the page's visual hero
                    () => (
                        <h2 className="text-3xl font-semibold leading-tight text-foreground underline-offset-4 decoration-[var(--separator-tertiary)] group-hover:underline">
                            {post.title}
                        </h2>
                    ),
                    () => (post.excerpt ? <p className="text-base text-muted">{post.excerpt}</p> : null),

                    () => (
                        <StackH gap={3} principle="identity" align="center"
