}

import React, { useEffect, useMemo, useState } from "react"
import { ArrowRightIcon, ShoppingCartIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import { Container } from "@/components/frames/Container"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { PriceTagInline } from "@/components/blocks/commerce/PriceTag"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { CartLine } from "@/components/blocks/commerce/CartLine"
import { publicEnv } from "@/resources/env/public"
import type { CartItemEntity } from "@/modules/api/graphql/queries/types/my-cart"
import type { CoursesCheckoutPreviewLine } from "@/modules/api/graphql/queries/types/courses-checkout-preview"
import type { CourseEntity } from "@/modules/types/entities/course"

/** How many placeholder rows the co-located skeleton shows for the cart-line list. */
const SKELETON_ROW_COUNT = 3

/** Format an integer VND amount as "1.275.000₫". */
export const formatVnd = (amount: number): string => `${amount.toLocaleString("vi-VN")}₫`

/**
 * A course's DISPLAY list VND price from its entity (active-phase price, falling
 * back to the list price, ÷ non-prod test divisor). Used only as the FALLBACK
 * total when the checkout preview fails — the real charged total comes from the
 * preview, whose amounts are already display-ready.
 */
const displayPriceVnd = (course: CourseEntity): number => {
    const divisor = publicEnv().pricing.testDivisor
    const toVnd = (amount: number): number =>
        divisor === 1 ? amount : Math.max(1, Math.round(amount / divisor))
    const phasePrice = course.pricingPhases?.find(
        (phase) => phase.phase === course.currentPhase,
    )?.price
    return toVnd(phasePrice ?? course.originalPrice ?? 0)
}

/**
 * One row's minimal shimmer standing in for {@link CartLine} while the cart's
 * first load is in flight. `CartLine` takes no `isSkeleton` prop, so this mirrors
 * its leading-tile + title/price + trailing-button shape right where the row
 * sits, instead of a hand-kept parallel skeleton tree (missingSkeletonSupport).
 */
const CartLineSkeletonRow = () => (
    <SurfaceListCardItem>
        <StackH gap={4} items={[
            () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
            () => (
                <StackV gap={3} classNames={["min-w-0", "flex-1"]} items={[
                    () => <Skeleton.Typography type="body-sm" width="1/2" />,
                    () => <Skeleton className="h-4 w-24 rounded-lg" />,
                ]} />
            ),
            () => <Skeleton className="size-9 shrink-0 rounded-lg" />,
        ]} />
    </SurfaceListCardItem>
)

/** Props for the private {@link ClearCartButton} helper. */
interface ClearCartButtonProps {
    isDisabled: boolean
    onClear: () => void
    /** Already-translated resting label ("Clear cart"). */
    clearLabel: string
    /** Already-translated armed-state label ("Press again to confirm"). */
    confirmLabel: string
}

/**
 * "Clear cart" with a lightweight inline 2-step confirm (no modal): first press
 * arms a danger-soft "confirm" state that auto-disarms after 3s; second press
 * within the window actually clears — so a destroy-all action can't fire on one
 * stray click. (canon: destructive action needs confirmation.)
 */
const ClearCartButton = ({ isDisabled, onClear, clearLabel, confirmLabel }: ClearCartButtonProps) => {
    const [confirming, setConfirming] = useState(false)
    useEffect(() => {
        if (!confirming) return
        const timer = setTimeout(() => setConfirming(false), 3000)
        return () => clearTimeout(timer)
    }, [confirming])
    return (
        <Button
            variant={confirming ? "danger-soft" : "tertiary"}
            isDisabled={isDisabled}
            label={confirming ? confirmLabel : clearLabel}
            classNames={["w-full"]}
            onPress={() => {
                if (confirming) {
                    onClear()
                    setConfirming(false)
                } else {
                    setConfirming(true)
                }
            }}
        />
    )
}

/** All display text, already localized by the connected `CartPage`; a story passes i18n keys. */
export interface CartPageLabels {
    title: string
    description: string
    empty: string
    emptyHint: string
    browseCourses: string
    error: string
    retry: string
    total: string
    /** Full "Checkout (N)" sentence — the connected file interpolates the count. */
    checkoutCount: string
    clear: string
    clearConfirm: string
    /** Present only when the preview reports a real saving over the list total. */
    savings?: string
    /** Present only when the preview also reports a multi-course bundle bonus. */
    bundleBonus?: string
    /** Present only when an installment plan exists for this cart. */
    installmentHint?: string
    /** "Add one more to unlock the next tier" nudge — present only at cart size 1 or 2. */
    addMoreHint?: string
}

/** Props for {@link _CartPage} — presentational; all data resolved, no fetch/store/i18n. */
export interface CartPageProps {
    /** Every cart row with its full course. */
    items: Array<CartItemEntity>
    /** The checkout preview's per-course lines, for per-line pricing inside {@link CartLine}. */
    previewLines: Array<CoursesCheckoutPreviewLine>
    /** Real charged total from the checkout preview; undefined while it's pending or on error. */
    totalChargedVnd?: number
    /** Real list (pre-discount) total from the checkout preview. */
    totalListVnd?: number
    /** Disables the remove/checkout/clear affordances while a cart write is in flight. */
    isMutating: boolean
    /** First load, nothing in hand yet → the cart-line list + footer shimmer in place. */
    isSkeleton?: boolean
    /** Settled with zero rows → the empty message (offers browsing courses). */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file's settled cart-fetch error. */
    error?: unknown
    /**
     * The cart itself has resolved but the checkout-preview query (a separate SWR
     * key) is still pending — only the footer total/savings block shimmers.
     */
    isPreviewSkeleton?: boolean
    /** Retry handler for the error branch — re-fetches the cart. */
    onRetry: () => void
    /** Remove one course from the cart. */
    onRemove: (courseId: string) => void
    /** Opens the payment overlay for the current cart. */
    onCheckout: () => void
    /** Empties the cart (after the inline 2-step confirm). */
    onClearCart: () => void
    /** Jumps to course browsing — the empty state's action. */
    onBrowseCourses: () => void
    labels: CartPageLabels
}

/**
 * Shopping-cart page — the presentational half of {@link import("./index").CartPage}.
 * Header (always shown) → error/empty/content in that order (`error` beats a stale
 * `isSkeleton`; `isEmpty` only once settled) → cart lines in one `SurfaceListCard` →
 * a footer with the REAL discounted total (progressive loyalty + multi-course bundle
 * bonus), the saving, a bundle chip, an "add more to save more" nudge, a primary
 * "Checkout" CTA (opens the payment modal), and a tertiary "Clear cart". The cart-line
 * list and the footer's preview total shimmer independently (two separate SWR keys —
 * `isSkeleton` for the cart itself, `isPreviewSkeleton` for the checkout preview),
 * both threaded co-located rather than built as a parallel skeleton tree. See
 * `tiers/split.md` — the connected `./index.tsx` owns the fetch and i18n.
 *
 * @param props - {@link CartPageProps}
 */
export const _CartPage = ({
    items,
    previewLines,
    totalChargedVnd,
    totalListVnd,
    isMutating,
    isSkeleton = false,
    isEmpty = false,
    error,
    isPreviewSkeleton = false,
    onRetry,
    onRemove,
    onCheckout,
    onClearCart,
    onBrowseCourses,
    labels,
}: CartPageProps) => {
    const { savings: savingsLabel, bundleBonus: bundleBonusLabel, installmentHint: installmentHintLabel, addMoreHint: addMoreHintLabel } = labels

    // courseId → preview line, for per-line pricing.
    const previewByCourse = useMemo(() => {
        const map = new Map<string, CoursesCheckoutPreviewLine>()
        previewLines.forEach((line) => map.set(line.courseId, line))
        return map
    }, [previewLines])

    // plain summed list total from the cart entities — the fallback shown when the
    // preview total hasn't arrived (still pending, or errored).
    const fallbackTotalVnd = useMemo(
        () => items.reduce((sum, item) => sum + displayPriceVnd(item.course), 0),
        [items],
    )

    // the footer summary block: total (real charged) + savings + bundle chip + nudge.
    // While the preview itself is pending it shimmers independently of the cart list.
    const summaryItems = isPreviewSkeleton
        ? [() => <Skeleton className="h-4 w-40 rounded-lg" />]
        : [
            ...(savingsLabel ? [() => (
                <StackH gap={3} principle="flex-action" justify="between"
                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                    items={[
                        () => <Typography size="sm" color="success-soft" text={savingsLabel} />,
                        () => (bundleBonusLabel ? <Chip tone="accent" text={bundleBonusLabel} /> : null),
                    ]} />
            )] : []),
            ...(installmentHintLabel ? [() => <Typography size="xs" color="muted" text={installmentHintLabel} />] : []),
            ...(addMoreHintLabel ? [() => <Typography size="xs" color="muted" text={addMoreHintLabel} />] : []),
        ]

    // error beats a stale isSkeleton flag; empty only once settled (BLOCK-8) — the
    // two message branches are the shared `AsyncContent*` frames, not hand-written JSX.
    const contentBody = () => {
        if (error) {
            return <AsyncContentError title={labels.error} onRetry={onRetry} retryLabel={labels.retry} />
        }
        if (!isSkeleton && isEmpty) {
            return (
                <AsyncContentEmpty
                    icon={ShoppingCartIcon}
                    title={labels.empty}
                    description={labels.emptyHint}
                    onRetry={onBrowseCourses}
                    retryLabel={labels.browseCourses}
                />
            )
        }
        return (
            <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                    () => (
                        <SurfaceListCard>
                            {isSkeleton
                                ? Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => (
                                    <CartLineSkeletonRow key={index} />
                                ))
                                : items.map((item) => (
                                    <CartLine
                                        key={item.id}
                                        item={item}
                                        previewLine={previewByCourse.get(item.courseId)}
                                        onRemove={onRemove}
                                        isMutating={isMutating}
                                    />
                                ))}
                        </SurfaceListCard>
                    ),
                    () => {
                    // Items hoisted so this gap-only column is not scanned as owning nested
                    // justify/principle from its children (check-pattern-coverage opens to `>`).
                        const footerColumnItems = isSkeleton
                            ? [() => <Skeleton className="h-12 w-full rounded-2xl" />]
                            : [
                                () => (
                                    <StackV gap={3} principle="sibling-stack" isSkeleton={isPreviewSkeleton}
                                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                        items={[
                                            () => (
                                                <StackH gap={4} principle="content-row" justify="between"
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    items={[
                                                        () => <Typography size="base" weight="semibold" text={labels.total} isSkeleton={isPreviewSkeleton} />,
                                                        () => (isPreviewSkeleton
                                                            ? <Skeleton className="h-7 w-32 rounded-lg" />
                                                            : (totalChargedVnd != null
                                                                ? (
                                                                    <PriceTagInline
                                                                        discounted={totalChargedVnd}
                                                                        original={totalListVnd}
                                                                        currency="VND"
                                                                    />
                                                                )
                                                                : <Typography size="h4" weight="bold" text={formatVnd(fallbackTotalVnd)} />)),
                                                    ]} />
                                            ),
                                            ...summaryItems,
                                        ]} />
                                ),
                                () => (
                                    <Button
                                        variant="primary"
                                        size="lg"
                                        isDisabled={isMutating}
                                        onPress={onCheckout}
                                        label={labels.checkoutCount}
                                        suffixIcon={ArrowRightIcon}
                                        classNames={["w-full"]}
                                    />
                                ),
                                () => (
                                    <ClearCartButton
                                        isDisabled={isMutating}
                                        onClear={onClearCart}
                                        clearLabel={labels.clear}
                                        confirmLabel={labels.clearConfirm}
                                    />
                                ),
                            ]
                        return <StackV gap={4} items={footerColumnItems} />
                    },
                ]} />
        )
    }

    return (
        <Container
            size="md"
            padding={6}
            identity={{ tier: "block", component: "CartPage" }}
            body={() => (
                <StackV gap={7} items={[
                    () => <PageHeader title={labels.title} description={labels.description} />,
                    contentBody,
                ]} />
            )}
        />
    )
}

import { InputTextarea } from "@/components/atoms/forms"
import React, { useCallback, useState } from "react"
import { SealCheckIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { Button } from "@/components/atoms/buttons/Button"

import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { ScrollArea } from "@/components/frames/ScrollArea"
import { StackH, StackV } from "@/components/frames/Stack"
import { ChatBubble } from "@/components/blocks/feed/ChatBubble"
import { UserCell } from "@/components/composites/lists/UserCell"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import type { ChatMessageNode } from "@/modules/api/graphql/queries/types/chat"

/** How many placeholder rows the co-located skeleton shows for the message list. */
const SKELETON_ROW_COUNT = 3

/** All display text, already localized by the connected `ChatPane`; a story passes i18n keys. */
export interface ChatPaneLabels {
    /** Empty-state title — no messages yet. */
    empty: string
    /** Error-state title — the message list failed to load. */
    error: string
    /** Retry-button label paired with {@link ChatPaneProps.onRetry}. */
    retry: string
    /** Composer placeholder / accessible name. */
    placeholder: string
    /** Send-button label. */
    send: string
}

/** Props for {@link _ChatPane} — presentational; all data resolved, no fetch/store/i18n. */
export interface ChatPaneProps {
    /** First load, nothing in hand → the message list shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with zero messages → the empty message. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler for the error branch. */
    onRetry?: () => void
    /** Messages, oldest→newest, already resolved by the connected file. */
    messages?: Array<ChatMessageNode>
    /** `true` while a send is in flight — locks the send button and shows its spinner. */
    isSending?: boolean
    /** Sends the composed body; resolves `true` on success (the composer clears itself), `false` otherwise. */
    onSend: (body: string) => Promise<boolean>
    /** Already-translated copy — see {@link ChatPaneLabels}. */
    labels: ChatPaneLabels
}

/**
 * `_ChatPane` — the presentational half of {@link import(".").ChatPane}: one
 * chat conversation's message list + composer. Three states in the fixed
 * order error → empty → content (`loading-and-skeleton.md`): `error` falls
 * to the shared `AsyncContentError` frame, a settled `isEmpty` to
 * `AsyncContentEmpty`, and otherwise the message list renders with
 * `isSkeleton` threaded down to every leaf that supports it — placeholder
 * rows keep the SAME `ChatBubble` shape as the loaded state, alternating
 * `isMine` the way real messages do so the sender row shows/hides in the
 * same pattern. `UserCell` itself has no `isSkeleton`, so that one sender
 * row is mirrored in place with `Skeleton.UserCell` instead (still
 * co-located, not a parallel tree). Only the message-list zone branches —
 * the composer stays mounted underneath regardless, so a member can still
 * write while the history is loading or failed to load. See
 * `tiers/split.md` — the connected `index.tsx` owns the fetch, the socket
 * subscription, and i18n.
 *
 * @param props - {@link ChatPaneProps}
 */
export const _ChatPane = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    messages = [],
    isSending = false,
    onSend,
    labels,
}: ChatPaneProps) => {
    const [body, setBody] = useState("")

    /** Trim + guard, hand off to the connected sender, clear the composer on success. */
    const onSendPress = useCallback(async () => {
        const trimmed = body.trim()
        if (!trimmed) {
            return
        }
        const ok = await onSend(trimmed)
        if (ok) {
            setBody("")
        }
    }, [body, onSend])

    // Row shape shared by both states: while shimmering, placeholder rows alternate
    // `isMine` the same way real messages do, so the sender row (UserCell) shows/hides
    // in the SAME pattern the loaded list will settle into — nothing collapses or jumps.
    const rows = isSkeleton
        ? Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => ({
            isMine: index % 2 === 1,
            body: undefined as string | undefined,
            author: undefined as ChatMessageNode["author"] | undefined,
            isFounderAuthor: false,
        }))
        : messages.map((message) => ({
            isMine: message.isMine,
            body: message.body as string | undefined,
            author: message.author as ChatMessageNode["author"] | undefined,
            isFounderAuthor: message.isFounderAuthor,
        }))

    const messageRows: Array<ComponentTypeWithSkeleton> = rows.map((row) => () => (
        <StackV gap={2} items={[
            ...(!row.isMine ? [() => (
                isSkeleton || !row.author ? (
                    <Skeleton.UserCell withHandle={false} />
                ) : (
                    <UserCell
                        username={row.author!.username}
                        displayName={row.author!.displayName ?? undefined}
                        avatar={row.author!.avatar ?? undefined}
                        size="sm"
                        trailing={row.isFounderAuthor
                            ? () => <SealCheckIcon weight="fill" className="size-3.5 shrink-0 text-accent-soft-foreground" />
                            : undefined}
                    />
                )
            )] : []),
            () => (
                <ChatBubble role={row.isMine ? "user" : "assistant"}>
                    <Typography size="sm" text={row.body ?? ""} isSkeleton={isSkeleton} />
                </ChatBubble>
            ),
        ]} />
    ))

    return (
        <StackV
            gap={4}
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            identity={{ tier: "block", component: "ChatPane" }}
            items={[
                () => (
                    error ? (
                        <AsyncContentError title={labels.error} onRetry={onRetry} retryLabel={labels.retry} />
                    ) : !isSkeleton && isEmpty ? (
                        <AsyncContentEmpty title={labels.empty} />
                    ) : (
                        // NEW-VOCABULARY GAP: no frame owns "cap this region's height and scroll
                        // it locally" — `ScrollArea`'s `classNames` is a closed, positioning-only
                        // enum (no height values) — so the height cap goes through `Box` (the
                        // sanctioned raw-appearance escape hatch), same shape as `FollowListModal`.
                        <Box className="max-h-[60vh]">
                            <ScrollArea axis="y" body={() => <StackV gap={4} isSkeleton={isSkeleton} items={messageRows} />} />
                        </Box>
                    )
                ),
                () => (
                    <StackV gap={3} principle="flex-action"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        items={[
                            () => (
                                <InputTextarea
                                    variant="secondary"
                                    rows={2}
                                    value={body}
                                    onValueChange={setBody}
                                    placeholder={labels.placeholder}
                                    ariaLabel={labels.placeholder}
                                />
                            ),
                            () => (
                                <StackH gap={1} principle="name-handle"
                                    explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
                                    justify="end" items={[
                                        () => (
                                            <Button
                                                variant="primary"
                                                size="sm"
                                                label={labels.send}
                                                isPending={isSending}
                                                isDisabled={!body.trim()}
                                                onPress={() => void onSendPress()}
                                            />
                                        ),
                                    ]} />
                            ),
                        ]} />
                ),
            ]}
        />
    )
}

