"use client"

import React, {
    useCallback,
    useState,
} from "react"
import {
    Button,
    Card,
    CardContent,
    Chip,
    Spinner,
    TextField,
    Typography,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    SettingsBreadcrumb,
} from "@/components/blocks/settings/SettingsBreadcrumb"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { Callout } from "@/components/composites/feedback/Callout"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { useQueryMyInstallmentPlansSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyInstallmentPlansSwr"
import { useMutatePayNextInstallmentSwr } from "@/hooks/swr/api/graphql/mutations/useMutatePayNextInstallmentSwr"
import type { InstallmentPlanItem } from "@/modules/api/graphql/queries/types/my-installment-plans"
import { PaymentType } from "@/modules/types/enums/payment-type"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import { submitCheckout } from "@/modules/payment/submit-checkout"
import { pathConfig } from "@/resources/path"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"

/** Format an integer VND amount as "1.275.000₫". */
const formatVnd = (amount: number): string => `${amount.toLocaleString("vi-VN")}₫`

/** Chip color per plan lifecycle status — semantic only, never accent. */
const STATUS_COLOR: Record<string, "success" | "warning" | "danger" | "muted"> = {
    Active: "success",
    Overdue: "warning",
    Defaulted: "danger",
    Completed: "muted",
}

/**
 * "My installment plans" — lists the viewer's non-completed installment
 * plans and lets them pay the current cycle.
 *
 * Two render shapes share one list (mirrors `Sessions` — per-plan `Card` with a
 * row action, not a `SurfaceListCard` since each plan is its own bounded object):
 * `Fixed` (fixed monthly amount + `ProgressMeter` "paid N/M installments") and
 * `FlexiblePool` (outstanding balance + an editable amount, floor-clamped to
 * this cycle's minimum). Paying opens the gateway checkout via the shared
 * `payNextInstallment` mutation, then revalidates the list. Mounted by
 * `/profile/settings/installments`.
 */
export const InstallmentPlansPage = () => {
    const t = useTranslations()
    const router = useRouter()
    const {
        data: plans,
        isLoading,
        error,
        mutate,
    } = useQueryMyInstallmentPlansSwr()
    const { trigger: triggerPayNextInstallment } = useMutatePayNextInstallmentSwr()
    const runGraphQL = useGraphQLWithToast()

    // the plan id currently being paid (drives the per-row spinner)
    const [payingId, setPayingId] = useState<string | null>(null)
    // FlexiblePool custom amounts, keyed by plan id — seeded lazily from minPaymentVnd
    const [customAmountByPlan, setCustomAmountByPlan] = useState<Record<string, number>>({})

    const planList = plans ?? []

    /** The amount to charge for a plan — the edited FlexiblePool value, else the minimum. */
    const amountFor = useCallback(
        (plan: InstallmentPlanItem) => customAmountByPlan[plan.id] ?? plan.minPaymentVnd,
        [customAmountByPlan],
    )

    /** Clamp a FlexiblePool amount edit to never go below this cycle's minimum. */
    const onAmountChange = useCallback(
        (plan: InstallmentPlanItem, raw: string) => {
            const digits = Number(raw.replace(/\D/g, ""))
            const clamped = Math.max(digits || 0, plan.minPaymentVnd)
            setCustomAmountByPlan((prev) => ({ ...prev, [plan.id]: clamped }))
        },
        [],
    )

    /** Pay a plan's current cycle (PayOS — the only gateway offered here), then refresh the list. */
    const onPay = useCallback(
        async (plan: InstallmentPlanItem) => {
            setPayingId(plan.id)
            try {
                let checkoutUrl = ""
                let checkoutFields: string | null | undefined
                const success = await runGraphQL(
                    async () => {
                        const amountVnd = plan.planType === "FlexiblePool" ? amountFor(plan) : undefined
                        const response = await triggerPayNextInstallment({
                            planId: plan.id,
                            paymentType: PaymentType.PayOS,
                            returnUrl: window.location.href,
                            cancelUrl: window.location.href,
                            amountVnd,
                        })
                        if (!response.data?.payNextInstallment) {
                            throw new Error(response.error?.message)
                        }
                        const data = response.data.payNextInstallment.data
                        checkoutUrl = data?.checkoutUrl ?? ""
                        checkoutFields = data?.checkoutFields
                        return response.data.payNextInstallment
                    },
                    {
                        showSuccessToast: false,
                        showErrorToast: true,
                    },
                )
                if (success && checkoutUrl) {
                    submitCheckout({ checkoutUrl, checkoutFields })
                }
            } finally {
                setPayingId(null)
            }
        },
        [runGraphQL, triggerPayNextInstallment, amountFor],
    )

    return (
        <StackV gap={7} principle="layout-split"
        explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
        items={[
            () => (
                <PageHeader
                    breadcrumb={<SettingsBreadcrumb current={t("installmentPlans.title")} />}
                    title={t("installmentPlans.title")}
                    description={t("installmentPlans.subtitle")}
                />
            ),

            () => (
                <AsyncContent
                    isLoading={isLoading && !plans}
                    skeleton={(
                        <StackV gap={4} principle="content-row" items={[0, 1].map((row) => () => (
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            <Skeleton key={row} className="h-40 w-full rounded-2xl" />
                        ))} />
                    )}
                    isEmpty={planList.length === 0}
                    emptyContent={{
                        title: t("installmentPlans.empty"),
                        description: t("installmentPlans.emptyDesc"),
                        onRetry: () => router.push(pathConfig().locale().course().build()),
                        retryLabel: t("installmentPlans.emptyCta"),
                    }}
                    error={error}
                    errorContent={{
                        title: t("installmentPlans.empty"),
                        onRetry: () => { void mutate() },
                    }}
                >
                    <StackV gap={4} principle="content-row" items={planList.map((plan) => () => {
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                        const isFixed = plan.planType === "Fixed"
                        const isLocked = plan.status === "Defaulted"
                        const statusColor = STATUS_COLOR[plan.status] ?? "muted"
                        const isPaying = payingId === plan.id
                        return (
                            <Card key={plan.id}>
                                <CardContent>
                                    <StackV gap={4} principle="content-row"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    items={[
                                        () => (
                                            <StackH gap={4} principle="content-row" justify="between" align="center"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            items={[
                                                () => (
                                                    <Chip
                                                        size="sm"
                                                        variant="soft"
                                                        color={statusColor === "muted" ? "default" : statusColor}
                                                    >
                                                        <Chip.Label>{t(`installmentPlans.status.${plan.status}`)}</Chip.Label>
                                                    </Chip>
                                                ),
                                                () => (
                                                    <Typography type="body-xs" color="muted">
                                                        {isFixed
                                                            ? t("installmentPlans.termMonths", { months: plan.months ?? 0 })
                                                            : t("installmentPlans.flexiblePool")}
                                                    </Typography>
                                                ),
                                            ]} />
                                        ),

                                        () => (plan.courses.length > 0 ? (
                                            <Cluster gap={3} principle="chip-row" items={plan.courses.map((course) => () => (
                                            explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                                <Chip key={course.id} size="sm" variant="soft" color="default">
                                                    <Chip.Label>{course.title}</Chip.Label>
                                                </Chip>
                                            ))} />
                                        ) : null),

                                        () => (isFixed ? (
                                            <>
                                                <StackH gap={4} principle="content-row" justify="between" align="center" items={[() => (
                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    <Typography type="body-sm" weight="semibold">
                                                        {formatVnd(plan.monthlyAmountVnd ?? 0)}
                                                        <Typography type="body-xs" color="muted" className="ml-1 inline">
                                                            {t("installmentPlans.perCycle")}
                                                        </Typography>
                                                    </Typography>
                                                )]} />
                                                <ProgressMeter
                                                    value={plan.installmentsPaid ?? 0}
                                                    max={plan.months ?? 1}
                                                    label={t("installmentPlans.progress", {
                                                        paid: plan.installmentsPaid ?? 0,
                                                        months: plan.months ?? 0,
                                                    })}
                                                />
                                            </>
                                        ) : (
                                            <>
                                                <StackH gap={4} principle="content-row" justify="between" align="center"
                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                items={[
                                                    () => (
                                                        <Typography type="body-sm" color="muted">
                                                            {t("installmentPlans.remaining")}
                                                        </Typography>
                                                    ),
                                                    () => (
                                                        <Typography type="body-sm" weight="semibold">
                                                            {formatVnd(plan.remainingVnd ?? 0)}
                                                        </Typography>
                                                    ),
                                                ]} />
                                                <Typography type="body-xs" color="muted">
                                                    {t("installmentPlans.minPaymentFormula", {
                                                        percent: plan.minPaymentPercent ?? 0,
                                                        floor: formatVnd(plan.minPaymentFloorVnd ?? 0),
                                                    })}
                                                </Typography>
                                                <StackH gap={3} principle="identity" align="center"
                                                explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                                                items={[
                                                    () => (
                                                        <TextField
                                                            className="max-w-[160px]"
                                                            value={amountFor(plan).toLocaleString("vi-VN")}
                                                            onChange={(value) => onAmountChange(plan, value)}
                                                            isDisabled={isPaying}
                                                            aria-label={t("installmentPlans.amountLabel")}
                                                        />
                                                    ),
                                                    () => (
                                                        <Typography type="body-xs" color="muted">
                                                            {t("installmentPlans.minLabel", { amount: formatVnd(plan.minPaymentVnd) })}
                                                        </Typography>
                                                    ),
                                                ]} />
                                            </>
                                        )),

                                        () => (isLocked ? (
                                            <Callout
                                                status="danger"
                                                title={t("installmentPlans.lockedTitle")}
                                                description={t("installmentPlans.lockedDesc")}
                                            />
                                        ) : null),

                                        () => (
                                            <StackH gap={4} principle="content-row" justify="between" align="center"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            items={[
                                                () => (
                                                    <Typography type="body-xs" color="muted">
                                                        {plan.nextDueAt
                                                            ? t("installmentPlans.nextDue", { date: new Date(plan.nextDueAt).toLocaleDateString("vi-VN") })
                                                            : ""}
                                                    </Typography>
                                                ),
                                                () => (
                                                    <Button
                                                        variant={isLocked ? "danger" : "primary"}
                                                        size="sm"
                                                        isDisabled={isPaying}
                                                        onPress={() => { void onPay(plan) }}
                                                    >
                                                        {isPaying ? (
                                                            <Spinner size="sm" color="current" />
                                                        ) : isLocked ? (
                                                            t("installmentPlans.unlock")
                                                        ) : isFixed ? (
                                                            t("installmentPlans.payThisCycle")
                                                        ) : (
                                                            t("installmentPlans.pay")
                                                        )}
                                                    </Button>
                                                ),
                                            ]} />
                                        ),
                                    ]} />
                                </CardContent>
                            </Card>
                        )
                    })} />
                </AsyncContent>
            ),
        ]} />
    )
}

import React, { useState } from "react"
import type { ReactNode } from "react"
import { BriefcaseIcon, FunnelIcon, TrayIcon } from "@phosphor-icons/react"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { Badge } from "@/components/atoms/display/Badge"
import { Button } from "@/components/atoms/buttons/Button"
import { Popover } from "@/components/atoms/overlay/Popover"
import { Typography } from "@/components/atoms/text/Typography"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Cluster } from "@/components/frames/Cluster"
import { Container } from "@/components/frames/Container"
import { StackH, StackV } from "@/components/frames/Stack"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { SearchInput } from "@/components/blocks/form/SearchInput"
import { FlexWrapButtonRadio, type FlexWrapButtonRadioItem } from "@/components/blocks/navigation/FlexWrapButtonRadio"
import { Pagination } from "@/components/blocks/navigation/Pagination"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import type { JobPostingEntity } from "@/modules/types/entities/job-posting"
import { JobEmploymentType } from "@/modules/types/enums/job-employment-type"
import { WorkMode } from "@/modules/types/enums/work-mode"
import { JobListRow } from "./JobListRow"

/** Single-select work-mode filter value — `"all"` clears the filter. */
export type WorkModeFilterValue = "all" | WorkMode
/** Single-select employment-type filter value — `"all"` clears the filter. */
export type EmploymentTypeFilterValue = "all" | JobEmploymentType

/** How many placeholder rows the co-located skeleton shows while the first page loads. */
const SKELETON_ROW_COUNT = 6

/** All display text, already localized by the connected {@link import("./index").JobListPage}; a story passes i18n keys. */
export interface JobListLabels {
    pageTitle: string
    pageDescription: string
    postCta: string
    searchPlaceholder: string
    filterButtonAria: string
    workModeHeading: string
    workModeAria: string
    employmentTypeHeading: string
    employmentTypeAria: string
    clearFacets: string
    /** Already interpolated with the total count (e.g. "3 postings"). */
    found: string
    emptyPlatformTitle: string
    emptyPlatformDescription: string
    emptyPlatformCta: string
    emptyFilteredTitle: string
    emptyFilteredClearFilters: string
    errorTitle: string
    retry: string
}

/** Props for {@link _JobListPage} — presentational; all data resolved, no fetch/store/i18n. */
export interface JobListPageProps {
    /** First load, nothing in hand → the row list shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with zero matching postings → the empty branch. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retries the failed fetch. */
    onRetry?: () => void
    /** The current page of postings, already resolved. */
    items?: Array<JobPostingEntity>
    /** `true` → the board itself has zero postings (no filter applied); `false` → a filtered search matched nothing. */
    isPlatformEmpty?: boolean
    /** Clears search + every facet — the filtered-empty branch's retry action. */
    onClearFilters?: () => void
    /** Opens the "post a job" flow — the header CTA AND the platform-empty branch's action. */
    onPostJob: () => void

    /** Current search query (controlled). */
    search: string
    /** Fired with the new query on every keystroke. */
    onSearchChange: (value: string) => void
    /** Currently selected work-mode facet. */
    workModeFilter: WorkModeFilterValue
    onWorkModeFilterChange: (value: WorkModeFilterValue) => void
    /** Work-mode facet options, already localized. */
    workModeItems: Array<FlexWrapButtonRadioItem<WorkModeFilterValue>>
    /** Currently selected employment-type facet. */
    employmentTypeFilter: EmploymentTypeFilterValue
    onEmploymentTypeFilterChange: (value: EmploymentTypeFilterValue) => void
    /** Employment-type facet options, already localized. */
    employmentTypeItems: Array<FlexWrapButtonRadioItem<EmploymentTypeFilterValue>>
    /** Facets currently applied (0–2) — badges the filter trigger. */
    activeFacetCount: number
    /** Resets both facet rows without touching the search box. */
    onClearFacets: () => void

    /** 1-based current page. */
    page: number
    totalPages: number
    onPageChange: (page: number) => void

    labels: JobListLabels
}

/**
 * Loading placeholder for one job-posting row — mirrors {@link JobListRow}'s
 * IconTile + title/company/meta + salary/time shape so the list does not
 * collapse or jump when data resolves. Co-located right here (not a separate
 * hand-kept file) since `JobListRow` takes no `isSkeleton` prop of its own to
 * thread through (`loading-and-skeleton.md`).
 */
const JobListRowSkeleton = () => (
    <SurfaceListCardItem>
        <StackH
            gap={4}
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            align="center"
            items={[
                () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                () => (
                    <StackV
                        gap={2}
                        principle="title-subtitle"
                        explain="Title over supporting line — not label-field, because neither line is a form control label."
                        classNames={["min-w-0", "flex-1"]}
                        items={[
                            () => <Skeleton.Typography type="body-sm" width="1/2" />,
                            () => <Skeleton.Typography type="body-xs" width="1/3" />,
                            () => (
                                <Cluster
                                    gap={3}
                                    principle="chip-row"
                                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                    items={[
                                        () => <Skeleton.Typography type="body-xs" width="1/4" />,
                                        () => <Skeleton.Chip />,
                                    ]}
                                />
                            ),
                        ]}
                    />
                ),
                () => (
                    <StackV
                        gap={2}
                        principle="title-subtitle"
                        explain="Title over supporting line — not label-field, because neither line is a form control label."
                        align="end"
                        classNames={["shrink-0"]}
                        items={[
                            () => <Skeleton.Typography type="body-sm" width="full" className="w-16" />,
                            () => <Skeleton.Typography type="body-xs" width="full" className="w-12" />,
                        ]}
                    />
                ),
            ]}
        />
    </SurfaceListCardItem>
)

/**
 * The job board (`/jobs`) — the presentational half of {@link import("./index").JobListPage}. Search +
 * two single-select filter rows (work mode, employment type) behind a funnel popover drive a
 * paginated ROW LIST (not a card grid — a posting has too many attributes — title, company,
 * location, work mode, salary — to read comfortably in a tile; every real job board renders rows).
 * Public — works for anonymous viewers.
 *
 * The header + search/filter toolbar always render; only the row-list region below switches
 * error → (settled) empty → content, with `isSkeleton` threaded to every leaf that can mirror
 * itself (`loading-and-skeleton.md`). `JobListRow` (a sibling component owned outside this pass)
 * takes no `isSkeleton` prop, so the loading branch mirrors it minimally with the co-located
 * `JobListRowSkeleton` at the SAME position and the SAME row count — not a parallel tree.
 *
 * Two distinct empty states (per the brainstorm's cold-start marketplace note): a filtered search
 * with zero matches offers a "clear filters" affordance, while a genuinely empty board (no postings
 * at all, yet) becomes a two-sided funnel — "no listings yet — is your company hiring? post one
 * free" — instead of a dead end.
 *
 * @param props - {@link JobListPageProps}
 */
export const _JobListPage = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    items = [],
    isPlatformEmpty = false,
    onClearFilters,
    onPostJob,
    search,
    onSearchChange,
    workModeFilter,
    onWorkModeFilterChange,
    workModeItems,
    employmentTypeFilter,
    onEmploymentTypeFilterChange,
    employmentTypeItems,
    activeFacetCount,
    onClearFacets,
    page,
    totalPages,
    onPageChange,
    labels,
}: JobListPageProps) => {
    // funnel popover open state — purely visual, needs no server/store/session (split.md's own test)
    const [filterOpen, setFilterOpen] = useState(false)

    const emptyPlatformAction: ComponentTypeWithSkeleton = () => (
        <Button variant="tertiary" size="sm" label={labels.emptyPlatformCta} onPress={onPostJob} />
    )

    const filterPopoverContent = (
        <StackV gap={3} items={[
            () => (
                <StackV gap={2} items={[
                    () => <Typography size="xs" color="muted" text={labels.workModeHeading} />,
                    () => (
                        <FlexWrapButtonRadio<WorkModeFilterValue>
                            ariaLabel={labels.workModeAria}
                            value={workModeFilter}
                            onChange={onWorkModeFilterChange}
                            items={workModeItems}
                        />
                    ),
                ]} />
            ),
            () => (
                <StackV gap={2} items={[
                    () => <Typography size="xs" color="muted" text={labels.employmentTypeHeading} />,
                    () => (
                        <FlexWrapButtonRadio<EmploymentTypeFilterValue>
                            ariaLabel={labels.employmentTypeAria}
                            value={employmentTypeFilter}
                            onChange={onEmploymentTypeFilterChange}
                            items={employmentTypeItems}
                        />
                    ),
                ]} />
            ),
            ...(activeFacetCount > 0 ? [() => (
                <Button variant="danger-soft" size="sm" label={labels.clearFacets} onPress={onClearFacets} classNames={["self-start"]} />
            )] : []),
        ]} />
    )

    // toolbar: search + funnel popover on the left, the resolved count on the right —
    // always rendered, unaffected by the row-list region's own error/empty/content switch
    const toolbar = (
        <StackH gap={3} principle="flex-action" justify="between" align="center" at="sm"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            items={[
                () => (
                    <StackH gap={3} principle="flex-action" align="center" classNames={["min-w-0", "flex-1"]}
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        items={[
                            () => (
                                <SearchInput
                                    className="min-w-0 flex-1"
                                    value={search}
                                    onValueChange={onSearchChange}
                                    placeholder={labels.searchPlaceholder}
                                />
                            ),
                            () => (
                                <Badge count={activeFacetCount} color="accent" size="sm" placement="top-left">
                                    <Popover
                                        triggerLabel={<span className="sr-only">{labels.filterButtonAria}</span>}
                                        triggerIcon={FunnelIcon}
                                        triggerVariant="ghost"
                                        isOpen={filterOpen}
                                        onOpenChange={setFilterOpen}
                                        classNames={["shrink-0"]}
                                        content={filterPopoverContent}
                                    />
                                </Badge>
                            ),
                        ]} />
                ),
                () => <Typography size="sm" color="muted" classNames={["shrink-0"]} text={labels.found} />,
            ]} />
    )

    // row-list region — the ONLY part of this block that switches state; the header +
    // toolbar above always render regardless of error/loading/empty/content.
    let listRegion: ReactNode
    if (error) {
        listRegion = <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    } else if (!isSkeleton && isEmpty) {
        listRegion = isPlatformEmpty ? (
            <AsyncContentEmpty
                icon={BriefcaseIcon}
                title={labels.emptyPlatformTitle}
                description={labels.emptyPlatformDescription}
                action={emptyPlatformAction}
            />
        ) : (
            <AsyncContentEmpty
                icon={TrayIcon}
                title={labels.emptyFilteredTitle}
                onRetry={onClearFilters}
                retryLabel={labels.emptyFilteredClearFilters}
            />
        )
    } else {
        // rows — while shimmering, the SAME position holds SKELETON_ROW_COUNT placeholder
        // rows (JobListRow takes no isSkeleton prop, so the mirror is JobListRowSkeleton,
        // co-located here rather than a separate branch — see missingSkeletonSupport).
        listRegion = (
            <StackV gap={3} items={[
                () => (
                    <SurfaceListCard>
                        {isSkeleton
                            ? Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => (
                                <JobListRowSkeleton key={index} />
                            ))
                            : items.map((job) => <JobListRow key={job.id} job={job} />)}
                    </SurfaceListCard>
                ),
                // pager: left-aligned with the rows, hidden on a single page
                ...(totalPages > 1 ? [() => (
                    <Pagination
                        className="mt-0 justify-start"
                        currentPage={page}
                        totalPages={totalPages}
                        onPageChange={onPageChange}
                    />
                )] : []),
            ]} />
        )
    }

    const jobListBody = (
        <StackV gap={8} items={[
            () => (
                <PageHeader
                    title={labels.pageTitle}
                    description={labels.pageDescription}
                    actions={<Button variant="secondary" label={labels.postCta} onPress={onPostJob} />}
                />
            ),
            () => toolbar,
            () => listRegion,
        ]} />
    )

    return (
        <Container
            size="md"
            padding={6}
            body={() => jobListBody}
            identity={{ tier: "block", component: "JobListPage" }}
        />
    )
}

"use client"

import React from "react"
import {
    Button,
    Chip,
    cn,
    Typography,
} from "@heroui/react"
import {
    BuildingsIcon,
    CaretRightIcon,
    CheckCircleIcon,
    LightningIcon,
    RocketLaunchIcon,
} from "@phosphor-icons/react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { pathConfig } from "@/resources/path"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { LANDING_SAMPLE_CANDIDATE } from "../constants"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { SectionHeading } from "@/components/blocks/marketing/SectionHeading"
import { ShowcaseMockup, SHOWCASE_THEMES } from "@/components/blocks/marketing/ShowcaseMockup"
import { UserAvatar } from "@/components/blocks/identity/UserAvatar"
import { StackH, StackV } from "@/components/frames/Stack"

/** Props for {@link TalentMarketplace}. */
export type TalentMarketplaceProps = WithClassNames<undefined>

/** One flat "journey" row (engineer / company) — icon tile + claim + proof copy. */
const JourneyRow = ({
    icon,
    title,
    body,
}: {
    icon: React.ReactNode
    title: string
    body: string
}) => (
    <StackH gap={4} align="start" principle="content-row"
        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
        items={[
            () => <IconTile icon={icon} tone="accent" size="md" />,
            () => (
                <StackV gap={3} principle="sibling-stack"
                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                    items={[
                        () => <Typography type="h5" weight="semibold">{title}</Typography>,
                        () => <Typography type="body-sm" color="muted">{body}</Typography>,
                    ]} />
            ),
        ]} />
)

/** One label → value stat line inside the sample candidate card. */
const StatLine = ({ label, value }: { label: string; value: string }) => (
    <StackH gap={4} justify="between" principle="content-row"
        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
        items={[
            () => <Typography type="body-sm" color="muted">{label}</Typography>,
            () => <Typography type="body-sm" weight="medium">{value}</Typography>,
        ]} />
)

/**
 * Static sample candidate card — an illustrative "engineer profile" rendered as
 * a mini browser window (ShowcaseMockup chrome + profile URL), mirroring the real
 * public profile page: rank avatar, open-to-work badge, CV score, system
 * challenges, skills, XP. NOT backed by an API; numbers come from
 * {@link LANDING_SAMPLE_CANDIDATE}. Labels via `landing.outcome.card.*`.
 */
const SampleCandidateCard = () => {
    const t = useTranslations()
    const locale = useLocale()
    const c = LANDING_SAMPLE_CANDIDATE

    return (
        <ShowcaseMockup
            url={`starci.academy/profile/${c.slug}`}
            theme={SHOWCASE_THEMES.starci}
            backdrop="glow"
            contentClassName="flex flex-col gap-3 p-4"
        >
            <StackH gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => <UserAvatar username={c.name} avatar={c.avatarUrl} seed={c.name} className="size-14 !rounded-full" />,
                    () => (
                        <div className="flex min-w-0 flex-col gap-0">
                            <Typography type="body" weight="semibold" truncate>
                                {c.name}
                            </Typography>
                            <Typography type="body-xs" color="muted" truncate>
                                {t("landing.outcome.card.role")}
                            </Typography>
                        </div>
                    ),
                ]} />

            <Chip variant="soft" color="success" size="sm" className="self-start">
                <CheckCircleIcon aria-hidden focusable="false" className="size-4" />
                <Chip.Label>{t("landing.outcome.card.openToWork")}</Chip.Label>
            </Chip>

            <div data-principle="sibling-stack" className="flex flex-col gap-2 border-t border-default pt-3">
                <StatLine
                    label={t("landing.outcome.card.cvScore")}
                    value={`${c.cvScore} / 100`}
                />
                <StatLine
                    label={t("landing.outcome.card.challenges")}
                    value={t("landing.outcome.card.challengeValue", {
                        count: c.challengeCount,
                        avg: c.challengeAvg,
                    })}
                />
            </div>

            <div data-principle="chip-row" className="flex flex-wrap items-center gap-2 border-t border-default pt-3">
                {c.skills.map((skill) => (
                    <Chip key={skill} variant="soft" color="default" size="sm">
                        <Chip.Label>{skill}</Chip.Label>
                    </Chip>
                ))}
                <span data-principle="push-end" className="ml-auto inline-flex items-center gap-2 text-sm text-muted">
                    <LightningIcon aria-hidden focusable="false" className="size-4 text-muted" />
                    {t("landing.outcome.card.xp", { xp: c.xp.toLocaleString(locale) })}
                </span>
            </div>
        </ShowcaseMockup>
    )
}

/**
 * Two-sided talent marketplace beat — the engineer / company outcome split,
 * product-led: the left column states each journey + its CTA, the right column
 * SHOWS the candidate card a recruiter browses (a static sample). Pure +
 * navigation only (no API); replaces the old outcome cards + recruiter-proof beat.
 *
 * @param props - optional className (placement only).
 */
export const TalentMarketplace = ({ className }: TalentMarketplaceProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()

    const onBuildPortfolio = () => router.push(pathConfig().locale(locale).course().build())
    const onBrowseTalents = () => router.push(pathConfig().locale(locale).talents().build())
    const onBrowseJobs = () => router.push(pathConfig().locale(locale).jobs().build())

    return (
        <section className={cn("flex flex-col gap-16", className)}>
            <SectionHeading
                eyebrow={t("landing.outcome.eyebrow")}
                title={t("landing.outcome.title")}
            />
            <div className="grid grid-cols-1 gap-x-12 gap-y-20 @app-lg:grid-cols-2 @app-lg:items-center">
                {/* Left — two journeys + separate CTAs */}
                <StackV gap={6} principle="block-boundary"
                    explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                    items={[
                        () => (
                            <StackV gap={6} principle="block-boundary"
                                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                                items={[
                                    () => (
                                        <JourneyRow
                                            icon={<RocketLaunchIcon aria-hidden focusable="false" />}
                                            title={t("landing.outcome.items.engineer.title")}
                                            body={t("landing.outcome.items.engineer.body")}
                                        />
                                    ),
                                    () => (
                                        <JourneyRow
                                            icon={<BuildingsIcon aria-hidden focusable="false" />}
                                            title={t("landing.outcome.items.enterprise.title")}
                                            body={t("landing.outcome.items.enterprise.body")}
                                        />
                                    ),
                                ]} />
                        ),
                        () => (
                            <div data-principle="content-row" className="flex flex-wrap items-center gap-3">
                                <Button variant="primary" size="lg" onPress={onBuildPortfolio}>
                                    <RocketLaunchIcon aria-hidden focusable="false" className="size-5" />
                                    {t("landing.outcome.items.engineer.cta")}
                                </Button>
                                <Button variant="secondary" size="md" onPress={onBrowseTalents}>
                                    {t("landing.outcome.items.enterprise.cta")}
                                    <CaretRightIcon aria-hidden focusable="false" weight="bold" className="size-4" />
                                </Button>
                                <Button variant="tertiary" onPress={onBrowseJobs}>
                                    {t("landing.outcome.items.engineer.jobsCta")}
                                    <CaretRightIcon aria-hidden focusable="false" weight="bold" className="size-4" />
                                </Button>
                            </div>
                        ),
                    ]} />

                {/* Right — sample candidate card (static) */}
                <SampleCandidateCard />
            </div>
        </section>
    )
}

"use client"

import React from "react"
import {
    Accordion,
    Button,
    Link,
    Typography,
} from "@heroui/react"
import {
    ArrowRightIcon,
    ArrowUpIcon,
    CaretRightIcon,
    CloudArrowUpIcon,
    CubeIcon,
    StackIcon,
    TreeStructureIcon,
    UserIcon,
} from "@phosphor-icons/react"
import { FaFacebook, FaGithub, FaLinkedin } from "react-icons/fa6"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import dynamic from "next/dynamic"
/** Hero architecture diagram in real 3D (WebGL/R3F). Client-only — never SSRs;
 * while the WebGL chunk loads, show a neutral sized skeleton (the old fallback
 * was a *different* SVG diagram → jarring swap to the 3D scene). */
const ArchitectureScene3D = dynamic(
    () => import("@/components/blocks/marketing/ArchitectureScene").then((m) => m.ArchitectureScene),
    {
        ssr: false,
        loading: () => (
            <div
                aria-hidden
                className="h-[440px] w-full animate-pulse rounded-3xl bg-default/20 @app-sm:h-[560px]"
            />
        ),
    },
)
import { pathConfig } from "@/resources/path"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { FOUNDER_FACEBOOK, FOUNDER_GITHUB, FOUNDER_LINKEDIN } from "@/resources/contact"
import { StatStrip } from "./StatStrip"
import { TalentMarketplace } from "./TalentMarketplace"
import { LearnLoopScroll } from "./LearnLoopScroll"
import { KnowledgeGraph } from "./KnowledgeGraph"
import { KNOWLEDGE_NODES } from "./KnowledgeGraph/data"
import {
    LANDING_COURSE_TRACKS,
    LANDING_FAQ_INDEXES,
    LANDING_FOUNDER_TRUTH_INDEXES,
    LANDING_HERO_KEYWORDS,
    LANDING_ROADMAP_TIERS,
    LANDING_TRACK_COURSE_SLUG,
} from "./constants"
import { HeroBanner } from "@/components/blocks/marketing/HeroBanner"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { SectionHeading } from "@/components/blocks/marketing/SectionHeading"
import { TrackCard } from "@/components/blocks/marketing/TrackCard"
import { TruthList } from "@/components/blocks/marketing/TruthList"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/** Icon per featured course track. */
const COURSE_TRACK_ICONS: Record<string, React.ReactNode> = {
    fullstack: <StackIcon aria-hidden focusable="false" />,
    systemDesign: <TreeStructureIcon aria-hidden focusable="false" />,
    devops: <CloudArrowUpIcon aria-hidden focusable="false" />,
}

/** Metro line colour per track. */
const TRACK_LINE_COLOR: Record<string, "accent" | "success" | "warning"> = {
    fullstack: "accent",
    systemDesign: "success",
    devops: "warning",
}

/** Founder social proof links (brand-icon row in the founder beat). */
const FOUNDER_SOCIALS = [
    { key: "github", href: FOUNDER_GITHUB, icon: FaGithub, label: "GitHub" },
    { key: "linkedin", href: FOUNDER_LINKEDIN, icon: FaLinkedin, label: "LinkedIn" },
    { key: "facebook", href: FOUNDER_FACEBOOK, icon: FaFacebook, label: "Facebook" },
] as const

/** Props for {@link LandingPage}. */
export type LandingPageProps = WithClassNames<undefined>

/**
 * Public landing page. Show-don't-tell information architecture: hero → live
 * proof → the wedge (challenge + AI grading) → track ladder → founder beat →
 * recruiter proof → two-sided outcomes → course catalog (conversion) → FAQ →
 * closing CTA. Real data only (platform stats, open-to-work talent, courses);
 * narrative beats stay tight. Container reads SWR + i18n and composes blocks;
 * all styling lives in the blocks.
 *
 * @param props - optional className (placement only).
 */
export const LandingPage = ({ className }: LandingPageProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()

    /** Smooth-scroll to the embedded course catalog (the conversion surface). */
    const onSeeCourses = () => {
        document.getElementById("courses")?.scrollIntoView({ behavior: "smooth" })
    }
    const onLogin = () => router.push(pathConfig().locale(locale).authentication().build())

    // Back-to-top FAB — shows after scrolling past the first screen (scrollY > 600), click smooth-scrolls back to the top.
    const [showTop, setShowTop] = React.useState(false)
    React.useEffect(() => {
        const onScroll = () => setShowTop(window.scrollY > 600)
        window.addEventListener("scroll", onScroll, { passive: true })
        onScroll()
        return () => window.removeEventListener("scroll", onScroll)
    }, [])

    // HERO only fills the first fold (min-height = viewport − navbar, dvh prevents the mobile
    // URL bar from causing jumps, vertically centered). Other beats shrink to their content
    // (no min-h) → no more "half-empty screen", and rhythm is even via the root gap.
    const screen = "flex min-h-[calc(100dvh-4rem)] flex-col justify-center"

    return (
        <div className={className}>
            {/* Section-to-section rhythm: gap-16→20 (64–80px) between beats. ONLY the HERO is
                min-h-screen; other beats shrink to their content → this small gap is REAL
                whitespace, enough to separate sections without a short section (stats,
                learn-loop) drifting in the middle of a half-empty screen. */}
            <Box principle="center-measure" className="mx-auto flex max-w-6xl flex-col gap-16 px-4 pt-8 pb-16 @app-sm:px-6 @app-md:gap-20 @app-md:pb-20 @app-md:pt-10 @app-lg:px-8"
                explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport.">
                {/* 1 — Hero */}
                <div className={screen}>
                    <HeroBanner
                        eyebrow={t("landing.hero.eyebrow")}
                        eyebrowIcon={<CubeIcon aria-hidden focusable="false" className="size-3" />}
                        headline={t.rich("landing.hero.headline", {
                            accent: (chunks) => <span className="text-accent-soft-foreground">{chunks}</span>,
                        })}
                        subline={t("landing.hero.subline")}
                        primary={(
                            <Button variant="primary" size="lg" onPress={onSeeCourses}>
                                {t("landing.hero.ctaPrimary")}
                                <ArrowRightIcon aria-hidden focusable="false" className="size-5" />
                            </Button>
                        )}
                        secondary={(
                            <Button variant="secondary" size="lg" onPress={onLogin}>
                                {t("landing.hero.ctaSecondary")}
                            </Button>
                        )}
                        keywords={LANDING_HERO_KEYWORDS}
                        keywordsLabel={t("landing.hero.solveWith")}
                        visual={(
                        // grounded StarCi backend topology in real 3D (R3F) — the System Design
                        // value prop made visible (no image; client-only, SVG fallback while loading).
                            <ArchitectureScene3D caption={t("landing.hero.diagramCaption")} />
                        )}
                    />
                </div>

                {/* 2 — Live proof strip + "transparent" header: frames REAL numbers (early,
                    small) as an honest signal instead of bragging. Header → strip = gap-16
                    (synced with other sections); spacing between beats is handled by the root gap. */}
                <div id="stats" className="flex scroll-mt-24 flex-col gap-16">
                    <SectionHeading
                        anchorId="stats"
                        eyebrow={t("landing.stats.eyebrow")}
                        title={t("landing.stats.title")}
                        intro={t("landing.stats.intro")}
                    />
                    <StatStrip />
                </div>

                {/* 3 — 4-step learn loop (read → grade → capstone → rank): scroll-pinned
                    scrollytelling (section pins, scroll → active step + visual must change;
                    scroll finishes → releases). Falls back to a static layout on
                    mobile / reduced-motion. */}
                <LearnLoopScroll />

                {/* 3 — Roadmap: 3 flagship tracks. Each card = identity (icon/module/tag/title/desc)
                    + tier path (foundation → application) + "Enter course" → the real course. Merged
                    from 2 old sections (Courses + Roadmap) since track = course → avoids rendering
                    the same 3 tracks twice. */}
                <section id="courses" className="flex scroll-mt-24 flex-col gap-12">
                    <SectionHeading
                        anchorId="courses"
                        eyebrow={t("landing.courses.eyebrow")}
                        title={t("landing.courses.title")}
                        intro={t("landing.courses.intro")}
                    />
                    {/* "Three roadmaps · one mindset": each track = 1 self-contained card (identity +
                        a VERTICAL 4-tier path foundation→application + "Enter course" → the real
                        course). 3 cards side by side to read + compare; the same 4-tier structure
                        = "one mindset". */}
                    <Box principle="block-boundary" className="grid grid-cols-1 gap-6 @app-md:grid-cols-3"
                        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups.">
                        {LANDING_COURSE_TRACKS.map((key) => (
                            <TrackCard
                                key={key}
                                icon={COURSE_TRACK_ICONS[key]}
                                title={t(`landing.courses.items.${key}.title`)}
                                meta={`${t(`landing.courses.items.${key}.modules`)} · ${t(`landing.courses.items.${key}.systems`)}`}
                                color={TRACK_LINE_COLOR[key]}
                                tiers={LANDING_ROADMAP_TIERS[key]}
                                viewLabel={t("landing.courses.view")}
                                onView={() => router.push(pathConfig().locale(locale).course(LANDING_TRACK_COURSE_SLUG[key]).build())}
                            />
                        ))}
                    </Box>
                </section>

                {/* Skill map — SPLIT: "flex your skills" copy (left) + knowledge graph contained
                    (right). The graph is NO LONGER full-bleed (no more "sprawling everywhere") but
                    keeps the interactive wow factor. */}
                <section id="treasure" className="scroll-mt-24">
                    <div className="grid grid-cols-1 items-center gap-10 @app-lg:grid-cols-[0.85fr_1.15fr] @app-lg:gap-12">
                        {/* LEFT — flex copy: heading + editorial stat + interconnection line + CTA */}
                        <StackV gap={6} principle="block-boundary"
                            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                            items={[
                                () => (
                                    <SectionHeading
                                        anchorId="treasure"
                                        align="start"
                                        eyebrow={t("landing.treasure.eyebrow")}
                                        title={t("landing.treasure.title")}
                                        intro={t("landing.treasure.intro")}
                                    />
                                ),
                                () => (
                                    <StackH gap={6} principle="block-boundary"
                                        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                                        items={[
                                            () => (
                                                <div className="flex flex-col">
                                                    <span className="text-3xl font-medium tracking-tight text-foreground @app-sm:text-4xl">
                                                        {KNOWLEDGE_NODES.length}
                                                    </span>
                                                    <Typography type="body-xs" color="muted">
                                                        {t("landing.treasure.statConcepts")}
                                                    </Typography>
                                                </div>
                                            ),
                                            () => <span aria-hidden className="h-10 w-px bg-default" />,
                                            () => (
                                                <div className="flex flex-col">
                                                    <span className="text-3xl font-medium tracking-tight text-foreground @app-sm:text-4xl">
                                                        {LANDING_COURSE_TRACKS.length}
                                                    </span>
                                                    <Typography type="body-xs" color="muted">
                                                        {t("landing.treasure.statTracks")}
                                                    </Typography>
                                                </div>
                                            ),
                                        ]} />
                                ),
                                () => (
                                    <Typography type="body-sm" color="muted">
                                        {t("landing.treasure.interconnect")}
                                    </Typography>
                                ),
                                () => (
                                    <Button variant="primary" size="lg" onPress={onSeeCourses} className="self-start">
                                        {t("landing.treasure.cta")}
                                        <ArrowRightIcon aria-hidden focusable="false" className="size-5" />
                                    </Button>
                                ),
                            ]} />
                        {/* RIGHT — knowledge graph contained: ~38 REAL concepts (nodes) linked by
                            builds-on + cross-track relations (d3-force live, drag/zoom). Node colour
                            follows its track, click → the course containing it. "Interconnected
                            knowledge" (Qdrant vibe, @xyflow). */}
                        <KnowledgeGraph />
                    </div>
                </section>

                {/* 5 — Founder beat */}
                <section id="founder" className="flex scroll-mt-24 flex-col gap-12">
                    <SectionHeading
                        anchorId="founder"
                        eyebrow={t("landing.founder.eyebrow")}
                        title={t("landing.founder.title")}
                        intro={t("landing.founder.thesis")}
                    />
                    {/* the uncomfortable truths are the hero; the founder recedes to a
                        byline (who's saying this), each truth anchored to a real mechanism */}
                    <TruthList
                        items={LANDING_FOUNDER_TRUTH_INDEXES.map((index) => ({
                            truth: t(`landing.founder.truth${index}`),
                            fix: t(`landing.founder.fix${index}`),
                        }))}
                        byline={(
                            <>
                                <IconTile
                                    size="sm"
                                    tone="accent"
                                    src="/landing/founder.jpg"
                                    alt={t("landing.founder.name")}
                                    icon={<UserIcon aria-hidden focusable="false" />}
                                />
                                <StackV gap={3} principle="sibling-stack" classNames={["min-w-0"]}
                                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                    items={[
                                        () => (
                                            <Typography type="body-sm" weight="semibold">
                                                {t("landing.founder.name")}
                                            </Typography>
                                        ),
                                        () => (
                                            <Typography type="body-xs" color="muted">
                                                {t("landing.founder.titles")}
                                            </Typography>
                                        ),
                                    ]} />
                                <div data-principle="content-row" className="flex items-center gap-3 @app-sm:ml-auto">
                                    {/* social proof — brand icons (GitHub · LinkedIn · Facebook) */}
                                    {FOUNDER_SOCIALS.map(({ key, href, icon: Icon, label }) => (
                                        <Link
                                            key={key}
                                            href={href}
                                            target="_blank"
                                            aria-label={label}
                                            className="text-muted transition-colors hover:text-accent-soft-foreground"
                                        >
                                            <Icon aria-hidden className="size-4" />
                                        </Link>
                                    ))}
                                    {/* blog = "go read + judge the quality yourself" CTA */}
                                    <Link href={pathConfig().locale(locale).blog().build()} data-principle="flex-action" className="inline-flex items-center gap-2 text-accent-soft-foreground">
                                        {t("landing.founder.blog")}
                                        <ArrowRightIcon aria-hidden focusable="false" className="size-4" />
                                    </Link>
                                </div>
                            </>
                        )}
                    />
                </section>

                {/* 6 — Two-sided talent marketplace (engineer outcome + recruiter browse, product-led) */}
                <TalentMarketplace />

                {/* 9 — FAQ */}
                <section id="faq" className="flex scroll-mt-24 flex-col gap-12">
                    <SectionHeading
                        anchorId="faq"
                        eyebrow={t("landing.faq.eyebrow")}
                        title={t("landing.faq.title")}
                    />
                    <Accordion variant="surface">
                        {LANDING_FAQ_INDEXES.map((index) => (
                            <Accordion.Item key={index} aria-label={t(`landing.faq.q${index}`)}>
                                <Accordion.Heading>
                                    <Accordion.Trigger>
                                        <Typography type="body-sm" weight="medium">
                                            {t(`landing.faq.q${index}`)}
                                        </Typography>
                                    </Accordion.Trigger>
                                </Accordion.Heading>
                                <Accordion.Panel>
                                    <Accordion.Body>
                                        <Typography type="body-sm" color="muted">
                                            {t(`landing.faq.a${index}`)}
                                        </Typography>
                                    </Accordion.Body>
                                </Accordion.Panel>
                            </Accordion.Item>
                        ))}
                    </Accordion>
                </section>

                {/* 10 — Closing CTA */}
                <StackV as="section" align="center" gap={6} principle="block-boundary"
                    explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                    items={[
                        () => (
                            <StackV align="center" gap={4} principle="card-caption"
                                explain="Holds caption text under card media so the caption stays attached to the image above it."
                                items={[
                                    () => (
                                        <Typography.Heading level={2} weight="bold" align="center" className="max-w-2xl">
                                            {t("landing.closing.title")}
                                        </Typography.Heading>
                                    ),
                                    () => (
                                        <Typography type="body" color="muted" align="center" className="max-w-xl">
                                            {t("landing.closing.subtitle")}
                                        </Typography>
                                    ),
                                ]} />
                        ),
                        () => (
                            <Button variant="primary" size="lg" onPress={onSeeCourses}>
                                {t("landing.closing.cta")}
                                <CaretRightIcon aria-hidden focusable="false" weight="bold" className="size-4" />
                            </Button>
                        ),
                    ]} />
            </Box>

            {/* Back-to-top FAB — floats bottom-right (primary accent), shows after scrolling past the first screen */}
            {showTop ? (
                <Button
                    isIconOnly
                    variant="primary"
                    aria-label={t("landing.backToTop")}
                    onPress={() => window.scrollTo({ top: 0, behavior: "smooth" })}
                    className="fixed bottom-6 right-[calc(var(--app-rail-w,0px)+1.5rem)] z-40 size-12 rounded-full shadow-lg"
                >
                    <ArrowUpIcon aria-hidden focusable="false" className="size-5" />
                </Button>
            ) : null}
        </div>
    )
}

import React from "react"
import type { ReactNode } from "react"
import Link from "next/link"
import {
    TrophyIcon,
} from "@phosphor-icons/react"
import {
    AsyncContentEmpty,
} from "@/components/composites/async/AsyncContent"
import {
    Typography,
} from "@/components/atoms/text/Typography"
import {
    Box,
} from "@/components/frames/Box"
import {
    StackV,
    StackH,
} from "@/components/frames/Stack"
import {
    Skeleton,
} from "@/components/blocks/skeleton/Skeleton"
import {
    UserCell,
} from "@/components/composites/lists/UserCell"
import {
    StandingHeroCard,
    type StandingHeroProgress,
} from "@/components/blocks/dashboard/StandingHeroCard"
import {
    Podium,
} from "@/components/blocks/dashboard/Podium"
import {
    IconTile,
} from "@/components/blocks/identity/IconTile"
import {
    SurfaceListCard,
    SurfaceListCardItem,
} from "@/components/blocks/cards/SurfaceListCard"
import {
    FollowButton,
} from "@/components/blocks/community/FollowButton"
import {
    Confetti,
} from "@/components/blocks/dashboard/Confetti"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"

/** How many placeholder rank-4+ rows the co-located skeleton shows. */
const SKELETON_ROW_COUNT = 6

/** One top-3 podium finisher, already resolved (points formatted, "mine" decided). */
export interface GlobalBoardPodiumEntry {
    rank: number
    username: string | null
    avatar: string | null
    /** Already-translated points label, e.g. "1420 XP". */
    pointsLabel: string
    /** True when this finisher is the viewer — ring-accent avatar + accent name (`Podium`'s own contract). */
    isMe: boolean
}

/**
 * One rank-4+ row, already resolved: display name already carries the — · You"
 * suffix when it's the viewer's own row (matches the connected file's old
 * string composition), follow state resolved from the connected file's sets.
 */
export interface GlobalBoardRow {
    key: string
    rank: number
    isMine: boolean
    /** Already composed with the — · You" suffix when {@link GlobalBoardRow.isMine}. */
    displayName: string
    avatar: string | null
    profileHref: string
    /** Already-translated points label, e.g. "1420 XP". */
    pointsLabel: string
    following: boolean
    isPending: boolean
    onToggleFollow: () => void
}

/** The viewer's own pinned row, appended after an ellipsis when they sit below the fetched slice. */
export interface GlobalBoardSelfRow {
    rank: number
    /** Already composed with the — · You" suffix (matches the connected file's old string composition). */
    displayName: string
    avatar: string | null
    /** Already-translated points label. */
    pointsLabel: string
}

/** Props for {@link _GlobalBoard} — presentational; all data resolved, no fetch/store/i18n. */
export interface GlobalBoardProps extends WithClassNames<undefined> {
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no ranked entries → the empty message (funnel to courses). */
    isEmpty?: boolean

    /** Rank-driven badge art for the standing hero (`rankBadgeIcon`) — already a built node (block API). */
    rankBadge?: ReactNode
    /** e.g. "Rank #9 platform-wide". */
    rankLabel?: string
    /** e.g. "1420 XP". */
    pointsMeta?: string
    /** Goal-gradient meter toward the next rank; omitted when the viewer is already #1 or has no baseline. */
    progress?: StandingHeroProgress
    /** North-star CTA label — funnels to courses. Shown on the hero and (as the retry action) on the empty state. */
    climbCtaLabel: string
    onClimb: () => void

    /** Top-3 finishers for the podium. */
    podiumEntries?: Array<GlobalBoardPodiumEntry>
    /** "You" suffix label for the podium's own finisher. */
    meLabel: string

    /** Rank 4+ rows. Shown whenever there's more than the podium, or the viewer sits below it. */
    rows?: Array<GlobalBoardRow>
    /** Whether the rank-4+ section renders at all (mirrors the connected file's old gate). */
    showRows?: boolean
    /** Pinned self-row appended after an ellipsis when the viewer sits below the fetched slice. */
    selfRow?: GlobalBoardSelfRow
    /** "{count} more" between the fetched slice and the pinned self-row; omitted when there's no gap. */
    hiddenBetweenLabel?: string

    /** Bumped to fire a confetti burst on a top-3 platform finish. */
    celebrateKey?: number

    emptyTitle: string
    emptyDescription: string
}

/**
 * The global (all-users) leaderboard — presentational half of {@link import("./index").GlobalBoard}.
 * Same shell as the weekly board: a {@link StandingHeroCard} of the viewer's platform-wide standing,
 * the top-3 {@link Podium}, then rank 4+ as a followable {@link SurfaceListCard}. `isSkeleton`
 * threads down to every leaf; `StandingHeroCard`/`Podium`/`IconTile`/`SurfaceListCard`/`FollowButton`/
 * `UserCell` take no `isSkeleton` of their own (`missingSkeletonSupport`), so each is mirrored in
 * place with `Skeleton.*` at the exact position it renders, instead of a parallel skeleton tree. See
 * `tiers/split.md` — the connected `index.tsx` owns the fetch, the follow mutation, and every label.
 *
 * @param props - {@link GlobalBoardProps}
 */
export const _GlobalBoard = ({
    className,
    isSkeleton = false,
    isEmpty = false,
    rankBadge,
    rankLabel,
    pointsMeta,
    progress,
    climbCtaLabel,
    onClimb,
    podiumEntries = [],
    meLabel,
    rows = [],
    showRows = false,
    selfRow,
    hiddenBetweenLabel,
    celebrateKey = 0,
    emptyTitle,
    emptyDescription,
}: GlobalBoardProps) => {
    // settled, nothing to rank yet → funnel to courses (BLOCK-8: error/loading beat empty; this
    // component has no distinct error state — an SWR error settles with `!data`, which the
    // connected file already folds into `isEmpty`, exactly like the retired `AsyncContent` did).
    if (!isSkeleton && isEmpty) {
        return (
            <AsyncContentEmpty
                icon={TrophyIcon}
                title={emptyTitle}
                description={emptyDescription}
                onRetry={onClimb}
                retryLabel={climbCtaLabel}
            />
        )
    }

    const podiumRows = isSkeleton
        ? [false, true, false]
        : podiumEntries.slice(0, 3).map((entry) => entry.rank === 1)
    const skeletonRows = Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => index)

    // `StackV`'s own `classNames` is the closed positioning-only allowlist (ATOM-4 vocabulary),
    // not a free-form passthrough — an incoming placement `className` from the caller needs the
    // frame tier's escape hatch (`Box`), which is the ONLY frame that takes a raw string.
    return (
        <Box className={className}>
            <StackV
                gap={6}
                principle="block-boundary"
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                identity={{ tier: "block", component: "GlobalBoard" }}
                items={[
                    // celebrate a top-3 platform finish — only meaningful once real data has settled
                    ...(!isSkeleton ? [() => <Confetti fireKey={celebrateKey} />] : []),

                    // ── your platform-wide standing ── `StandingHeroCard` has no `isSkeleton` of its
                    // own (missingSkeletonSupport): mirrored in place with `Skeleton.*`, same box.
                    () => (isSkeleton ? (
                        <Box principle="card-padding" className="rounded-3xl bg-surface p-4 shadow-surface"
                            explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                            <StackV gap={5} principle="group-boundary"
                                explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                                items={[
                                    () => (
                                        <StackH gap={5} principle="group-boundary"
                                            explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                                            align="center" items={[
                                                () => <Skeleton className="size-10 shrink-0 rounded-2xl" />,
                                                () => (
                                                    <StackV gap={2} principle="title-subtitle"
                                                        explain="Title over supporting line — not label-field, because neither line is a form control label."
                                                        classNames={["min-w-0", "flex-1"]} items={[
                                                            () => <Skeleton.Typography type="h6" width="1/2" />,
                                                            () => <Skeleton.Typography type="body-sm" width="1/3" />,
                                                        ]} />
                                                ),
                                            ]} />
                                    ),
                                    () => (
                                        <StackV gap={2} principle="title-subtitle"
                                            explain="Title over supporting line — not label-field, because neither line is a form control label."
                                            items={[
                                                () => <Skeleton.Typography type="body-xs" width="1/3" />,
                                                () => <Skeleton.ProgressBar />,
                                            ]} />
                                    ),
                                    () => <Skeleton className="h-10 w-40 rounded-full" />,
                                ]} />
                        </Box>
                    ) : (
                        <StandingHeroCard
                            badge={rankBadge ? <IconTile icon={rankBadge} tone="neutral" size="sm" /> : undefined}
                            rankLabel={rankLabel}
                            meta={pointsMeta}
                            progress={progress}
                            ctaLabel={climbCtaLabel}
                            onCta={onClimb}
                        />
                    )),

                    // ── the winners' dais ── `Podium` has no `isSkeleton` of its own
                    // (missingSkeletonSupport): mirrored in place, champion centered + raised.
                    () => (isSkeleton ? (
                        <StackH gap={4} principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            align="end" justify="center" items={podiumRows.map((isChampion) => () => (
                                <StackV gap={2} principle="title-subtitle"
                                    explain="Title over supporting line — not label-field, because neither line is a form control label."
                                    align="center" items={[
                                        () => <Skeleton className={isChampion ? "size-14 shrink-0 rounded-full" : "size-12 shrink-0 rounded-full"} />,
                                        () => (
                                            <StackV gap={2} principle="title-subtitle"
                                                explain="Title over supporting line — not label-field, because neither line is a form control label."
                                                align="center" classNames={["w-full"]} items={[
                                                    () => <Skeleton.Typography type="body-sm" width="3/4" />,
                                                    () => <Skeleton.Typography type="body-xs" width="1/2" />,
                                                ]} />
                                        ),
                                        () => (
                                            <Box className={isChampion
                                                ? "h-16 w-20 rounded-t-2xl rounded-b-none"
                                                : "h-10 w-20 rounded-t-2xl rounded-b-none"}
                                            >
                                                <Skeleton className="h-full w-full rounded-t-2xl rounded-b-none" />
                                            </Box>
                                        ),
                                    ]} />
                            ))} />
                    ) : (
                        <Podium
                            meLabel={meLabel}
                            entries={podiumEntries.map((entry) => ({
                                rank: entry.rank,
                                username: entry.username,
                                avatar: entry.avatar,
                                pointsLabel: entry.pointsLabel,
                                isMe: entry.isMe,
                            }))}
                        />
                    )),

                    // ── rank 4+ ── a followable list; `SurfaceListCard`/`FollowButton`/`UserCell`
                    // have no `isSkeleton` of their own (missingSkeletonSupport): each row is
                    // mirrored in place with `Skeleton.UserCell` + bare bars, same row shape.
                    ...(isSkeleton || showRows ? [() => (
                        <SurfaceListCard>
                            {isSkeleton
                                ? skeletonRows.map((row) => (
                                    <SurfaceListCardItem key={row}>
                                        <StackH gap={4} principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            align="center" items={[
                                                () => <Skeleton className="h-3 w-6 shrink-0 rounded-sm" />,
                                                () => <Skeleton.UserCell className="min-w-0 flex-1" withHandle={false} />,
                                                () => <Skeleton className="h-3 w-10 shrink-0 rounded-sm" />,
                                            ]} />
                                    </SurfaceListCardItem>
                                ))
                                : rows.map((row) => (
                                    <SurfaceListCardItem key={row.key}>
                                        <StackH gap={4} principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            align="center" items={[
                                                () => (
                                                    <Box className="w-6 shrink-0">
                                                        <Typography
                                                            size="xs"
                                                            align="end"
                                                            color={row.isMine ? "accent" : "muted"}
                                                            weight={row.isMine ? "semibold" : undefined}
                                                            text={String(row.rank)}
                                                        />
                                                    </Box>
                                                ),
                                                () => (
                                                    <Link
                                                        href={row.profileHref}
                                                        className="flex min-w-0 flex-1 items-center text-foreground no-underline transition-opacity hover:opacity-60"
                                                    >
                                                        <UserCell username={row.displayName} avatar={row.avatar} />
                                                    </Link>
                                                ),
                                                () => (
                                                    <Typography
                                                        size="sm"
                                                        color={row.isMine ? "accent" : "muted"}
                                                        weight={row.isMine ? "semibold" : undefined}
                                                        classNames={["shrink-0"]}
                                                        text={row.pointsLabel}
                                                    />
                                                ),
                                                ...(!row.isMine ? [() => (
                                                    <FollowButton
                                                        className="shrink-0"
                                                        quiet
                                                        following={row.following}
                                                        isPending={row.isPending}
                                                        onToggle={row.onToggleFollow}
                                                    />
                                                )] : []),
                                            ]} />
                                    </SurfaceListCardItem>
                                ))}

                            {/* viewer below the fetched slice → ellipsis + pinned self-row (hidden while shimmering) */}
                            {!isSkeleton && selfRow ? (
                                <>
                                    <Box principle="control-pad" className="bg-surface-secondary px-3 py-2 text-xs text-muted"
                                        explain="Control hit-area inset — not row-pad, because this pads a single interactive control rather than a full content row.">
                                        <StackH gap={3} principle="sibling-stack"
                                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                            align="center" justify="center" items={[
                                                () => <span className="text-base leading-none tracking-widest">⋯</span>,
                                                ...(hiddenBetweenLabel ? [() => <Typography size="xs" color="muted" text={hiddenBetweenLabel} />] : []),
                                            ]} />
                                    </Box>
                                    <SurfaceListCardItem>
                                        <StackH gap={4} principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            align="center" items={[
                                                () => (
                                                    <Box className="w-6 shrink-0">
                                                        <Typography size="xs" align="end" color="accent" weight="semibold" text={String(selfRow.rank)} />
                                                    </Box>
                                                ),
                                                () => (
                                                    <Box className="min-w-0 flex-1">
                                                        <UserCell username={selfRow.displayName} avatar={selfRow.avatar} />
                                                    </Box>
                                                ),
                                                () => (
                                                    <Typography size="sm" color="accent" weight="semibold" classNames={["shrink-0"]} text={selfRow.pointsLabel} />
                                                ),
                                            ]} />
                                    </SurfaceListCardItem>
                                </>
                            ) : null}
                        </SurfaceListCard>
                    )] : []),
                ]}
            />
        </Box>
    )
}

import React from "react"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { StandingHeroCard } from "@/components/blocks/dashboard/StandingHeroCard"
import { Podium, type PodiumEntry } from "@/components/blocks/dashboard/Podium"
import { rankBadgeIcon } from "@/components/blocks/dashboard/rankBadge"
import { Confetti } from "@/components/blocks/dashboard/Confetti"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { UserCell } from "@/components/composites/lists/UserCell"
import { RankDeltaCaret } from "@/components/blocks/profile/RankDeltaCaret"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { StackV, StackH } from "@/components/frames/Stack"

/** Number of placeholder cohort rows (rank 4+) shown while the board shimmers. */
const SKELETON_ROW_COUNT = 6

/** "Your standing" hero — already resolved (i18n interpolated) by the connected `WeeklyBoard`. */
export interface WeeklyBoardHero {
    /** 1-based rank, drives the {@link rankBadgeIcon} art. */
    rank: number
    /** Primary line, e.g. "Rank #1 · Bronze" (already translated + interpolated). */
    rankLabel: string
    /** Secondary meta line — points · reset countdown (already translated + interpolated). */
    meta: string
    /** Optional goal-gradient meter toward the promotion cutoff. */
    progress?: {
        /** Fill ratio, `0..1`. */
        ratio: number
        /** Muted line above the meter (already translated + interpolated). */
        label: string
    }
}

/** One top-3 podium finisher — see {@link PodiumEntry}. */
export type WeeklyBoardPodiumEntry = PodiumEntry

/** One rank 4+ cohort row, already resolved by the connected `WeeklyBoard`. */
export interface WeeklyBoardRowEntry {
    /** Stable row identity. */
    userGlobalId: string
    /** 1-based rank. */
    rank: number
    /** True when this row is the viewer's own. */
    mine: boolean
    /** Resolved, locale-aware link to this user's public profile. */
    profileHref: string
    /** Display username — the viewer's own row already carries the "· you" suffix. */
    displayUsername: string
    /** Avatar URL, or `null` for the generated fallback. */
    avatar: string | null
    /** Pre-formatted points label (already translated). */
    pointsLabel: string
    /** Weekly rank movement (`>0` climbed, `<0` dropped, `0`/`null` unchanged/no baseline). */
    rankDelta: number | null
}

/** All display text, already localized by the connected `WeeklyBoard`; a story passes i18n keys. */
export interface WeeklyBoardLabels {
    /** Nothing to show until the viewer is placed in a cohort — funnel-to-courses title. */
    emptyTitle: string
    /** Funnel-to-courses supporting line under {@link WeeklyBoardLabels.emptyTitle}. */
    emptyDescription: string
    /** North-star CTA — shown both on the hero and as the empty-state retry action. */
    climbCta: string
    /** "you" suffix appended to the viewer's own podium finisher. */
    you: string
    /** Promote-zone legend line (already interpolated with the cohort's promote count). */
    legendPromote: string
    /** Demote-zone legend line (already interpolated with the cohort's demote count). */
    legendDemote: string
}

/** Props for {@link _WeeklyBoard} — presentational; all data resolved, no fetch/store/i18n. */
export interface WeeklyBoardProps {
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no cohort placement → the empty message (funnel to courses). */
    isEmpty?: boolean
    /** The viewer's own standing hero — omitted when the viewer isn't placed in the loaded cohort. */
    hero?: WeeklyBoardHero
    /** Top-3 finishers, best → worst. */
    podiumEntries?: ReadonlyArray<WeeklyBoardPodiumEntry>
    /** Rank 4+ rows — the runners the podium can't hold. */
    rows?: ReadonlyArray<WeeklyBoardRowEntry>
    /** Bumped to fire a top-3 confetti burst (owned by the connected file's one-shot effect). */
    celebrateKey?: number
    /** North-star funnel — both the hero CTA and the empty-state retry action. */
    onClimb: () => void
    labels: WeeklyBoardLabels
    className?: string
}

/**
 * Loading placeholder for the "your standing" hero — mirrors {@link StandingHeroCard}'s shape
 * (badge · rank/meta lines · goal meter · CTA) since the block has no `isSkeleton` of its own.
 */
const HeroSkeleton = () => (
    <Box principle="card-padding" className="rounded-3xl bg-surface p-4 shadow-surface"
        explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
        <StackV gap={5} principle="group-boundary"
            explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
            items={[
                () => (
                    <StackH gap={5} principle="group-boundary"
                        explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                        items={[
                            () => <Skeleton className="size-10 shrink-0 rounded-2xl" />,
                            () => <StackV gap={2} principle="title-subtitle"
                                explain="Title over supporting line — not label-field, because neither line is a form control label."
                                classNames={["min-w-0", "flex-1"]} items={[
                                    () => <Skeleton.Typography type="h6" width="1/2" />,
                                    () => <Skeleton.Typography type="body-sm" width="1/3" />,
                                ]} />,
                        ]} />
                ),
                () => (
                    <StackV gap={2} principle="title-subtitle"
                        explain="Title over supporting line — not label-field, because neither line is a form control label."
                        items={[
                            () => <Skeleton.Typography type="body-xs" width="1/3" />,
                            () => <Skeleton.ProgressBar />,
                        ]} />
                ),
                () => <Skeleton className="h-10 w-40 rounded-full" />,
            ]} />
    </Box>
)

/**
 * Loading placeholder for the top-3 dais — mirrors {@link Podium}'s shape (champion centered +
 * raised) since the block has no `isSkeleton` of its own.
 */
const PodiumSkeleton = () => (
    <StackH gap={4} principle="content-row"
        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
        justify="center" items={[false, true, false].map((isChampion) => () => (
            <StackV gap={3} principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                align="center" items={[
                    () => <Skeleton className={isChampion ? "size-14 shrink-0 rounded-full" : "size-12 shrink-0 rounded-full"} />,
                    // The podium column's fixed width is not a member of the closed AllowedClassName
                    // union, so it sits on Box — the frame tier's sanctioned escape hatch — rather than
                    // widening that union for one skeleton.
                    () => <Box className="w-20"><StackV gap={2} principle="title-subtitle"
                        explain="Title over supporting line — not label-field, because neither line is a form control label."
                        align="center" items={[
                            () => <Skeleton.Typography type="body-sm" width="3/4" />,
                            () => <Skeleton.Typography type="body-xs" width="1/2" />,
                        ]} /></Box>,
                    () => <Skeleton className={isChampion ? "h-16 w-20 rounded-t-2xl rounded-b-none" : "h-10 w-20 rounded-t-2xl rounded-b-none"} />,
                ]} />
        ))} />
)

/** Loading placeholder for one rank 4+ row — mirrors the [rank · avatar · name · points · caret] shape. */
const RowSkeleton = () => (
    <StackH gap={4} principle="content-row"
        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
        items={[
            () => <Skeleton className="h-3 w-6 shrink-0 rounded-sm" />,
            () => <Skeleton.Avatar size="sm" />,
            () => <Skeleton.Typography type="body-sm" width="1/3" className="min-w-0 flex-1" />,
            () => <Skeleton className="h-3 w-8 shrink-0 rounded-sm" />,
            () => <Skeleton className="h-4 w-8 shrink-0 rounded-sm" />,
        ]} />
)

/** One resolved rank 4+ row: rank cell · profile-linked user cell · points · movement caret. */
const Row = ({ row }: { row: WeeklyBoardRowEntry }) => (
    <StackH gap={4} principle="content-row"
        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
        items={[
            () => (
                <Box as="span" className="w-6 shrink-0 text-right">
                    <Typography size="xs" color={row.mine ? "accent" : "muted"} weight={row.mine ? "semibold" : undefined} text={String(row.rank)} />
                </Box>
            ),
            () => (
                <Box className="min-w-0 flex-1">
                    <UserCell username={row.displayUsername} avatar={row.avatar} isOwnRow={row.mine } />
                </Box>
            ),
            () => (
                <Typography size="sm" color={row.mine ? "accent" : "muted"} weight={row.mine ? "semibold" : undefined} classNames={["shrink-0"]} text={row.pointsLabel} />
            ),
            () => <RankDeltaCaret delta={row.rankDelta} className="w-8 shrink-0 justify-end" />,
        ]} />
)

/**
 * `_WeeklyBoard` — the presentational half of {@link import("./index").WeeklyBoard}: the full
 * weekly-league board shell shared with the global board — a {@link StandingHeroCard} of the
 * viewer's own standing, the top-3 {@link Podium}, the promote/demote legend, then rank 4+ in a
 * {@link SurfaceListCard}. Renders ONE tree with `isSkeleton` threaded to every leaf that supports
 * it; the sub-blocks that don't ({@link StandingHeroCard}, {@link Podium}, {@link SurfaceListCard},
 * {@link UserCell}, {@link RankDeltaCaret}) are mirrored in place with `Skeleton.*` at the exact
 * site they render, so the shimmer stays co-located instead of a hand-kept parallel tree
 * (`loading-and-skeleton.md`). See `tiers/split.md` — the connected `index.tsx` owns the fetch,
 * the async decisions, and every interpolated string.
 *
 * @param props - {@link WeeklyBoardProps}
 */
export const _WeeklyBoard = ({
    isSkeleton = false,
    isEmpty = false,
    hero,
    podiumEntries = [],
    rows = [],
    celebrateKey = 0,
    onClimb,
    labels,
    className,
}: WeeklyBoardProps) => {
    // empty only once settled — a first-load skeleton always wins over a structurally-empty isEmpty.
    if (!isSkeleton && isEmpty) {
        return (
            <AsyncContentEmpty
                title={labels.emptyTitle}
                description={labels.emptyDescription}
                onRetry={onClimb}
                retryLabel={labels.climbCta}
            />
        )
    }

    const showHero = isSkeleton || Boolean(hero)
    const showPodium = isSkeleton || podiumEntries.length > 0
    const showRows = isSkeleton || rows.length > 0

    const rowItems: Array<ComponentTypeWithSkeleton> = isSkeleton
        ? Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => () => (
            <SurfaceListCardItem key={`pending-${index}`}>
                <RowSkeleton />
            </SurfaceListCardItem>
        ))
        : rows.map((row) => () => (
            <SurfaceListCardItem
                key={row.userGlobalId}
                href={row.profileHref}
                withVerdict={{
                    enable: (row.rankDelta ?? 0) !== 0,
                    variant: (row.rankDelta ?? 0) > 0 ? "success" : "danger",
                }}
            >
                <Row row={row} />
            </SurfaceListCardItem>
        ))

    return (
        <Box className={className} identity={{ tier: "block", component: "WeeklyBoard" }}>
            <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                    () => <Confetti fireKey={celebrateKey} />,

                    // your standing hero — rank-driven badge · rank/meta · goal meter · CTA
                    ...(showHero ? [() => (
                        isSkeleton || !hero
                            ? <HeroSkeleton />
                            : (
                                <StandingHeroCard
                                    badge={<IconTile icon={rankBadgeIcon(hero.rank)} tone="neutral" size="sm" />}
                                    rankLabel={hero.rankLabel}
                                    meta={hero.meta}
                                    progress={hero.progress}
                                    ctaLabel={labels.climbCta}
                                    onCta={onClimb}
                                />
                            )
                    )] : []),

                    // the winners' dais — top-3 (viewer's own column ringed)
                    ...(showPodium ? [() => (
                        isSkeleton
                            ? <PodiumSkeleton />
                            : <Podium meLabel={labels.you} entries={[...podiumEntries]} />
                    )] : []),

                    // promote / demote legend
                    () => (
                        <StackH gap={4} principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            items={[
                                () => (
                                    <StackH gap={3} principle="sibling-stack"
                                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                        items={[
                                            () => <Box as="span" className="size-2 shrink-0 rounded-full bg-success" />,
                                            () => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={labels.legendPromote} />,
                                        ]} />
                                ),
                                () => (
                                    <StackH gap={3} principle="sibling-stack"
                                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                        items={[
                                            () => <Box as="span" className="size-2 shrink-0 rounded-full bg-danger" />,
                                            () => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={labels.legendDemote} />,
                                        ]} />
                                ),
                            ]} />
                    ),

                    // rank 4+ — the runners the podium can't hold; zone edge-markers via `withVerdict`
                    ...(showRows ? [() => <SurfaceListCard>{rowItems.map((Item, index) => <Item key={index} isSkeleton={isSkeleton} />)}</SurfaceListCard>] : []),
                ]} />
        </Box>
    )
}

