                                                            </Typography>
                                                        ),
                                                    ]}
                                                />
                                            </Box>
                                        ),
                                        () => (
                                            <Cluster
                                                gap={3}
                                                principle="chip-row"
                                                explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                                items={RUBRIC_KEYS.map((key) => () => (
                                                    <Chip key={key} size="sm" variant="soft" className="w-fit">
                                                        {t(`mockInterview.gatePreview.${key}`)}
                                                    </Chip>
                                                ))}
                                            />
                                        ),
                                    ]}
                                />
                            )}
                        />
                    ),
                    () => (
                        <SurfaceCard
                            padding={5}
                            body={() => (
                                <StackV
                                    gap={4}
                                    items={[
                                        () => (
                                            <Chip size="sm" variant="soft" color="accent" className="w-fit">
                                                {t("mockInterview.gatePreview.q2Badge")}
                                            </Chip>
                                        ),
                                        () => (
                                            <Typography type="body" weight="semibold">
                                                {t("mockInterview.gatePreview.q2Title")}
                                            </Typography>
                                        ),
                                        () => (
                                            <Typography type="body-sm" color="muted">
                                                {t("mockInterview.gatePreview.q2Body")}
                                            </Typography>
                                        ),
                                    ]}
                                />
                            )}
                        />
                    ),
                ]}
            />
        </Box>
    )
}

"use client"

import React, { useEffect, useMemo, useRef, useState } from "react"
import { Badge, Button, Card, CardContent, Chip, Popover, Typography } from "@heroui/react"
import { CaretRightIcon, FunnelIcon } from "@phosphor-icons/react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { SurfaceListCard, SurfaceListCardRow, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SearchInput } from "@/components/blocks/form/SearchInput"
import { FlexWrapButtonRadio } from "@/components/blocks/navigation/FlexWrapButtonRadio"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"
import { useQueryMyMockInterviewAttemptsSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyMockInterviewAttemptsSwr"
import { groupByTimeBucket } from "@/modules/utils/history-buckets"
import { sessionDisplayName } from "@/modules/utils/session-display-name"
import { pathConfig } from "@/resources/path"
import type { MockInterviewAttemptItem } from "@/modules/api/graphql/queries/types/my-mock-interview-attempts"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link MockInterviewHistory}. */
export interface MockInterviewHistoryProps extends WithClassNames<undefined> {
    /** Course whose mock-interview history to list. */
    courseId: string
    /** Course display id, for the scorecard result deep link. */
    courseDisplayId: string
    /** Jumps the setup tab strip back to "Start" (empty-state action). */
    onStartInterview?: () => void
}

/** History items fetched per "load more" page. */
const PAGE_SIZE = 10

/** The mode filter's fixed option order — "all" first, then the 2 top-level modes. */
type HistoryModeFilter = "all" | "qna" | "design"

/** Verdict → chip color (pass / borderline / fail) — mirrors {@link MockInterviewScorecard}'s convention. */
const verdictColorOf = (verdict: string): "success" | "warning" | "danger" =>
    verdict === "pass" ? "success" : verdict === "borderline" ? "warning" : "danger"

/**
 * The viewer's past mock-interview sessions for this course, newest first — the
 * setup screen's "History" tab. Mirrors the WORKING Flashcard history exactly
 * (teacher, 2026-07-17): fetch ALL modes then filter CLIENT-side (mode facet behind a
 * funnel + search by prompt title), accumulate pages with a `previousCourseIdRef`
 * guard (only a real course change resets — NOT a mere remount), group runs by
 * TIME BUCKET (today / 7 days / 30 days / older), and a "load more" button.
 * Each row opens the read-only scorecard. Server-side `mode` paging was dropped —
 * it desynced `totalCount` from a cleared `items` (count said 12 while the list
 * read empty).
 * @param props - {@link MockInterviewHistoryProps}
 */
export const MockInterviewHistory = ({ courseId, courseDisplayId, onStartInterview, className }: MockInterviewHistoryProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()

    const [offset, setOffset] = useState(0)
    const [items, setItems] = useState<Array<MockInterviewAttemptItem>>([])
    const [totalCount, setTotalCount] = useState(0)
    const [modeFilter, setModeFilter] = useState<HistoryModeFilter>("all")
    const [search, setSearch] = useState("")
    const [filterOpen, setFilterOpen] = useState(false)

    // fetch ALL modes (no server-side mode filter) — the mode facet narrows the
    // loaded rows client-side, exactly like Flashcard history.
    const attemptsSwr = useQueryMyMockInterviewAttemptsSwr(courseId, PAGE_SIZE, offset)

    // accumulate pages as `offset` advances ("load more").
    useEffect(() => {
        const data = attemptsSwr.data
        if (!data) {
            return
        }
        setItems((previous) => (offset === 0 ? data.items : [...previous, ...data.items]))
        setTotalCount(data.totalCount)
    }, [attemptsSwr.data, offset])

    // course changed → start the accumulator over. Guarded against firing on mere
    // MOUNT (the setup tab remounts this component; an unguarded reset would wipe
    // the `items` the data-effect just set from SWR's warm cache — see
    // FlashcardReviewHistory for the same fix).
    const previousCourseIdRef = useRef(courseId)
    useEffect(() => {
        if (previousCourseIdRef.current === courseId) {
            return
        }
        previousCourseIdRef.current = courseId
        setOffset(0)
        setItems([])
    }, [courseId])

    const formatDate = (iso: string) =>
        new Intl.DateTimeFormat(locale, { dateStyle: "medium" }).format(new Date(iso))

    // only offer a mode the loaded history actually contains — no dead facet.
    const presentModes = useMemo(
        () => Array.from(new Set(items.map((item) => item.mode))),
        [items],
    )
    const filteredItems = useMemo(() => {
        const needle = search.trim().toLowerCase()
        return items.filter((item) =>
            (modeFilter === "all" || item.mode === modeFilter)
            && (!needle || item.promptTitle.toLowerCase().includes(needle)),
        )
    }, [items, modeFilter, search])

    // group filtered runs by time window (teacher, 2026-07-17 "render history day by day")
    const timeBuckets = useMemo(
        () => groupByTimeBucket(filteredItems, (item) => item.createdAt),
        [filteredItems],
    )

    const hasFacets = presentModes.length > 1
    const activeFacetCount = modeFilter !== "all" ? 1 : 0
    const shownCount = search.trim() || activeFacetCount > 0 ? filteredItems.length : totalCount
    const hasMore = items.length < totalCount

    /** One attempt row → opens the read-only scorecard result. Primary line is the
     *  learner's own session name (or its time-based fallback, see
     *  `sessionDisplayName`); the drawn prompt + date move to the subtitle so
     *  neither is lost. */
    const renderRow = (attempt: MockInterviewAttemptItem) => (
        <SurfaceListCardRow
            key={attempt.id}
            title={sessionDisplayName(attempt.name, attempt.createdAt, t, locale)}
            subtitle={`${attempt.promptTitle} · ${formatDate(attempt.createdAt)}`}
            meta={() => (
                <Chip size="sm" variant="soft" color={verdictColorOf(attempt.verdict)}>
                    <Chip.Label>{attempt.overallScore}</Chip.Label>
                </Chip>
            )}
            trailing={() => <CaretRightIcon weight="bold" className="size-4 text-muted" aria-hidden focusable="false" />}
            onPress={() => router.push(
                pathConfig()
                    .locale(locale)
                    .course(courseDisplayId)
                    .learn()
                    .mockInterview()
                    .interview(attempt.sessionId)
                    .result()
                    .build(),
            )}
        />
    )

    return (
        <AsyncContent
            isLoading={attemptsSwr.isLoading && items.length === 0}
            skeleton={(
                // MIRROR the loaded tree: a funnel toolbar (search + funnel button + count)
                // above a SurfaceListCard of attempt rows (name/subtitle + verdict score
                // chip + caret).
                <StackV
                    gap={4}
                    items={[
                        () => (
                            <StackH
                                gap={4}
                                principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                justify="between"
                                classNames={["w-full"]}
                                items={[
                                    () => (
                                        <StackH
                                            gap={4}
                                            principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            classNames={["min-w-0", "flex-1"]}
                                            items={[
                                                () => <Skeleton className="h-9 min-w-0 flex-1 rounded-medium" />,
                                                () => <Skeleton className="size-9 shrink-0 rounded-medium" />,
                                            ]}
                                        />
                                    ),
                                    () => <Skeleton className="h-[14px] w-16 shrink-0 rounded" />,
                                ]}
                            />
                        ),
                        () => (
                            <SurfaceListCard>
                                {Array.from({ length: 4 }).map((_unused, index) => (
                                    <SurfaceListCardItem key={index}>
                                        <StackH
                                            gap={4}
                                            principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            classNames={["w-full"]}
                                            items={[
                                                () => (
                                                    <StackV
                                                        gap={2}
                                                        principle="title-subtitle"
                                                        explain="Title over supporting line — not label-field, because neither line is a form control label."
                                                        classNames={["min-w-0", "flex-1"]}
                                                        items={[
                                                            () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                                            () => <Skeleton.Typography type="body-xs" width="1/3" />,
                                                        ]}
                                                    />
                                                ),
                                                () => <Skeleton className="h-6 w-10 shrink-0 rounded-full" />,
                                                () => <Skeleton className="size-4 shrink-0 rounded" />,
                                            ]}
                                        />
                                    </SurfaceListCardItem>
                                ))}
                            </SurfaceListCard>
                        ),
                    ]}
                />
            )}
            error={items.length === 0 ? attemptsSwr.error : undefined}
            errorContent={{
                title: t("mockInterview.historyError"),
                onRetry: () => void attemptsSwr.mutate(),
                retryLabel: t("mockInterview.promptsRetry"),
            }}
        >
            {items.length === 0 ? (
                // no attempts at all → a single bounded empty card (matches the
                // populated SurfaceListCard shape; components/card.md §2).
                <Card className={className}>
                    <CardContent>
                        <EmptyState
                            title={t("mockInterview.historyEmpty")}
                            action={onStartInterview ? () => (
                                <Button size="sm" variant="secondary" onPress={onStartInterview}>
                                    {t("mockInterview.begin")}
                                </Button>
                            ) : undefined}
                        />
                    </CardContent>
                </Card>
            ) : (
                <div className={className}>
                    <StackV
                        gap={4}
                        items={[
                            () => (
                                <StackH
                                    gap={4}
                                    principle="content-row"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    justify="between"
                                    classNames={["w-full"]}
                                    items={[
                                        () => (
                                            <StackH
                                                gap={4}
                                                principle="content-row"
                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                classNames={["min-w-0", "flex-1"]}
                                                items={[
                                                    () => (
                                                        <SearchInput
                                                            className="min-w-0 flex-1"
                                                            value={search}
                                                            onValueChange={setSearch}
                                                            placeholder={t("mockInterview.historySearchPlaceholder")}
                                                        />
                                                    ),
                                                    ...(hasFacets
                                                        ? [() => (
                                                            <Popover isOpen={filterOpen} onOpenChange={setFilterOpen}>
                                                                <Button
                                                                    isIconOnly
                                                                    variant="ghost"
                                                                    aria-label={t("mockInterview.historyFilterButton")}
                                                                    className="shrink-0"
                                                                >
                                                                    {activeFacetCount > 0 ? (
                                                                        <Badge.Anchor>
                                                                            <FunnelIcon className="size-5" />
                                                                            <Badge size="sm" color="accent" placement="top-left">{activeFacetCount}</Badge>
                                                                        </Badge.Anchor>
                                                                    ) : (
                                                                        <FunnelIcon className="size-5" />
                                                                    )}
                                                                </Button>
                                                                <Popover.Content className="w-72">
                                                                    <Box principle="cell-pad" className="p-3"
                                                                        explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body.">
                                                                        <StackV
                                                                            gap={4}
                                                                            items={[
                                                                                () => (
                                                                                    <StackV
                                                                                        gap={4}
                                                                                        principle="label-field"
                                                                                        explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                                                                                        items={[
                                                                                            () => (
                                                                                                <Typography type="body-xs" color="muted">{t("mockInterview.historyFilterHeading")}</Typography>
                                                                                            ),
                                                                                            () => (
                                                                                                <FlexWrapButtonRadio<HistoryModeFilter>
                                                                                                    ariaLabel={t("mockInterview.historyFilterHeading")}
                                                                                                    value={modeFilter}
                                                                                                    onChange={setModeFilter}
                                                                                                    items={[
                                                                                                        { value: "all", content: t("mockInterview.historyFilterAll") },
                                                                                                        { value: "qna", content: t("mockInterview.historyFilterQna") },
                                                                                                        { value: "design", content: t("mockInterview.historyFilterDesign") },
                                                                                                    ]}
                                                                                                />
                                                                                            ),
                                                                                        ]}
                                                                                    />
                                                                                ),
                                                                                ...(activeFacetCount > 0
                                                                                    ? [() => (
                                                                                        <Button variant="danger-soft" size="sm" className="self-start" onPress={() => setModeFilter("all")}>
                                                                                            {t("mockInterview.historyClearFilters")}
                                                                                        </Button>
                                                                                    )]
                                                                                    : []),
                                                                            ]}
                                                                        />
                                                                    </Box>
                                                                </Popover.Content>
                                                            </Popover>
                                                        )]
                                                        : []),
                                                ]}
                                            />
                                        ),
                                        () => (
                                            <Typography type="body-sm" color="muted" className="shrink-0">
                                                {t("mockInterview.historyCount", { count: shownCount })}
                                            </Typography>
                                        ),
                                    ]}
                                />
                            ),
                            () => (
                                filteredItems.length === 0 ? (
                                    <Card>
                                        <CardContent>
                                            <Box principle="page-pad" className="p-6"
                                                explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                                                <Typography type="body-sm" color="muted" align="center">
                                                    {t("mockInterview.historyEmptyFiltered")}
                                                </Typography>
                                            </Box>
                                        </CardContent>
                                    </Card>
                                ) : (
                                    <StackV
                                        gap={4}
                                        items={timeBuckets.map((bucket) => () => (
                                            <LabeledCard
                                                key={bucket.key}
                                                frameless
                                                subtleLabel
                                                label={t(`flashcard.timeBucket.${bucket.key}`)}
                                                labelEnd={t("flashcard.runCount", { count: bucket.items.length })}
                                            >
                                                <SurfaceListCard>
                                                    {bucket.items.map((attempt) => renderRow(attempt))}
                                                </SurfaceListCard>
                                            </LabeledCard>
                                        ))}
                                    />
                                )
                            ),
                            ...(hasMore
                                ? [() => (
                                    <Button
                                        variant="secondary"
                                        size="sm"
                                        className="self-center"
                                        isDisabled={attemptsSwr.isLoading}
                                        onPress={() => setOffset((previous) => previous + PAGE_SIZE)}
                                    >
                                        {t("mockInterview.historyLoadMore")}
                                    </Button>
                                )]
                                : []),
                        ]}
                    />
                </div>
            )}
        </AsyncContent>
    )
}

"use client"

import React, {
    useCallback,
    useMemo,
    useState,
} from "react"
import {
    ArrowRightIcon,
    BellIcon,
    ChatCircleIcon,
    ChecksIcon as CheckDoubleIcon,
    CircleIcon,
    CodeIcon,
    FlameIcon,
    FlagIcon,
    MegaphoneIcon,
    PuzzlePieceIcon,
    SparkleIcon,
    UserPlusIcon,
    UsersThreeIcon,
} from "@phosphor-icons/react"
import {
    Button,
    Card,
    CardContent,
    Typography,
    cn,
} from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import type {
    Key,
    ReactNode,
} from "react"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"
import { mutateMarkAllNotificationsAsRead } from "@/modules/api/graphql/mutations/mutation-mark-all-notifications-as-read"
import { mutateMarkNotificationAsRead } from "@/modules/api/graphql/mutations/mutation-mark-notification-as-read"
import {
    NotificationType,
    type QueryNotificationData,
} from "@/modules/api/graphql/queries/types/notifications"
import { resolveNotificationTargetPath } from "@/modules/notifications/resolve-notification-target"
import { useQueryMyNotificationsSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyNotificationsSwr"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { SurfaceListCard, SurfaceListCardRow } from "@/components/blocks/cards/SurfaceListCard"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { ResponsiveBreadcrumb } from "@/components/blocks/navigation/ResponsiveBreadcrumb"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { pathConfig } from "@/resources/path"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/** Props for {@link NotificationsPage}. */
export type NotificationsPageProps = WithClassNames<undefined>

/** Page size for the notification center's pager (bigger than the bell's popover page). */
const PAGE_SIZE = 20

/** The "All" tab has no `type` filter — a dedicated key distinct from any real
 *  {@link NotificationType} so it round-trips through the tab strip cleanly. */
const ALL_TAB = "all"

/** One filter tab: 1:1 with a real {@link NotificationType} (plus the "All"
 *  catch-all) — every type stays reachable, nothing is silently grouped away. */
type TabKey = typeof ALL_TAB | NotificationType

/** Icon per {@link NotificationType} — mirrors the motif each type's action carries
 *  elsewhere in the app (challenge = puzzle piece, streak = flame, …). */
const TYPE_ICONS: Record<NotificationType, ReactNode> = {
    [NotificationType.System]: <BellIcon aria-hidden focusable="false" />,
    [NotificationType.ChallengeGraded]: <PuzzlePieceIcon aria-hidden focusable="false" />,
    [NotificationType.CodingGraded]: <CodeIcon aria-hidden focusable="false" />,
    [NotificationType.MilestoneGraded]: <FlagIcon aria-hidden focusable="false" />,
    [NotificationType.NewFollower]: <UserPlusIcon aria-hidden focusable="false" />,
    [NotificationType.CommentReply]: <ChatCircleIcon aria-hidden focusable="false" />,
    [NotificationType.CommunityReply]: <UsersThreeIcon aria-hidden focusable="false" />,
    [NotificationType.SubscriptionGranted]: <SparkleIcon aria-hidden focusable="false" />,
    [NotificationType.Announcement]: <MegaphoneIcon aria-hidden focusable="false" />,
    [NotificationType.StreakMilestone]: <FlameIcon aria-hidden focusable="false" />,
}

/**
 * "Notification Center" — the full notification feed the bell's "View all"
 * deep-links into. Same query/mutations/deep-link resolution as
 * `NotificationBell` (`components/features/navbar/Navbar/NotificationBell`),
 * just with type filter tabs + a bigger offset-paginated page instead of the
 * popover's fixed recent slice. `"use client"` for the SWR hook, tab/page state,
 * and navigation.
 * @param props - optional root class name
 */
export const NotificationsPage = ({ className }: NotificationsPageProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const runGraphQL = useGraphQLWithToast()

    const [tab, setTab] = useState<TabKey>(ALL_TAB)
    const [page, setPage] = useState(1)

    const type = tab === ALL_TAB ? undefined : tab
    const offset = (page - 1) * PAGE_SIZE
    const { data, isLoading, error, mutate } = useQueryMyNotificationsSwr({
        limit: PAGE_SIZE,
        offset,
        type,
    })

    const items = data?.items ?? []
    const total = data?.total ?? 0
    const unreadCount = data?.unreadCount ?? 0
    const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE))

    /** Locale-aware relative-time formatter for the item timestamps — same
     *  formatting rule as the bell. */
    const relativeFormat = useMemo(
        () => new Intl.RelativeTimeFormat(locale, { numeric: "auto" }),
        [locale],
    )

    const formatRelative = useCallback(
        (iso: string): string => {
            const diffMs = new Date(iso).getTime() - Date.now()
            const diffMin = Math.round(diffMs / 60_000)
            const absMin = Math.abs(diffMin)
            if (absMin < 60) {
                return relativeFormat.format(diffMin, "minute")
            }
            const diffHour = Math.round(diffMin / 60)
            if (Math.abs(diffHour) < 24) {
                return relativeFormat.format(diffHour, "hour")
            }
            const diffDay = Math.round(diffHour / 24)
            return relativeFormat.format(diffDay, "day")
        },
        [relativeFormat],
    )

    /** Switching tabs re-queries from the first page — a filtered set may have
     *  fewer pages than the one the viewer was on. */
    const onSelectTab = useCallback((key: Key) => {
        setTab(String(key) as TabKey)
        setPage(1)
    }, [])

    /** Mark a single notification read and navigate to its resolved target —
     *  identical flow to the bell's `onPressItem`, sharing the same helper. */
    const onPressItem = useCallback(
        async (notification: QueryNotificationData) => {
            if (!notification.isRead) {
                await runGraphQL(
                    async () => {
                        const env = await mutateMarkNotificationAsRead({
                            request: { notificationId: notification.id },
                        })
                        return env.data!.markNotificationAsRead
                    },
                    { showSuccessToast: false, showErrorToast: false },
                )
                await mutate()
            }
            const { target } = notification
            if (!target) {
                return
            }
            const path = await resolveNotificationTargetPath(target)
            if (path) {
                router.push(`/${locale}${path}`)
            }
        },
        [locale, mutate, router, runGraphQL],
    )

    const onMarkAllRead = useCallback(
        async () => {
            await runGraphQL(
                async () => {
                    const env = await mutateMarkAllNotificationsAsRead({
                        request: undefined,
                    })
                    return env.data!.markAllNotificationsAsRead
                },
                { showSuccessToast: false, showErrorToast: true },
            )
            await mutate()
        },
        [mutate, runGraphQL],
    )

    const goToCourses = () => router.push(pathConfig().locale(locale).course().build())

    return (
        <Box principle="center-measure" className={cn("mx-auto max-w-3xl p-6", className)}
            explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport."
        >
            <StackV gap={7} principle="layout-split"
                explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
                items={[
                    () => (
                        <PageHeader
                            breadcrumb={(
                                <ResponsiveBreadcrumb
                                    items={[
                                        {
                                            key: "home",
                                            label: t("nav.home"),
                                            onPress: () => router.push(pathConfig().locale(locale).build()),
                                        },
                                        {
                                            key: "notifications",
                                            label: t("notifications.title"),
                                        },
                                    ]}
                                />
                            )}
                            title={t("notifications.title")}
                            description={t("notifications.description")}
                            actions={unreadCount > 0 ? (
                                <Button
                                    variant="secondary"
                                    size="sm"
                                    onPress={onMarkAllRead}
                                >
                                    <CheckDoubleIcon className="size-4" aria-hidden focusable="false" />
                                    {t("notifications.markAllRead")}
                                </Button>
                            ) : undefined}
                        />
                    ),

                    () => (
                        <StackV gap={6} principle="block-boundary"
                            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                            items={[
                                () => (
                                    <TabsCard
                                        leftTabs={{
                                            items: [
                                                { key: ALL_TAB, label: t("notifications.tabs.all") },
                                                {
                                                    key: NotificationType.CommentReply,
                                                    label: t("notifications.tabs.commentReply"),
                                                    icon: <ChatCircleIcon className="size-4" aria-hidden focusable="false" />,
                                                },
                                                {
                                                    key: NotificationType.CommunityReply,
                                                    label: t("notifications.tabs.communityReply"),
                                                    icon: <UsersThreeIcon className="size-4" aria-hidden focusable="false" />,
                                                },
                                                {
                                                    key: NotificationType.MilestoneGraded,
                                                    label: t("notifications.tabs.milestoneGraded"),
                                                    icon: <FlagIcon className="size-4" aria-hidden focusable="false" />,
                                                },
                                                {
                                                    key: NotificationType.ChallengeGraded,
                                                    label: t("notifications.tabs.challengeGraded"),
                                                    icon: <PuzzlePieceIcon className="size-4" aria-hidden focusable="false" />,
                                                },
                                                {
                                                    key: NotificationType.CodingGraded,
                                                    label: t("notifications.tabs.codingGraded"),
                                                    icon: <CodeIcon className="size-4" aria-hidden focusable="false" />,
                                                },
                                                {
                                                    key: NotificationType.NewFollower,
                                                    label: t("notifications.tabs.newFollower"),
                                                    icon: <UserPlusIcon className="size-4" aria-hidden focusable="false" />,
                                                },
                                                {
                                                    key: NotificationType.SubscriptionGranted,
                                                    label: t("notifications.tabs.subscriptionGranted"),
                                                    icon: <SparkleIcon className="size-4" aria-hidden focusable="false" />,
                                                },
                                                {
                                                    key: NotificationType.StreakMilestone,
                                                    label: t("notifications.tabs.streakMilestone"),
                                                    icon: <FlameIcon className="size-4" aria-hidden focusable="false" />,
                                                },
                                                {
                                                    key: NotificationType.Announcement,
                                                    label: t("notifications.tabs.announcement"),
                                                    icon: <MegaphoneIcon className="size-4" aria-hidden focusable="false" />,
                                                },
                                                {
                                                    key: NotificationType.System,
                                                    label: t("notifications.tabs.system"),
                                                    icon: <BellIcon className="size-4" aria-hidden focusable="false" />,
                                                },
                                            ],
                                            selectedKey: tab,
                                            ariaLabel: t("notifications.tabsAria"),
                                            onSelectionChange: onSelectTab,
                                        }}
                                        className="overflow-x-auto"
                                    />
                                ),

                                () => (
                                    <AsyncContent
                                        isLoading={isLoading && !data}
                                        skeleton={(
                                            <SurfaceListCard>
                                                {[0, 1, 2, 3, 4].map((row) => (
                                                    <Box key={row} principle="row-pad" className="px-4 py-4"
                                                        explain="Row content inset — not cell-pad, because this pads a horizontal content row rather than a dense table cell.">
                                                        <StackH gap={4} principle="content-row" align="center"
                                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                            items={[
                                                                () => <Skeleton className="size-9 shrink-0 rounded-full" />,
                                                                () => (
                                                                    <StackV gap={3} principle="sibling-stack" classNames={["flex-1"]}
                                                                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                                        items={[
                                                                            () => <Skeleton className="h-4 w-2/3 rounded-medium" />,
                                                                            () => <Skeleton className="h-3 w-1/3 rounded-medium" />,
                                                                        ]} />
                                                                ),
                                                            ]} />
                                                    </Box>
                                                ))}
                                            </SurfaceListCard>
                                        )}
                                        error={error}
                                        errorContent={{
                                            title: t("notifications.loadError"),
                                            onRetry: () => { void mutate() },
                                            retryLabel: t("notifications.retry"),
                                        }}
                                    >
                                        {items.length === 0 ? (
                                        // `EmptyState` intentionally omits its own frame — wrap it in `<Card>` to
                                        // match the shape of the list card when there is data (`components/card.md` §2).
                                            <Card>
                                                <CardContent>
                                                    <EmptyState
                                                        icon={BellIcon}
                                                        title={tab === ALL_TAB ? t("notifications.empty") : t("notifications.emptyFiltered")}
                                                        action={() => tab === ALL_TAB ? (
                                                        // Genuinely platform-empty (never had any notification) — the CTA must be
                                                        // a primary funnel invitation, not a quiet secondary one (canon §Conversion).
                                                            <Button size="sm" variant="primary" onPress={goToCourses}>
                                                                {t("notifications.emptyCta")}
                                                                <ArrowRightIcon aria-hidden focusable="false" className="size-4" />
                                                            </Button>
                                                        ) : (
                                                        // Filtered-empty (a filtered tab that's empty) — the CTA must go back to
                                                        // viewing everything (clear the filter), not push out to the course page
                                                        // (canon §State-matrix: 2 different reasons for empty → 2 CTAs with different meaning).
                                                            <Button size="sm" variant="secondary" onPress={() => onSelectTab(ALL_TAB)}>
                                                                {t("notifications.clearFilters")}
                                                            </Button>
                                                        )}
                                                    />
                                                </CardContent>
                                            </Card>
                                        ) : (
                                            <StackV gap={4} principle="content-row"
                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                items={[
                                                    () => (
                                                        <SurfaceListCard>
                                                            {items.map((notification) => (
                                                                <SurfaceListCardRow
                                                                    key={notification.id}
                                                                    leading={() => (
                                                                        <span
                                                                            className={cn(
                                                                                "flex size-9 shrink-0 items-center justify-center rounded-full [&>svg]:size-4",
                                                                                notification.isRead
                                                                                    ? "bg-default text-muted"
                                                                                    : "bg-accent-soft text-accent-soft-foreground",
                                                                            )}
                                                                        >
                                                                            {TYPE_ICONS[notification.type]}
                                                                        </span>
                                                                    )}
                                                                    title={t(
                                                                        notification.title.key,
                                                                        notification.title.params ?? undefined,
                                                                    )}
                                                                    subtitle={notification.body
                                                                        ? t(
                                                                            notification.body.key,
                                                                            notification.body.params ?? undefined,
                                                                        )
                                                                        : undefined}
                                                                    meta={() => (
                                                                        <Typography type="body-xs" color="muted" className="whitespace-nowrap">
                                                                            {formatRelative(notification.createdAt)}
                                                                        </Typography>
                                                                    )}
                                                                    // unread dot moves here from beside the title: `title` is plain
                                                                    // text now (never a built element) and `titleClassName` stays
                                                                    // lint-forbidden, so the unread signal — already echoed by the
                                                                    // leading badge's accent tint — rides the row's one remaining slot.
                                                                    trailing={!notification.isRead ? () => (
                                                                        <CircleIcon
                                                                            weight="fill"
                                                                            aria-hidden
                                                                            focusable="false"
                                                                            className="size-1.5 shrink-0 text-accent-soft-foreground"
                                                                        />
                                                                    ) : undefined}
                                                                    onPress={() => onPressItem(notification)}
                                                                />
                                                            ))}
                                                        </SurfaceListCard>
                                                    ),

                                                    () => (totalPages > 1 ? (
                                                        <StackH gap={4} principle="content-row" justify="between" align="center"
                                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                            items={[
                                                                () => (
                                                                    <Typography type="body-xs" color="muted">
                                                                        {t("notifications.pageInfo", {
                                                                            from: offset + 1,
                                                                            to: Math.min(offset + PAGE_SIZE, total),
                                                                            total,
                                                                        })}
                                                                    </Typography>
                                                                ),
                                                                () => (
                                                                    <StackH gap={3} principle="flex-action" align="center"
                                                                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                                                        items={[
                                                                            () => (
                                                                                <Button
                                                                                    variant="secondary"
                                                                                    size="sm"
                                                                                    isDisabled={page <= 1}
                                                                                    onPress={() => setPage((current) => Math.max(1, current - 1))}
                                                                                >
                                                                                    {t("common.pagination.previous")}
                                                                                </Button>
                                                                            ),
                                                                            () => (
                                                                                <Button
                                                                                    variant="secondary"
                                                                                    size="sm"
                                                                                    isDisabled={page >= totalPages}
                                                                                    onPress={() => setPage((current) => Math.min(totalPages, current + 1))}
                                                                                >
                                                                                    {t("common.pagination.next")}
                                                                                </Button>
                                                                            ),
                                                                        ]} />
                                                                ),
                                                            ]} />
                                                    ) : null),
                                                ]} />
                                        )}
                                    </AsyncContent>
                                ),
                            ]} />
                    ),
                ]} />
        </Box>
    )
}

import { InputText } from "@/components/atoms/forms"
import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { CaretRightIcon, GearSixIcon, SparkleIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import { Breadcrumbs, type BreadcrumbItem } from "@/components/atoms/navigation/Breadcrumbs"
import { Chip } from "@/components/atoms/chips/Chip"

import { Typography } from "@/components/atoms/text/Typography"
import {
    SurfaceCard,
    SurfaceCardAccordion,
    type SurfaceCardAccordionItem,
} from "@/components/composites/cards/SurfaceCard"
import { Callout } from "@/components/composites/feedback/Callout"
import { ListRow } from "@/components/composites/lists/List"
import { PageHeader } from "@/components/composites/layout/Page"
import { MarkdownContent } from "@/components/composites/viewers/MarkdownContent"
import { Container } from "@/components/frames/Container"
import { StackH, StackV } from "@/components/frames/Stack"
import { SplitWorkspace } from "@/components/frames/SplitWorkspace"
import {
    ContentRelatedList,
    type ContentRelatedItem,
} from "@/components/blocks/learn/ContentRelatedList"
import {
    SubmissionScoreCard,
    type AiModelCategory,
} from "@/components/blocks/learn/SubmissionScoreCard"

/**
 * `PersonalProjectTaskPage` — the screen to solve one personal-project task. A
 * screen owns a list of functions. Split workspace: a reading column that swaps
 * per task (task identity, the locked-preview banner, the authored brief or the
 * legacy rubric/implementation guides, and related lessons) beside a
 * persistent, sticky act column (repo URL, the settings-drawer trigger,
 * evaluate/secondary actions, and the latest graded result). Two columns
 * composed with `SplitWorkspace`: a `min-w-0 flex-1` reading column beside a
 * `shrink-0 w-[360px]` sticky aside, stacked on mobile/tablet →
 * `@app-xl:flex-row` on desktop. The grading-settings drawer content is not
 * built — `onOpenSettings` is a chrome trigger only.
 *
 * PRESENTATIONAL — every input arrives as a prop; this twin owns no data of
 * its own, so `index.tsx` IS the presentational file (no separate connected
 * wrapper, no `component.tsx` split) — mirrors `MindMapPage`'s convention.
 *
 * Emits its own identity (`data-tier="page"` / `data-component="PersonalProjectTaskPage"`)
 * unconditionally, handed down to the root `Container` via its `identity` prop
 * (see `frames/_identity.ts`) rather than drawn on a wrapper `div` of its own
 * (`tiers/block.md` BLOCK-2: a page never draws a shape of its own) — same as
 * `split.md`'s "Identity is data-tier + data-component" section. The
 * breadcrumb sits in a `StackH inline` (shrink-to-content sizing) rather
 * than a raw `div`.
 */

/** One personal-project schema-v1 evaluation criterion — the legacy rubric row. */
export interface PersonalProjectTaskLegacyCriterionItem {
    /** Stable React key, also the accordion item id. */
    key: string
    /** The criterion sentence itself. */
    text: string
    /** Points this criterion is worth. */
    score: number
    /** Optional grading hint, markdown. Omit → the panel shows a plain "no hint" line. */
    hint?: string
}

/** One legacy per-language implementation guide (schema-v1 tasks with no authored brief). */
export interface PersonalProjectTaskLegacyCodeImplementationItem {
    /** Stable React key, also the accordion item id. */
    key: string
    /** Target language label, e.g. "TypeScript". */
    lang: string
    /** How to approach the task in this language, markdown. */
    guide: string
    /** A worked example, markdown. */
    example: string
}

/** The task identity this screen reads about. */
export interface PersonalProjectTaskPageTask {
    /** Task title. */
    title: string
    /** One-paragraph summary of what the task asks for. */
    description?: string
}

/** The schema-v2 authored brief for this task. */
export interface PersonalProjectTaskPageBrief {
    /** The brief itself, markdown, already resolved to the active language/locale. */
    body: string
}

/** Cost/quality tier + model byline data for a graded submission — see {@link SubmissionScoreCard}. */
export interface PersonalProjectSubmissionResult {
    /** Points earned on the latest graded attempt. */
    score: number
    /** Points the attempt was scored out of. */
    maxScore?: number
    /** Whether this score cleared the pass bar. */
    isPassing: boolean
    /** The pass bar itself, in points. */
    passScore?: number
    /** A short line of grader feedback. */
    shortFeedback?: string
    /** The model that produced this grade. */
    gradedByModel?: string
    /** Cost/quality tier of {@link gradedByModel}. */
    modelCategory?: AiModelCategory
    /** Relative time since grading, already localized. */
    timeAgo?: string
}

/** Everything the persistent, sticky act column needs — the project-level submission loop. */
export interface PersonalProjectTaskSubmissionPanelProps {
    /** The GitHub repo URL as typed so far. */
    repoUrl: string
    /** Fired as the learner types the repo URL. */
    onRepoUrlChange: (value: string) => void
    /** Validation message for the repo URL field. Set → the field shows invalid. */
    repoUrlError?: string
    /** Grading language summary shown in the settings row, e.g. "TypeScript". */
    settingsLangLabel: string
    /** Grading branch summary shown in the settings row, e.g. "main". */
    settingsBranch: string
    /** Fired when the settings summary row is pressed — chrome trigger only, see file header. */
    onOpenSettings: () => void
    /** Fired to submit the current repo for AI evaluation. */
    onEvaluate: () => void
    /** `true` → the evaluate CTA shows its own spinner and blocks further presses. */
    isEvaluatePending?: boolean
    /** `true` → the evaluate CTA is disabled (the caller's own combined business rule — locked, syncing, …). */
    isEvaluateDisabled?: boolean
    /** `true` → at least one attempt exists, so the secondary actions unlock and the CTA reads "Re-evaluate". */
    hasAttempts?: boolean
    /** Fired to open the full feedback/result page. */
    onOpenFeedbackDetails: () => void
    /** Fired to open the attempts history drawer. */
    onOpenAttempts: () => void
    /** The latest graded attempt. Present → the score card renders; omit → nothing has been graded yet. */
    result?: PersonalProjectSubmissionResult
}

/** Props for {@link PersonalProjectTaskPage}. */
export interface PersonalProjectTaskPageProps {
    /** Breadcrumb trail as DATA — `PageHeader` builds `Breadcrumbs` itself. */
    breadcrumbItems?: Array<BreadcrumbItem>
    /** The task being read/solved. */
    task: PersonalProjectTaskPageTask
    /**
     * `true` → this task is not yet unlocked for the learner (previewing ahead
     * of their current milestone position). Shows the warning banner; nothing
     * else in the reading column changes shape.
     */
    isLocked?: boolean
    /** The schema-v2 authored brief. */
    brief: PersonalProjectTaskPageBrief
    /** Schema-v1 legacy rubric — only present on tasks with no authored brief. */
    legacyCriteria?: Array<PersonalProjectTaskLegacyCriterionItem>
    /** Schema-v1 legacy per-language implementation guides — only present alongside {@link legacyCriteria}. */
    legacyCodeImplementations?: Array<PersonalProjectTaskLegacyCodeImplementationItem>
    /** Lessons related to this task's subject, auto-derived by the caller from its title/description. */
    relatedItems: Array<ContentRelatedItem>
    /** Section label for {@link relatedItems}, e.g. "You might want to read". */
    relatedLabel: string
    /** Everything the persistent, sticky act column needs. */
    submissionPanelProps: PersonalProjectTaskSubmissionPanelProps
    /**
     * `true` → every part that can mirror itself does. Flows down into the
     * reading column's composed parts and the act column's fields/buttons/score
     * card (§12c) rather than a parallel skeleton tree built here.
     */
    isSkeleton?: boolean
}

/** Skeleton placeholder count for the legacy accordions while real data hasn't landed yet. */
const LEGACY_SKELETON_ROWS = 2

/** `ListRow.leading` for the grading-settings summary row — a gear icon, hidden while skeleton. */
const SettingsLeading = ({ isSkeleton }: SkeletonProps) =>
    isSkeleton ? null : <GearSixIcon aria-hidden focusable="false" className="size-4" />

/** `ListRow.trailing` for the grading-settings summary row — the disclosure chevron. */
const SettingsChevron = () => <CaretRightIcon aria-hidden focusable="false" weight="bold" className="size-4" />

/** One markdown body at the `compact` measure the legacy accordion panels use. */
const legacyMarkdown = (body: string) => (
    <MarkdownContent source={body} measure="compact" />
)

/** One legacy code-implementation accordion panel body: guide, then a worked example. */
const legacyCodeBody = (item: PersonalProjectTaskLegacyCodeImplementationItem) => {
    const guideSection = (
        <>
            <Typography size="xs" weight="medium" color="muted" text="Guide" />
            {legacyMarkdown(item.guide)}
        </>
    )
    const exampleSection = (
        <>
            <Typography size="xs" weight="medium" color="muted" text="Example" />
            {legacyMarkdown(item.example)}
        </>
    )
    return (
        <StackV
            gap={4}

            items={[
                () => <StackV gap={2} items={[() => guideSection]} />,
                () => <StackV gap={2} items={[() => exampleSection]} />,
            ]}
        />
    )
}

/**
 * The reading column: task identity (`PageHeader`) + the locked banner + the
 * brief itself + the legacy rubric/implementation guides + related lessons.
 * A private render helper (see file header for why this is not a separate
 * storied component), not an anatomy node of its own.
 */
const readingColumn = (props: {
    breadcrumbItems?: Array<BreadcrumbItem>
    task: PersonalProjectTaskPageTask
    isLocked: boolean
    brief: PersonalProjectTaskPageBrief
    legacyCriteria?: Array<PersonalProjectTaskLegacyCriterionItem>
    legacyCodeImplementations?: Array<PersonalProjectTaskLegacyCodeImplementationItem>
    relatedItems: Array<ContentRelatedItem>
    relatedLabel: string
    isSkeleton: boolean
}) => {
    const {
        breadcrumbItems,
        task,
        isLocked,
        brief,
        legacyCriteria,
        legacyCodeImplementations,
        relatedItems,
        relatedLabel,
        isSkeleton,
    } = props

    const hasLegacyCriteria = (legacyCriteria?.length ?? 0) > 0
    const hasLegacyCode = (legacyCodeImplementations?.length ?? 0) > 0
    const showLegacy = isSkeleton || hasLegacyCriteria || hasLegacyCode
    // Schema-v2 tasks always carry an authored brief; schema-v1 (legacy) tasks
    // hand this screen an empty `body` and rely on the legacy section instead
    // (mirrors `src`'s `TaskBrief` self-hiding when `briefs.length === 0`).
    const showBrief = isSkeleton || brief.body.trim().length > 0

    const criteriaItems: Array<SurfaceCardAccordionItem> = hasLegacyCriteria
        ? (legacyCriteria ?? []).map((item, index) => ({
            id: item.key,
            title: `${index + 1}. ${item.text}`,
            titleEnd: () => <Chip tone="accent" text={`${item.score} points`} />,
            body: () => (
                item.hint
                    ? legacyMarkdown(item.hint)
                    : <Typography size="sm" color="muted"
                        isItalic text="No grading hint yet" />
            ),
        }))
        : isSkeleton
            ? Array.from({ length: LEGACY_SKELETON_ROWS }, (_unused, index) => ({ id: `criteria-skeleton-${index}`, title: "", body: () => null }))
            : []

    const codeItems: Array<SurfaceCardAccordionItem> = hasLegacyCode
        ? (legacyCodeImplementations ?? []).map((item) => ({
            id: item.key,
            title: item.lang,
            body: () => legacyCodeBody(item),
        }))
        : isSkeleton
            ? Array.from({ length: LEGACY_SKELETON_ROWS }, (_unused, index) => ({ id: `code-skeleton-${index}`, title: "", body: () => null }))
            : []

    const legacyAccordions = (
        <>
            {hasLegacyCriteria || isSkeleton ? (
                <SurfaceCardAccordion
                    variant="nested"
                    items={criteriaItems}
                    allowsMultipleExpanded
                    isSkeleton={isSkeleton}


                />
            ) : null}
            {hasLegacyCode || isSkeleton ? (
                <SurfaceCardAccordion
                    variant="nested"
                    items={codeItems}
                    allowsMultipleExpanded
                    isSkeleton={isSkeleton}


                />
            ) : null}
        </>
    )

    const readingSections = (
        <>
            <PageHeader

                isSkeleton={isSkeleton}
                breadcrumb={() =>
                    isSkeleton || breadcrumbItems?.length ? (
                        <StackH
                            inline
                            gap={1}
                            body={() => (
                                <Breadcrumbs collapseOnMobile collapseFrom={4} items={breadcrumbItems ?? []} isSkeleton={isSkeleton} />
                            )}
                        />
                    ) : undefined
                }
                title={task.title}
                description={task.description}
            />

            {!isSkeleton && isLocked ? (
                <Callout
                    status="warning"
                    title="Preview of a task not yet unlocked"
                    description="You need to finish the current task before you can work on this one."

                />
            ) : null}

            {showBrief ? (
                <SurfaceCard
                    label="Guide"
                    isSkeleton={isSkeleton}

                    body={() => <MarkdownContent source={brief.body} />}
                />
            ) : null}

            {showLegacy ? (
                <SurfaceCard
                    label="Evaluation criteria (legacy)"
                    isSkeleton={isSkeleton}

                    body={() => <StackV gap={6} items={[() => legacyAccordions]} />}
                />
            ) : null}

            <ContentRelatedList
                label={relatedLabel}
                items={relatedItems}
                isSkeleton={isSkeleton}

            />
        </>
    )

    return <StackV gap={7} isSkeleton={isSkeleton} items={[() => readingSections]} />
}

/**
 * The persistent, sticky act column: repo URL + settings summary trigger +
 * evaluate/secondary actions + the latest graded result. A private render
 * helper (see file header), not an anatomy node of its own.
 */
const submissionPanel = (props: {
    panel: PersonalProjectTaskSubmissionPanelProps
    isSkeleton: boolean
}) => {
    const { panel, isSkeleton } = props
    const hasAttempts = panel.hasAttempts ?? false

    const evaluateActions = (
        <>
            <Button
                label={hasAttempts ? "Re-evaluate" : "Evaluate"}
                prefixIcon={SparkleIcon}
                onPress={panel.onEvaluate}
                isPending={panel.isEvaluatePending}
                isDisabled={panel.isEvaluateDisabled}
                isSkeleton={isSkeleton}

            />
            <Button
                label="View feedback"
                variant="tertiary"
                onPress={panel.onOpenFeedbackDetails}
                isDisabled={!hasAttempts}
                isSkeleton={isSkeleton}

            />
            <Button
                label="View submission history"
                variant="tertiary"
                onPress={panel.onOpenAttempts}
                isDisabled={!hasAttempts}
                isSkeleton={isSkeleton}

            />
        </>
    )

    const githubFields = (
        <>
            <InputText
                label="GitHub repo URL"
                value={panel.repoUrl}
                onValueChange={panel.onRepoUrlChange}
                errorMessage={panel.repoUrlError}
                placeholder="https://github.com/…"
                ariaLabel="GitHub repo URL"
                isSkeleton={isSkeleton}

            />
            <div>
                <ListRow
                    leading={SettingsLeading}
                    title="Grading settings"
                    meta={() => <Typography size="sm" color="muted" text={`${panel.settingsLangLabel} · ${panel.settingsBranch}`} />}
                    trailing={SettingsChevron}
                    onPress={panel.onOpenSettings}
                    isSkeleton={isSkeleton}

                />
            </div>
            <StackH gap={3} at="sm" principle="flex-action" isSkeleton={isSkeleton} items={[() => evaluateActions]}
                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            />
        </>
    )

    const panelSections = (
        <>
            <SurfaceCard
                label="Project GitHub"
                isSkeleton={isSkeleton}

                body={() => <StackV gap={6} isSkeleton={isSkeleton} items={[() => githubFields]} />}
            />

            {isSkeleton || panel.result != null ? (
                <SubmissionScoreCard
                    label="Latest grading result"
                    score={panel.result?.score ?? 0}
                    maxScore={panel.result?.maxScore}
                    isPassing={panel.result?.isPassing ?? true}
                    passScore={panel.result?.passScore}
                    shortFeedback={panel.result?.shortFeedback}
                    gradedByModel={panel.result?.gradedByModel}
                    modelCategory={panel.result?.modelCategory}
                    timeAgo={panel.result?.timeAgo}
                    isSkeleton={isSkeleton}


                />
            ) : null}
        </>
    )

    return <StackV gap={6} isSkeleton={isSkeleton} items={[() => panelSections]} />
}

/**
 * The personal-project task solve screen. See the file header for the function
 * list, the reuse map, and the two-column layout's known limits.
 *
 * @param props - {@link PersonalProjectTaskPageProps}
 */
const PersonalProjectTaskPage = ({
    breadcrumbItems,
    task,
    isLocked = false,
    brief,
    legacyCriteria,
    legacyCodeImplementations,
    relatedItems,
    relatedLabel,
    submissionPanelProps,
    isSkeleton = false,
}: PersonalProjectTaskPageProps) => (
    <Container
        identity={{ tier: "page", component: "PersonalProjectTaskPage" }}
        size="xl"
        padding={6}
        body={() => (
            <SplitWorkspace

                main={() => readingColumn({
                    breadcrumbItems,
                    task,
                    isLocked,
                    brief,
                    legacyCriteria,
                    legacyCodeImplementations,
                    relatedItems,
                    relatedLabel,
                    isSkeleton,
                })}
                aside={() => submissionPanel({ panel: submissionPanelProps, isSkeleton })}
            />
        )}
    />
)

export { PersonalProjectTaskPage }

"use client"

import React from "react"
import {
    Button,
    Label,
    ListBox,
    SearchField,
    Select,
    Typography,
    cn,
} from "@heroui/react"
import { useTranslations } from "next-intl"
import {
    RowsIcon,
    SquaresFourIcon,
} from "@phosphor-icons/react"
import { FlexWrapButtonRadio } from "@/components/blocks/navigation/FlexWrapButtonRadio"
import { StackH, StackV } from "@/components/frames/Stack"
import { usePracticeFilters } from "../hooks/usePracticeFilters"
import {
    CODING_DIFFICULTY_META,
    DIFFICULTY_FILTERS,
    SORT_KEYS,
    STATUS_FILTERS,
} from "../constants"
import type {
    DifficultyFilter,
    SortKey,
    StatusFilter,
} from "../types"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link PracticeFilters}. */
export type PracticeFiltersProps = WithClassNames<undefined>

/**
 * The PracticeHubPage catalog filter bar — a title search box plus difficulty / status
 * filter chips (HeroUI Buttons, secondary when active / ghost when not), a sort
 * `Select`, and a group-by-domain toggle. The topic (domain) filter lives in the
 * {@link import("../PracticeRail").PracticeRail} sidebar, not here. Reads + writes
 * the URL-backed filter state itself ({@link usePracticeFilters}); composes blocks
 * + HeroUI only.
 *
 * @param props - optional className for the root element.
 */
export const PracticeFilters = ({
    className,
}: PracticeFiltersProps) => {
    const t = useTranslations()
    const { filters, setFilters } = usePracticeFilters()

    return (
        <div className={cn("flex flex-col gap-4", className)}>
            {/* title search — client-side filter over loaded problems */}
            <SearchField
                aria-label={t("PracticeHubPage.filters.searchPlaceholder")}
                value={filters.q}
                onChange={(value) => setFilters({ q: value })}
            >
                <Label className="sr-only">{t("PracticeHubPage.filters.searchPlaceholder")}</Label>
                <SearchField.Group>
                    <SearchField.SearchIcon />
                    <SearchField.Input placeholder={t("PracticeHubPage.filters.searchPlaceholder")} />
                    <SearchField.ClearButton />
                </SearchField.Group>
            </SearchField>

            {/* difficulty + status chip groups */}
            <StackV gap={4} principle="card-caption"
                explain="Holds caption text under card media so the caption stays attached to the image above it."
                items={[
                    () => (
                        <FlexWrapButtonRadio
                            ariaLabel={t("PracticeHubPage.filters.difficultyAria")}
                            value={filters.difficulty}
                            onChange={(value) => setFilters({ difficulty: value as DifficultyFilter })}
                            items={DIFFICULTY_FILTERS.map((value) => ({
                                value,
                                content: value === "all"
                                    ? t("PracticeHubPage.filters.allDifficulties")
                                    : t(CODING_DIFFICULTY_META[value].labelKey),
                            }))}
                        />
                    ),
                    () => (
                        <FlexWrapButtonRadio
                            ariaLabel={t("PracticeHubPage.filters.statusAria")}
                            value={filters.status}
                            onChange={(value) => setFilters({ status: value as StatusFilter })}
                            items={STATUS_FILTERS.map((value) => ({
                                value,
                                content: t(`PracticeHubPage.filters.status.${value}`),
                            }))}
                        />
                    ),
                ]} />

            {/* sort dropdown + group toggle */}
            <StackH gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (
                        <StackV gap={3} principle="sibling-stack"
                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                            items={[
                                () => <Label className="sr-only">{t("PracticeHubPage.filters.sortAria")}</Label>,
                                () => (
                                    <Select.Root<{ id: string }, "single">
                                        aria-label={t("PracticeHubPage.filters.sortAria")}
                                        selectedKey={filters.sort}
                                        onSelectionChange={(key) => setFilters({ sort: String(key) as SortKey })}
                                    >
                                        <Select.Trigger aria-label={t("PracticeHubPage.filters.sortAria")} className="w-fit min-w-40">
                                            <Select.Value>
                                                {() => (
                                                    <Typography type="body-sm">
                                                        {t(`PracticeHubPage.filters.sort.${filters.sort}`)}
                                                    </Typography>
                                                )}
                                            </Select.Value>
                                            <Select.Indicator />
                                        </Select.Trigger>
                                        <Select.Popover>
                                            <ListBox.Root aria-label={t("PracticeHubPage.filters.sortAria")}>
                                                {SORT_KEYS.map((value) => (
                                                    <ListBox.Item
                                                        key={value}
                                                        id={value}
                                                        textValue={t(`PracticeHubPage.filters.sort.${value}`)}
                                                    >
                                                        {t(`PracticeHubPage.filters.sort.${value}`)}
                                                    </ListBox.Item>
                                                ))}
                                            </ListBox.Root>
                                        </Select.Popover>
                                    </Select.Root>
                                ),
                            ]} />
                    ),
                    () => (
                        <Button
                            size="sm"
                            variant={filters.group ? "secondary" : "ghost"}
                            aria-pressed={filters.group}
                            onPress={() => setFilters({ group: !filters.group })}
                        >
                            {filters.group ? (
                                <SquaresFourIcon aria-hidden focusable="false" className="size-5" />
                            ) : (
                                <RowsIcon aria-hidden focusable="false" className="size-5" />
                            )}
                            {filters.group
                                ? t("PracticeHubPage.filters.grouped")
                                : t("PracticeHubPage.filters.flat")}
                        </Button>
                    ),
                ]} />
        </div>
    )
}

"use client"

import React from "react"
import {
    Button,
    ScrollShadow,
    cn,
} from "@heroui/react"
import {
    ListChecksIcon,
    TrophyIcon,
} from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { CODING_DOMAIN_ORDER } from "@/modules/api/graphql/queries/types/coding"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { StackH } from "@/components/frames/Stack"
import { usePracticeView } from "../../hooks/usePracticeView"
import { usePracticeFilters } from "../../hooks/usePracticeFilters"
import type { PracticeView } from "../../hooks/usePracticeView"
import type { DomainFilter } from "../../types"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link PracticeMobileNav}. */
export type PracticeMobileNavProps = WithClassNames<undefined>

/** All topic options for the mobile chip row: "all" + the canonical domain order. */
const MOBILE_TOPICS: ReadonlyArray<DomainFilter> = ["all", ...CODING_DOMAIN_ORDER]

/**
 * Mobile counterpart of {@link import("..").PracticeRail}: the docs-style rail
 * hides below `lg`, so the mode switch + topic filter fold into scrollable chip
 * rows above the work pane (the master-detail mobile pattern). Reads/writes the
 * same URL state as the rail ({@link usePracticeView} + {@link usePracticeFilters}),
 * so the two stay in lockstep. Topics show only in Problems mode.
 *
 * @param props - {@link PracticeMobileNavProps}
 */
export const PracticeMobileNav = ({ className }: PracticeMobileNavProps) => {
    const t = useTranslations()
    const { view, setView } = usePracticeView()
    const { filters, setFilters } = usePracticeFilters()

    return (
        <div className={cn("flex flex-col gap-3 @app-lg:hidden", className)}>
            {/* mode switch — mirrors the desktop rail's TabsCard (see PracticeRail) */}
            <TabsCard
                variant="primary"
                leftTabs={{
                    selectedKey: view,
                    ariaLabel: t("PracticeHubPage.rail.modeAria"),
                    onSelectionChange: (key) => setView(String(key) as PracticeView),
                    items: [
                        {
                            key: "problems",
                            label: (
                                <StackH gap={3} principle="flex-action" as="span"
                                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                    items={[
                                        () => <ListChecksIcon className="size-4 shrink-0" aria-hidden focusable="false" />,
                                        () => <>{t("PracticeHubPage.tabs.problems")}</>,
                                    ]} />
                            ),
                        },
                        {
                            key: "leaderboard",
                            label: (
                                <StackH gap={3} principle="flex-action" as="span"
                                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                    items={[
                                        () => <TrophyIcon className="size-4 shrink-0" aria-hidden focusable="false" />,
                                        () => <>{t("PracticeHubPage.tabs.leaderboard")}</>,
                                    ]} />
                            ),
                        },
                    ],
                }}
            />

            {/* topic chips — problems mode only */}
            {view === "problems" ? (
                <ScrollShadow
                    orientation="horizontal"
                    hideScrollBar
                    className="overflow-x-auto"
                >
                    <StackH
                        gap={3}
                        principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        items={MOBILE_TOPICS.map((domain) => (
                            () => (
                                <Button
                                    size="sm"
                                    variant={filters.domain === domain ? "secondary" : "ghost"}
                                    aria-pressed={filters.domain === domain}
                                    className="shrink-0"
                                    onPress={() => setFilters({ domain })}
                                >
                                    {domain === "all"
                                        ? t("PracticeHubPage.filters.allDomains")
                                        : t(`codingPractice.domain.${domain}`)}
                                </Button>
                            )
                        ))}
                    />
                </ScrollShadow>
            ) : null}
        </div>
    )
}

"use client"

import React, {
    useMemo,
    useState,
} from "react"
import {
    Input,
    Label,
    ListBox,
    ScrollShadow,
    TextField,
    Typography,
    cn,
} from "@heroui/react"
import {
    ListChecksIcon,
    TrophyIcon,
} from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { CODING_DOMAIN_ORDER } from "@/modules/api/graphql/queries/types/coding"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"
import { usePracticeView } from "../hooks/usePracticeView"
import { usePracticeFilters } from "../hooks/usePracticeFilters"
import type { PracticeView } from "../hooks/usePracticeView"
import type { DomainFilter } from "../types"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link PracticeRail}. */
export type PracticeRailProps = WithClassNames<undefined>

/**
 * The PracticeHubPage LEFT RAIL — the same docs-style sidebar as the flashcards /
 * content-map rail (a pinned header over a scroll region, full rail height). A
 * mode switch (Problems / Leaderboard) above the course-domain topics as a
 * searchable nav list. The mode drives the URL view ({@link usePracticeView}); the
 * chosen topic drives the catalog domain filter ({@link usePracticeFilters}), so
 * the rail and the work pane share one source of truth. Topics show only in
 * Problems mode (the leaderboard is topic-agnostic). Placed in the rail column by
 * the page shell; reads/writes URL state directly (no data props).
 *
 * @param props - {@link PracticeRailProps}
 */
export const PracticeRail = ({ className }: PracticeRailProps) => {
    const t = useTranslations()
    const { view, setView } = usePracticeView()
    const { filters, setFilters } = usePracticeFilters()
    const [query, setQuery] = useState("")

    /** Resolve a topic's display label ("All topics" or a domain name). */
    const topicLabel = (domain: DomainFilter): string =>
        domain === "all"
            ? t("PracticeHubPage.filters.allDomains")
            : t(`codingPractice.domain.${domain}`)

    // the topic rows: "all" + the canonical domain order, narrowed by the search box
    const topics = useMemo<Array<DomainFilter>>(() => {
        const all: Array<DomainFilter> = ["all", ...CODING_DOMAIN_ORDER]
        const normalized = query.trim().toLowerCase()
        if (!normalized) {
            return all
        }
        return all.filter((domain) => topicLabel(domain).toLowerCase().includes(normalized))
    }, [query, t])

    return (
        <div className={cn("relative flex min-h-0 min-w-0 flex-col gap-3 p-6", className)}>
            {/* pinned header: mode switch + topic search */}
            <StackV gap={4} principle="card-caption"
                explain="Holds caption text under card media so the caption stays attached to the image above it."
                items={[
                    () => (
                        <TabsCard
                            variant="primary"
                            leftTabs={{
                                selectedKey: view,
                                ariaLabel: t("PracticeHubPage.rail.modeAria"),
                                onSelectionChange: (key) => setView(String(key) as PracticeView),
                                items: [
                                    {
                                        key: "problems",
                                        label: (
                                            <StackH gap={3} principle="flex-action" as="span"
                                                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                                items={[
                                                    () => <ListChecksIcon className="size-4 shrink-0" aria-hidden focusable="false" />,
                                                    () => <>{t("PracticeHubPage.tabs.problems")}</>,
                                                ]} />
                                        ),
                                    },
                                    {
                                        key: "leaderboard",
                                        label: (
                                            <StackH gap={3} principle="flex-action" as="span"
                                                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                                items={[
                                                    () => <TrophyIcon className="size-4 shrink-0" aria-hidden focusable="false" />,
                                                    () => <>{t("PracticeHubPage.tabs.leaderboard")}</>,
                                                ]} />
                                        ),
                                    },
                                ],
                            }}
                        />
                    ),
                    () => view === "problems" ? (
                        <StackV gap={3} principle="sibling-stack"
                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                            items={[
                                () => <Label className="px-1 text-xs text-muted" data-principle="control-pad">{t("PracticeHubPage.rail.topicsLabel")}</Label>,
                                () => (
                                    <TextField>
                                        <Input
                                            type="search"
                                            aria-label={t("PracticeHubPage.rail.searchTopic")}
                                            placeholder={t("PracticeHubPage.rail.searchTopic")}
                                            value={query}
                                            onChange={(event) => setQuery(event.target.value)}
                                        />
                                    </TextField>
                                ),
                            ]} />
                    ) : null,
                ]} />

            {/* scroll region: the topic nav list (problems mode only) */}
            {view === "problems" ? (
                <ScrollShadow
                    hideScrollBar
                    className="-mx-1 min-h-0 min-w-0 flex-1 overflow-y-auto px-1" data-principle="control-pad"
                >
                    {topics.length === 0 ? (
                        <Box principle="control-pad" className="px-3 py-2"
                            explain="Control hit-area inset — not row-pad, because this pads a single interactive control rather than a full content row.">
                            <Typography type="body-sm" color="muted">
                                {t("PracticeHubPage.rail.searchTopicEmpty", { query: query.trim() })}
                            </Typography>
                        </Box>
                    ) : (
                        <ListBox
                            aria-label={t("PracticeHubPage.rail.topicsAria")}
                            selectionMode="single"
                            disallowEmptySelection
                            selectedKeys={[filters.domain]}
                            onSelectionChange={(keys) => {
                                // controlled single-select → filter the catalog by the chosen topic
                                const key = [...keys][0]
                                if (typeof key === "string") {
                                    setFilters({ domain: key as DomainFilter })
                                }
                            }}
                            className="gap-1 p-0" data-principle="title-subtitle"
                        >
                            {topics.map((domain) => (
                                <ListBox.Item
                                    key={domain}
                                    id={domain}
                                    textValue={topicLabel(domain)}
                                    className="cursor-pointer rounded-2xl px-3 py-2 text-foreground data-[hovered=true]:bg-default-100 data-[selected=true]:bg-accent-soft data-[selected=true]:text-accent-soft-foreground" data-principle="control-pad"
                                >
                                    <Typography type="body-sm" className="min-w-0 flex-1 truncate text-inherit">
                                        {topicLabel(domain)}
                                    </Typography>
                                </ListBox.Item>
                            ))}
                        </ListBox>
                    )}
                </ScrollShadow>
            ) : null}
        </div>
    )
}

"use client"

import React from "react"
import {
    Typography,
    cn,
} from "@heroui/react"
import { useTranslations } from "next-intl"
import {
    CheckCircleIcon,
    CircleHalfIcon,
    CircleIcon,
} from "@phosphor-icons/react"
import { CODING_DIFFICULTY_META } from "../../constants"
import type { ProblemStatus } from "../../types"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { StatusChip } from "@/components/blocks/chips/StatusChip"
import { SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import type { CodingProblem } from "@/modules/api/graphql/queries/types/coding"
import { StackH, StackV } from "@/components/frames/Stack"
import { Box } from "@/components/frames/Box"

/** Props for {@link ProblemRow}. A list-item, so it accepts its data as props. */
export interface ProblemRowProps extends WithClassNames<undefined> {
    /** The problem to render. */
    problem: CodingProblem
    /** The viewer's solve status for this problem (drives the status icon). */
    status: ProblemStatus
}

/** Status icon + colour + aria-label key per {@link ProblemStatus}. */
const STATUS_META: Record<
    ProblemStatus,
    { Icon: typeof CircleIcon; className: string; labelKey: string }
> = {
    solved: {
        Icon: CheckCircleIcon,
        className: "text-success-soft-foreground",
        labelKey: "PracticeHubPage.row.status.solved",
    },
    attempted: {
        Icon: CircleHalfIcon,
        className: "text-warning-soft-foreground",
        labelKey: "PracticeHubPage.row.status.attempted",
    },
    unsolved: {
        Icon: CircleIcon,
        className: "text-muted",
        labelKey: "PracticeHubPage.row.status.unsolved",
    },
}

/**
 * One catalog row: a prominent status icon (✓ solved / ◐ attempted / ○ unsolved),
 * the problem title (underlines on hover) navigating into the solve page, a
 * difficulty {@link StatusChip}, a domain chip, and the point value — with topic
 * tags shown secondary below. Renders as a {@link SurfaceListCardItem} (the WHOLE
 * row is the single nav link — `hover="underline"` per the go-there row style) so
 * it joins its siblings inside the parent {@link SurfaceListCard}, not a
 * hand-rolled bordered div. Styling lives in the blocks, this only places them.
 *
 * @param props - {@link ProblemRowProps}.
 */
export const ProblemRow = ({
    problem,
    status,
    className,
}: ProblemRowProps) => {
    const t = useTranslations()
    const statusMeta = STATUS_META[status]
    const StatusIcon = statusMeta.Icon
    const difficultyMeta = CODING_DIFFICULTY_META[problem.difficulty]

    return (
        <SurfaceListCardItem
            href={`/PracticeHubPage/${problem.slug}`}
            hover="underline"
            className={className}
        >
            <StackH gap={4} align="center" principle="content-row" classNames={["min-w-0"]}
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (
                        <StatusIcon
                            weight={status === "unsolved" ? "regular" : "fill"}
                            aria-label={t(statusMeta.labelKey)}
                            className={cn("size-5 shrink-0", statusMeta.className)}
                        />
                    ),
                    () => (
                        <StackV gap={3} principle="sibling-stack" classNames={["min-w-0", "flex-1"]}
                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                            items={[
                                () => (
                                    <Typography
                                        type="body-sm"
                                        weight="medium"
                                        truncate
                                        className="w-fit underline-offset-4 decoration-[var(--separator-tertiary)] group-hover:underline"
                                    >
                                        {problem.title}
                                    </Typography>
                                ),
                                ...(problem.tags.length > 0 ? [
                                    () => (
                                        <Box principle="chip-row" className="flex flex-wrap items-center gap-2"
                                            explain="Lets chips share one wrapping row so related tags stay together without stacking as a column.">
                                            {problem.tags.slice(0, 4).map((tag) => (
                                                <Typography key={tag} type="body-xs" color="muted">
                                                    {tag}
                                                </Typography>
                                            ))}
                                            {problem.tags.length > 4 ? (
                                                <Typography
                                                    type="body-xs"
                                                    color="muted"
                                                    title={problem.tags.slice(4).join(", ")}
                                                >
                                                    {t("PracticeHubPage.row.moreTags", {
                                                        count: problem.tags.length - 4,
                                                    })}
                                                </Typography>
                                            ) : null}
                                        </Box>
                                    ),
                                ] : []),
                            ]} />
                    ),
                    () => (
                        <Box principle="push-end" className="ml-auto flex shrink-0 items-center gap-2"
                            explain="Pushes this peer to the trailing edge so trailing meta stays right-aligned in the row.">
                            <StatusChip tone={difficultyMeta.tone}>
                                {t(difficultyMeta.labelKey)}
                            </StatusChip>
                            <StatusChip tone="neutral">
                                {t(`codingPractice.domain.${problem.domain}`)}
                            </StatusChip>
                            <Typography type="body-xs" color="muted">
                                {t("codingPractice.points", { points: problem.points })}
                            </Typography>
                        </Box>
                    ),
                ]} />
        </SurfaceListCardItem>
    )
}

"use client"

import React, {
    useMemo,
} from "react"
import {
    Chip,
    Typography,
    cn,
} from "@heroui/react"
import { useTranslations } from "next-intl"
import { usePracticeFilters } from "../hooks/usePracticeFilters"
import { useCodingProblemsSwr } from "../hooks/useCodingProblemsSwr"
import { useMyCodingProgressSwr } from "../hooks/useMyCodingProgressSwr"
import {
    deriveStatus,
    filterProblems,
    sortProblems,
} from "../utils"
import { ProblemRow } from "./ProblemRow"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { CODING_DOMAIN_ORDER, type CodingDomain, type CodingProblem } from "@/modules/api/graphql/queries/types/coding"
import { StackH, StackV } from "@/components/frames/Stack"
import { Box } from "@/components/frames/Box"

/** Props for {@link ProblemCatalog}. */
export type ProblemCatalogProps = WithClassNames<undefined>

/** One rendered domain section: the domain plus its (already sorted) problems. */
interface CatalogGroup {
    /** The domain this section groups. */
    domain: CodingDomain
    /** Problems under the domain, in the active sort order. */
    problems: Array<CodingProblem>
}

/**
 * The PracticeHubPage problem list. Loads the whole catalog + the viewer's progress,
 * overlays per-problem status, applies the URL-backed client filters / search /
 * sort, then renders either domain-grouped sections (LeetCode topic style) or a
 * flat sorted list per the group toggle. Every fetch goes through
 * {@link AsyncContent} (loading skeleton, filter-aware empty, retry on error).
 * Composes blocks + the {@link ProblemRow} list-item.
 *
 * @param props - optional className for the root element.
 */
export const ProblemCatalog = ({
    className,
}: ProblemCatalogProps) => {
    const t = useTranslations()
    const { filters, isFiltered, clearFilters } = usePracticeFilters()

    const {
        data: problems,
        isLoading,
        error,
        mutate,
    } = useCodingProblemsSwr()
    // progress overlay — drives row status + the status filter (anonymous → null)
    const { data: progress } = useMyCodingProgressSwr()

    // apply client filters then sort the survivors
    const filtered = useMemo(
        () => sortProblems(filterProblems(problems ?? [], progress, filters), filters.sort),
        [problems, progress, filters],
    )

    // group the filtered+sorted problems by domain, in canonical domain order
    const groups = useMemo<Array<CatalogGroup>>(() => {
        const byDomain = new Map<CodingDomain, Array<CodingProblem>>()
        filtered.forEach((problem) => {
            const bucket = byDomain.get(problem.domain) ?? []
            bucket.push(problem)
            byDomain.set(problem.domain, bucket)
        })
        return CODING_DOMAIN_ORDER
            .filter((domain) => byDomain.has(domain))
            .map((domain) => ({ domain, problems: byDomain.get(domain) ?? [] }))
    }, [filtered])

    return (
        <AsyncContent
            isLoading={isLoading && !problems}
            // intentionally flat regardless of `filters.group` — real layout can be
            // N domain-header sections when grouped, but we keep the skeleton a
            // simple 5-row approximation rather than pre-guessing group shape
            skeleton={(
                <SurfaceListCard className={className}>
                    {[0, 1, 2, 3, 4].map((row) => (
                        <SurfaceListCardItem key={row}>
                            <StackH gap={4} align="center" principle="content-row" classNames={["min-w-0"]}
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                items={[
                                    () => <Skeleton className="size-5 shrink-0 rounded-full" />,
                                    () => (
                                        <StackV gap={3} principle="sibling-stack" classNames={["min-w-0", "flex-1"]}
                                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                            items={[
                                                () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                                () => (
                                                    <Box principle="chip-row" className="flex flex-wrap items-center gap-2"
                                                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column.">
                                                        <Skeleton.Typography type="body-xs" width="1/4" />
                                                        <Skeleton.Typography type="body-xs" width="1/4" />
                                                    </Box>
                                                ),
                                            ]} />
                                    ),
                                    () => (
                                        <Box principle="push-end" className="ml-auto flex shrink-0 items-center gap-2"
                                            explain="Pushes this peer to the trailing edge so trailing meta stays right-aligned in the row.">
                                            <Skeleton.Chip />
                                            <Skeleton.Chip />
                                            <Skeleton.Typography type="body-xs" width="1/4" className="w-10" />
                                        </Box>
                                    ),
                                ]} />
                        </SurfaceListCardItem>
                    ))}
                </SurfaceListCard>
            )}
            isEmpty={filtered.length === 0}
            emptyContent={isFiltered
                ? {
                    title: t("PracticeHubPage.catalog.noMatch"),
                    onRetry: clearFilters,
                    retryLabel: t("PracticeHubPage.catalog.clearFilters"),
                }
                : { title: t("codingPractice.empty"), description: t("codingPractice.emptyHint") }}
            error={error}
            errorContent={{
                title: t("PracticeHubPage.catalog.loadError"),
                onRetry: () => { void mutate() },
                retryLabel: t("PracticeHubPage.retry"),
            }}
        >
            {filters.group ? (
                <div className={cn("flex flex-col gap-6", className)}>
                    {groups.map((group) => (
                        <StackV key={group.domain} gap={3} principle="sibling-stack" as="section"
                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                            items={[
                                () => (
                                    <StackH gap={3} principle="flex-action"
                                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                        items={[
                                            () => (
                                                <Typography type="h5" weight="semibold">
                                                    {t(`codingPractice.domain.${group.domain}`)}
                                                </Typography>
                                            ),
                                            () => (
                                                <Chip size="sm" variant="soft" color="default">
                                                    <Chip.Label>{group.problems.length}</Chip.Label>
                                                </Chip>
                                            ),
                                        ]} />
                                ),
                                () => (
                                    <SurfaceListCard>
                                        {group.problems.map((problem) => (
                                            <ProblemRow
                                                key={problem.id}
                                                problem={problem}
                                                status={deriveStatus(problem.id, progress)}
                                            />
                                        ))}
                                    </SurfaceListCard>
                                ),
                            ]} />
                    ))}
                </div>
            ) : (
                <SurfaceListCard className={className}>
                    {filtered.map((problem) => (
                        <ProblemRow
                            key={problem.id}
                            problem={problem}
                            status={deriveStatus(problem.id, progress)}
                        />
                    ))}
                </SurfaceListCard>
            )}
        </AsyncContent>
    )
}

"use client"

import React from "react"
import {
    Label,
    cn,
} from "@heroui/react"
import { useTranslations } from "next-intl"
import { CODING_DIFFICULTY_META } from "../constants"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { useQueryUserCodingProgressSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCodingProgressSwr"
import { useQueryUserCodingRankSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCodingRankSwr"
import { useQueryUserCodingSkillsSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCodingSkillsSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { MetricCard } from "@/components/composites/stats/MetricCard"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { useAppSelector } from "@/redux/hooks"
import { CodingDifficulty } from "@/modules/api/graphql/queries/types/coding"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"

/** Props for {@link ProgressCockpit}. */
export type ProgressCockpitProps = WithClassNames<undefined>

/** Difficulty order for the distribution SegmentBar (easy → hard). */
const COCKPIT_DIFFICULTY: ReadonlyArray<CodingDifficulty> = [
    CodingDifficulty.Easy,
    CodingDifficulty.Medium,
    CodingDifficulty.Hard,
]

/**
 * The PracticeHubPage cockpit — the signed-in user's coding standing at a glance, built
 * from the SAME blocks as the profile Coding tab: a {@link MetricCard} row
 * (solved · points · rank · percentile, the last two hidden when unranked) over a
 * difficulty {@link SegmentBar} (easy/medium/hard solved counts, coding 3-tone
 * scale). Self-contained: reads the signed-in user id from the store and drives
 * its own SWR. Hides entirely for anonymous viewers (no user id → empty cockpit).
 *
 * @param props - optional className for the root element.
 */
export const ProgressCockpit = ({
    className,
}: ProgressCockpitProps) => {
    const t = useTranslations()
    // signed-in user id — the rank/skills queries key off it (null when anonymous)
    const userId = useAppSelector((state) => state.user.user?.id) ?? null

    const {
        data: progress,
        isLoading,
        error,
        mutate,
    } = useQueryUserCodingProgressSwr(userId)
    const skillsSwr = useQueryUserCodingSkillsSwr(userId)
    const standingSwr = useQueryUserCodingRankSwr(userId)
    const skills = skillsSwr.data
    const standing = standingSwr.data

    const solved = progress?.solvedProblemIds.length ?? 0
    // `totalPoints` is the user's whole spendable Coin balance, NOT a coding-only
    // figure — the `coding` leaderboard ranks on distinct problems solved instead
    // (points are a different currency). Labelled "Coin" via `metric.points`.
    const totalPoints = progress?.totalPoints ?? 0

    // 2026-07-12: `skills`/`standing` fire alongside `progress` but the outer
    // skeleton only watches `progress` — while they're still in flight, rank/
    // percentile stat cards and the whole difficulty bar used to be silently
    // absent, then pop in a beat after the "solved"/"points" cards had already
    // rendered. Gate each dependent section on its OWN pending state instead of
    // just omitting it.
    const standingPending = standingSwr.isLoading && !standing

    // headline metric row; rank + percentile hide when the user is unranked
    const stats: Array<{ key: string; value: string | null }> = [
        { key: "solved", value: String(solved) },
        { key: "points", value: String(totalPoints) },
    ]
    if (standingPending) {
        stats.push({ key: "rank", value: null }, { key: "percentile", value: null })
    } else {
        if (standing?.rank != null) {
            stats.push({ key: "rank", value: `#${standing.rank}` })
        }
        if (standing?.percentile != null) {
            stats.push({ key: "percentile", value: `${standing.percentile}%` })
        }
    }

    // difficulty distribution (easy→hard), coloured by the coding 3-tone scale
    const skillsPending = skillsSwr.isLoading && !skills
    const solvedByDifficulty = new Map((skills?.byDifficulty ?? []).map((item) => [item.key, item.solved]))
    const difficultySegments = COCKPIT_DIFFICULTY
        .filter((difficulty) => (solvedByDifficulty.get(difficulty) ?? 0) > 0)
        .map((difficulty) => ({
            key: difficulty,
            label: t(CODING_DIFFICULTY_META[difficulty].labelKey),
            value: solvedByDifficulty.get(difficulty) ?? 0,
            color: CODING_DIFFICULTY_META[difficulty].color,
        }))

    // anonymous viewers never fire the queries (key disabled) — bail out
    // instead of `isLoading`/`!userId` feeding `isFirstLoad` forever.
    if (!userId) return null

    // first load in flight only when no progress has resolved yet
    const isFirstLoad = !progress && isLoading

    return (
        <AsyncContent
            isLoading={isFirstLoad}
            skeleton={(
                <div className={cn("flex flex-col gap-6", className)}>
                    {/* metric row — solved · points · rank · percentile */}
                    <Box principle="content-row" className="grid grid-cols-2 gap-3 @app-sm:grid-cols-4"
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title.">
                        {[0, 1, 2, 3].map((index) => (
                            <Skeleton key={index} className="h-24 w-full rounded-2xl" />
                        ))}
                    </Box>
                    {/* difficulty distribution bar */}
                    <StackV gap={3} principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                        items={[
                            () => <Skeleton.Typography type="body-sm" width="1/4" />,
                            () => <Skeleton.SegmentBar legendItems={3} />,
                        ]} />
                </div>
            )}
            error={error}
            errorContent={{
                title: t("PracticeHubPage.cockpit.loadError"),
                onRetry: () => { void mutate() },
                retryLabel: t("PracticeHubPage.retry"),
            }}
        >
            <div className={cn("flex flex-col gap-6", className)}>
                {/* headline metric row — pending rank/percentile cards skeleton in place */}
                <Box principle="content-row" className="grid grid-cols-2 gap-3 @app-sm:grid-cols-4"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title.">
                    {stats.map((stat) => (
                        stat.value === null ? (
                            <Skeleton key={stat.key} className="h-24 w-full rounded-2xl" />
                        ) : (
                            <MetricCard
                                key={stat.key}
                                value={stat.value}
                                label={t(`PracticeHubPage.cockpit.metric.${stat.key}`)}
                            />
                        )
                    ))}
                </Box>

                {/* difficulty distribution — skeleton while resolving, hidden once
                    resolved with nothing solved yet, real bar otherwise */}
                {skillsPending ? (
                    <StackV gap={3} principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                        items={[
                            () => <Skeleton.Typography type="body-sm" width="1/4" />,
                            () => <Skeleton.SegmentBar legendItems={3} />,
                        ]} />
                ) : difficultySegments.length > 0 ? (
                    <StackV gap={3} principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                        items={[
                            () => <Label>{t("PracticeHubPage.cockpit.byDifficulty")}</Label>,
                            () => (
                                <SegmentBar
                                    ariaLabel={t("PracticeHubPage.cockpit.byDifficulty")}
                                    segments={difficultySegments}
                                />
                            ),
                        ]} />
                ) : null}
            </div>
        </AsyncContent>
    )
}

"use client"

import React from "react"
import { useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { ResizableRail } from "@/components/blocks/layout/ResizableRail"
import { ResponsiveBreadcrumb } from "@/components/blocks/navigation/ResponsiveBreadcrumb"
import { pathConfig } from "@/resources/path"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"
import { PracticeRail } from "./PracticeRail"
import { PracticeMobileNav } from "./PracticeRail/PracticeMobileNav"
import { ProgressCockpit } from "./ProgressCockpit"
import { PracticeFilters } from "./PracticeFilters"
import { ProblemCatalog } from "./ProblemCatalog"
import { CodingLeaderboard } from "./CodingLeaderboard"
import { usePracticeView } from "./hooks/usePracticeView"

/**
 * `/PracticeHubPage` — the LeetCode-style coding-PracticeHubPage page, laid out docs-style: a
 * persistent left {@link PracticeRail} (the mode switch Problems ⇄ Leaderboard +
 * the course-domain topics as a nav list) beside a padded work pane. The rail and
 * the pane share one source of truth through the URL (the {@link usePracticeView}
 * mode + the {@link PracticeFilters} topic), so navigation is shareable. Below
 * `lg` the rail folds into the in-pane {@link PracticeMobileNav} chip rows.
 *
 * The pane stacks: a {@link PageHeader}, the {@link ProgressCockpit} (the viewer's
 * solve standing, shown for BOTH views), then the active view — **Problems** (the
 * {@link PracticeFilters} bar + {@link ProblemCatalog}) or the global
 * **Leaderboard** ({@link CodingLeaderboard}). Pure composition — each child reads
 * its own SWR / URL state; this root only places them and owns the shell.
 */
export const PracticeHubPage = () => {
    const t = useTranslations()
    const router = useRouter()
    const { view } = usePracticeView()

    return (
        // single column on mobile/tablet; rail + content side-by-side from lg up
        <div className="flex w-full flex-col items-start @app-lg:flex-row">
            {/* docs-style left rail — sticks under the navbar, viewport-tall, drag-resizable */}
            <ResizableRail
                className="hidden shrink-0 @app-lg:sticky @app-lg:top-16 @app-lg:flex @app-lg:h-[calc(100dvh-4rem)] @app-lg:flex-col @app-lg:self-start"
                storageKey="starci.PracticeHubPage.rail.width"
                defaultWidth={300}
                minWidth={256}
                maxWidth={420}
                ariaLabel={t("PracticeHubPage.rail.modeAria")}
            >
                <PracticeRail className="min-h-0 @app-lg:flex-1" />
            </ResizableRail>

            {/* content column — owns the canonical p-6 reading padding */}
            <Box principle="page-pad" className="min-h-0 min-w-0 flex-1 p-6"
                explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                <Box principle="center-measure" className="mx-auto flex max-w-5xl flex-col gap-10"
                    explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport.">
                    <PageHeader
                        breadcrumb={(
                            <ResponsiveBreadcrumb
                                items={[
                                    {
                                        key: "home",
                                        label: t("nav.home"),
                                        onPress: () => router.push(pathConfig().locale().build()),
                                    },
                                    {
                                        key: "current",
                                        label: t("codingPractice.title"),
                                    },
                                ]}
                            />
                        )}
                        title={t("codingPractice.title")}
                        description={t("codingPractice.subtitle")}
                    />

                    <StackV gap={6} principle="block-boundary"
                        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                        items={[
                            () => <PracticeMobileNav />,
                            () => <ProgressCockpit />,
                            () => (view === "problems" ? (
                                <>
                                    <Box principle="pill-pad" className="sticky top-16 z-40 bg-background py-2"
                                        explain="Pill/chip inset — not control-pad, because this pads a compact badge shape rather than a form control.">
                                        <PracticeFilters />
                                    </Box>
                                    <ProblemCatalog />
                                </>
                            ) : (
                                <CodingLeaderboard />
                            )),
                        ]} />
                </Box>
            </Box>
        </div>
    )
}

"use client"

import React, {
    useCallback,
    useEffect,
    useMemo,
    useState,
    useRef,
} from "react"
import useSWR from "swr"
import Editor from "@monaco-editor/react"
import {
    Button,
    Tabs,
    Typography,
} from "@heroui/react"
import { ArrowCounterClockwiseIcon, PlayIcon, MagnifyingGlassIcon } from "@phosphor-icons/react"
import { useLocale, useTranslations } from "next-intl"
import { useTheme } from "next-themes"
import { useParams, useRouter } from "next/navigation"
import { pathConfig } from "@/resources/path"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { AIProcessingText } from "@/components/blocks/learn/AIProcessingText"
import { SurfaceListCard, SurfaceListCardRow } from "@/components/blocks/cards/SurfaceListCard"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { BackLink } from "@/components/blocks/navigation/BackLink"
import { StatusChip, type StatusChipTone } from "@/components/blocks/chips/StatusChip"
import { ExtendedTabs } from "@/components/blocks/navigation/ExtendedTabs"
import { StatGridCard } from "@/components/composites/stats/StatGridCard"
import { IOExampleCard } from "@/components/blocks/code/IOExampleCard"
import { CodeConsole } from "@/components/blocks/code/CodeConsole"
import { TestCaseResultGrid, type TestCaseResult } from "@/components/blocks/code/TestCaseResultGrid"
import { PracticeProblemSkeleton } from "./PracticeProblemSkeleton"
import { queryCodingProblem } from "@/modules/api/graphql/queries/query-coding-problem"
import { queryCodingProblemHint } from "@/modules/api/graphql/queries/query-coding-problem-hint"
import { queryMyCodingSubmissions } from "@/modules/api/graphql/queries/query-my-coding-submissions"
import { mutateSubmitCodingSolution } from "@/modules/api/graphql/mutations/mutation-submit-coding-solution"
import { mutateRevealCodingSolution } from "@/modules/api/graphql/mutations/mutation-reveal-coding-solution"
import {
    CodingDifficulty,
    CodingLanguage,
    CodingVerdict,
    parsePerCaseResults,
    type CodingProblem,
    type CodingProblemSolution,
    type CodingSubmission,
} from "@/modules/api/graphql/queries/types/coding"
import { useJobNotificationsSocketIo } from "@/hooks/socketio/useJobNotificationsSocketIo"
import { PublicationEvent } from "@/hooks/socketio/enums/publication-event"
import { JobCategory } from "@/modules/types/enums/job-category"
import { JobStatus } from "@/modules/types/enums/job-status"
import { useAppSelector } from "@/redux/hooks"
import { StackH, StackV } from "@/components/frames/Stack"
import { Cluster } from "@/components/frames/Cluster"
import { Box } from "@/components/frames/Box"

/** Props for {@link PracticeProblemPage}. */
export type PracticeProblemPageProps = Record<string, never>

/** Seniority level i18n key per difficulty (easy=junior, medium=mid, hard=senior). */
const LEVEL_KEY: Record<CodingDifficulty, string> = {
    [CodingDifficulty.Easy]: "junior",
    [CodingDifficulty.Medium]: "mid",
    [CodingDifficulty.Hard]: "senior",
}

/** Difficulty → chip tone (mirrors the list-card difficulty palette). */
const DIFFICULTY_TONE: Record<CodingDifficulty, StatusChipTone> = {
    [CodingDifficulty.Easy]: "success",
    [CodingDifficulty.Medium]: "warning",
    [CodingDifficulty.Hard]: "danger",
}

/** Map a coding language to its Monaco editor language id. */
const MONACO_LANGUAGE: Record<CodingLanguage, string> = {
    [CodingLanguage.Python]: "python",
    [CodingLanguage.JavaScript]: "javascript",
    [CodingLanguage.TypeScript]: "typescript",
    [CodingLanguage.Java]: "java",
    [CodingLanguage.Cpp]: "cpp",
}

/** Chip tone per verdict (accepted = success, terminal failures = danger). */
const VERDICT_TONE: Record<CodingVerdict, StatusChipTone> = {
    [CodingVerdict.Accepted]: "success",
    [CodingVerdict.WrongAnswer]: "danger",
    [CodingVerdict.TimeLimitExceeded]: "danger",
    [CodingVerdict.MemoryLimitExceeded]: "danger",
    [CodingVerdict.RuntimeError]: "danger",
    [CodingVerdict.CompileError]: "danger",
    [CodingVerdict.InternalError]: "warning",
    [CodingVerdict.Pending]: "neutral",
    [CodingVerdict.Judging]: "neutral",
}

/** Left-pane tab ids. */
type LeftTab = "description" | "solution" | "submissions"
/** Console (right-pane bottom) tab ids. */
type ConsoleTab = "testcase" | "result"

/** Terminal job statuses — judging has finished (success or failure). */
const isTerminalStatus = (status: JobStatus | undefined): boolean =>
    status === JobStatus.Completed || status === JobStatus.Failed

/**
 * Coding-problem detail + editor — a full-bleed 2-pane IDE (`/practice/[slug]`).
 * LEFT = tabbed reading column (`ExtendedTabs`: Description / Solution / Submissions);
 * RIGHT = Monaco editor over a `CodeConsole` (Test case / Result) whose result
 * tab renders the judged PER-CASE outcome (`TestCaseResultGrid` off the API's
 * `perCaseResults`) plus runtime/memory stats. The submit → async-judge →
 * realtime-verdict flow (SWR + `/job_notifications` socket + anti-cheat
 * telemetry) is unchanged from the prior build; only the shell is new.
 */
export const PracticeProblemPage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const params = useParams()
    const slug = String(params.slug ?? "")
    const { theme } = useTheme()
    const socket = useJobNotificationsSocketIo()

    const [language, setLanguage] = useState<CodingLanguage>(CodingLanguage.Python)
    const [code, setCode] = useState<string>("")
    const [pendingJobId, setPendingJobId] = useState<string | null>(null)
    const [submitting, setSubmitting] = useState(false)
    const [leftTab, setLeftTab] = useState<LeftTab>("description")
    const [consoleTab, setConsoleTab] = useState<ConsoleTab>("testcase")
    // Live job status mirrored from Redux — the global /job_notifications lifecycle
    // dispatches every subscribed job's status into socketIo.jobStatusByJobId, the same
    // single source the challenge panel reads (no per-component EventEmitter listener).
    const pendingJobMessage = useAppSelector((state) =>
        (pendingJobId ? state.socketIo.jobStatusByJobId[pendingJobId] : undefined))
    const pendingJobStatus = pendingJobMessage?.data?.status
    const pendingJobError = pendingJobMessage?.data?.error
    const [showHint, setShowHint] = useState(false)
    const [showSolution, setShowSolution] = useState(false)
    // reference solutions arrive ONLY from the gated reveal mutation (never the
    // problem detail read) — held here once the learner reveals them
    const [revealedSolutions, setRevealedSolutions] = useState<Array<CodingProblemSolution>>([])
    const [solutionLanguage, setSolutionLanguage] = useState<CodingLanguage>(CodingLanguage.Python)
    const [touchedLanguages, setTouchedLanguages] = useState<Set<CodingLanguage>>(new Set())

    const telemetryRef = useRef({
        pasteCount: 0,
        pasteSizeMax: 0,
        keystrokeCount: 0,
        tabBlurCount: 0,
        timeOpen: Date.now(),
    })

    // Reset telemetry when the slug changes (user selects a new problem)
    useEffect(() => {
        telemetryRef.current = {
            pasteCount: 0,
            pasteSizeMax: 0,
            keystrokeCount: 0,
            tabBlurCount: 0,
            timeOpen: Date.now(),
        }
    }, [slug])

    // Track when window loses focus (user switching browser tabs/windows)
    useEffect(() => {
        const handleBlur = () => {
            telemetryRef.current.tabBlurCount += 1
        }
        window.addEventListener("blur", handleBlur)
        return () => window.removeEventListener("blur", handleBlur)
    }, [])

    const {
        data: problem,
        isLoading,
        error: problemError,
        mutate: mutateProblem,
    } = useSWR<CodingProblem | null>(
        ["coding-problem", slug],
        async () => {
            const response = await queryCodingProblem({ request: { slug } })
            return response.data?.codingProblem.data ?? null
        },
    )

    const { data: hint } = useSWR<string | null>(
        ["coding-problem-hint", slug],
        async () => {
            const response = await queryCodingProblemHint({ request: { slug } })
            return response.data?.codingProblemHint.data?.hint ?? null
        },
    )

    const { data: submissionsData, mutate: mutateSubmissions } = useSWR(
        ["my-coding-submissions", slug],
        async () => {
            const response = await queryMyCodingSubmissions({
                request: { slug, page: 1, limit: 20 },
            })
            return response.data?.myCodingSubmissions.data ?? null
        },
    )

    const starterByLanguage = useMemo(() => {
        const map = new Map<CodingLanguage, string>()
        problem?.starterCodes?.forEach((starter) => map.set(starter.language, starter.code))
        return map
    }, [problem?.starterCodes])

    const languages = useMemo<Array<CodingLanguage>>(() => {
        const withStarter = problem?.starterCodes?.map((starter) => starter.language) ?? []
        return withStarter.length > 0 ? withStarter : Object.values(CodingLanguage)
    }, [problem?.starterCodes])

    useEffect(() => {
        if (languages.length > 0 && !languages.includes(language)) {
            setLanguage(languages[0])
        }
    }, [languages, language])

    useEffect(() => {
        if (!touchedLanguages.has(language)) {
            setCode(starterByLanguage.get(language) ?? "")
        }
    }, [language, starterByLanguage, touchedLanguages])

    const latestSubmission = useMemo<CodingSubmission | undefined>(
        () => submissionsData?.submissions[0],
        [submissionsData?.submissions],
    )

    // decode the judged per-case outcome (input/expected/got for samples) — the
    // data the API always returned but the old UI threw away.
    const resultCases = useMemo<Array<TestCaseResult>>(
        () => parsePerCaseResults(latestSubmission?.perCaseResults ?? null).map((perCase) => ({
            key: String(perCase.orderIndex),
            label: t("codingPractice.caseLabel", { index: perCase.orderIndex }),
            passed: perCase.verdict === CodingVerdict.Accepted,
            isSample: perCase.isSample,
            input: perCase.input,
            expectedOutput: perCase.expectedOutput,
            got: perCase.stdout,
        })),
        [latestSubmission?.perCaseResults, t],
    )

    // reference solution code keyed by language (revealed in the "answer" panel)
    const solutionByLanguage = useMemo(() => {
        const map = new Map<CodingLanguage, string>()
        revealedSolutions.forEach((solution) => map.set(solution.language, solution.code))
        return map
    }, [revealedSolutions])

    // languages that actually ship a reference solution
    const solutionLanguages = useMemo<Array<CodingLanguage>>(
        () => revealedSolutions.map((solution) => solution.language),
        [revealedSolutions],
    )

    // keep the solution language switcher pinned to an available language
    useEffect(() => {
        if (solutionLanguages.length > 0 && !solutionLanguages.includes(solutionLanguage)) {
            setSolutionLanguage(solutionLanguages[0])
        }
    }, [solutionLanguages, solutionLanguage])

    /** Back to the practice catalog. */
    const onBack = useCallback(
        () => router.push(pathConfig().locale(locale).practice().build()),
        [router, locale],
    )

    /** Reset the editor to the language's starter code (drops local edits). */
    const onResetCode = useCallback(() => {
        setCode(starterByLanguage.get(language) ?? "")
        setTouchedLanguages((prev) => {
            const next = new Set(prev)
            next.delete(language)
            return next
        })
    }, [language, starterByLanguage])

    // toggle the answer panel; revealing it forfeits the problem's points, so
    // confirm first and record the reveal server-side (best-effort)
    const onToggleSolution = useCallback(async () => {
        if (showSolution) {
            setShowSolution(false)
            return
        }
        if (!window.confirm(t("codingPractice.revealConfirm"))) {
            return
        }
        try {
            // the gated reveal mutation both records the forfeit AND returns the
            // reference solutions — the only path by which they reach the client
            const response = await mutateRevealCodingSolution({ request: { slug } })
            setRevealedSolutions(response.data?.revealCodingSolution.data?.solutions ?? [])
            setShowSolution(true)
        } catch {
            // reveal failed (network/auth) — keep the answer panel closed
        }
    }, [showSolution, slug, t])

    const onSubmit = useCallback(async () => {
        setSubmitting(true)
        setConsoleTab("result")
        try {
            const timeOpenToSubmitMs = Date.now() - telemetryRef.current.timeOpen
            const response = await mutateSubmitCodingSolution({
                request: {
                    slug,
                    language,
                    sourceCode: code,
                    telemetry: {
                        pasteCount: telemetryRef.current.pasteCount,
                        pasteSizeMax: telemetryRef.current.pasteSizeMax,
                        keystrokeCount: telemetryRef.current.keystrokeCount,
                        tabBlurCount: telemetryRef.current.tabBlurCount,
                        timeOpenToSubmitMs,
                    },
                },
            })
            const jobId = response.data?.submitCodingSolution.data?.jobId
            if (!jobId) return
            // Subscribe to the job room BEFORE the refetch so an early socket push is
            // never missed (race-free, like challenge). Status comes from Redux.
            setPendingJobId(jobId)
            socket.emit(PublicationEvent.SubscribeJobNotification, {
                data: { jobId },
                locale,
            })
            void mutateSubmissions()
        } finally {
            setSubmitting(false)
        }
    }, [slug, language, code, mutateSubmissions, socket, locale])

    // When the watched job reaches a terminal status (from Redux), refetch the
    // submissions (verdict now persisted) and stop watching.
    useEffect(() => {
        if (pendingJobId && isTerminalStatus(pendingJobStatus)) {
            void mutateSubmissions()
            setPendingJobId(null)
        }
    }, [pendingJobId, pendingJobStatus, mutateSubmissions])

    const judging = pendingJobId !== null

    // first load in flight → skeleton
    if (isLoading) {
        return <PracticeProblemSkeleton />
    }

    // load resolved with no problem: either a network/GraphQL error (`problemError`)
    // or the BE's uniform 404 for an unknown/disabled slug (fetcher yields `null`).
    // Distinguish the two, and never leave the skeleton spinning forever.
    if (!problem) {
        return (
            <div className="flex h-[calc(100vh-4rem)] flex-col">
                <Box principle="page-pad" className="flex flex-col border-b border-default px-6 py-3"
                explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                    <BackLink target={t("codingPractice.title")} onPress={onBack} />
                </Box>
                <Box principle="page-pad" className="flex min-h-0 flex-1 items-center justify-center px-6"
                explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                    {problemError ? (
                        <AsyncContentError
                            title={t("codingPractice.detailError")}
                            description={t("codingPractice.detailErrorHint")}
                            onRetry={() => { void mutateProblem() }}
                            retryLabel={t("common.retry")}
                        />
                    ) : (
                        <EmptyState
                            icon={MagnifyingGlassIcon}
                            title={t("codingPractice.notFound")}
                            description={t("codingPractice.notFoundHint")}
                            action={() => (
                                <Button variant="primary" size="sm" onPress={onBack}>
                                    {t("codingPractice.backToPractice")}
                                </Button>
                            )}
                        />
                    )}
                </Box>
            </div>
        )
    }

    const samples = problem.testcases ?? []
    const memoryMb = problem.memoryLimitKb ? Math.round(problem.memoryLimitKb / 1024) : null

    /** LEFT: problem statement, samples, hint. */
    const descriptionPanel = (
        <StackV gap={6} principle="block-boundary"
        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
        items={[
            () => (
                <StackV gap={4} principle="card-caption"
                explain="Holds caption text under card media so the caption stays attached to the image above it."
                items={[
                    () => (
                        <StackH gap={3} principle="flex-action"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        items={[
                            () => <Typography type="h4" weight="bold">{problem.title}</Typography>,
                            () => (
                                <StatusChip tone={DIFFICULTY_TONE[problem.difficulty]}>
                                    {t(`codingPractice.level.${LEVEL_KEY[problem.difficulty]}`)}
                                </StatusChip>
                            ),
                        ]} />
                    ),
                    () => (
                        <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-muted">
                            <span>{t("codingPractice.points", { points: problem.points })}</span>
                            {problem.timeLimitMs ? <span>· {t("codingPractice.timeLimit", { ms: problem.timeLimitMs })}</span> : null}
                            {memoryMb ? <span>· {t("codingPractice.memoryLimit", { mb: memoryMb })}</span> : null}
                            {problem.tags.map((tag) => <span key={tag}>· {tag}</span>)}
                        </div>
                    ),
                ]} />
            ),
            () => <MarkdownContent markdown={problem.statement ?? ""} />,
            ...(samples.length > 0 ? [
                () => (
                    <StackV gap={4} principle="card-caption"
                    explain="Holds caption text under card media so the caption stays attached to the image above it."
                    items={[
                        () => <hr className="border-default" />,
                        () => <p className="font-semibold">{t("codingPractice.samples")}</p>,
                        ...samples.map((testcase, index) => () => (
                            <IOExampleCard
                                key={testcase.id}
                                rows={[
                                    { key: "in", label: `${t("codingPractice.example")} ${index + 1} · ${t("codingPractice.input")}`, value: testcase.input },
                                    { key: "out", label: t("codingPractice.output"), value: testcase.expectedOutput },
                                ]}
                            />
                        )),
                    ]} />
                ),
            ] : []),
            ...(hint ? [
                () => (
                    <StackV gap={4} principle="card-caption"
                    explain="Holds caption text under card media so the caption stays attached to the image above it."
                    items={[
                        () => <hr className="border-default" />,
                        () => (
                            <StackH gap={3} principle="flex-action" justify="between"
                            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                            items={[
                                () => <p className="font-semibold">{t("codingPractice.hintTitle")}</p>,
                                () => (
                                    <Button size="sm" variant="secondary" onPress={() => setShowHint((prev) => !prev)}>
                                        {showHint ? t("codingPractice.hideHint") : t("codingPractice.showHint")}
                                    </Button>
                                ),
                            ]} />
                        ),
                        ...(showHint ? [() => <MarkdownContent markdown={hint} />] : []),
                    ]} />
                ),
            ] : []),
        ]} />
    )

    /** LEFT: reveal-gated reference solution, one tab per language. */
    const solutionPanel = (
        <StackV gap={4} principle="card-caption"
        explain="Holds caption text under card media so the caption stays attached to the image above it."
        items={[
            () => (
                <StackH gap={3} principle="flex-action" justify="between"
                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                items={[
                    () => <p className="font-semibold">{t("codingPractice.solutionTitle")}</p>,
                    () => (
                        <Button size="sm" variant="secondary" onPress={onToggleSolution}>
                            {showSolution ? t("codingPractice.hideSolution") : t("codingPractice.showSolution")}
                        </Button>
                    ),
                ]} />
            ),
            () => showSolution && solutionLanguages.length > 0 ? (
                <StackV gap={4} principle="card-caption"
                explain="Holds caption text under card media so the caption stays attached to the image above it."
                items={[
                    () => (
                        <Cluster gap={3} principle="flex-action" items={solutionLanguages.map((option) => () => (
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                            <Button
                                key={option}
                                size="sm"
                                variant={solutionLanguage === option ? "primary" : "secondary"}
                                onPress={() => setSolutionLanguage(option)}
                            >
                                {t(`codingPractice.language.${option}`)}
                            </Button>
                        ))} />
                    ),
                    () => (
                        <MarkdownContent
                            markdown={`\`\`\`${MONACO_LANGUAGE[solutionLanguage]}\n${
                                solutionByLanguage.get(solutionLanguage) ?? ""
                            }\n\`\`\``}
                        />
                    ),
                ]} />
            ) : (
                <Typography type="body-sm" color="muted">
                    {t("codingPractice.solutionLocked")}
                </Typography>
            ),
        ]} />
    )

    /** LEFT: the learner's prior submissions for this problem. */
    const submissionsPanel = submissionsData && submissionsData.submissions.length > 0 ? (
        <SurfaceListCard>
            {submissionsData.submissions.map((submission: CodingSubmission) => (
                <SurfaceListCardRow
                    key={submission.id}
                    title={new Date(submission.createdAt).toLocaleString()}
                    meta={() => (
                        <>
                            <Typography type="body-xs" color="muted">
                                {t(`codingPractice.language.${submission.language}`)}
                            </Typography>
                            <StatusChip tone={VERDICT_TONE[submission.verdict]}>
                                {t(`codingPractice.verdict.${submission.verdict}`)}
                            </StatusChip>
                        </>
                    )}
                />
            ))}
        </SurfaceListCard>
    ) : (
        <EmptyState title={t("codingPractice.historyEmpty")} />
    )

    /** CONSOLE: sample testcases (pre-run reference). */
    const testcaseTab = samples.length > 0 ? (
        <StackV gap={4} principle="card-caption" items={samples.map((testcase, index) => () => (
        explain="Holds caption text under card media so the caption stays attached to the image above it."
            <IOExampleCard
                key={testcase.id}
                rows={[
                    { key: "in", label: `${t("codingPractice.example")} ${index + 1} · ${t("codingPractice.input")}`, value: testcase.input },
                    { key: "out", label: t("codingPractice.output"), value: testcase.expectedOutput },
                ]}
            />
        ))} />
    ) : (
        <Typography type="body-sm" color="muted">{t("codingPractice.noSamples")}</Typography>
    )

    /** CONSOLE: live judging / verdict + per-case grid + stats. */
    const resultTab = judging && pendingJobStatus ? (
        <AIProcessingText
            jobCategory={JobCategory.JudgeCoding}
            jobStatus={pendingJobStatus}
            error={pendingJobError}
        />
    ) : latestSubmission ? (
        <StackV gap={5} principle="group-boundary"
        explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
        items={[
            () => (
                <Cluster gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (
                        <StatusChip tone={VERDICT_TONE[latestSubmission.verdict]}>
                            {t(`codingPractice.verdict.${latestSubmission.verdict}`)}
                        </StatusChip>
                    ),
                    () => (
                        <Typography type="body-sm" color="muted">
                            {t("codingPractice.passed")}: {latestSubmission.passedCount}/{latestSubmission.totalCount}
                        </Typography>
                    ),
                ]} />
            ),
            () => (
                <StatGridCard
                    items={[
                        {
                            key: "passed",
                            content: () => (
                                <div className="flex flex-col gap-0">
                                    <span className="text-lg font-bold">{latestSubmission.passedCount}/{latestSubmission.totalCount}</span>
                                    <span className="text-xs text-muted">{t("codingPractice.statPassed")}</span>
                                </div>
                            ),
                        },
                        {
                            key: "runtime",
                            content: () => (
                                <div className="flex flex-col gap-0">
                                    <span className="text-lg font-bold">{latestSubmission.runtimeMs ?? "—"}<span className="text-xs"> ms</span></span>
                                    <span className="text-xs text-muted">{t("codingPractice.statRuntime")}</span>
                                </div>
                            ),
                        },
                        {
                            key: "memory",
                            content: () => (
                                <div className="flex flex-col gap-0">
                                    <span className="text-lg font-bold">{latestSubmission.memoryKb ?? "—"}<span className="text-xs"> KB</span></span>
                                    <span className="text-xs text-muted">{t("codingPractice.statMemory")}</span>
                                </div>
                            ),
                        },
                    ]}
                />
            ),
            ...(resultCases.length > 0 ? [
                () => (
                    <TestCaseResultGrid
                        cases={resultCases}
                        labels={{
                            input: t("codingPractice.input"),
                            expected: t("codingPractice.expected"),
                            got: t("codingPractice.got"),
                            hidden: t("codingPractice.hiddenCase"),
                        }}
                    />
                ),
            ] : []),
            ...(latestSubmission.compileOutput ? [
                () => (
                    <pre data-principle="cell-pad" className="whitespace-pre-wrap rounded-2xl bg-danger-soft p-3 text-xs text-danger-soft-foreground">
                        {latestSubmission.compileOutput}
                    </pre>
                ),
            ] : []),
        ]} />
    ) : (
        <Typography type="body-sm" color="muted">{t("codingPractice.resultEmpty")}</Typography>
    )

    return (
        // full-bleed 2-pane IDE: left reading column | right editor + console
        <div className="grid h-[calc(100vh-4rem)] grid-cols-1 @app-lg:grid-cols-2">

            {/* ── LEFT: tabbed reading column ── */}
            <div className="flex min-h-0 flex-col overflow-hidden border-r border-default">
                <Box principle="page-pad" className="flex flex-col border-b border-default px-6 py-3"
                explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                    <StackV gap={4} principle="card-caption"
                    explain="Holds caption text under card media so the caption stays attached to the image above it."
                    items={[
                        () => <BackLink target={t("codingPractice.title")} onPress={onBack} />,
                        () => (
                            <ExtendedTabs
                                selectedKey={leftTab}
                                onSelectionChange={(key) => setLeftTab(key as LeftTab)}
                            >
                                <Tabs.ListContainer>
                                    <Tabs.List aria-label={problem.title}>
                                        <Tabs.Tab id="description">
                                            {t("codingPractice.tabDescription")}
                                            <Tabs.Indicator />
                                        </Tabs.Tab>
                                        <Tabs.Tab id="solution">
                                            {t("codingPractice.tabSolution")}
                                            <Tabs.Indicator />
                                        </Tabs.Tab>
                                        <Tabs.Tab id="submissions">
                                            {t("codingPractice.tabSubmissions")}
                                            <Tabs.Indicator />
                                        </Tabs.Tab>
                                    </Tabs.List>
                                </Tabs.ListContainer>
                            </ExtendedTabs>
                        ),
                    ]} />
                </Box>
                <Box principle="page-pad" className="min-h-0 flex-1 overflow-auto px-6 py-5"
                explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                    {leftTab === "description" && descriptionPanel}
                    {leftTab === "solution" && solutionPanel}
                    {leftTab === "submissions" && submissionsPanel}
                </Box>
            </div>

            {/* ── RIGHT: editor + console ── */}
            <div className="flex min-h-0 flex-col overflow-hidden">
                {/* language selector + reset */}
                <Box principle="pill-pad" className="flex flex-wrap items-center justify-between border-b border-default px-4 py-2"
                explain="Pill/chip inset — not control-pad, because this pads a compact badge shape rather than a form control.">
                    <Cluster gap={3} principle="flex-action" items={languages.map((option) => () => (
                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        <Button
                            key={option}
                            size="sm"
                            variant={language === option ? "primary" : "secondary"}
                            onPress={() => setLanguage(option)}
                        >
                            {t(`codingPractice.language.${option}`)}
                        </Button>
                    ))} />
                    <Button size="sm" variant="tertiary" onPress={onResetCode}>
                        <ArrowCounterClockwiseIcon className="size-4" aria-hidden focusable="false" />
                        {t("codingPractice.resetCode")}
                    </Button>
                </Box>

                {/* Monaco editor */}
                <div className="min-h-0 flex-1">
                    <Editor
                        height="100%"
                        language={MONACO_LANGUAGE[language]}
                        theme={theme === "dark" ? "vs-dark" : "light"}
                        value={code}
                        onChange={(value) => {
                            setCode(value ?? "")
                            setTouchedLanguages((prev) => new Set(prev).add(language))
                        }}
                        onMount={(editor) => {
                            editor.getDomNode()?.querySelector("textarea")?.setAttribute("spellcheck", "false")
                            editor.onDidPaste((e) => {
                                const model = editor.getModel()
                                const pastedText = model ? model.getValueInRange(e.range) : ""
                                const size = pastedText.length
                                telemetryRef.current.pasteCount += 1
                                telemetryRef.current.pasteSizeMax = Math.max(
                                    telemetryRef.current.pasteSizeMax,
                                    size
                                )
                            })
                            editor.onKeyDown(() => {
                                telemetryRef.current.keystrokeCount += 1
                            })
                            editor.onDidBlurEditorText(() => {
                                telemetryRef.current.tabBlurCount += 1
                            })
                        }}
                        options={{
                            minimap: { enabled: false },
                            fontSize: 14,
                            scrollBeyondLastLine: false,
                            padding: { top: 12, bottom: 12 },
                            bracketPairColorization: { enabled: true },
                            cursorBlinking: "smooth",
                            smoothScrolling: true,
                        }}
                    />
                </div>

                {/* bottom console — Test case / Result + Run/Submit bar */}
                <CodeConsole
                    className="h-[42%]"
                    ariaLabel={t("codingPractice.consoleLabel")}
                    selectedTab={consoleTab}
                    onSelectTab={(key) => setConsoleTab(key as ConsoleTab)}
                    tabs={[
                        { key: "testcase", label: t("codingPractice.tabTestcase"), content: testcaseTab },
                        { key: "result", label: t("codingPractice.tabResult"), content: resultTab },
                    ]}
                    hint={t("codingPractice.runVsSubmit")}
                    actions={(
                        <>
                            {/* "Run on sample" needs a dedicated judge-sample endpoint on the BE —
                                doesn't exist yet, so it's left disabled (the console hint explains it) instead of silently dropping it. */}
                            <Button
                                size="sm"
                                variant="secondary"
                                isDisabled
                            >
                                <PlayIcon className="size-4" aria-hidden focusable="false" />
                                {t("codingPractice.run")}
                            </Button>
                            <Button
                                size="sm"
                                variant="primary"
                                isPending={submitting || judging}
                                isDisabled={code.trim().length === 0}
                                onPress={onSubmit}
                            >
                                {judging ? t("codingPractice.judging") : t("codingPractice.submit")}
                            </Button>
                        </>
                    )}
                />
            </div>
        </div>
    )
}

"use client"

import React, { useCallback, useEffect, useState } from "react"
import {
    Button,
    Label,
    Spinner,
    Switch,
    Typography,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    SettingsBreadcrumb,
} from "@/components/blocks/settings/SettingsBreadcrumb"
import { useAppDispatch, useAppSelector } from "@/redux/hooks"
import { setUser } from "@/redux/slices/user"
import { useMutateUpdateProfileSwr } from "@/hooks/swr/api/graphql/mutations/useMutateUpdateProfileSwr"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { StackH, StackV } from "@/components/frames/Stack"
import type { SectionVisibility } from "@/modules/types/entities/user"

/**
 * The four gateable profile sections + their reused tab labels (Overview + CV are
 * never gated here). Each row toggles `sectionVisibility.<key>`; the label reuses
 * the existing `publicProfile.tabs.*` keys so it always matches the tab it hides.
 */
const SECTION_VISIBILITY_OPTIONS = [
    { key: "projects", labelKey: "publicProfile.tabs.projects", descKey: "profileEdit.sectionVisibilityDesc.projects" },
    { key: "challenges", labelKey: "publicProfile.tabs.challenges", descKey: "profileEdit.sectionVisibilityDesc.challenges" },
    { key: "skills", labelKey: "publicProfile.tabs.skills", descKey: "profileEdit.sectionVisibilityDesc.skills" },
    { key: "activity", labelKey: "publicProfile.tabs.activity", descKey: "profileEdit.sectionVisibilityDesc.activity" },
] as const

/** Seed the per-section visibility from the redux user (absent flags default to visible). */
const seedSectionVisibility = (
    visibility: SectionVisibility | undefined,
): SectionVisibility => ({
    projects: visibility?.projects ?? true,
    challenges: visibility?.challenges ?? true,
    skills: visibility?.skills ?? true,
    activity: visibility?.activity ?? true,
})

/**
 * Privacy settings feature container.
 *
 * The profile-VISIBILITY controls — "Lock profile" (lock) + the per-section
 * "Profile visibility" group — moved out of the edit-profile form into their own
 * settings page. Owns a small local form state seeded from the redux user; on save
 * it persists ONLY `{ profileLocked, sectionVisibility }` via `updateProfile` and
 * pushes the fresh user into redux. Mounted by `/profile/settings/privacy`.
 */
export const PrivacySettingsPage = () => {
    const t = useTranslations()
    const dispatch = useAppDispatch()
    const user = useAppSelector((state) => state.user.user)

    const runGraphQL = useGraphQLWithToast()
    const updateProfileSwr = useMutateUpdateProfileSwr()

    // small local form state (this page only touches two fields, no RHF needed)
    const [profileLocked, setProfileLocked] = useState<boolean>(user?.profileLocked ?? false)
    const [sectionVisibility, setSectionVisibility] = useState<SectionVisibility>(
        seedSectionVisibility(user?.sectionVisibility),
    )
    const [isSubmitting, setIsSubmitting] = useState(false)

    // re-seed when the redux user changes (mirrors RHF `values` reinit)
    useEffect(() => {
        if (!user) {
            return
        }
        setProfileLocked(user.profileLocked ?? false)
        setSectionVisibility(seedSectionVisibility(user.sectionVisibility))
    }, [user])

    /** Persist ONLY the visibility fields, then push the fresh user into redux. */
    const onSubmit = useCallback(async () => {
        setIsSubmitting(true)
        await runGraphQL(
            async () => {
                const result = await updateProfileSwr.trigger({
                    profileLocked,
                    sectionVisibility,
                })
                const env = result?.data?.updateProfile
                if (!env) {
                    throw new Error(t("profileEdit.error"))
                }
                if (env.success && env.data) {
                    dispatch(setUser(env.data))
                }
                return env
            },
            {
                showErrorToast: true,
                showSuccessToast: true,
            },
        )
        setIsSubmitting(false)
    }, [runGraphQL, updateProfileSwr, profileLocked, sectionVisibility, dispatch, t])

    // signed-out guard
    if (!user) {
        return (
            <div className="flex flex-col items-center py-12">
                <StackV
                    gap={3}
                    align="center"
                    principle="sibling-stack"
                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                    items={[
                        () => (
                            <Typography type="h5" weight="semibold" align="center">
                                {t("profile.signedOut.title")}
                            </Typography>
                        ),
                        () => (
                            <Typography type="body-sm" color="muted" align="center">
                                {t("profile.signedOut.desc")}
                            </Typography>
                        ),
                    ]}
                />
            </div>
        )
    }

    const lockRow = () => (
        <div className="my-2">
            <StackH
                gap={4}
                align="start"
                justify="between"
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (
                        <div className="flex flex-col gap-0">
                            <Label htmlFor="profile-locked">{t("profileEdit.lockProfile")}</Label>
                            <Typography type="body-xs" color="muted">
                                {t("profileEdit.lockProfileHint")}
                            </Typography>
                        </div>
                    ),
                    () => (
                        <Switch
                            className="shrink-0"
                            isSelected={profileLocked}
                            onChange={(selected) => setProfileLocked(selected)}
                            aria-label={t("profileEdit.lockProfile")}
                        >
                            <Switch.Content>
                                <Switch.Control>
                                    <Switch.Thumb />
                                </Switch.Control>
                            </Switch.Content>
                        </Switch>
                    ),
                ]}
            />
        </div>
    )

    const sectionRows = SECTION_VISIBILITY_OPTIONS.map((option) => () => (
        <div key={option.key} className="my-2">
            <StackH
                gap={4}
                align="start"
                justify="between"
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (
                        <div className="flex min-w-0 flex-col gap-0">
                            <Label htmlFor={`profile-section-${option.key}`}>
                                {t(option.labelKey)}
                            </Label>
                            <Typography type="body-xs" color="muted">
                                {t(option.descKey)}
                            </Typography>
                        </div>
                    ),
                    () => (
                        <Switch
                            className="shrink-0"
                            isSelected={sectionVisibility[option.key]}
                            isDisabled={profileLocked}
                            onChange={(selected) => setSectionVisibility((prev) => ({
                                ...prev,
                                [option.key]: selected,
                            }))}
                            aria-label={t(option.labelKey)}
                        >
                            <Switch.Content>
                                <Switch.Control>
                                    <Switch.Thumb />
                                </Switch.Control>
                            </Switch.Content>
                        </Switch>
                    ),
                ]}
            />
        </div>
    ))

    const sectionGroupItems = [
        () => (
            <div className="flex flex-col gap-0">
                <Label htmlFor="profile-section-visibility">
                    {t("profileEdit.sectionVisibility")}
                </Label>
                <Typography type="body-xs" color="muted">
                    {profileLocked
                        ? t("profileEdit.sectionVisibilityLockedHint")
                        : t("profileEdit.sectionVisibilityHint")}
                </Typography>
            </div>
        ),
        () => (
            <div
                id="profile-section-visibility"
                className={profileLocked ? "pointer-events-none opacity-50" : undefined}
            >
                <StackV gap={4} items={sectionRows} />
            </div>
        ),
    ]

    const formItems = [
        lockRow,
        () => (
            <div aria-disabled={profileLocked}>
                <StackV gap={6} items={sectionGroupItems} />
            </div>
        ),
        () => (
            <Button
                variant="primary"
                size="lg"
                className="h-12 self-end text-base"
                isDisabled={isSubmitting}
                isPending={isSubmitting}
                onPress={() => onSubmit()}
            >
                {({ isPending }) => (
                    <>
                        {isPending ? (
                            <Spinner
                                color="current"
                                size="sm"
                            />
                        ) : null}
                        {t("profileEdit.save")}
                    </>
                )}
            </Button>
        ),
    ]

    return (
        <StackV gap={7} principle="layout-split"
            explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
            items={[
                () => (
                    <PageHeader
                        breadcrumb={<SettingsBreadcrumb current={t("profileSettings.privacy.title")} />}
                        title={t("profileSettings.privacy.title")}
                        description={t("profileSettings.privacy.description")}
                    />
                ),
                () => <StackV gap={6} items={formItems} />,
            ]} />
    )
}

"use client"

import React, {
    useMemo,
    useState,
} from "react"
import {
    Badge,
    Button,
    Popover,
    Typography,
    cn,
} from "@heroui/react"
import {
    FunnelIcon,
} from "@phosphor-icons/react"
import {
    useParams,
    useRouter,
} from "next/navigation"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useProfileUsername,
} from "@/hooks/profile/useProfileUsername"
import {
    difficultyLevel,
} from "@/modules/utils/challenge-difficulty"
import { pathConfig } from "@/resources/path"
import { dayjs } from "@/modules/dayjs"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { useQueryUserSolvedChallengesSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserSolvedChallengesSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { BackLink } from "@/components/blocks/navigation/BackLink"
import { DifficultyChip } from "@/components/blocks/chips/DifficultyChip"
import { LanguageChip } from "@/components/blocks/chips/LanguageChip"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { SearchInput } from "@/components/blocks/form/SearchInput"
import { FlexWrapButtonRadio } from "@/components/blocks/navigation/FlexWrapButtonRadio"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { Box } from "@/components/frames/Box"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Single-select difficulty filter value — `"all"` clears the filter. */
type DifficultyFilterValue = "all" | string
/** Single-select language filter value — `"all"` clears the filter. */
type LanguageFilterValue = "all" | string
/** Sort order for the submission list. */
type SortValue = "newest" | "score"

/**
 * Score → attention colour the eye catches fast: high green, mid yellow, low red.
 * @param score - the graded score (0–100).
 * @returns a `text-{token}` class for the score label.
 */
const scoreToneClass = (score: number): string => {
    if (score >= 90) {
        return "text-success-soft-foreground"
    }
    if (score >= 70) {
        return "text-warning-soft-foreground"
    }
    return "text-danger-soft-foreground"
}

/** Props for {@link ProfileChallengeManagePage}. */
export type ProfileChallengeManagePageProps = WithClassNames<undefined>

/**
 * `/profile/<u>/challenges/<courseSlug>` — the MANAGE tier of the 3-tier
 * challenges flow: search ONE course's passed-challenge submissions, with sort
 * (newest / highest score) and the difficulty/language facets tucked behind a
 * single FUNNEL popover next to the search box (keeps the toolbar one clean line).
 * Reads the course SLUG from the route, filters the profile owner's full
 * solved-challenges list down to it client-side (the list is already small
 * per-user; no server-side pagination needed here), then renders each match as
 * a nav row to the submission DETAIL page.
 *
 * @param props - optional className for the root element.
 */
export const ProfileChallengeManagePage = ({
    className,
}: ProfileChallengeManagePageProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const username = useProfileUsername()
    const params = useParams<{ courseId: string }>()
    const courseSlug = params?.courseId ? String(params.courseId) : null

    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const {
        data,
        isLoading,
        error,
        mutate,
    } = useQueryUserSolvedChallengesSwr(userId)

    const [search, setSearch] = useState("")
    const [filterOpen, setFilterOpen] = useState(false)
    const [difficultyFilter, setDifficultyFilter] = useState<DifficultyFilterValue>("all")
    const [languageFilter, setLanguageFilter] = useState<LanguageFilterValue>("all")
    const [sort, setSort] = useState<SortValue>("newest")

    const allChallenges = data ?? []
    // scope down to THIS course only — the manage page's whole reason to exist
    const courseChallenges = useMemo(
        () => allChallenges.filter((challenge) => challenge.courseSlug === courseSlug),
        [allChallenges, courseSlug],
    )
    const courseTitle = courseChallenges[0]?.courseTitle ?? null
    // how many of the two facet filters are narrowing right now (drives the funnel badge)
    const activeFacetCount = (difficultyFilter !== "all" ? 1 : 0) + (languageFilter !== "all" ? 1 : 0)
    const clearFacets = () => {
        setDifficultyFilter("all")
        setLanguageFilter("all")
    }

    // filter option pools — only difficulties/languages actually present in this course
    const difficultyOptions = useMemo(
        () => Array.from(new Set(courseChallenges.map((challenge) => challenge.difficulty).filter((value): value is string => Boolean(value)))),
        [courseChallenges],
    )
    const languageOptions = useMemo(
        () => Array.from(new Set(courseChallenges.map((challenge) => challenge.selectedLang).filter((value): value is string => Boolean(value)))),
        [courseChallenges],
    )

    const filtered = useMemo(() => {
        const query = search.trim().toLowerCase()
        const rows = courseChallenges.filter((challenge) => {
            if (query && !challenge.title.toLowerCase().includes(query)) {
                return false
            }
            if (difficultyFilter !== "all" && challenge.difficulty !== difficultyFilter) {
                return false
            }
            if (languageFilter !== "all" && challenge.selectedLang !== languageFilter) {
                return false
            }
            return true
        })
        const sorted = [...rows]
        if (sort === "score") {
            sorted.sort((a, b) => (b.score ?? -1) - (a.score ?? -1))
        } else {
            sorted.sort((a, b) => {
                const bTime = b.passedAt ? new Date(b.passedAt).getTime() : 0
                const aTime = a.passedAt ? new Date(a.passedAt).getTime() : 0
                return bTime - aTime
            })
        }
        return sorted
    }, [courseChallenges, search, difficultyFilter, languageFilter, sort])

    const hasActiveFilter = Boolean(search.trim() || difficultyFilter !== "all" || languageFilter !== "all")

    return (
        <div className={cn("mx-auto flex max-w-4xl flex-col gap-6", className)}>
            <PageHeader
                breadcrumb={(
                    <BackLink
                        target={t("publicProfile.challengesTab.repoHeading")}
                        onPress={() => router.push(pathConfig().locale(locale).profile(username ?? undefined).challenges().build())}
                    />
                )}
                title={courseTitle ?? t("publicProfile.challengesTab.manage.title")}
                description={t("publicProfile.challengesTab.manage.description")}
            />

            {/* search + a FUNNEL popover (difficulty/language facets) + sort, one row.
                Facets live behind the funnel so the toolbar stays a single clean line
                regardless of how many facet values exist. */}
            <Cluster gap={4} principle="content-row" justify="between" align="center" classNames={["w-full"]}
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (
                        <StackH gap={4} principle="flex-action" classNames={["min-w-0", "flex-1"]}
                            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                            items={[
                                () => (
                                    <SearchInput
                                        className="min-w-0 flex-1"
                                        value={search}
                                        onValueChange={setSearch}
                                        placeholder={t("publicProfile.challengesTab.manage.searchPlaceholder")}
                                    />
                                ),
                                () => (
                                    <Popover isOpen={filterOpen} onOpenChange={setFilterOpen}>
                                        <Button
                                            isIconOnly
                                            variant="ghost"
                                            aria-label={t("publicProfile.challengesTab.manage.filterButton")}
                                            className="shrink-0"
                                        >
                                            {activeFacetCount > 0 ? (
                                                <Badge.Anchor>
                                                    <FunnelIcon className="size-5" />
                                                    <Badge size="sm" color="accent" placement="top-left">{activeFacetCount}</Badge>
                                                </Badge.Anchor>
                                            ) : (
                                                <FunnelIcon className="size-5" />
                                            )}
                                        </Button>
                                        <Popover.Content className="w-72">
                                            <Box principle="cell-pad" className="p-3"
                                                explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body.">
                                                <StackV gap={4} principle="group-boundary"
                                                    explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                                                    items={[
                                                        () => (
                                                            <StackV gap={4} principle="label-field"
                                                                explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                                                                items={[
                                                                    () => <Typography type="body-xs" color="muted">{t("publicProfile.challengesTab.manage.sortHeading")}</Typography>,
                                                                    () => (
                                                                        <FlexWrapButtonRadio<SortValue>
                                                                            ariaLabel={t("publicProfile.challengesTab.manage.sortAria")}
                                                                            value={sort}
                                                                            onChange={setSort}
                                                                            items={[
                                                                                { value: "newest", content: t("publicProfile.challengesTab.manage.sortNewest") },
                                                                                { value: "score", content: t("publicProfile.challengesTab.manage.sortScore") },
                                                                            ]}
                                                                        />
                                                                    ),
                                                                ]} />
                                                        ),
                                                        ...(difficultyOptions.length > 0 ? [() => (
                                                            <StackV gap={4} principle="label-field"
                                                                explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                                                                items={[
                                                                    () => <Typography type="body-xs" color="muted">{t("publicProfile.challengesTab.manage.difficultyHeading")}</Typography>,
                                                                    () => (
                                                                        <FlexWrapButtonRadio<DifficultyFilterValue>
                                                                            ariaLabel={t("publicProfile.challengesTab.manage.difficultyFilterAria")}
                                                                            value={difficultyFilter}
                                                                            onChange={setDifficultyFilter}
                                                                            items={[
                                                                                { value: "all", content: t("publicProfile.challengesTab.manage.allDifficulties") },
                                                                                ...difficultyOptions.map((raw) => ({
                                                                                    value: raw,
                                                                                    content: <DifficultyChip difficulty={difficultyLevel(raw) ?? "beginner"} />,
                                                                                })),
                                                                            ]}
                                                                        />
                                                                    ),
                                                                ]} />
                                                        )] : []),
                                                        ...(languageOptions.length > 0 ? [() => (
                                                            <StackV gap={4} principle="label-field"
                                                                explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                                                                items={[
                                                                    () => <Typography type="body-xs" color="muted">{t("publicProfile.challengesTab.manage.languageHeading")}</Typography>,
                                                                    () => (
                                                                        <FlexWrapButtonRadio<LanguageFilterValue>
                                                                            ariaLabel={t("publicProfile.challengesTab.manage.languageFilterAria")}
                                                                            value={languageFilter}
                                                                            onChange={setLanguageFilter}
                                                                            items={[
                                                                                { value: "all", content: t("publicProfile.challengesTab.manage.allLanguages") },
                                                                                ...languageOptions.map((lang) => ({
                                                                                    value: lang,
                                                                                    content: <LanguageChip language={lang} />,
                                                                                })),
                                                                            ]}
                                                                        />
                                                                    ),
                                                                ]} />
                                                        )] : []),
                                                        ...(activeFacetCount > 0 ? [() => (
                                                            <Button variant="danger-soft" size="sm" className="self-start" onPress={clearFacets}>
                                                                {t("publicProfile.challengesTab.manage.clearFilters")}
                                                            </Button>
                                                        )] : []),
                                                    ]} />
                                            </Box>
                                        </Popover.Content>
                                    </Popover>
                                ),
                            ]} />
                    ),
                    () => (
                        <Typography type="body-sm" color="muted" className="shrink-0">
                            {t("publicProfile.challengesTab.manage.found", { count: filtered.length })}
                        </Typography>
                    ),
                ]} />

            <AsyncContent
                isLoading={(isLoading || !userId) && courseChallenges.length === 0}
                skeleton={(
                    <SurfaceListCard>
                        {[0, 1, 2].map((row) => (
                            <SurfaceListCardItem key={row}>
                                <StackV gap={2} principle="title-subtitle"
                                    explain="Title over supporting line — not label-field, because neither line is a form control label."
                                    items={[
                                        () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                        () => <Skeleton.Typography type="body-xs" width="1/3" />,
                                    ]} />
                            </SurfaceListCardItem>
                        ))}
                    </SurfaceListCard>
                )}
                isEmpty={filtered.length === 0}
                emptyContent={hasActiveFilter
                    ? {
                        title: t("publicProfile.challengesTab.manage.emptyFiltered"),
                        onRetry: () => {
                            setSearch("")
                            setDifficultyFilter("all")
                            setLanguageFilter("all")
                        },
                        retryLabel: t("jobs.list.emptyFiltered.clearFilters"),
                    }
                    : {
                        title: t("publicProfile.challengesTab.empty"),
                        description: t("publicProfile.challengesTab.emptyHint"),
                    }}
                error={courseChallenges.length === 0 ? error : undefined}
                errorContent={{
                    title: t("publicProfile.loadError"),
                    onRetry: () => { void mutate() },
                    retryLabel: t("publicProfile.loadErrorRetry"),
                }}
            >
                <SurfaceListCard>
                    {filtered.map((challenge, index) => {
                        const level = difficultyLevel(challenge.difficulty)
                        const passedAt = challenge.passedAt
                            ? dayjs(challenge.passedAt).locale(locale).format("hh:mm MMMM DD, YYYY")
                            : undefined
                        const selectedLang = challenge.selectedLang
                        const score = challenge.score
                        return (
                            <SurfaceListCardItem
                                key={challenge.id ?? `${challenge.submissionUrl}-${index}`}
                                hover="underline"
                                href={username && challenge.id
                                    ? pathConfig().locale(locale).profile(username).challenges()
                                        .course(courseSlug ?? "").submission(challenge.id).build()
                                    : undefined}
                            >
                                <StackH gap={4} principle="content-row" justify="between" align="center"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    items={[
                                        () => (
                                            <StackV gap={2} principle="title-subtitle" classNames={["min-w-0", "flex-1"]}
                                                explain="Title over supporting line — not label-field, because neither line is a form control label."
                                                items={[
                                                    () => (
                                                        <Typography type="body-sm" weight="medium" truncate className="underline-offset-4 decoration-[var(--separator-tertiary)] group-hover:underline">
                                                            {challenge.title}
                                                        </Typography>
                                                    ),
                                                    () => (
                                                        <Cluster gap={3} principle="chip-row" align="center"
                                                            explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                                            items={[
                                                                ...(level ? [() => <DifficultyChip difficulty={level} />] : []),
                                                                ...(selectedLang ? [() => <LanguageChip language={selectedLang} />] : []),
                                                                ...(passedAt ? [() => (
                                                                    <Typography type="body-xs" color="muted">
                                                                        {passedAt}
                                                                    </Typography>
                                                                )] : []),
                                                            ]} />
                                                    ),
                                                ]} />
                                        ),
                                        ...(typeof score === "number" ? [() => (
                                            <Typography
                                                type="body-xs"
                                                weight="medium"
                                                className={cn("shrink-0", scoreToneClass(score))}
                                            >
                                                {t("publicProfile.challengesTab.score", { score })}
                                            </Typography>
                                        )] : []),
                                    ]} />
                            </SurfaceListCardItem>
                        )
                    })}
                </SurfaceListCard>
            </AsyncContent>
        </div>
    )
}

"use client"

import React from "react"
import {
    Label,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"
import {
    useProfileUsername,
} from "@/hooks/profile/useProfileUsername"
import {
    buildDifficultySegments,
} from "@/modules/utils/challenge-difficulty"
import {
    groupByCourse,
} from "./groupByCourse"
import {
    ChallengeCourseRow,
} from "./ChallengeCourseRow"
import { useQueryUserChallengeStrengthSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserChallengeStrengthSwr"
import { useQueryUserCoursesSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCoursesSwr"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { useQueryUserSolvedChallengesSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserSolvedChallengesSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { StatRibbon } from "@/components/composites/stats/StatRibbon"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { StackH, StackV } from "@/components/frames/Stack"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { getLanguageColor, getLanguageLabel } from "@/modules/utils/language"

/** Props for {@link ProfileChallenges}. */
export type ProfileChallengesProps = WithClassNames<undefined>

/**
 * Challenges tab — the profile owner's graded-challenge proof of work. Leads with
 * a passed count + a 4-tone difficulty {@link SegmentBar} (easy→green /
 * medium→yellow / hard→red / insane→purple), then the submission list rendered as
 * Projects-tab-style rows: one collapsible {@link ChallengeCourseRow} per course
 * (its own difficulty bar + count), expanded on demand to reveal the repo links.
 * Self-contained: reads the username from the route, resolves it to the entity id,
 * and drives its own projection-backed SWR.
 *
 * @param props - optional className for the root element.
 */
export const ProfileChallenges = ({
    className,
}: ProfileChallengesProps) => {
    const t = useTranslations()
    // route carries the username; resolve to the entity id the query keys off
    const username = useProfileUsername()
    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const {
        data,
        isLoading,
        error,
        mutate,
    } = useQueryUserSolvedChallengesSwr(userId)
    // difficulty-weighted challenge strength: global percentile + rank (null until passed)
    const { data: strength } = useQueryUserChallengeStrengthSwr(userId)
    // joined courses → total challenges per course (for the per-course progress bar)
    const { data: coursesData } = useQueryUserCoursesSwr(userId)
    const totalChallengesByCourse = new Map(
        (coursesData ?? []).map((course) => [course.label, course.challengeTotal]),
    )

    const challenges = data ?? []
    // difficulty distribution across all passed challenges (the headline bar)
    const difficultySegments = buildDifficultySegments(challenges)
    // language breadth: count per language, skipping rows with no language
    const langCounts = challenges.reduce<Record<string, number>>((acc, challenge) => {
        if (!challenge.selectedLang) {
            return acc
        }
        acc[challenge.selectedLang] = (acc[challenge.selectedLang] ?? 0) + 1
        return acc
    }, {})
    const langs = Object.entries(langCounts).sort((a, b) => b[1] - a[1])
    // submission list grouped by course (when the backend resolves titles)
    const groups = groupByCourse(challenges)

    // headline metric row (Coding-tab style): passed + XP + percentile + rank.
    // XP is the REAL ledger sum from the backend (NOT a FE sum of scores).
    const metricStats: Array<{ key: string; value: string }> = [
        { key: "passed", value: String(challenges.length) },
    ]
    if (strength?.xp != null) {
        metricStats.push({ key: "xp", value: String(strength.xp) })
    }
    if (strength?.percentile != null) {
        metricStats.push({ key: "percentile", value: `${strength.percentile}%` })
    }
    if (strength?.rank != null) {
        metricStats.push({ key: "rank", value: `#${strength.rank}` })
    }

    const rootClassNames: Array<AllowedClassName> = []
    if (className) {
        rootClassNames.push(className as AllowedClassName)
    }

    return (
        <AsyncContent
            isLoading={(isLoading || !userId) && challenges.length === 0}
            skeleton={(
                <StackV gap={6} principle="block-boundary" classNames={rootClassNames}
                    explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                    items={[
                        () => (
                            <StackV gap={4} items={[
                                () => <Skeleton.Typography type="body-sm" width="1/4" />,
                                () => <Skeleton className="h-20 w-full rounded-2xl" />,
                            ]} />
                        ),
                        () => (
                            <StackV gap={4} items={[
                                () => <Skeleton.Typography type="body-sm" width="1/4" />,
                                () => (
                                    <SurfaceListCard>
                                        <SurfaceListCardItem>
                                            <Skeleton.SegmentBar legendItems={4} />
                                        </SurfaceListCardItem>
                                        <SurfaceListCardItem>
                                            <Skeleton.SegmentBar legendItems={4} />
                                        </SurfaceListCardItem>
                                    </SurfaceListCard>
                                ),
                            ]} />
                        ),
                        () => (
                            <StackV gap={4} items={[
                                () => <Skeleton.Typography type="body-sm" width="1/4" />,
                                () => (
                                    <SurfaceListCard>
                                        {[0, 1, 2].map((row) => (
                                            <SurfaceListCardItem key={row}>
                                                <StackH gap={4} principle="content-row" align="start"
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    items={[
                                                        () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                                                        () => (
                                                            <StackV gap={3} principle="sibling-stack" classNames={["min-w-0", "flex-1"]}
                                                                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                                items={[
                                                                    () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                                                    () => <Skeleton.ProgressBar />,
                                                                    () => <Skeleton.Typography type="body-xs" width="1/3" />,
                                                                ]} />
                                                        ),
                                                    ]} />
                                            </SurfaceListCardItem>
                                        ))}
                                    </SurfaceListCard>
                                ),
                            ]} />
                        ),
                    ]} />
            )}
            isEmpty={challenges.length === 0}
            emptyContent={{
                title: t("publicProfile.challengesTab.empty"),
                description: t("publicProfile.challengesTab.emptyHint"),
            }}
            error={challenges.length === 0 ? error : undefined}
            errorContent={{
                title: t("publicProfile.loadError"),
                onRetry: () => { void mutate() },
                retryLabel: t("publicProfile.loadErrorRetry"),
            }}
        >
            <StackV gap={6} principle="block-boundary" classNames={rootClassNames}
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                    () => (
                        <LabeledCard label={t("publicProfile.challengesTab.metricsHeading")} frameless>
                            <StatRibbon
                                items={metricStats.map((stat) => ({
                                    key: stat.key,
                                    value: stat.value,
                                    label: t(`publicProfile.challengesTab.metric.${stat.key}`),
                                }))}
                            />
                        </LabeledCard>
                    ),
                    () => (
                        <LabeledCard
                            label={t("publicProfile.challengesTab.statsHeading")}
                            frameless
                        >
                            <SurfaceListCard>
                                {difficultySegments.length > 0 ? (
                                    <SurfaceListCardItem>
                                        <StackV gap={3} principle="sibling-stack"
                                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                            items={[
                                                () => <Label>{t("publicProfile.challengesTab.difficultyHeading")}</Label>,
                                                () => (
                                                    <SegmentBar
                                                        ariaLabel={t("publicProfile.challengesTab.difficultyHeading")}
                                                        segments={difficultySegments}
                                                    />
                                                ),
                                            ]} />
                                    </SurfaceListCardItem>
                                ) : null}
                                {langs.length > 0 ? (
                                    <SurfaceListCardItem>
                                        <StackV gap={3} principle="sibling-stack"
                                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                            items={[
                                                () => <Label>{t("publicProfile.challengesTab.languageHeading")}</Label>,
                                                () => (
                                                    <SegmentBar
                                                        ariaLabel={t("publicProfile.challengesTab.languageHeading")}
                                                        segments={langs.map(([lang, count]) => ({
                                                            key: lang,
                                                            label: getLanguageLabel(lang),
                                                            value: count,
                                                            color: getLanguageColor(lang),
                                                        }))}
                                                    />
                                                ),
                                            ]} />
                                    </SurfaceListCardItem>
                                ) : null}
                            </SurfaceListCard>
                        </LabeledCard>
                    ),
                    () => (
                        <LabeledCard
                            label={t("publicProfile.challengesTab.repoHeading")}
                            frameless
                        >
                            <SurfaceListCard>
                                {groups.map((group, groupIndex) => (
                                    <ChallengeCourseRow
                                        key={group.courseTitle ?? `__ungrouped-${groupIndex}`}
                                        username={username}
                                        courseTitle={group.courseTitle}
                                        courseSlug={group.courseSlug}
                                        items={group.items}
                                        totalChallenges={group.courseTitle
                                            ? totalChallengesByCourse.get(group.courseTitle)
                                            : undefined}
                                    />
                                ))}
                            </SurfaceListCard>
                        </LabeledCard>
                    ),
                ]} />
        </AsyncContent>
    )
}

"use client"

import React from "react"
import { Typography } from "@heroui/react"
import { useTranslations } from "next-intl"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { useProfileUsername } from "@/hooks/profile/useProfileUsername"
import { buildDifficultySegments } from "@/modules/utils/challenge-difficulty"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { useQueryUserSolvedChallengesSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserSolvedChallengesSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StatPair } from "@/components/composites/stats/StatPair"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { StackV } from "@/components/frames/Stack"
import { getLanguageColor, getLanguageLabel } from "@/modules/utils/language"

/** Props for {@link OverviewChallengeSkills}. */
export interface OverviewChallengeSkillsProps extends WithClassNames<undefined> {
    /** Section label, rendered outside the card (owned here, like every other self-contained section). */
    label: string
    /** Optional "see more" link on the label row. */
    onSeeMore?: () => void
    /** Text for the see-more link. */
    seeMoreLabel?: string
    /** Stretch the section (and its card) to fill the row's height. */
    fillHeight?: boolean
}

/**
 * Overview snapshot — skills proven by graded CHALLENGES, mirroring the "Skills
 * via Practice" card: a passed-count headline, the 4-tone DIFFICULTY
 * {@link SegmentBar}, then a language {@link SegmentBar} (brand legend, same as the
 * Challenges tab). A teaser only — the full submission list lives behind "See
 * more" in the Challenges tab. Owns its own `LabeledCard`, with `frameless`
 * computed HERE (not hardcoded) so the loaded snapshot (self-framed as a
 * `SurfaceListCard`) skips the outer `Card` — but the skeleton/empty/error
 * states, which have no bounded surface of their own, still get one. The fetch
 * goes through {@link AsyncContent}.
 *
 * @param props - {@link OverviewChallengeSkillsProps}
 */
export const OverviewChallengeSkills = ({ className, label, onSeeMore, seeMoreLabel, fillHeight }: OverviewChallengeSkillsProps) => {
    const t = useTranslations()
    const username = useProfileUsername()
    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const { data, isLoading, error, mutate } = useQueryUserSolvedChallengesSwr(userId)

    const challenges = data ?? []
    // difficulty distribution across all passed challenges
    const difficultySegments = buildDifficultySegments(challenges)
    // language breadth: count per language, skipping rows with no language (V1-legacy)
    const langCounts = challenges.reduce<Record<string, number>>((acc, challenge) => {
        if (!challenge.selectedLang) {
            return acc
        }
        acc[challenge.selectedLang] = (acc[challenge.selectedLang] ?? 0) + 1
        return acc
    }, {})
    const langs = Object.entries(langCounts).sort((a, b) => b[1] - a[1])
    const hasChallenges = !(isLoading || !userId) && !error && challenges.length > 0

    return (
        <LabeledCard
            className={className}
            label={label}
            onSeeMore={onSeeMore}
            seeMoreLabel={seeMoreLabel}
            fillHeight={fillHeight}
            frameless={hasChallenges}
        >
            <AsyncContent
                isLoading={(isLoading || !userId) && challenges.length === 0}
                skeleton={(
                    <SurfaceListCard>
                        <SurfaceListCardItem>
                            {/* gap-only column: vertical peers at house step 4 (12px) — no step-4 peer-stack token */}
                            <StackV gap={4} items={[
                                () => <Skeleton.Metric />,
                                () => <Skeleton.SegmentBar legendItems={4} />,
                                () => (
                                    <StackV gap={3} principle="sibling-stack"
                                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                        items={[
                                            () => <Skeleton.Typography type="body-xs" width="1/4" />,
                                            () => <Skeleton.SegmentBar legendItems={4} />,
                                        ]} />
                                ),
                            ]} />
                        </SurfaceListCardItem>
                    </SurfaceListCard>
                )}
                isEmpty={challenges.length === 0}
                emptyContent={{ title: t("publicProfile.skills.empty") }}
                error={challenges.length === 0 ? error : undefined}
                errorContent={{
                    title: t("publicProfile.loadError"),
                    onRetry: () => { void mutate() },
                    retryLabel: t("publicProfile.loadErrorRetry"),
                }}
            >
                <SurfaceListCard className="h-full">
                    <SurfaceListCardItem>
                        <StackV gap={4} items={[
                            () => (
                                <StatPair
                                    value={String(challenges.length)}
                                    label={t("publicProfile.challengesCount")}
                                />
                            ),
                            ...(difficultySegments.length > 0
                                ? [() => (
                                    <SegmentBar
                                        ariaLabel={`${challenges.length} ${t("publicProfile.challengesCount")}`}
                                        segments={difficultySegments}
                                    />
                                )]
                                : []),
                            ...(langs.length > 0
                                ? [() => (
                                    <StackV gap={3} principle="sibling-stack"
                                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                        items={[
                                            () => (
                                                <Typography type="body-xs" color="muted">
                                                    {t("publicProfile.skillsSnapshot.languagesLabel")}
                                                </Typography>
                                            ),
                                            () => (
                                                <SegmentBar
                                                    ariaLabel={t("publicProfile.skillsSnapshot.languagesLabel")}
                                                    segments={langs.map(([lang, count]) => ({
                                                        key: lang,
                                                        label: getLanguageLabel(lang),
                                                        value: count,
                                                        color: getLanguageColor(lang),
                                                    }))}
                                                />
                                            ),
                                        ]} />
                                )]
                                : []),
                        ]} />
                    </SurfaceListCardItem>
                </SurfaceListCard>
            </AsyncContent>
        </LabeledCard>
    )
}

"use client"

import React, {
    useMemo,
} from "react"
import {
    Typography,
    cn,
} from "@heroui/react"
import {
    useParams,
    useRouter,
} from "next/navigation"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    CheckCircleIcon,
    CircleIcon,
    RocketIcon,
    SealCheckIcon,
} from "@phosphor-icons/react"
import {
    useProfileUsername,
} from "@/hooks/profile/useProfileUsername"
import { pathConfig } from "@/resources/path"
import { useQueryUserCapstoneProgressSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCapstoneProgressSwr"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { BackLink } from "@/components/blocks/navigation/BackLink"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StatusChip } from "@/components/blocks/chips/StatusChip"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { StackH, StackV } from "@/components/frames/Stack"
import type { WithClassNames } from "@/modules/types/base/class-name"

/**
 * Score → attention colour the eye catches fast: high green, mid yellow, low red.
 * @param score - the graded score (0–100).
 * @returns a `text-{token}` class for the score label.
 */
const scoreToneClass = (score: number): string => {
    if (score >= 90) {
        return "text-success-soft-foreground"
    }
    if (score >= 70) {
        return "text-warning-soft-foreground"
    }
    return "text-danger-soft-foreground"
}

/** Props for {@link ProfileProjectRoadmapPage}. */
export type ProfileProjectRoadmapPageProps = WithClassNames<undefined>

/**
 * `/profile/<u>/projects/<courseGlobalId>` — the DETAIL tier of the projects
 * flow: the FULL milestone/task roadmap of ONE capstone course, no inline
 * expand cap (unlike the list's compact {@link import("../ProfileCapstone/ProjectCard").ProjectCard}
 * row). Reads the course id from the route, then filters the profile owner's
 * full `userCapstoneProgress` list down to it client-side — the same data the
 * list already fetched, per the BE recommendation (no dedicated detail query).
 *
 * @param props - optional className for the root element.
 */
export const ProfileProjectRoadmapPage = ({
    className,
}: ProfileProjectRoadmapPageProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const username = useProfileUsername()
    const params = useParams<{ courseId: string }>()
    const courseGlobalId = params?.courseId ? String(params.courseId) : null

    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const {
        data: projectsData,
        isLoading,
        error: projectsError,
        mutate: reloadProjects,
    } = useQueryUserCapstoneProgressSwr(userId)

    const projects = projectsData ?? []
    // scope down to THIS course only — the detail page's whole reason to exist
    const project = useMemo(
        () => projects.find((item) => item.courseGlobalId === courseGlobalId) ?? null,
        [projects, courseGlobalId],
    )

    // milestones ordered along the roadmap (defensive copy before sort)
    const milestones = useMemo(
        () => [...(project?.milestones ?? [])].sort((a, b) => a.position - b.position),
        [project],
    )

    const totalTasks = Math.max(project?.totalTasks ?? 0, 1)
    const percent = Math.round(((project?.completedTasks ?? 0) / totalTasks) * 100)
    const hasVerified = (project?.completedTasks ?? 0) > 0

    const resolvedLoading = (isLoading || !userId) && !projectsData
    // resolved (not loading, no error) but no match → "not found" empty state
    const notFound = !resolvedLoading && !projectsError && !project

    return (
        <div className={cn("mx-auto flex max-w-4xl flex-col gap-6", className)}>
            <PageHeader
                breadcrumb={(
                    <BackLink
                        target={t("publicProfile.capstone.roadmapBackToProjects")}
                        onPress={() => router.push(pathConfig().locale(locale).profile(username ?? undefined).projects().build())}
                    />
                )}
                title={project?.courseTitle ?? t("publicProfile.capstone.roadmapTitle")}
                meta={project ? (
                    <StackV gap={3} principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                        items={[
                            () => (
                                <StackH gap={3} principle="chip-row" align="center"
                                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                    items={[
                                        ...(hasVerified ? [() => (
                                            <StatusChip
                                                tone="success"
                                                icon={<SealCheckIcon aria-hidden focusable="false" className="size-4" />}
                                            >
                                                {t("pinnedProjects.verified")}
                                            </StatusChip>
                                        )] : []),
                                        () => (
                                            <Typography type="body-xs" color="muted">
                                                {t("publicProfile.capstone.roadmapSummary", {
                                                    completedMilestones: project.completedMilestones,
                                                    totalMilestones: project.totalMilestones,
                                                    completedTasks: project.completedTasks,
                                                    totalTasks: project.totalTasks,
                                                })}
                                            </Typography>
                                        ),
                                    ]} />
                            ),
                            () => (
                                <SegmentBar
                                    hideLegend
                                    max={totalTasks}
                                    ariaLabel={`${project.courseTitle} · ${percent}%`}
                                    segments={[
                                        {
                                            key: "verified",
                                            label: t("publicProfile.capstone.projectsHeading"),
                                            value: project.completedTasks,
                                            color: "var(--success)",
                                        },
                                    ]}
                                />
                            ),
                        ]} />
                ) : undefined}
            />

            <AsyncContent
                isLoading={resolvedLoading}
                skeleton={(
                    <SurfaceListCard>
                        {[0, 1].map((row) => (
                            <SurfaceListCardItem key={row}>
                                <StackH gap={4} principle="content-row" align="start"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    items={[
                                        () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                                        () => (
                                            <StackV gap={4} principle="label-field" classNames={["min-w-0", "flex-1"]}
                                                explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                                                items={[
                                                    () => <Skeleton.Typography type="body-sm" width="1/3" />,
                                                    () => <Skeleton.ProgressBar />,
                                                    () => <Skeleton.Typography type="body-xs" width="2/3" />,
                                                    () => (
                                                        <StackV gap={1} principle="name-handle"
                                                            explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
                                                            items={
                                                                [0, 1].map((task) => () => (
                                                                    <StackH key={task} gap={4} principle="content-row" align="center"
                                                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                        items={[
                                                                            () => <Skeleton className="size-5 shrink-0 rounded-full" />,
                                                                            () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                                                        ]} />
                                                                ))
                                                            } />
                                                    ),
                                                ]} />
                                        ),
                                    ]} />
                            </SurfaceListCardItem>
                        ))}
                    </SurfaceListCard>
                )}
                isEmpty={notFound || (Boolean(project) && milestones.length === 0)}
                emptyContent={notFound
                    ? {
                        title: t("publicProfile.capstone.roadmapNotFound"),
                        description: t("publicProfile.capstone.roadmapNotFoundHint"),
                    }
                    : {
                        title: t("publicProfile.capstone.roadmapEmpty"),
                    }}
                error={projectsError}
                errorContent={{
                    title: t("publicProfile.capstone.loadErrorTitle"),
                    description: t("publicProfile.capstone.loadErrorDescription"),
                    onRetry: () => {
                        void reloadProjects()
                    },
                    retryLabel: t("publicProfile.capstone.loadErrorRetry"),
                }}
            >
                <SurfaceListCard>
                    {milestones.map((milestone, milestoneIndex) => (
                        <SurfaceListCardItem key={milestone.milestoneGlobalId ?? `${milestone.title}-${milestoneIndex}`}>
                            <StackH gap={4} principle="content-row" align="start"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                items={[
                                    () => (
                                        <IconTile
                                            size="sm"
                                            icon={<RocketIcon aria-hidden focusable="false" />}
                                        />
                                    ),
                                    () => (
                                        <StackV gap={4} principle="label-field" classNames={["min-w-0", "flex-1"]}
                                            explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                                            items={[
                                                () => (
                                                    <ProgressMeter
                                                        label={milestone.title}
                                                        value={milestone.passedTasks}
                                                        max={Math.max(milestone.totalTasks, 1)}
                                                        showValue
                                                    />
                                                ),
                                                () => (
                                                    <Typography type="body-xs" color="muted">
                                                        {t("publicProfile.capstone.roadmapMilestoneProgress", {
                                                            completed: milestone.passedTasks,
                                                            total: milestone.totalTasks,
                                                        })}
                                                    </Typography>
                                                ),
                                                () => (
                                                    <StackV gap={1} principle="name-handle"
                                                        explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
                                                        items={
                                                            milestone.tasks.map((task, taskIndex) => () => (
                                                                <div
                                                                    key={task.taskGlobalId ?? `${task.title}-${taskIndex}`}
                                                                    className={cn(
                                                                        taskIndex < milestone.tasks.length - 1 && "border-b border-default",
                                                                    )}
                                                                >
                                                                    <StackH
                                                                        gap={4}
                                                                        principle="content-row"
                                                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                        align="center"
                                                                        items={[
                                                                            () => (
                                                                                task.passed ? (
                                                                                    <CheckCircleIcon aria-hidden focusable="false" className="size-5 shrink-0 text-success-soft-foreground" />
                                                                                ) : (
                                                                                    <CircleIcon aria-hidden focusable="false" className="size-5 shrink-0 text-muted-foreground" />
                                                                                )
                                                                            ),
                                                                            () => (
                                                                                <Typography
                                                                                    type="body-sm"
                                                                                    className={cn("min-w-0 flex-1 truncate", task.passed && "text-success-soft-foreground")}
                                                                                >
                                                                                    {task.title}
                                                                                </Typography>
                                                                            ),
                                                                            ...(task.passed ? [() => (
                                                                                <StackH gap={2} principle="separator-dot" classNames={["shrink-0"]}
                                                                                    explain="Places a middle-dot separator between short meta peers so the items read as one inline list."
                                                                                    items={[
                                                                                        () => (
                                                                                            <Typography
                                                                                                type="body-xs"
                                                                                                weight="medium"
                                                                                                className={scoreToneClass(task.score)}
                                                                                            >
                                                                                                {t("publicProfile.capstone.score", { score: task.score })}
                                                                                            </Typography>
                                                                                        ),
                                                                                        ...(task.passedAt ? [() => {
                                                                                            const passedAt = task.passedAt as string | number | Date
                                                                                            return (
                                                                                                <Typography type="body-xs" color="muted">
                                                                                                    {` · ${new Date(passedAt).toLocaleDateString(locale)}`}
                                                                                                </Typography>
                                                                                            )
                                                                                        }] : []),
                                                                                    ]} />
                                                                            )] : []),
                                                                        ]}
                                                                    />
                                                                </div>
                                                            ))
                                                        } />
                                                ),
                                            ]} />
                                    ),
                                ]} />
                        </SurfaceListCardItem>
                    ))}
                </SurfaceListCard>
            </AsyncContent>
        </div>
    )
}

﻿"use client"

import React from "react"
import {
    cn,
    Chip,
    Typography,
} from "@heroui/react"
import {
    ArrowSquareOutIcon,
    SealCheckIcon,
    GraduationCapIcon,
    CodeIcon,
} from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import type { WithClassNames } from "@/modules/types/base/class-name"
import type { QueryUserPinnedProjectItem } from "@/modules/api/graphql/queries/types/user-pinned-projects"
import { Box } from "@/components/frames/Box"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"

/** Tech-stack chips shown inline before collapsing the rest into a "+N" chip. */
const MAX_TECH_CHIPS = 3

/** Props for {@link PinnedProjectCard}. */
export interface PinnedProjectCardProps extends WithClassNames<undefined> {
    /** The pinned project to render (list-item data prop — store can't index it). */
    pin: QueryUserPinnedProjectItem
}

/**
 * Display-only card for one pinned project (public-profile showcase, GitHub-pinned
 * style).
 *
 * @param props - {@link PinnedProjectCardProps}
 */
export const PinnedProjectCard = ({ pin, className }: PinnedProjectCardProps) => {
    const t = useTranslations()

    const isCourse = pin.type === "course"
    const TypeIcon = isCourse ? GraduationCapIcon : CodeIcon
    const title = pin.title ?? t("pinnedProjects.untitled")

    const tech = pin.techStack ?? []
    const visibleTech = tech.slice(0, MAX_TECH_CHIPS)
    const overflow = tech.length - visibleTech.length

    const chipItems = [
        ...visibleTech.map((techName) => (
            () => (
                <Chip key={techName} variant="soft" size="sm">
                    <Chip.Label>{techName}</Chip.Label>
                </Chip>
            )
        )),
        ...(overflow > 0
            ? [() => (
                <Chip variant="soft" size="sm">
                    <Chip.Label>{`+${overflow}`}</Chip.Label>
                </Chip>
            )]
            : []),
    ]

    const body = (
        <>
            <Box principle="card-padding" className="p-4"
            explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                <StackV gap={3} principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                items={[
                    () => (
                        <StackH gap={3} principle="flex-action" justify="between"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        items={[
                            () => (
                                <span
                                    className={cn(
                                        "inline-flex items-center rounded-full px-2 py-0 text-xs",
                                        isCourse
                                            ? "bg-success-soft text-success-soft-foreground"
                                            : "border border-default text-muted",
                                    )}
                                >
                                    <StackH gap={2} principle="icon-text" inline
                                    explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                                    items={[
                                        () => <TypeIcon className="size-4" aria-hidden="true" focusable="false" />,
                                        () => <span>{isCourse ? t("pinnedProjects.typeCapstone") : t("pinnedProjects.typeExternal")}</span>,
                                    ]} />
                                </span>
                            ),
                            () => (
                                <ArrowSquareOutIcon
                                    className="size-4 shrink-0 text-muted"
                                    aria-hidden="true"
                                    focusable="false"
                                />
                            ),
                        ]} />
                    ),
                    () => (
                        <Typography
                            type="body-sm"
                            weight="medium"
                            className="line-clamp-2 underline-offset-4 decoration-[var(--separator-tertiary)] group-hover:underline"
                        >
                            {title}
                        </Typography>
                    ),
                    ...(pin.description
                        ? [() => (
                            <Typography type="body-xs" color="muted" className="line-clamp-1">
                                {pin.description}
                            </Typography>
                        )]
                        : []),
                    ...(visibleTech.length > 0
                        ? [() => <Cluster gap={3} principle="chip-row" items={chipItems} />]
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        : []),
                ]} />
            </Box>
            {pin.isVerified ? (
                <Box principle="pill-pad" className="border-t border-success/30 bg-success-soft px-4 py-2"
                explain="Pill/chip inset — not control-pad, because this pads a compact badge shape rather than a form control.">
                    <StackH gap={3} items={[
                        () => (
                            <SealCheckIcon
                                className="size-4 shrink-0 text-success-soft-foreground"
                                aria-hidden="true"
                                focusable="false"
                            />
                        ),
                        () => (
                            <Typography type="body-xs" weight="medium" className="text-success-soft-foreground">
                                {t("pinnedProjects.verifiedByStarci")}
                            </Typography>
                        ),
                    ]} />
                </Box>
            ) : null}
        </>
    )

    const cardClassName = cn(
        "group flex flex-col overflow-hidden rounded-2xl border bg-surface",
        pin.isVerified ? "border-success/40" : "border-default",
        className,
    )

    if (pin.url) {
        return (
            <a
                href={pin.url}
                target="_blank"
                rel="noopener noreferrer"
                aria-label={t("pinnedProjects.openAria", { title })}
                className={cn(cardClassName, "cursor-pointer")}
            >
                {body}
            </a>
        )
    }

    return <div className={cardClassName}>{body}</div>
}

"use client"

import React from "react"
import { FileTextIcon, PencilSimpleIcon } from "@phosphor-icons/react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Button } from "@/components/atoms/buttons/Button"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"
import { pathConfig } from "@/resources/path"
import { useAppSelector } from "@/redux/hooks"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { useQueryPublicUserCvSwr } from "@/hooks/swr/api/graphql/queries/useQueryPublicUserCvSwr"
import { useProfileUsername } from "@/hooks/profile/useProfileUsername"

/**
 * A4 "paper" frame reused from the CV editor's live preview
 * (`CvBlocksWorkspace/CvPdfPreview`) — a scrollable, white, A4-proportioned card.
 * A page-proportioned sheet is not a shape any frame names, so it stays a literal
 * on `Box` — but ONE literal, shared by the resting and loaded states.
 */
const PAPER_FRAME =
    "relative mx-auto flex h-full max-w-[820px] flex-col overflow-hidden rounded-3xl bg-white shadow-surface"

/** Viewport-proportioned height of the resting sheet. */
const RESTING_HEIGHT = "h-[70vh] min-h-[480px]"

/** Viewport-proportioned height of the loaded sheet. */
const LOADED_HEIGHT = "h-[80vh] min-h-[520px]"

const PublicCvEditButton = ({ label, onPress }: { label: string; onPress: () => void }) => (
    <Button
        label={label}
        variant="secondary"
        prefixIcon={PencilSimpleIcon}
        onPress={onPress}
    />
)

/**
 * Public CV tab (`/profile/<username>/cv`) — the read-only, PDF-only view of the
 * ONE CV a user has flagged public. Anyone (signed in or not) can view it. When
 * the viewer IS the owner (`isSelf`), an "Edit CV" button links to the private
 * editor gallery (`/profile/cv`). Branches:
 *
 *   - data + `pdfUrl`   → the compiled PDF embedded read-only in the paper frame
 *   - data, no `pdfUrl` → the public CV was never compiled (a note)
 *   - no data           → the user has no public CV
 *
 * Self-contained: reads the username from the route, derives `isSelf` from the
 * viewer (redux) + the profile owner (`userProfile`), and drives its own SWR.
 */
export const ProfilePublicCvPage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const username = useProfileUsername()
    const viewer = useAppSelector((state) => state.user.user)
    const { data: user } = useQueryUserProfileSwr(username)
    const isSelf = !!viewer && !!user?.id && viewer.id === user.id

    const cvSwr = useQueryPublicUserCvSwr(username)
    const cv = cvSwr.data
    const isSkeleton = cvSwr.isLoading && !cvSwr.data

    const editLabel = t("publicProfile.publicCv.editCta")
    const onEdit = () => router.push(pathConfig().locale(locale).profile().cv().build())

    // error beats a stale loading flag (BLOCK-8 order).
    if (cvSwr.error) {
        return (
            <AsyncContentError
                title={t("publicProfile.publicCv.errorTitle")}
                onRetry={() => cvSwr.mutate()}
                retryLabel={t("publicProfile.publicCv.retry")}
            />
        )
    }

    // the resting state IS the paper frame, shimmering — same literal, same proportions
    if (isSkeleton) {
        return (
            <Box className={RESTING_HEIGHT}>
                <Box principle="center-measure" className={PAPER_FRAME}
                    explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport."
                >
                    <Skeleton className="h-full w-full" />
                </Box>
            </Box>
        )
    }

    // no public CV at all, or flagged public but never compiled — same shape, different line
    if (!cv || !cv.pdfUrl) {
        return (
            <AsyncContentEmpty
                icon={FileTextIcon}
                title={cv
                    ? t("publicProfile.publicCv.notCompiled")
                    : t("publicProfile.publicCv.emptyTitle")}
                description={isSelf
                    ? (cv
                        ? t("publicProfile.publicCv.notCompiledSelfHint")
                        : t("publicProfile.publicCv.emptySelfHint"))
                    : undefined}
                action={isSelf ? () => <PublicCvEditButton label={editLabel} onPress={onEdit} /> : undefined}
            />
        )
    }

    // captured out of the guard: property narrowing does not survive into the slot closures
    const pdfUrl = cv.pdfUrl
    const pdfTitle = cv.label || t("publicProfile.publicCv.iframeTitle")

    return (
        <StackV
            identity={{ tier: "block", component: "ProfilePublicCvPage" }}
            gap={5}
            principle="group-boundary"
            explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
            items={[
                ...(isSelf ? [() => (
                    <div className="flex justify-end">
                        <PublicCvEditButton label={editLabel} onPress={onEdit} />
                    </div>
                )] : []),
                () => (
                    <Box className={LOADED_HEIGHT}>
                        <Box principle="center-measure" className={PAPER_FRAME}
                            explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport."
                        >
                            <iframe
                                title={pdfTitle}
                                src={pdfUrl}
                                className="h-full w-full flex-1 border-0"
                            />
                        </Box>
                    </Box>
                ),
            ]}
        />
    )
}

"use client"

import React, {
    useMemo,
    useState,
} from "react"
import {
    Badge,
    Button,
    Label,
    Popover,
    Typography,
} from "@heroui/react"
import {
    FunnelIcon,
} from "@phosphor-icons/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useProfileUsername,
} from "@/hooks/profile/useProfileUsername"
import {
    CODING_DIFFICULTY_CHIP,
    domainLabel,
} from "@/modules/utils/coding-difficulty"
import { pathConfig } from "@/resources/path"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"
import { useQueryUserCodingHistorySwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCodingHistorySwr"
import { useQueryUserCodingProgressSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCodingProgressSwr"
import { useQueryUserCodingRankSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCodingRankSwr"
import { useQueryUserCodingSkillsSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCodingSkillsSwr"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { useQueryUserXpSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserXpSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { LanguageChip } from "@/components/blocks/chips/LanguageChip"
import { StatRibbon } from "@/components/composites/stats/StatRibbon"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { SearchInput } from "@/components/blocks/form/SearchInput"
import { FlexWrapButtonRadio } from "@/components/blocks/navigation/FlexWrapButtonRadio"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StatusChip } from "@/components/blocks/chips/StatusChip"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { TopicMasteryGrid } from "@/components/blocks/stats/TopicMasteryGrid"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { getLanguageColor, getLanguageLabel } from "@/modules/utils/language"

/** Solve-history rows shown before the "see more" link kicks in. */
const INITIAL_HISTORY = 6

/** Props for {@link ProfileCoding}. */
export type ProfileCodingProps = WithClassNames<undefined>

/**
 * CODING difficulty scale (easy/medium/hard ONLY — coding problems, NOT the
 * challenge beginner/intermediate/advanced/insane taxonomy). 3-tone semantic
 * colours for the distribution bar: easy → green, medium → yellow, hard → red.
 */
const CODING_DIFFICULTY: ReadonlyArray<{ key: string; labelKey: string; color: string }> = [
    { key: "easy", labelKey: "publicProfile.skillsSnapshot.diffEasy", color: "var(--success)" },
    { key: "medium", labelKey: "publicProfile.skillsSnapshot.diffMedium", color: "var(--warning)" },
    { key: "hard", labelKey: "publicProfile.skillsSnapshot.diffHard", color: "var(--danger)" },
]

/** Single-select difficulty filter value — `"all"` clears the filter. */
type DifficultyFilterValue = "all" | string
/** Single-select language filter value — `"all"` clears the filter. */
type LanguageFilterValue = "all" | string

/**
 * Coding tab ("Skills & Coding") — the profile owner's coding-practice proof
 * of work, built as a sibling of the Challenges tab: a headline metric row
 * (solved · points · acceptance · rank · top-percentile placeholder), a single
 * "Stats" {@link LabeledCard} that gathers the three breakdowns (by difficulty /
 * by topic / by language) under {@link Label} sub-headings, then a "Solve
 * history" card whose rows mirror the Challenges submission style (title on top,
 * date on the left, difficulty/topic/language chips pushed right). Self-contained:
 * reads the username from the route, resolves it to the entity id, and drives its
 * own projection-backed SWR.
 *
 * @param props - optional className for the root element.
 */
export const ProfileCoding = ({
    className,
}: ProfileCodingProps) => {
    const t = useTranslations()
    const locale = useLocale()
    // route carries the username; resolve to the entity id the queries key off
    const username = useProfileUsername()
    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const {
        data,
        isLoading,
        error,
        mutate,
    } = useQueryUserCodingProgressSwr(userId)
    const historySwr = useQueryUserCodingHistorySwr(userId)
    const skillsSwr = useQueryUserCodingSkillsSwr(userId)
    // coding standing — global rank + percentile by solved count (null when unranked)
    const standingSwr = useQueryUserCodingRankSwr(userId)
    // per-source XP breakdown — codingXp is the coding-only XP (ledger sum),
    // NOT the global users.points balance the legacy "Code score" metric read
    const xpSwr = useQueryUserXpSwr(userId)
    const history = historySwr.data
    const skills = skillsSwr.data
    const standing = standingSwr.data
    const xp = xpSwr.data

    // null data (no coding activity yet) → treat every metric as zero
    const solved = data?.solvedProblemIds.length ?? 0

    // headline metric row (count · XP · top percentile · rank), mirroring the Challenges tab.
    // percentile + rank hide when unranked (no solved problems).
    const stats: Array<{ key: string; value: string }> = [
        { key: "solved", value: String(solved) },
        { key: "xp", value: String(xp?.codingXp ?? 0) },
    ]
    if (standing?.percentile != null) {
        stats.push({ key: "percentile", value: `${standing.percentile}%` })
    }
    if (standing?.rank != null) {
        stats.push({ key: "rank", value: `#${standing.rank}` })
    }

    // breakdowns for the gathered "Stats" card
    const byLanguage = skills?.byLanguage ?? []
    const byDifficulty = skills?.byDifficulty ?? []
    const byDomain = skills?.byDomain ?? []
    const orderedDomain = [...byDomain].sort((a, b) => b.solved - a.solved)
    // difficulty distribution (easy→hard), coloured by the coding 3-tone scale
    const solvedByDifficulty = new Map(byDifficulty.map((item) => [item.key, item.solved]))
    const difficultySegments = CODING_DIFFICULTY
        .filter((difficulty) => (solvedByDifficulty.get(difficulty.key) ?? 0) > 0)
        .map((difficulty) => ({
            key: difficulty.key,
            label: t(difficulty.labelKey),
            value: solvedByDifficulty.get(difficulty.key) ?? 0,
            color: difficulty.color,
        }))
    const hasStats = difficultySegments.length > 0 || orderedDomain.length > 0 || byLanguage.length > 0

    const solvedHistory = history ?? []

    // search/filter toolbar (the "manage" layer) — client-side, the list is
    // already small per-user; no server-side pagination needed here.
    const [search, setSearch] = useState("")
    const [difficultyFilter, setDifficultyFilter] = useState<DifficultyFilterValue>("all")
    const [languageFilter, setLanguageFilter] = useState<LanguageFilterValue>("all")
    // difficulty/language facets live behind a FUNNEL popover (same toolbar shape as
    // ProfileChallengeManage) — the toolbar stays a single clean line regardless of how
    // many facet values exist; the funnel badges the active facet count.
    const [filterOpen, setFilterOpen] = useState(false)
    const activeFacetCount = (difficultyFilter !== "all" ? 1 : 0) + (languageFilter !== "all" ? 1 : 0)
    const clearFacets = () => {
        setDifficultyFilter("all")
        setLanguageFilter("all")
    }
    // filter option pools — only difficulties/languages actually present in the history
    const difficultyOptions = useMemo(
        () => Array.from(new Set(solvedHistory.map((item) => item.difficulty).filter(Boolean))),
        [solvedHistory],
    )
    const languageOptions = useMemo(
        () => Array.from(new Set(solvedHistory.flatMap((item) => item.languages).filter(Boolean))),
        [solvedHistory],
    )
    const filteredHistory = useMemo(() => {
        const query = search.trim().toLowerCase()
        return solvedHistory.filter((item) => {
            if (query && !item.problemTitle.toLowerCase().includes(query)) {
                return false
            }
            if (difficultyFilter !== "all" && item.difficulty !== difficultyFilter) {
                return false
            }
            if (languageFilter !== "all" && !item.languages.includes(languageFilter)) {
                return false
            }
            return true
        })
    }, [solvedHistory, search, difficultyFilter, languageFilter])

    // cap the history; the rest hides behind a "see more" link
    const [showAllHistory, setShowAllHistory] = useState(false)
    const visibleHistory = showAllHistory ? filteredHistory : filteredHistory.slice(0, INITIAL_HISTORY)
    const hiddenHistory = filteredHistory.length - INITIAL_HISTORY
    // 2026-07-12: history/skills/standing/xp fire alongside `progress` but were
    // not part of this gate — once `progress` resolved, the tab's sub-sections
    // (metric row's rank/percentile, the stats card, solve history) popped in
    // individually as each of those queries finished. Wait on all of them so the
    // one skeleton below covers the whole chain instead of only the first hop.
    const isFirstLoad = (!data && (isLoading || !userId))
        || (historySwr.isLoading && !history)
        || (skillsSwr.isLoading && !skills)
        || (standingSwr.isLoading && !standing)
        || (xpSwr.isLoading && !xp)

    const rootClassNames: Array<AllowedClassName> = []
    if (className) {
        rootClassNames.push(className as AllowedClassName)
    }

    return (
        <AsyncContent
            isLoading={isFirstLoad}
            skeleton={(
                <StackV gap={6} principle="block-boundary" classNames={rootClassNames}
                    explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                    items={[
                        () => (
                            <StackV gap={4} items={[
                                () => <Skeleton.Typography type="body-sm" width="1/4" />,
                                () => <Skeleton className="h-20 w-full rounded-2xl" />,
                            ]} />
                        ),
                        () => (
                            <StackV gap={4} items={[
                                () => <Skeleton.Typography type="body-sm" width="1/4" />,
                                () => (
                                    <SurfaceListCard>
                                        <SurfaceListCardItem>
                                            <Skeleton.SegmentBar legendItems={3} />
                                        </SurfaceListCardItem>
                                        <SurfaceListCardItem>
                                            <Cluster gap={3} principle="chip-row"
                                                explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                                items={
                                                    [0, 1, 2, 3, 4, 5, 6, 7].map((chip) => (
                                                        () => <Skeleton key={chip} className="h-7 w-20 rounded-full" />
                                                    ))
                                                } />
                                        </SurfaceListCardItem>
                                        <SurfaceListCardItem>
                                            <Skeleton.SegmentBar legendItems={3} />
                                        </SurfaceListCardItem>
                                    </SurfaceListCard>
                                ),
                            ]} />
                        ),
                        () => (
                            <StackV gap={4} items={[
                                () => <Skeleton.Typography type="body-sm" width="1/4" />,
                                () => (
                                    <Cluster gap={4} principle="content-row" justify="between"
                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                        items={[
                                            () => (
                                                <StackH gap={4} principle="content-row" classNames={["min-w-0", "flex-1"]}
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    items={[
                                                        () => <Skeleton className="h-9 min-w-0 flex-1 rounded-medium" />,
                                                        () => <Skeleton className="size-9 shrink-0 rounded-full" />,
                                                    ]} />
                                            ),
                                            () => <Skeleton.Typography type="body-sm" className="w-16 shrink-0" />,
                                        ]} />
                                ),
                                () => (
                                    <SurfaceListCard>
                                        {[0, 1, 2].map((row) => (
                                            <SurfaceListCardItem key={row}>
                                                <StackH gap={4} principle="content-row"
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    items={[
                                                        () => (
                                                            <StackV gap={3} principle="sibling-stack" classNames={["min-w-0", "flex-1"]}
                                                                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                                items={[
                                                                    () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                                                    () => <Skeleton.Typography type="body-xs" width="1/3" />,
                                                                ]} />
                                                        ),
                                                        () => <Skeleton.Chip />,
                                                        () => <Skeleton.Chip />,
                                                    ]} />
                                            </SurfaceListCardItem>
                                        ))}
                                    </SurfaceListCard>
                                ),
                            ]} />
                        ),
                    ]} />
            )}
            isEmpty={solved === 0 && !hasStats && solvedHistory.length === 0}
            emptyContent={{
                title: t("publicProfile.coding.empty"),
                description: t("publicProfile.coding.emptyHint"),
            }}
            error={error}
            errorContent={{
                title: t("publicProfile.loadError"),
                onRetry: () => { void mutate() },
                retryLabel: t("publicProfile.loadErrorRetry"),
            }}
        >
            <StackV gap={6} principle="block-boundary" classNames={rootClassNames}
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                    () => (
                        <LabeledCard label={t("publicProfile.coding.metricsHeading")} frameless>
                            <StatRibbon
                                items={stats.map((stat) => ({
                                    key: stat.key,
                                    value: stat.value,
                                    label: t(`publicProfile.coding.metric.${stat.key}`),
                                }))}
                            />
                        </LabeledCard>
                    ),
                    ...(hasStats
                        ? [() => (
                            <LabeledCard
                                label={t("publicProfile.coding.statsHeading")}
                                frameless
                            >
                                <SurfaceListCard>
                                    {difficultySegments.length > 0 ? (
                                        <SurfaceListCardItem>
                                            <StackV gap={3} principle="sibling-stack"
                                                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                items={[
                                                    () => <Label>{t("publicProfile.coding.byDifficulty")}</Label>,
                                                    () => (
                                                        <SegmentBar
                                                            ariaLabel={t("publicProfile.coding.byDifficulty")}
                                                            segments={difficultySegments}
                                                        />
                                                    ),
                                                ]} />
                                        </SurfaceListCardItem>
                                    ) : null}
                                    {orderedDomain.length > 0 ? (
                                        <SurfaceListCardItem>
                                            <StackV gap={3} principle="sibling-stack"
                                                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                items={[
                                                    () => <Label>{t("publicProfile.coding.byDomain")}</Label>,
                                                    () => (
                                                        <TopicMasteryGrid
                                                            ariaLabel={t("publicProfile.coding.byDomain")}
                                                            topics={orderedDomain.map((item) => ({
                                                                key: item.key,
                                                                label: domainLabel(item.key),
                                                                solved: item.solved,
                                                            }))}
                                                        />
                                                    ),
                                                ]} />
                                        </SurfaceListCardItem>
                                    ) : null}
                                    {byLanguage.length > 0 ? (
                                        <SurfaceListCardItem>
                                            <StackV gap={3} principle="sibling-stack"
                                                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                items={[
                                                    () => <Label>{t("publicProfile.coding.byLanguage")}</Label>,
                                                    () => (
                                                        <SegmentBar
                                                            ariaLabel={t("publicProfile.coding.byLanguage")}
                                                            segments={byLanguage.map((item) => ({
                                                                key: item.key,
                                                                label: getLanguageLabel(item.key),
                                                                value: item.solved,
                                                                color: getLanguageColor(item.key),
                                                            }))}
                                                        />
                                                    ),
                                                ]} />
                                        </SurfaceListCardItem>
                                    ) : null}
                                </SurfaceListCard>
                            </LabeledCard>
                        )]
                        : []),
                    ...(solvedHistory.length > 0
                        ? [() => {
                            const facetBodyItems = [
                                ...(difficultyOptions.length > 0
                                    ? [() => (
                                        <StackV gap={3} principle="sibling-stack"
                                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                            items={[
                                                () => <Typography type="body-xs" color="muted">{t("publicProfile.coding.manage.difficultyHeading")}</Typography>,
                                                () => (
                                                    <FlexWrapButtonRadio<DifficultyFilterValue>
                                                        ariaLabel={t("publicProfile.coding.manage.difficultyFilterAria")}
                                                        value={difficultyFilter}
                                                        onChange={setDifficultyFilter}
                                                        items={[
                                                            { value: "all", content: t("publicProfile.coding.manage.allDifficulties") },
                                                            ...difficultyOptions.map((raw) => {
                                                                const meta = CODING_DIFFICULTY_CHIP[raw]
                                                                return {
                                                                    value: raw,
                                                                    content: meta ? <StatusChip tone={meta.tone}>{t(meta.labelKey)}</StatusChip> : raw,
                                                                }
                                                            }),
                                                        ]}
                                                    />
                                                ),
                                            ]} />
                                    )]
                                    : []),
                                ...(languageOptions.length > 0
                                    ? [() => (
                                        <StackV gap={3} principle="sibling-stack"
                                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                            items={[
                                                () => <Typography type="body-xs" color="muted">{t("publicProfile.coding.manage.languageHeading")}</Typography>,
                                                () => (
                                                    <FlexWrapButtonRadio<LanguageFilterValue>
                                                        ariaLabel={t("publicProfile.coding.manage.languageFilterAria")}
                                                        value={languageFilter}
                                                        onChange={setLanguageFilter}
                                                        items={[
                                                            { value: "all", content: t("publicProfile.coding.manage.allLanguages") },
                                                            ...languageOptions.map((lang) => ({
                                                                value: lang,
                                                                content: <LanguageChip language={lang} />,
                                                            })),
                                                        ]}
                                                    />
                                                ),
                                            ]} />
                                    )]
                                    : []),
                                ...(activeFacetCount > 0
                                    ? [() => (
                                        <Button variant="danger-soft" size="sm" className="self-start" onPress={clearFacets}>
                                            {t("publicProfile.coding.manage.clearFilters")}
                                        </Button>
                                    )]
                                    : []),
                            ]
                            return (
                                <LabeledCard
                                    label={t("publicProfile.coding.history")}
                                    frameless
                                >
                                    <StackV gap={4} items={[
                                        () => (
                                            <Cluster gap={4} principle="content-row" justify="between"
                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                items={[
                                                    () => (
                                                        <StackH gap={4} principle="content-row" classNames={["min-w-0", "flex-1"]}
                                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                            items={[
                                                                () => (
                                                                    <SearchInput
                                                                        className="min-w-0 flex-1"
                                                                        value={search}
                                                                        onValueChange={setSearch}
                                                                        placeholder={t("publicProfile.coding.manage.searchPlaceholder")}
                                                                    />
                                                                ),
                                                                ...((difficultyOptions.length > 0 || languageOptions.length > 0)
                                                                    ? [() => (
                                                                        <Popover isOpen={filterOpen} onOpenChange={setFilterOpen}>
                                                                            <Button
                                                                                isIconOnly
                                                                                variant="ghost"
                                                                                aria-label={t("publicProfile.coding.manage.filterButton")}
                                                                                className="shrink-0"
                                                                            >
                                                                                {activeFacetCount > 0 ? (
                                                                                    <Badge.Anchor>
                                                                                        <FunnelIcon className="size-5" />
                                                                                        <Badge size="sm" color="accent" placement="top-left">{activeFacetCount}</Badge>
                                                                                    </Badge.Anchor>
                                                                                ) : (
                                                                                    <FunnelIcon className="size-5" />
                                                                                )}
                                                                            </Button>
                                                                            <Popover.Content className="w-72">
                                                                                <StackV gap={1} padding={4} principle="cell-pad"
                                                                                    explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body."
                                                                                    items={[
                                                                                        () => (
                                                                                            <StackV gap={4} items={facetBodyItems} />
                                                                                        ),
                                                                                    ]} />
                                                                            </Popover.Content>
                                                                        </Popover>
                                                                    )]
                                                                    : []),
                                                            ]} />
                                                    ),
                                                    () => (
                                                        <Typography type="body-sm" color="muted" className="shrink-0">
                                                            {t("publicProfile.coding.manage.found", { count: filteredHistory.length })}
                                                        </Typography>
                                                    ),
                                                ]} />
                                        ),
                                        () => (filteredHistory.length === 0 ? (
                                            <Typography type="body-sm" color="muted">
                                                {t("publicProfile.coding.manage.emptyFiltered")}
                                            </Typography>
                                        ) : (
                                            <SurfaceListCard>
                                                {visibleHistory.map((item, index) => {
                                                    const difficulty = CODING_DIFFICULTY_CHIP[item.difficulty]
                                                    const solvedAt = item.firstSolvedAt
                                                        ? new Date(item.firstSolvedAt).toLocaleDateString(locale)
                                                        : undefined
                                                    const chipItems = [
                                                        ...(difficulty
                                                            ? [() => (
                                                                <StatusChip tone={difficulty.tone}>
                                                                    {t(difficulty.labelKey)}
                                                                </StatusChip>
                                                            )]
                                                            : []),
                                                        ...(item.domain
                                                            ? [() => (
                                                                <StatusChip tone="neutral">
                                                                    {domainLabel(item.domain!)}
                                                                </StatusChip>
                                                            )]
                                                            : []),
                                                        ...item.languages.map((language) => (
                                                            () => <LanguageChip key={language} language={language} />
                                                        )),
                                                    ]
                                                    return (
                                                        <SurfaceListCardItem
                                                            key={`${item.slug}-${index}`}
                                                            hover="underline"
                                                            href={username
                                                                ? pathConfig().locale(locale).profile(username).skills().problem(item.slug).build()
                                                                : undefined}
                                                        >
                                                            <StackH gap={4} principle="content-row"
                                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                items={[
                                                                    () => (
                                                                        <StackV gap={3} principle="sibling-stack" classNames={["min-w-0", "flex-1"]}
                                                                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                                            items={[
                                                                                () => (
                                                                                    <Typography type="body-sm" weight="medium" truncate className="underline-offset-4 decoration-[var(--separator-tertiary)] group-hover:underline">
                                                                                        {item.problemTitle}
                                                                                    </Typography>
                                                                                ),
                                                                                ...(solvedAt
                                                                                    ? [() => (
                                                                                        <Typography type="body-xs" color="muted">
                                                                                            {solvedAt}
                                                                                        </Typography>
                                                                                    )]
                                                                                    : []),
                                                                            ]} />
                                                                    ),
                                                                    () => (
                                                                        <Cluster gap={3} principle="chip-row" justify="end" classNames={["shrink-0"]} items={chipItems}
                                                                            explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                                                        />
                                                                    ),
                                                                ]} />
                                                        </SurfaceListCardItem>
                                                    )
                                                })}
                                                {hiddenHistory > 0 ? (
                                                    <SurfaceListCardItem onPress={() => setShowAllHistory((open) => !open)}>
                                                        <span className="text-muted">
                                                            {showAllHistory
                                                                ? t("publicProfile.coding.showLess")
                                                                : t("publicProfile.coding.showMore", { count: hiddenHistory })}
                                                        </span>
                                                    </SurfaceListCardItem>
                                                ) : null}
                                            </SurfaceListCard>
                                        )),
                                    ]} />
                                </LabeledCard>
                            )
                        }]
                        : []),
                ]} />
        </AsyncContent>
    )
}

"use client"

import React, {
    useCallback,
    useState,
} from "react"
import type { ReactNode } from "react"
import {
    Button,
    Card,
    Chip,
    Input,
    Label,
    Skeleton,
    TextField,
    Typography,
} from "@heroui/react"
import { toast } from "@/modules/toast/toast"
import { useTranslations } from "next-intl"
import {
    CheckCircleIcon,
    CopyIcon,
    GiftIcon,
    LightningIcon,
    SnowflakeIcon,
    TShirtIcon,
    TicketIcon,
} from "@phosphor-icons/react"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { Callout } from "@/components/composites/feedback/Callout"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { ModalShell } from "@/components/composites/layout/ModalShell"
import { useMutateRedeemRewardSwr } from "@/hooks/swr/api/graphql/mutations/useMutateRedeemRewardSwr"
import { useQueryMyRewardWalletSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyRewardWalletSwr"
import { useQueryMyVouchersSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyVouchersSwr"
import { useQueryRewardsSwr } from "@/hooks/swr/api/graphql/queries/useQueryRewardsSwr"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import type { QueryRewardData } from "@/modules/api/graphql/queries/types/rewards"
import type { RedeemRewardAiCreditGrant } from "@/modules/api/graphql/mutations/types/redeem-reward"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { Box } from "@/components/frames/Box"
import { Grid } from "@/components/frames/Grid"
import { StackH, StackV } from "@/components/frames/Stack"

/** Icon per catalog item, keyed by its stable reward key (falls back to a generic gift). */
const REWARD_ICON: Record<string, ReactNode> = {
    streakFreeze: <SnowflakeIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />,
    aiCreditBoost: <LightningIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />,
    voucher10: <TicketIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />,
    tshirt: <TShirtIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />,
}

/**
 * Coin-shop catalog grouped into user-facing SECTIONS by reward `kind` (instructor's
 * call, 2026-07-17, "split into more categories"). `aiCredit` + `digital` read as one
 * "speed up learning" bucket; `voucher` and `physical` each stand alone. Order = display
 * order. A reward whose `kind` matches no section is not shown in the grouped view —
 * every current kind is covered here; adding a new kind means adding a section.
 */
const REWARD_SECTIONS: ReadonlyArray<{ key: string, icon: ReactNode, kinds: ReadonlyArray<string> }> = [
    { key: "learn", icon: <LightningIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />, kinds: ["aiCredit", "digital"] },
    { key: "voucher", icon: <TicketIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />, kinds: ["voucher"] },
    { key: "physical", icon: <GiftIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />, kinds: ["physical"] },
]

/** One redeem effect's takeaway shown right after redeeming (voucher code / AI-credit bump). */
type JustRedeemed =
    | { kind: "voucher", code: string }
    | { kind: "aiCredit", grant: RedeemRewardAiCreditGrant }

/** Shipping form fields (physical rewards only). */
interface ShippingForm {
    recipientName: string
    phone: string
    address: string
}

const EMPTY_SHIPPING: ShippingForm = {
    recipientName: "",
    phone: "",
    address: "",
}

/** Props for {@link RewardCatalog}. */
export type RewardCatalogProps = WithClassNames<undefined>

/**
 * The Coin shop's "Store" tab: the redeemable catalog grid. Self-fetches the
 * catalog + the viewer's balance (the wallet SWR key is shared with the header
 * and the "My Wallet" tab, so a redeem here refreshes both instantly). Physical
 * rewards expand an inline shipping form before redeeming; a `voucher`/`aiCredit`
 * redemption surfaces its takeaway (code to copy / bonus credit granted) in a
 * dismissible callout above the grid.
 *
 * @param props - optional className for the root element.
 */
export const RewardCatalog = ({ className }: RewardCatalogProps) => {
    const t = useTranslations()
    const rewardsSwr = useQueryRewardsSwr()
    const walletSwr = useQueryMyRewardWalletSwr()
    const vouchersSwr = useQueryMyVouchersSwr()
    const { trigger: triggerRedeem } = useMutateRedeemRewardSwr()
    const runGraphQL = useGraphQLWithToast()

    /** The reward key currently being redeemed (single in-flight redeem). */
    const [redeeming, setRedeeming] = useState<string | null>(null)
    /** The physical reward whose shipping form is open (null = none). */
    const [shippingFor, setShippingFor] = useState<string | null>(null)
    const [ship, setShip] = useState<ShippingForm>(EMPTY_SHIPPING)
    /** The takeaway of the most recent voucher/aiCredit redemption, if any. */
    const [justRedeemed, setJustRedeemed] = useState<JustRedeemed | null>(null)
    /** A non-physical reward awaiting spend confirmation (Coin is real, redeem is irreversible). */
    const [confirming, setConfirming] = useState<QueryRewardData | null>(null)

    const balance = walletSwr.data?.balance ?? 0

    const onRedeem = useCallback(
        async (reward: QueryRewardData, shipping?: ShippingForm) => {
            setRedeeming(reward.key)
            try {
                let redeemed: { voucherCode?: string | null, aiCreditGranted?: RedeemRewardAiCreditGrant | null } | undefined
                const ok = await runGraphQL(async () => {
                    const result = await triggerRedeem({
                        rewardKey: reward.key,
                        ...shipping,
                    })
                    const wrapped = result.data!.redeemReward
                    redeemed = wrapped.data
                    return wrapped
                })
                if (ok) {
                    await walletSwr.mutate()
                    if (reward.kind === "voucher" && redeemed?.voucherCode) {
                        setJustRedeemed({ kind: "voucher", code: redeemed.voucherCode })
                        await vouchersSwr.mutate()
                    } else if (reward.kind === "aiCredit" && redeemed?.aiCreditGranted) {
                        setJustRedeemed({ kind: "aiCredit", grant: redeemed.aiCreditGranted })
                    }
                    // close + reset the shipping form on success
                    setShippingFor(null)
                    setShip(EMPTY_SHIPPING)
                }
            } finally {
                setRedeeming(null)
            }
        },
        [
            triggerRedeem,
            walletSwr,
            vouchersSwr,
            runGraphQL,
        ],
    )

    const onCopyCode = useCallback(
        async (code: string) => {
            try {
                await navigator.clipboard.writeText(code)
                toast.success(t("rewards.myVouchers.copied"))
            } catch {
                // clipboard blocked (permissions/http) → no-op, code is still selectable text
            }
        },
        [t],
    )

    return (
        <Box className={className}>
            <StackV gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (justRedeemed ? (
                        <Callout
                            status="accent"
                            icon={CheckCircleIcon}
                            title={
                                justRedeemed.kind === "voucher"
                                    ? t("rewards.justRedeemed.voucherTitle")
                                    : t("rewards.justRedeemed.aiCreditTitle")
                            }
                            description={
                                justRedeemed.kind === "voucher"
                                    ? undefined
                                    : t("rewards.justRedeemed.aiCreditDescription", {
                                        amount5h: justRedeemed.grant.amount5h,
                                        amountWeek: justRedeemed.grant.amountWeek,
                                    })
                            }
                            body={justRedeemed.kind === "voucher" ? () => (
                                <StackH gap={3} principle="flex-action"
                                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                    align="center" items={[
                                        () => <span className="font-mono font-medium text-foreground">{justRedeemed.code}</span>,
                                        () => (
                                            <Button
                                                variant="tertiary"
                                                size="sm"
                                                onPress={() => void onCopyCode(justRedeemed.code)}
                                            >
                                                <CopyIcon aria-hidden focusable="false" className="size-4" />
                                                {t("rewards.myVouchers.copy")}
                                            </Button>
                                        ),
                                    ]} />
                            ) : undefined}
                            onClose={() => setJustRedeemed(null)}
                            closeAriaLabel={t("rewards.justRedeemed.dismiss")}
                        />
                    ) : null),

                    () => (
                        <AsyncContent
                            isLoading={!rewardsSwr.data}
                            skeleton={(
                                <Grid
                                    columns={{ base: 1, sm: 2 }}
                                    principle="content-row"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    items={Array.from({ length: 4 }).map((_, index) => ({
                                        key: String(index),
                                        content: () => (
                                            <Box principle="card-padding" className="rounded-3xl bg-surface p-4 shadow-surface"
                                                explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                                                <StackV gap={4} principle="content-row"
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    items={[
                                                        () => (
                                                            <StackH gap={4} principle="content-row"
                                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                align="center" items={[
                                                                    () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                                                                    () => <Skeleton className="h-4 w-1/2 rounded-lg" />,
                                                                ]} />
                                                        ),
                                                        () => <Skeleton className="h-4 w-full rounded-lg" />,
                                                        () => <Skeleton className="h-9 w-24 self-end rounded-lg" />,
                                                    ]} />
                                            </Box>
                                        ),
                                    }))}
                                />
                            )}
                            isEmpty={(rewardsSwr.data ?? []).length === 0}
                            emptyContent={{
                                icon: <GiftIcon aria-hidden focusable="false" className="size-8 text-muted" />,
                                title: t("rewards.catalogEmptyTitle"),
                                description: t("rewards.catalogEmptyDescription"),
                            }}
                            error={rewardsSwr.error}
                            errorContent={{
                                title: t("rewards.catalogError"),
                                onRetry: () => void rewardsSwr.mutate(),
                            }}
                        >
                            <StackV gap={6} principle="block-boundary" items={REWARD_SECTIONS.map((section) => () => {
                                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                                const sectionItems = (rewardsSwr.data ?? []).filter((reward) => section.kinds.includes(reward.kind))
                                if (sectionItems.length === 0) {
                                    return null
                                }
                                return (
                                    <LabeledCard
                                        key={section.key}
                                        // `label` is plain text now (never a built element) — `LabeledCard`
                                        // has no leading-icon slot the way `SectionCard` does, so the
                                        // per-section icon has nowhere left to attach (flagged for a
                                        // follow-up: a real icon slot on `LabeledCard`, or switch this
                                        // section header to `SectionCard`).
                                        label={t(`rewards.section.${section.key}`)}
                                    >
                                        <Grid
                                            columns={{ base: 1, sm: 2 }}
                                            principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            items={sectionItems.map((reward) => ({
                                                key: reward.key,
                                                content: () => {
                                                    const affordable = balance >= reward.cost
                                                    const isPhysical = reward.kind === "physical"
                                                    const formOpen = shippingFor === reward.key
                                                    const shipReady = Boolean(
                                                        ship.recipientName.trim()
                                && ship.phone.trim()
                                && ship.address.trim(),
                                                    )
                                                    return (
                                                        <Card>
                                                            <StackV gap={4} principle="content-row"
                                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                items={[
                                                                    () => (
                                                                        <StackH gap={4} principle="content-row"
                                                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                            align="start" items={[
                                                                                () => (
                                                                                    <IconTile
                                                                                        size="sm"
                                                                                        tone="accent"
                                                                                        icon={REWARD_ICON[reward.key] ?? (
                                                                                            <GiftIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />
                                                                                        )}
                                                                                    />
                                                                                ),
                                                                                () => (
                                                                                    <StackV gap={1} principle="name-handle"
                                                                                        explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
                                                                                        classNames={["min-w-0", "flex-1"]} items={[
                                                                                            () => (
                                                                                                <span className="truncate text-sm font-semibold text-foreground">
                                                                                                    {reward.title}
                                                                                                </span>
                                                                                            ),
                                                                                            () => (
                                                                                                <span className="text-xs text-muted">
                                                                                                    {reward.description}
                                                                                                </span>
                                                                                            ),
                                                                                        ]} />
                                                                                ),
                                                                            ]} />
                                                                    ),
                                                                    () => (
                                                                        <StackH gap={4} principle="content-row" justify="between" align="center"
                                                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                            items={[
                                                                                () => (
                                                                                    <Chip color="accent" variant="soft" size="sm">
                                                                                        <Chip.Label>
                                                                                            {t("rewards.cost", { count: reward.cost })}
                                                                                        </Chip.Label>
                                                                                    </Chip>
                                                                                ),
                                                                                () => (!formOpen ? (
                                                                                    <Button
                                                                                        variant="primary"
                                                                                        size="sm"
                                                                                        isDisabled={!affordable || redeeming !== null}
                                                                                        isPending={redeeming === reward.key}
                                                                                        onPress={() => {
                                                                                            if (isPhysical) {
                                                                                                setShippingFor(reward.key)
                                                                                            } else {
                                                                                                // Coin is real + redeem is irreversible — confirm
                                                                                                // before spending (mirrors the shipping form's own
                                                                                                // "Confirm redeem" step for physical rewards).
                                                                                                setConfirming(reward)
                                                                                            }
                                                                                        }}
                                                                                    >
                                                                                        {affordable
                                                                                            ? t("rewards.redeem")
                                                                                            : t("rewards.cannotAfford")}
                                                                                    </Button>
                                                                                ) : null),
                                                                            ]} />
                                                                    ),
                                                                    () => (formOpen ? (
                                                                        <StackV gap={3} principle="sibling-stack"
                                                                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                                            items={[
                                                                                () => (
                                                                                    <TextField variant="secondary">
                                                                                        <Label htmlFor={`reward-ship-name-${reward.key}`}>
                                                                                            {t("rewards.shipName")}
                                                                                        </Label>
                                                                                        <Input
                                                                                            id={`reward-ship-name-${reward.key}`}
                                                                                            value={ship.recipientName}
                                                                                            onChange={(event) => setShip((prev) => ({
                                                                                                ...prev,
                                                                                                recipientName: event.target.value,
                                                                                            }))}
                                                                                        />
                                                                                    </TextField>
                                                                                ),
                                                                                () => (
                                                                                    <TextField variant="secondary">
                                                                                        <Label htmlFor={`reward-ship-phone-${reward.key}`}>
                                                                                            {t("rewards.shipPhone")}
                                                                                        </Label>
                                                                                        <Input
                                                                                            id={`reward-ship-phone-${reward.key}`}
                                                                                            type="tel"
                                                                                            value={ship.phone}
                                                                                            onChange={(event) => setShip((prev) => ({
                                                                                                ...prev,
                                                                                                phone: event.target.value,
                                                                                            }))}
                                                                                        />
                                                                                    </TextField>
                                                                                ),
                                                                                () => (
                                                                                    <TextField variant="secondary">
                                                                                        <Label htmlFor={`reward-ship-address-${reward.key}`}>
                                                                                            {t("rewards.shipAddress")}
                                                                                        </Label>
                                                                                        <Input
                                                                                            id={`reward-ship-address-${reward.key}`}
                                                                                            value={ship.address}
                                                                                            onChange={(event) => setShip((prev) => ({
                                                                                                ...prev,
                                                                                                address: event.target.value,
                                                                                            }))}
                                                                                        />
                                                                                    </TextField>
                                                                                ),
                                                                                () => (
                                                                                    <StackH gap={3} principle="flex-action"
                                                                                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                                                                        align="center" items={[
                                                                                            () => (
                                                                                                <Button
                                                                                                    variant="primary"
                                                                                                    size="sm"
                                                                                                    isDisabled={!shipReady || redeeming !== null}
                                                                                                    isPending={redeeming === reward.key}
                                                                                                    onPress={() => void onRedeem(reward, ship)}
                                                                                                >
                                                                                                    {t("rewards.confirmRedeem")}
                                                                                                </Button>
                                                                                            ),
                                                                                            () => (
                                                                                                <Button
                                                                                                    variant="tertiary"
                                                                                                    size="sm"
                                                                                                    onPress={() => setShippingFor(null)}
                                                                                                >
                                                                                                    {t("rewards.cancel")}
                                                                                                </Button>
                                                                                            ),
                                                                                        ]} />
                                                                                ),
                                                                            ]} />
                                                                    ) : null),
                                                                ]} />
                                                        </Card>
                                                    )
                                                },
                                            }))}
                                        />
                                    </LabeledCard>
                                )
                            })} />
                        </AsyncContent>
                    ),

                    // spend confirmation for non-physical rewards — Coin is real + redeem is
                    // irreversible, so a single accidental tap must never fire it (mirrors the
                    // shipping form's own "Confirm redeem" step for physical rewards).
                    () => (
                        <ModalShell
                            isOpen={confirming !== null}
                            onOpenChange={(open) => {
                                if (!open) {
                                    setConfirming(null)
                                }
                            }}
                            title={t("rewards.confirmRedeem")}
                            size="sm"
                            body={() => (
                                <Typography type="body-sm" color="muted">
                                    {confirming
                                        ? t("rewards.confirmRedeemBody", { cost: confirming.cost, title: confirming.title })
                                        : null}
                                </Typography>
                            )}
                            footer={() => (
                                <>
                                    <Button variant="tertiary" onPress={() => setConfirming(null)}>
                                        {t("rewards.cancel")}
                                    </Button>
                                    <Button
                                        variant="primary"
                                        isPending={redeeming !== null}
                                        onPress={() => {
                                            const reward = confirming
                                            setConfirming(null)
                                            if (reward) {
                                                void onRedeem(reward)
                                            }
                                        }}
                                    >
                                        {t("rewards.confirmRedeem")}
                                    </Button>
                                </>
                            )}
                        />
                    ),
                ]} />
        </Box>
    )
}

"use client"

import { ClockCountdownIcon as ClockCountdown } from "@phosphor-icons/react"
import React, {
    useCallback,
} from "react"
import {
    Button,
    Card,
} from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useSearchParams,
} from "next/navigation"
import {
    useRouter,
} from "@/i18n/navigation"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { pathConfig } from "@/resources/path"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"

/** Props for {@link CheckoutExpired}. */
export interface CheckoutExpiredProps {
    /** Re-arm the poll window and re-check the payment status once more. */
    onRecheck: () => void
}

/**
 * Terminal state shown when the SePay checkout window elapses without the
 * payment landing (the transaction has moved — or will move — to `Unpaid` on
 * the BE, `transactions/business.md` "Pending → Unpaid"). Replaces the
 * otherwise-indefinite QR + waiting spinner with an explicit dead-end + two
 * ways forward: re-check once more (in case the bank transfer just settled) or
 * start a fresh checkout from the course page.
 *
 * Self-contained (mirrors the sibling panels): reads its own `courseId` param
 * and owns the "start over" navigation; the re-check + timer reset is handed in
 * from the container as `onRecheck`. `"use client"` for the params / i18n / nav
 * hooks and the buttons.
 *
 * @param props - the container's re-check handler.
 */
export const CheckoutExpired = ({ onRecheck }: CheckoutExpiredProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const searchParams = useSearchParams()
    const courseId = searchParams.get("courseId") || ""

    /** Go back to the course page to start a fresh checkout. */
    const onStartOver = useCallback(
        () => {
            router.push(pathConfig().locale(locale).course(courseId).build())
        },
        [
            router,
            locale,
            courseId,
        ],
    )

    return (
        <Box principle="page-pad" className="flex min-h-[80vh] flex-col items-center justify-center p-4"
            explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
            <Card className="w-full max-w-md bg-default/40 text-center backdrop-blur-md">
                <Box principle="card-padding" className="p-8"
                    explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                    <Card.Content className="flex flex-col items-center">
                        <div className="mb-6 flex justify-center">
                            <IconTile icon={<ClockCountdown aria-hidden focusable="false" />} tone="warning" size="lg" />
                        </div>
                        <h1 className="mb-2 text-2xl font-bold">{t("payment.sepay.expired.title")}</h1>
                        <p className="mb-6 text-muted">{t("payment.sepay.expired.description")}</p>
                        <StackV gap={4} principle="content-row" classNames={["w-full"]}
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            items={[
                                () => (
                                    <Button variant="primary" onPress={onStartOver}>
                                        {t("payment.sepay.expired.startOver")}
                                    </Button>
                                ),
                                () => (
                                    <Button variant="secondary" onPress={onRecheck}>
                                        {t("payment.sepay.expired.recheck")}
                                    </Button>
                                ),
                            ]} />
                    </Card.Content>
                </Box>
            </Card>
        </Box>
    )
}

"use client"

import React, {
    useCallback,
    useMemo,
} from "react"
import {
    Card,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    useSearchParams,
} from "next/navigation"
import type {
    BankDetails,
} from "../types"
import {
    parseBankDetails,
} from "../utils"
import {
    DetailRow,
} from "../DetailRow"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * Right-hand panel: the price card plus the bank/account/amount/content rows.
 *
 * Self-contained section (single-use): reads its own checkout query params,
 * derives the destination bank from the QR url, and owns the clipboard copy
 * handler — so the checkout container only renders `<OrderSummary />` and the
 * logic lives next to where it is used. `"use client"` for the query-params /
 * i18n hooks and the interactive copy rows. The repeated rows are rendered via
 * the presentational {@link DetailRow} (list-style), which takes the local
 * `onCopy` handler as a prop.
 */
export const OrderSummary = () => {
    const t = useTranslations()
    const searchParams = useSearchParams()

    const amount = searchParams.get("amount") || ""
    const referenceId = searchParams.get("ref") || ""
    const courseTitle = searchParams.get("courseTitle") || ""
    const qrUrl = searchParams.get("qr") || ""

    /** Destination bank + account parsed once from the QR url. */
    const bankDetails = useMemo<BankDetails>(
        () => parseBankDetails(qrUrl),
        [
            qrUrl,
        ],
    )

    /** Copy the given text to the clipboard. */
    const onCopy = useCallback(
        (text: string) => {
            void navigator.clipboard.writeText(text)
        },
        [],
    )

    return (
        <StackV gap={6} principle="block-boundary"
            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
            items={[
                () => (
                    <Card className="bg-default/40 backdrop-blur-md">
                        <Box principle="card-padding" className="p-6"
                            explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                            <Card.Content>
                                <h3 className="mb-4 text-lg font-medium">{courseTitle}</h3>
                                <StackH gap={3} principle="value-row" align="baseline"
                                    explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                                    items={[
                                        () => (
                                            <span className="text-3xl font-bold text-primary">
                                                {Number(amount).toLocaleString("vi-VN")}
                                            </span>
                                        ),
                                        () => <span className="text-sm text-muted">VND</span>,
                                    ]} />
                            </Card.Content>
                        </Box>
                    </Card>
                ),

                () => (
                    <Card className="flex-grow bg-default/40 backdrop-blur-md">
                        <Box principle="card-padding" className="p-6"
                            explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                            <Card.Content>
                                <StackV gap={4} principle="content-row"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    items={[
                                        () => <DetailRow label={t("payment.sepay.bank")} value={bankDetails.bank} />,
                                        () => (
                                            <DetailRow
                                                copyValue={bankDetails.account}
                                                label={t("payment.sepay.account")}
                                                showCopy
                                                value={bankDetails.account}
                                                onCopy={onCopy}
                                            />
                                        ),
                                        () => (
                                            <DetailRow
                                                copyValue={amount}
                                                label={t("payment.sepay.amount")}
                                                showCopy
                                                value={`${Number(amount).toLocaleString("vi-VN")} VND`}
                                                onCopy={onCopy}
                                            />
                                        ),
                                        () => (
                                            <DetailRow
                                                copyValue={referenceId}
                                                isHighlighted
                                                label={t("payment.sepay.content")}
                                                showCopy
                                                value={referenceId}
                                                onCopy={onCopy}
                                            />
                                        ),
                                    ]} />
                            </Card.Content>
                        </Box>
                    </Card>
                ),
            ]} />
    )
}

"use client"

import { ArrowClockwiseIcon as ArrowsClockwise } from "@phosphor-icons/react"
import React, {
    useCallback,
} from "react"
import {
    Button,
    Card,
    Spinner,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    useSearchParams,
} from "next/navigation"
import {
    useQueryCourseEnrollmentStatusSwr,
} from "@/hooks/swr/api/graphql/queries/useQueryCourseEnrollmentStatusSwr"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * Left-hand panel: the SePay QR code + "waiting for payment" status + a manual
 * re-check button.
 *
 * Self-contained section (single-use): reads its own QR url query param and
 * triggers an enrollment-status re-check through the shared SWR singleton — so
 * the checkout container only renders `<QrPanel />` and the refresh logic lives
 * here. `"use client"` for the query-params / i18n hooks and the button.
 */
export const QrPanel = () => {
    const t = useTranslations()
    const searchParams = useSearchParams()
    const qrUrl = searchParams.get("qr") || ""

    const {
        mutate: refreshStatus,
    } = useQueryCourseEnrollmentStatusSwr()

    /** Manually re-check the enrollment/payment status. */
    const onRefresh = useCallback(
        () => {
            refreshStatus()
        },
        [
            refreshStatus,
        ],
    )

    return (
        <Card className="flex flex-col items-center overflow-hidden bg-default/40 backdrop-blur-md">
            <Box principle="card-padding" className="p-8"
                explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                <Card.Content className="flex w-full flex-col items-center">
                    <h2 className="mb-6 text-center text-xl font-semibold">
                        {t("payment.sepay.instruction")}
                    </h2>

                    <Box principle="card-padding" className="group relative rounded-2xl bg-white p-4 shadow-2xl transition-transform hover:scale-[1.02]"
                        explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                        {qrUrl ? (
                            <img
                                alt="SePay QR"
                                className="aspect-square w-full max-w-[300px] object-contain"
                                src={qrUrl}
                            />
                        ) : (
                            <div className="flex h-[300px] w-[300px] items-center justify-center">
                                <Spinner size="lg" />
                            </div>
                        )}
                    </Box>

                    <Box principle="push-end" className="mt-8 w-full"
                        explain="Pushes this peer to the trailing edge so trailing meta stays right-aligned in the row."
                    >
                        <StackV gap={4} principle="content-row" align="center"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            items={[
                                () => (
                                    <StackH gap={3} principle="icon-text" align="center"
                                        explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                                        items={[
                                            () => <Spinner size="sm" />,
                                            () => (
                                                <span className="text-sm italic text-muted">
                                                    {t("payment.sepay.waiting")}
                                                </span>
                                            ),
                                        ]} />
                                ),
                                () => (
                                    <Button
                                        variant="secondary"
                                        onPress={onRefresh}
                                    >
                                        <ArrowsClockwise className="h-5 w-5" />
                                        {t("payment.sepay.checkStatus")}
                                    </Button>
                                ),
                            ]} />
                    </Box>
                </Card.Content>
            </Box>
        </Card>
    )
}

"use client"

import React, {
    Suspense,
    useCallback,
    useEffect,
    useState,
} from "react"
import {
    Spinner,
} from "@heroui/react"
import {
    useLocale,
} from "next-intl"
import {
    useSearchParams,
} from "next/navigation"
import {
    useQueryCourseEnrollmentStatusSwr,
} from "@/hooks/swr/api/graphql/queries/useQueryCourseEnrollmentStatusSwr"
import {
    useRouter,
} from "@/i18n/navigation"
import {
    EnrolledSuccess,
} from "./EnrolledSuccess"
import {
    CheckoutExpired,
} from "./CheckoutExpired"
import {
    QrPanel,
} from "./QrPanel"
import {
    OrderSummary,
} from "./OrderSummary"
import { pathConfig } from "@/resources/path"
import { Box } from "@/components/frames/Box"
import { Grid } from "@/components/frames/Grid"

/** How often (ms) to re-poll the enrollment status while waiting for payment. */
const POLL_INTERVAL_MS = 5000
/** Delay (ms) before redirecting to the course once enrollment is confirmed. */
const REDIRECT_DELAY_MS = 2000
/**
 * How long (ms) to keep polling before treating the checkout as timed out.
 * There is no transaction-status query in the FE GraphQL layer (the only signal
 * is enrollment, which can never flip `true → false`), so once this window
 * elapses without enrollment we surface a terminal "expired" state rather than
 * spinning forever — matching the BE's `Pending → Unpaid` transition
 * (`transactions/business.md`). 15 minutes covers a slow bank transfer.
 */
const CHECKOUT_EXPIRY_MS = 15 * 60 * 1000

/**
 * SePay checkout container.
 *
 * Owns only the page-level concern: poll the course enrollment status via SWR
 * and redirect to the course once enrollment lands (showing the success screen
 * for a beat first). Each panel is self-contained — `QrPanel` and `OrderSummary`
 * read their own query params and own their own handlers — so this container
 * just composes them. `"use client"` because it runs effects + reads params.
 */
const SepayCheckoutPageContent = () => {
    const searchParams = useSearchParams()
    const locale = useLocale()
    const router = useRouter()

    const courseId = searchParams.get("courseId") || ""

    const {
        data: statusData,
        mutate: refreshStatus,
    } = useQueryCourseEnrollmentStatusSwr()
    const isEnrolled = statusData?.courseEnrollmentStatus?.data?.isEnrolled

    // once the checkout window elapses without enrollment, flip to the terminal
    // "expired" state (there is no tx-status query to observe `Unpaid` directly)
    const [isExpired, setIsExpired] = useState(false)

    // poll the enrollment status on a fixed interval while waiting for payment —
    // stops once we're enrolled (redirecting) or the checkout has expired, so we
    // don't keep hitting the API on a settled/dead checkout
    useEffect(
        () => {
            if (isEnrolled || isExpired) {
                return
            }
            const interval = setInterval(
                () => {
                    refreshStatus()
                },
                POLL_INTERVAL_MS,
            )
            return () => clearInterval(interval)
        },
        [
            refreshStatus,
            isEnrolled,
            isExpired,
        ],
    )

    // arm the expiry timeout while waiting; re-arms whenever the user re-checks
    // (which resets `isExpired` to false), and never fires once enrolled
    useEffect(
        () => {
            if (isEnrolled || isExpired) {
                return
            }
            const timer = setTimeout(
                () => {
                    setIsExpired(true)
                },
                CHECKOUT_EXPIRY_MS,
            )
            return () => clearTimeout(timer)
        },
        [
            isEnrolled,
            isExpired,
        ],
    )

    // re-open the poll window and re-check once more (e.g. a slow transfer just
    // settled after the timeout) — resets the terminal back to the waiting view
    const onRecheck = useCallback(
        () => {
            setIsExpired(false)
            refreshStatus()
        },
        [
            refreshStatus,
        ],
    )

    // once enrolled, give the success screen a beat then redirect to the course
    useEffect(
        () => {
            if (isEnrolled) {
                const timer = setTimeout(
                    () => {
                        router.push(pathConfig().locale(locale).course(courseId).build())
                    },
                    REDIRECT_DELAY_MS,
                )
                return () => clearTimeout(timer)
            }
        },
        [
            isEnrolled,
            courseId,
            locale,
            router,
        ],
    )

    if (isEnrolled) {
        return <EnrolledSuccess />
    }

    if (isExpired) {
        return <CheckoutExpired onRecheck={onRecheck} />
    }

    return (
        <Box principle="page-pad" className="flex min-h-screen flex-col items-center px-4 py-12"
            explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
            <Box principle="center-measure" className="w-full max-w-4xl"
                explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport."
            >
                <Grid
                    columns={{ base: 1, md: 2 }}
                    principle="layout-split"
                    explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
                    items={[
                        { key: "qr", content: QrPanel },
                        { key: "summary", content: OrderSummary },
                    ]}
                />
            </Box>
        </Box>
    )
}

/**
 * Public SePay checkout entry point.
 *
 * Wraps {@link SepayCheckoutPageContent} in a Suspense boundary (required because
 * the content + panels read `useSearchParams`) with a centered spinner fallback.
 * Mounted by the `/[locale]/checkout/sepay` route.
 */
export const SepayCheckoutPage = () => {
    return (
        <Suspense
            fallback={
                <div className="flex min-h-[80vh] items-center justify-center">
                    <Spinner size="lg" />
                </div>
            }
        >
            <SepayCheckoutPageContent />
        </Suspense>
    )
}

"use client"

import React, { useMemo } from "react"
import { Card, CardContent, cn } from "@heroui/react"
import { useTranslations } from "next-intl"
import { CpuIcon } from "@phosphor-icons/react"
import { Box } from "@/components/frames/Box"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"
import type { AiKeyHealthGroup } from "@/modules/api/graphql/queries/types/ai-key-health"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link AiKeyGroup}. */
export interface AiKeyGroupProps extends WithClassNames<undefined> {
    /** One per-model AI key health group from GraphQL. */
    group: AiKeyHealthGroup
}

/**
 * One model group of AI keys on the public status page. Header reads
 * "<models> · <provider> · healthy/total keys"; below it a row of masked key
 * chips, each tinted success (healthy) or danger (unhealthy). Token-only colors
 * → works light + dark. The masked label (`sk-...x9f`) is all that is shown.
 *
 * List item: keeps its own `group` payload but reads its own labels from i18n.
 * @param props.group - Masked AI key health for one model.
 */
export const AiKeyGroup = ({ group }: AiKeyGroupProps) => {
    const t = useTranslations("status")

    const header = useMemo(() => {
        const models = group.models.join(", ") || group.provider
        return t("aiKeyGroupHeader", {
            models,
            provider: group.provider,
            healthy: group.healthyKeys,
            total: group.totalKeys,
        })
    }, [group, t])

    const chipItems = group.keys.map((key, index) => () => (
        <span
            key={`${key.keyMask}-${index}`}
            className={cn(
                "inline-flex items-center rounded-full px-2 py-0 font-mono text-xs font-medium",
                key.healthy
                    ? "bg-success-soft text-success-soft-foreground"
                    : "bg-danger-soft text-danger-soft-foreground",
            )}
        >
            {key.keyMask}
        </span>
    ))

    return (
        <Card className="border border-default bg-surface">
            {/* Vendor CardContent padding cleared so house card-padding owns the inset. */}
            <CardContent className="p-0">
                <Box principle="card-padding" className="p-4"
                    explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                    <StackV
                        gap={4}
                        principle="label-field"
                        explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                        items={[
                            () => (
                                <StackH
                                    gap={3}
                                    principle="identity"
                                    explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                                    align="center"
                                    items={[
                                        () => (
                                            <CpuIcon
                                                aria-hidden
                                                focusable="false"
                                                className="size-4 shrink-0 text-muted"
                                            />
                                        ),
                                        () => (
                                            <span className="text-sm font-medium text-foreground">
                                                {header}
                                            </span>
                                        ),
                                    ]}
                                />
                            ),
                            () => (group.keys.length > 0 ? (
                                <Cluster gap={3} principle="chip-row" items={chipItems}
                                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                />
                            ) : (
                                <span className="text-xs text-muted">{t("noKeys")}</span>
                            )),
                        ]}
                    />
                </Box>
            </CardContent>
        </Card>
    )
}
